/* NavigAItor etkinlik kütüphanesi · 5 ders × 20 özgün şablon etkinlik (21. yy becerileri eşlemeli, kazanım kodsuz) */
const ACTLIB=[{"id":"tur-5-01","course":"TUR","grade":5,"themeNo":1,"themeName":"Oyun Dünyası","title":"Oyunun Kural Kitabı","subtitle":"Yönerge metni yazma ve yazım-noktalama","kazanim":["Yazısında içerik ve yapıya yönelik seçimlerini yönetebilme","Yazım ve noktalama işaretleriyle ilgili kuralları uygulayabilme"],"skills21":["Yaratıcılık","Oyunseverlik","İş Birliği","İletişim"],"digital":["Dijital İçerik Üretimi","Dijital Okuryazarlık"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Kâğıt-kalem","NavigAItor Stüdyo","ücretsiz bir sunum aracı"],"scenario":"Okulun teneffüs komitesi, bahçede oynanacak yeni bir oyun icat edecek öğrenciler arıyor. Komite tek bir şart koşuyor: Oyunu hiç bilmeyen bir 3. sınıf öğrencisi, yalnızca senin yazdığın kural kitabını okuyarak oyunu oynayabilmeli. Kuralların karışık olursa oyun kavgayla biter, eksik olursa kimse kazananı bilemez. Peki, bir oyunu hiç görmemiş birine onu yalnızca yazıyla nasıl anlatırsın?","visual":{"type":"flow","params":{"kind":"algoritma","steps":["Oyuncular ve malzemeler","Oyunun amacı","Başlangıç","Sırayla hamleler","Yasak hareketler","Oyunun bitişi ve kazanan"]},"caption":"Öğrenci kutuları doğru sıraya dizer ve her kutuya kendi oyununun kuralını tek cümleyle yazar."},"steps":[{"title":"Oyununu Tasarla","mode":"Bireysel · 15 dk","items":["Bahçede en fazla 6 kişiyle, en fazla 2 basit malzemeyle (top, tebeşir, ip gibi) oynanan bir oyun düşün.","Oyunun adını, amacını ve nasıl kazanıldığını üç kısa not hâlinde yaz.","Akış şemasındaki kutuları sırala; her kutuya bir anahtar kelime ekle."]},{"title":"Kural Kitabını Yaz","mode":"Bireysel · 25 dk","items":["Başlık, 'Malzemeler', 'Oyunun Amacı', 'Nasıl Oynanır?' ve 'Kim Kazanır?' bölümlerini oluştur.","'Nasıl Oynanır?' bölümünü numaralı adımlarla yaz; her adım tek bir eylem anlatsın.","Sıralama ifadeleri kullan: önce, ardından, sonra, en sonunda.","Cümle sonlarında nokta, sıralı ögeler arasında virgül, yönerge veren uyarılarda ünlem kullan."],"warn":"Sık yapılan hata: Kuralları tek uzun paragrafa yazmak. Okuyan kişi hangi adımda olduğunu kaybeder; her adımı ayrı satıra ve numaraya böl."},{"title":"Deneme Okuması","mode":"Grup · 25 dk","items":["Kural kitabını oyunu bilmeyen bir grup arkadaşına ver; sen hiç konuşmadan o kitabı okuyarak oyunu anlatmaya çalışsın.","Arkadaşının takıldığı ya da yanlış anladığı her yeri kitabın kenarına işaretle.","İşaretlenen yerleri birlikte konuşun: Eksik bilgi mi, yanlış sıra mı, belirsiz kelime mi?"],"warn":"Sık yapılan hata: 'Bunu herkes bilir.' diyerek bilgiyi atlamak. Okuyucunun aklındakini değil, sayfada yazanı okuduğunu unutma."},{"title":"Düzelt ve Yayımla","mode":"Bireysel · 15 dk","items":["İşaretli yerleri düzelt; büyük harf, nokta ve virgül kullanımını tek tek kontrol et.","Son metni NavigAItor Stüdyo'ya yükle ya da tek sayfalık bir slayta dönüştür.","Kural kitabının altına oyunun güvenli oynanması için bir uyarı cümlesi ekle."]}],"checklist":["Kural kitabıma başlık ve bölüm başlıkları koydum.","Oynanış adımlarını numaralandırdım ve her adımda tek eylem anlattım.","Sıralama ifadelerini (önce, sonra, en sonunda) kullandım.","Cümlelerimi büyük harfle başlatıp uygun noktalama işaretiyle bitirdim.","Bir arkadaşıma deneme okuması yaptırıp takıldığı yerleri düzelttim.","Kazananın nasıl belirleneceğini açıkça yazdım."],"rubric":[{"k":"Yapı ve Bölümler","d":"Metnin başlık, bölüm ve numaralı adımlarla düzenlenmesi","l4":"Tüm bölümler eksiksiz, adımlar mantıklı sırada ve numaralı","l3":"Bölümler var, bir adımın sırası karışık","l2":"Bazı bölümler eksik, adımlar paragraf içinde","l1":"Bölümleme yok, kurallar dağınık"},{"k":"İçerik Açıklığı","d":"Oyunu bilmeyen birinin metinle oyunu oynayabilmesi","l4":"Deneme okumasında hiç soru sorulmadan oyun oynandı","l3":"Bir-iki küçük soruyla oyun oynandı","l2":"Amaç ya da bitiş belirsiz kaldı","l1":"Metinden oyun anlaşılamıyor"},{"k":"Yazım ve Noktalama","d":"Büyük harf, nokta, virgül ve ünlem kullanımı","l4":"Hatasız ya da en fazla bir küçük hata","l3":"2–3 hata, anlamı bozmuyor","l2":"Sık hata, bazı cümleler karışıyor","l1":"Noktalama neredeyse hiç kullanılmamış"},{"k":"Düzeltme Süreci","d":"Geri bildirime göre metni iyileştirme","l4":"Tüm işaretli yerler gerekçeyle düzeltildi","l3":"İşaretli yerlerin çoğu düzeltildi","l2":"Yalnızca yazım hataları düzeltildi","l1":"Metin değiştirilmedi"}],"navi":["Oyunu hiç görmemiş biri, senin yazdığın ilk adımı okuyunca elinde ne olması gerektiğini biliyor mu?","Aynı anda iki oyuncu aynı hamleyi yaparsa ne olacağını kural kitabının neresi söylüyor?"],"diff":{"destek":"Bölüm başlıkları hazır verilmiş bir şablon ve 'önce, sonra, en sonunda' kelime kartlarıyla en az 4 adımlık kısa bir kural kitabı yazar.","ileri":"Oyunun 'kolay' ve 'zor' iki sürümünü yazar ve iki sürümün kurallarındaki farkları bir tabloda gösterir."},"misconception":"Yazan kişinin bildiği her şeyi okuyucunun da bildiğini varsaymak, yönerge metinlerinde en sık görülen yanılgıdır."},{"id":"tur-5-02","course":"TUR","grade":5,"themeNo":3,"themeName":"Duygularımı Tanıyorum","title":"Kayıp Kırmızı Bisiklet","subtitle":"Öyküleyici metinde hikâye unsurları ve duygu izleri","kazanim":["Öyküleyici metinde hikâye unsurlarını belirlemeye yönelik çözümleme yapabilme","Metinde geçen anlamını bilmediği söz varlığı unsurlarının anlamını tahmin edebilme"],"skills21":["Öz Farkındalık","Empati","Duygu Yönetimi","İletişim"],"digital":["Dijital Portfolyo","Dijital Etik"],"duration":"40 dk","format":"Bireysel","tools":["Kâğıt-kalem","NavigAItor okuma ekranı","renkli kalemler"],"scenario":"Okul kütüphanesi 'Duygu Haritası' adında bir sergi hazırlıyor ve her öğrenciden bir öykünün haritasını çıkarmasını istiyor. Sana düşen öyküde Deniz adlı bir çocuk, kardeşinin doğum gününde aldığı kırmızı bisikleti kıskanıyor. Öyküde kimlerin olduğu, nerede ve ne zaman geçtiği, olayın nasıl düğümlenip çözüldüğü haritada görünmeli. Bir duygunun bir öyküyü nasıl ilerlettiğini haritada gösterebilir misin?","visual":{"type":"organizer","params":{"kind":"hikaye","slots":["Kişiler","Yer","Zaman","Olay (Başlangıç)","Düğüm","Çözüm","Ana duygu"]},"caption":"Öğrenci öyküyü okuduktan sonra her kutuya metinden bulduğu ipucunu yazar ve ana duyguyu renklendirir."},"steps":[{"title":"Öyküyü Oku","mode":"Bireysel · 10 dk","items":["Öykü: 'Cumartesi sabahı bahçe kapısı açıldığında Deniz'in kalbi pır pır ediyordu. Babası, küçük kardeşi Ela'ya parıl parıl kırmızı bir bisiklet getirmişti. Deniz kendi eski bisikletinin paslı zincirine baktı, boğazında bir düğüm hissetti. Öğleden sonra Ela bisikletten düştü ve dizini sıyırdı. Deniz bir an duraksadı, sonra koşup kardeşini kaldırdı. Akşam, ikisi birlikte paslı zinciri temizlerken Deniz içindeki düğümün çözüldüğünü fark etti.'","Öyküyü bir kez sessiz, bir kez de duygulara dikkat ederek oku.","Anlamını bilmediğin ya da farklı kullanıldığını düşündüğün ifadelerin altını çiz."]},{"title":"Anlamı Tahmin Et","mode":"Bireysel · 10 dk","items":["'Kalbi pır pır etmek', 'boğazında düğüm hissetmek' ve 'düğümün çözülmesi' ifadelerinin anlamını cümlenin öncesine ve sonrasına bakarak tahmin et.","Tahminini 'Bence ... demek, çünkü metinde ... yazıyor.' kalıbıyla yaz.","Tahminini sözlükle karşılaştır; tuttuysa ✔, tutmadıysa düzeltmeyi yaz."],"warn":"Sık yapılan hata: 'Boğazında düğüm' ifadesini gerçek bir düğüm sanmak. İfadenin geçtiği yerde Deniz'in ne hissettiğine bak."},{"title":"Haritayı Çıkar","mode":"Bireysel · 15 dk","items":["Kişiler, yer ve zaman kutularını metindeki kelimelerle doldur.","Olayın başlangıcını, düğüm noktasını ve çözümünü birer cümleyle yaz.","Deniz'in duygusunun öykünün başında, ortasında ve sonunda nasıl değiştiğini üç kelimeyle göster."],"warn":"Sık yapılan hata: Düğüm ile çözümü karıştırmak. Düğüm, olayın en gergin anıdır; çözüm ise gerginliğin nasıl sona erdiğidir."},{"title":"Kendine Bağla","mode":"Bireysel · 5 dk","items":["Deniz'in yerinde olsan, kıskançlık duygusunu fark ettiğinde ne yapardın? İki cümle yaz.","Haritanı dijital portfolyona ekle; kişisel bir anı yazıyorsan yalnızca paylaşmak istediğin kadarını yaz."]}],"checklist":["Öyküyü iki kez okudum.","Bilmediğim ifadelerin anlamını metindeki ipuçlarından tahmin ettim.","Kişi, yer ve zaman kutularını metinden kanıtla doldurdum.","Düğüm ve çözümü birbirinden ayırdım.","Ana duygunun öykü boyunca nasıl değiştiğini gösterdim.","Kendi deneyimimle bağlantı kurdum."],"rubric":[{"k":"Hikâye Unsurları","d":"Kişi, yer, zaman ve olay örgüsünü doğru belirleme","l4":"Tüm unsurlar doğru ve metinden kanıtlı","l3":"Unsurlar doğru, bir kanıt eksik","l2":"Düğüm-çözüm karışık ya da bir unsur eksik","l1":"Unsurların çoğu yanlış ya da boş"},{"k":"Anlam Tahmini","d":"Bağlamdan söz varlığı unsurlarının anlamını çıkarma","l4":"Üç ifadenin anlamı gerekçeli ve doğru tahmin edildi","l3":"İki ifade gerekçeli doğru","l2":"Tahminler var ama gerekçe yok","l1":"Tahmin yapılmadı ya da gerçek anlam verildi"},{"k":"Duygu Takibi","d":"Ana duygunun öykü içindeki değişimini izleme","l4":"Başlangıç-orta-son duyguları ve değişimin nedeni açık","l3":"Değişim gösterildi, neden kısmen açık","l2":"Tek bir duygu yazıldı","l1":"Duygu belirtilmedi"},{"k":"Kişisel Bağlantı","d":"Öyküyü kendi yaşantısıyla ilişkilendirme","l4":"Saygılı, somut ve öyküyle tutarlı bağlantı","l3":"Bağlantı var ama genel","l2":"Bağlantı öyküyle ilgisiz","l1":"Bağlantı yok"}],"navi":["Deniz'in duygusu değişmeden hemen önce öyküde ne oldu?","'Düğüm' kelimesi öyküde iki kez geçiyor; ikisi aynı şeyi mi anlatıyor, yoksa ikinci kullanım ilkine bir cevap mı?"],"diff":{"destek":"Kutuların yanında öyküden alınmış seçenek cümleler verilir; öğrenci doğru cümleyi doğru kutuya eşleştirir.","ileri":"Öyküyü Ela'nın gözünden 5–6 cümleyle yeniden yazar ve iki anlatımda hikâye unsurlarından hangilerinin değiştiğini gösterir."},"misconception":"Öğrenciler olay örgüsündeki 'düğüm'ü öykünün ortasındaki herhangi bir olay sanır; oysa düğüm, çatışmanın en yoğun olduğu andır."},{"id":"tur-5-03","course":"TUR","grade":5,"themeNo":4,"themeName":"Geleneklerimiz","title":"Dedemin Ses Kaydı","subtitle":"Dinlediğini sınıflandırma ve yorumlama — sözlü kültür","kazanim":["Dinlediğindeki/izlediğindeki unsurları sınıflandırabilme","Dinlediğini/izlediğini yorumlayabilme"],"skills21":["Kültürel Farkındalık","Eleştirel Düşünme","İş Birliği","Sistematik Düşünme"],"digital":["Dijital Kültür Okuryazarlığı","Dijital Veri Toplama"],"duration":"80 dk (2 ders)","format":"İkili","tools":["NavigAItor ses oynatıcı","kulaklık","Kâğıt-kalem","çevrim içi anket formu"],"scenario":"Belediyenin kültür merkezi 'Mahallenin Hafızası' adlı bir sesli arşiv kuruyor. Arşive gelen ilk kayıtta yaşlı bir dede, çocukluğunda bayramlarda, düğünlerde ve uzun kış gecelerinde neler yapıldığını anlatıyor. Arşiv görevlisi olarak senden bu anlatıyı dinleyip içindeki gelenekleri doğru raflara yerleştirmen isteniyor. Peki bu geleneklerden hangileri bugün hâlâ yaşıyor, hangileri değişti?","visual":{"type":"sort","params":{"bins":["Bayram","Düğün","Kış gecesi"],"items":[{"t":"el öpüp harçlık almak","b":0},{"t":"kapı kapı şeker toplamak","b":0},{"t":"kına gecesinde türkü söylemek","b":1},{"t":"gelin alma alayı","b":1},{"t":"davul zurnayla halay","b":1},{"t":"sobanın başında masal anlatmak","b":2},{"t":"bilmece sormak","b":2},{"t":"kestane közlemek","b":2}]},"caption":"Öğrenci kayıtta duyduğu gelenekleri sürükleyip ait oldukları rafa bırakır."},"steps":[{"title":"Dinlemeye Hazırlan","mode":"İkili · 10 dk","items":["Kaydın başlığını oku: 'Bizim Zamanımızda'. Arkadaşınla bu kayıtta hangi geleneklerin anlatılabileceğini tahmin edin.","Bir not tablosu hazırlayın: 'Ne yapılırdı?', 'Ne zaman?', 'Kimler katılırdı?'"]},{"title":"Dinle ve Not Al","mode":"Bireysel · 20 dk","items":["Kaydı bir kez durdurmadan dinle; yalnızca konuyu yakala.","İkinci dinleyişte her geleneği bir anahtar kelimeyle not al.","Bilmediğin kelimeleri (ör. kına, alay, köz) yanına soru işaretiyle yaz; anlamını konuşmanın gidişinden tahmin et."],"warn":"Sık yapılan hata: Her cümleyi kelimesi kelimesine yazmaya çalışmak. Anahtar kelime yaz, dinlemeyi kaçırma."},{"title":"Raflara Yerleştir","mode":"İkili · 15 dk","items":["Notlarındaki gelenekleri 'Bayram', 'Düğün' ve 'Kış gecesi' raflarına yerleştir.","Arkadaşınla sınıflandırmalarınızı karşılaştırın; farklı rafa koyduğunuz ögeyi neden oraya koyduğunuzu açıklayın.","Hiçbir rafa uymayan bir gelenek duyduysanız yeni bir raf adı önerin."],"warn":"Sık yapılan hata: Bir ögeyi yalnızca kelimesine bakarak sınıflandırmak. 'Türkü' her yerde söylenebilir; dedenin onu hangi olay içinde anlattığına dikkat et."},{"title":"Dün ve Bugün","mode":"İkili · 20 dk","items":["Sınıfınızda 5 soruluk kısa bir çevrim içi anket yapın: 'Bu geleneği ailende hâlâ yaşıyor musunuz?'","Anket sonuçlarına göre en çok yaşayan ve en az yaşayan geleneği belirleyin.","Dedenin anlattıklarıyla anket sonucunu karşılaştırarak 'Bence ... geleneği değişmiş, çünkü ...' kalıbıyla iki yorum cümlesi yazın."]},{"title":"Arşiv Notu","mode":"Bireysel · 15 dk","items":["Arşiv için 4–5 cümlelik bir tanıtım notu yaz: Kayıtta ne anlatılıyor, hangi gruplar var, senin yorumun ne?","Notunu sesli okuyup NavigAItor'a kaydet."]}],"checklist":["Dinlemeden önce içerik hakkında tahminde bulundum.","Kaydı en az iki kez dinledim ve anahtar kelimelerle not aldım.","Duyduğum gelenekleri gerekçesiyle sınıflandırdım.","Arkadaşımla sınıflandırmalarımızı karşılaştırdım.","Anket sonuçlarını kullanarak geçmişle bugünü karşılaştırdım.","Yorumumu 'çünkü' ile gerekçelendirdim."],"rubric":[{"k":"Dinleme ve Not Alma","d":"Kayıttaki ana bilgileri anahtar kelimelerle yakalama","l4":"Tüm gelenekler kısa ve doğru notlarla yakalandı","l3":"Geleneklerin çoğu not edildi","l2":"Notlar eksik ya da cümle cümle kopyalanmış","l1":"Not alınmadı"},{"k":"Sınıflandırma","d":"Ögeleri ortak özelliğe göre doğru gruplama","l4":"Tüm ögeler doğru ve gerekçeli","l3":"Bir öge yanlış, gerekçeler var","l2":"Birkaç öge yanlış, gerekçe yok","l1":"Gruplama rastgele"},{"k":"Yorumlama","d":"Dinlediğine kendi bakışıyla anlam katma","l4":"Kayıt ve anket verisini birleştiren gerekçeli yorum","l3":"Gerekçeli yorum, tek kaynağa dayalı","l2":"Yorum var, gerekçe yok","l1":"Yalnızca özet var, yorum yok"},{"k":"Veri Kullanımı","d":"Anketten elde edilen sonucu yorumda kullanma","l4":"Sonuç doğru okunup yorumu destekliyor","l3":"Sonuç doğru, yoruma kısmen bağlı","l2":"Sonuç yanlış okunmuş","l1":"Anket yapılmadı"}],"navi":["Bir geleneği hangi rafa koyacağına karar verirken dede onu anlatmadan hemen önce ne söylüyordu?","Anket sonuçlarında bir gelenek az çıktıysa, bu o geleneğin yok olduğunu mu gösterir, yoksa başka bir açıklaması olabilir mi?"],"diff":{"destek":"Kayıt cümle cümle durdurularak dinletilir; öğrenciye ögelerin yazılı listesi verilir, yalnızca sınıflandırma ve tek bir yorum cümlesi istenir.","ileri":"Kendi ailesinden bir büyüğüyle 3 soruluk kısa bir sesli görüşme yapar ve yeni ögeleri aynı raflara ekler."},"misconception":"Dinlenen metindeki unsurları sınıflandırırken bağlam yerine yalnızca kelimenin kendisine bakmak, yanlış gruplamaya yol açar."},{"id":"tur-5-04","course":"TUR","grade":5,"themeNo":5,"themeName":"İletişim Ve Sosyal İlişkiler","title":"Mesaj Yanlış Anlaşıldı!","subtitle":"Soru sorarak iletişimi sürdürme ve açık-örtük ifadeler","kazanim":["İletişimi sürdürmek amacıyla soru sorabilme","Konuşmasında açık ve örtük ifadeleri kullanabilme"],"skills21":["Empati","Etkili İletişim","Problem Çözme","Dijital Vatandaşlık"],"digital":["Dijital İletişim","Dijital Etik ve Güvenlik"],"duration":"40 dk","format":"İkili","tools":["NavigAItor sohbet ekranı","Kâğıt-kalem","zamanlayıcı"],"scenario":"Sınıfın proje grubunda Ece, sabaha karşı grup mesajına 'Herkes kendi işini yapsa iyi olurdu.' yazmış. Ali bu mesajın kendisine söylendiğini düşünüp alınmış ve gruptan çıkmak istiyor. Grup başkanı olarak yarın teneffüste ikisiyle yüz yüze konuşacaksın. Sorular sorarak gerçekte ne kastedildiğini nasıl ortaya çıkarırsın?","visual":{"type":"chat","params":{"lines":[{"who":"Ece","t":"Afiş yarın teslim. Herkes kendi işini yapsa iyi olurdu."},{"who":"Ali","t":"Bu bana mı? Ben resimleri dün gönderdim zaten."},{"who":"Ece","t":"..."},{"who":"Ali","t":"Tamam, o zaman ben yokum."}]},"caption":"Öğrenci mesajlardaki örtük anlamı taşıyan ifadeleri işaretler ve yanlış anlaşılmanın başladığı balonu seçer."},"steps":[{"title":"Mesajları Çözümle","mode":"Bireysel · 8 dk","items":["Sohbetteki her mesaj için iki şey yaz: Açıkça söylenen ne? Söylenmeden ima edilen ne olabilir?","Ece'nin mesajının en az iki farklı anlama gelebileceğini göster.","Yalnızca '...' yazmanın karşı tarafta nasıl bir duygu uyandırabileceğini not et."],"warn":"Sık yapılan hata: Mesajın tek bir anlamı olduğunu düşünmek. Yazılı mesajda ses tonu ve yüz ifadesi yoktur; aynı cümle farklı okunabilir."},{"title":"Soru Bankası Hazırla","mode":"İkili · 10 dk","items":["Ece'ye ve Ali'ye sorulacak en az 3'er soru yazın.","Sorularınızı ikiye ayırın: 'Evet/Hayır' ile biten kapalı sorular ve 'Ne, nasıl, neden' ile başlayan açık uçlu sorular.","Suçlayıcı soruları ('Neden böyle yazdın?') merak eden sorulara ('Bunu yazarken ne düşünüyordun?') dönüştürün."],"warn":"Sık yapılan hata: Kapalı sorularla konuşmayı tıkamak. 'Kızgın mısın?' yerine 'Mesajı okuyunca neler hissettin?' diye sorarsan konuşma devam eder."},{"title":"Canlandırma","mode":"İkili · 15 dk","items":["Biri grup başkanı, diğeri sırayla Ece ve Ali olsun; her canlandırma 3 dakika sürsün.","Grup başkanı en az 3 soru sorarak konuşmayı sürdürsün ve gerçek niyeti ortaya çıkarsın.","Konuşmanın sonunda grup başkanı, gruba atılacak açık ve kırıcı olmayan yeni bir mesajı sesli söylesin.","Rolleri değiştirin."]},{"title":"Grup Mesajı Kuralı","mode":"Bireysel · 7 dk","items":["Sınıf grubunun mesaj kurallarına eklemek üzere 2 kural yaz (ör. kişisel bilgi paylaşımı, saat, ton).","Kendi canlandırmanda en işe yarayan soruyu yaz ve neden işe yaradığını açıkla."]}],"checklist":["Mesajlardaki açık ve örtük anlamları ayırdım.","Açık uçlu ve kapalı sorular hazırladım.","Suçlayıcı soruları merak eden sorulara dönüştürdüm.","Canlandırmada en az 3 soru sorarak konuşmayı sürdürdüm.","Gruba açık ve kırıcı olmayan bir mesaj önerdim.","Çevrim içi iletişim için iki kural yazdım."],"rubric":[{"k":"Soru Sorma","d":"Konuşmayı sürdüren, açık uçlu ve saygılı sorular","l4":"Soruların çoğu açık uçlu, konuşmayı derinleştiriyor","l3":"Açık ve kapalı sorular dengeli","l2":"Sorular çoğunlukla kapalı, konuşma kesiliyor","l1":"Soru sorulmadı ya da sorular suçlayıcı"},{"k":"Açık-Örtük Anlam","d":"İma edilen anlamı fark etme ve açık ifadeye dönüştürme","l4":"Örtük anlamlar doğru bulundu ve açık bir mesajla ifade edildi","l3":"Örtük anlam bulundu, yeni mesaj kısmen açık","l2":"Yalnızca açık anlam fark edildi","l1":"Anlam çözümlemesi yapılmadı"},{"k":"Empatik Tutum","d":"Her iki tarafın duygusunu dikkate alma","l4":"İki tarafın duygusu adlandırıldı ve yansıtıldı","l3":"Bir tarafın duygusu dikkate alındı","l2":"Duygular yüzeysel geçildi","l1":"Taraf tutuldu, duygu yok sayıldı"},{"k":"Dijital İletişim Kuralları","d":"Çevrim içi yazışma için uygulanabilir kurallar","l4":"İki kural somut, uygulanabilir ve gerekçeli","l3":"Kurallar somut, gerekçe eksik","l2":"Kurallar genel ('kibar ol')","l1":"Kural yazılmadı"}],"navi":["Ece mesajı yazarken aklında kim olabilirdi? Bunu ondan öğrenmenin en kısa yolu ne?","Sorduğun soru 'evet' ya da 'hayır' diye cevaplanırsa konuşma nereye gider?"],"diff":{"destek":"Hazır soru kalıpları kartları ('Bunu söylerken ... mı demek istedin?', 'Sence ...?') kullanılır; canlandırma 2 soruyla sınırlanır.","ileri":"Aynı yanlış anlaşılmanın yüz yüze konuşmada neden daha az yaşanacağını açıklayan 1 dakikalık hazırlıksız bir konuşma yapar."},"misconception":"Öğrenciler yazılı mesajdaki ima edilen anlamın herkes için aynı olduğunu sanır; oysa örtük anlam okuyanın duygusuna göre değişebilir."},{"id":"tur-5-05","course":"TUR","grade":5,"themeNo":6,"themeName":"Sağlıklı Yaşıyorum","title":"Mucize Kahvaltı mı?","subtitle":"Bilgilendirici metinden önemli bilgiyi ayıklama ve sözlü tartışma","kazanim":["Bilgilendirici metinde metin yapılarından hareketle önemli bilgileri belirlemeye yönelik çözümleme yapabilme","Sözlü olarak tartışabilme"],"skills21":["Eleştirel Düşünme","Bilgi Okuryazarlığı","Sorumlu Karar Verme","Analitik Düşünme"],"digital":["Dijital Sağlık Okuryazarlığı","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor okuma ekranı","Kâğıt-kalem","fosforlu kalem"],"scenario":"Sınıfının paylaşım panosuna biri, 'Bu kahvaltıyı yapan çocuklar sınavlarda iki kat başarılı!' başlıklı bir haber kartı asmış. Sınıf başkanı, kantinde kahvaltı menüsünün bu habere göre değiştirilmesini önermek istiyor. Sağlık kulübü üyesi olarak önce metni okuyup içindeki gerçek bilgiyle abartıyı ayırman, sonra sınıf tartışmasında görüşünü savunman gerekiyor. Bir metindeki önemli bilgiyi başlığın gürültüsünden nasıl ayırırsın?","visual":{"type":"news","params":{"headline":"Bu Kahvaltıyı Yapan Çocuklar Sınavlarda İki Kat Başarılı!","lead":"Bir okulda 20 öğrenciyle yapılan küçük bir gözlemde, düzenli kahvaltı edenlerin derse daha kolay odaklandığını söylediği belirtildi. Haberde önerilen tek bir 'mucize' tarifin ise bu gözlemde hiç denenmediği anlaşılıyor.","tags":["sağlık","beslenme","doğrula"]},"caption":"Öğrenci haber kartında başlık, giriş, kanıt ve sonuç bölümlerini işaretler; abartılı ifadeleri kırmızıyla boyar."},"steps":[{"title":"Metnin İskeletini Bul","mode":"Bireysel · 15 dk","items":["Haberi oku ve bölümlerini işaretle: başlık, giriş (ana fikir), kanıt, sonuç.","Her bölümün kaç cümle olduğunu ve neyi anlattığını kenara yaz.","Metinde sayı geçen her yeri fosforlu kalemle işaretle (öğrenci sayısı, süre, oran)."]},{"title":"Önemli Bilgi mi, Süs mü?","mode":"Bireysel · 20 dk","items":["İki sütunlu bir tablo yap: 'Kanıta dayanan bilgi' ve 'Abartı ya da kanıtsız iddia'.","'İki kat başarılı', 'mucize' gibi ifadeleri metindeki kanıtla karşılaştır; kanıt bu iddiayı gerçekten destekliyor mu?","Metnin önemli bilgisini başlıktan bağımsız olarak tek bir cümleyle yaz."],"warn":"Sık yapılan hata: Başlığı metnin özeti sanmak. Başlık dikkat çekmek için yazılır; önemli bilgi çoğunlukla kanıt bölümündedir."},{"title":"Tartışmaya Hazırlan","mode":"Grup · 15 dk","items":["Grup olarak bir tarafı savunun: 'Kantin menüsü bu habere göre değişmeli' ya da 'Değişmemeli, önce güvenilir bilgi bulunmalı'.","Görüşünüzü destekleyen 2 gerekçe ve karşı taraftan gelebilecek 1 itiraz yazın.","Güvenilir sağlık bilgisinin nereden alınabileceğini konuşun (ör. Sağlık Bakanlığının genel sayfaları, okul hemşiresi)."]},{"title":"Sınıf Tartışması","mode":"Grup · 25 dk","items":["Her grup 2 dakika görüşünü sunsun, karşı grup 1 dakika soru sorsun.","Konuşurken 'Bence ..., çünkü metinde ... yazıyor.' kalıbını kullan.","Söz almadan önce el kaldır; karşı görüşü özetlemeden itiraz etme."],"warn":"Sık yapılan hata: Tartışmayı kişiselleştirmek ('Sen hep böyle diyorsun!'). Kişiyi değil, görüşü ve kanıtı tartış."},{"title":"Karar ve Öz Değerlendirme","mode":"Bireysel · 5 dk","items":["Tartışmadan sonra fikrin değişti mi? Bir cümleyle yaz.","Okurken ve tartışırken en çok zorlandığın anı not et."]}],"checklist":["Haber metnini başlık, giriş, kanıt ve sonuç bölümlerine ayırdım.","Metindeki sayısal bilgileri işaretledim.","Kanıta dayanan bilgiyle abartıyı ayırdım.","Metnin önemli bilgisini tek cümleyle yazdım.","Tartışmada görüşümü metinden kanıtla savundum.","Karşı görüşü saygıyla dinleyip özetledim."],"rubric":[{"k":"Metin Yapısı","d":"Bilgilendirici metnin bölümlerini doğru ayırma","l4":"Dört bölüm doğru ve gerekçeyle ayrıldı","l3":"Bölümler doğru, bir gerekçe eksik","l2":"Giriş ile kanıt karıştırıldı","l1":"Bölümleme yapılmadı"},{"k":"Önemli Bilgiyi Belirleme","d":"Kanıta dayalı bilgiyi abartıdan ayırma","l4":"Tüm abartılar fark edildi, önemli bilgi doğru ve kısa yazıldı","l3":"Abartıların çoğu fark edildi","l2":"Başlık önemli bilgi sanıldı","l1":"Ayrım yapılmadı"},{"k":"Tartışmada Gerekçe","d":"Görüşü metinden kanıtla destekleme","l4":"İki gerekçe ve karşı itiraza yanıt var","l3":"İki gerekçe var","l2":"Tek gerekçe ya da kanıtsız görüş","l1":"Görüş belirtilmedi"},{"k":"Tartışma Kuralları","d":"Söz alma, dinleme ve saygılı itiraz","l4":"Kurallara tam uyuldu, karşı görüş özetlendi","l3":"Kurallara genelde uyuldu","l2":"Söz kesildi ya da kişiselleştirildi","l1":"Kurallara uyulmadı"}],"navi":["Başlıktaki 'iki kat' ifadesini destekleyen bir sayı metnin içinde var mı?","20 öğrenciyle yapılan bir gözlem, bütün okulların kantin menüsü hakkında ne kadar şey söyleyebilir?"],"diff":{"destek":"Metnin bölümleri renkli kutularla önceden ayrılmış olarak verilir; öğrenci yalnızca abartılı ifadeleri bulur ve tartışmada tek gerekçe sunar.","ileri":"Aynı konuda güvenilir bir kaynaktan kısa bir bilgi bulur ve iki metni 'kanıt gücü' açısından karşılaştıran 4–5 cümlelik bir not yazar."},"misconception":"Öğrenciler bilgilendirici metnin başlığını metnin en önemli bilgisi sanar; oysa başlık abartılı olabilir ve asıl bilgi kanıt bölümündedir."},{"id":"tur-6-06","course":"TUR","grade":6,"themeNo":1,"themeName":"Dilimizin Zenginliği","title":"Deyim Dedektifleri","subtitle":"Bağlamdan anlam tahmini ve deyimlerle yazıyı zenginleştirme","kazanim":["Metinde geçen anlamını bilmediği söz varlığı unsurlarının anlamını tahmin edebilme","Yazısını zenginleştirecek biçimde söz varlığını kullanabilme"],"skills21":["Kültürel Farkındalık","Yaratıcılık","Bilgi Okuryazarlığı","İletişim"],"digital":["Dijital Sözlük Kullanımı","Dijital İçerik Üretimi"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["çevrim içi resmî sözlük","NavigAItor Stüdyo","Kâğıt-kalem"],"scenario":"Okul gazetesinin 'Dilimizin Hazineleri' köşesi bu ay deyimlere ayrıldı. Editör, deyimlerin anlamlarını sözlükten kopyalamak yerine öğrencilerin onları bir hikâyenin içinden 'dedektif gibi' çözmesini istiyor. Elinde deyimlerle dolu kısa bir mektup var; ipuçlarını takip edip anlamları bulacak, sonra kendi yazında bu deyimleri yerinde kullanacaksın. Bir kelime grubunun anlamını sözlüğe bakmadan nasıl çözebilirsin?","visual":{"type":"cards","params":{"items":[{"w":"göz boyamak","tr":"aldatıcı bir görüntüyle gerçeği gizlemek","ic":"🎨"},{"w":"kulak misafiri olmak","tr":"başkalarının konuşmasını istemeden duymak","ic":"👂"},{"w":"eli kulağında","tr":"çok yakında olacak","ic":"⏰"},{"w":"dört gözle beklemek","tr":"çok istekle beklemek","ic":"👀"},{"w":"burnu havada","tr":"kendini beğenmiş","ic":"👃"},{"w":"ağzı kulaklarına varmak","tr":"çok sevinmek","ic":"😁"}]},"caption":"Öğrenci önce kartın ön yüzündeki deyimin anlamını tahmin eder, sonra kartı çevirerek tahminini kontrol eder."},"steps":[{"title":"Mektubu Oku","mode":"Bireysel · 15 dk","items":["Mektup: 'Sevgili Arda, şenlik eli kulağında; herkes dört gözle bekliyor. Dün öğretmenler odasının önünden geçerken kulak misafiri oldum: Bu yıl yarışmada ödül varmış! Sınıftaki bazıları şimdiden burnu havada dolaşıyor ama bence afişleri parlak renklerle göz boyamak yetmez, fikir de lazım. Kazanırsak ağzım kulaklarıma varacak!'","Mektuptaki deyimlerin altını çiz.","Her deyimin hemen önündeki ve arkasındaki kelimeleri ipucu olarak daire içine al."]},{"title":"İpucundan Anlama","mode":"Bireysel · 20 dk","items":["Her deyim için bir 'dedektif dosyası' doldur: İpucu → Tahminim → Kartın arkası → Tuttu mu?","Tahmininin tutmadığı deyimlerde hangi ipucunu kaçırdığını yaz.","Bir deyimi çevrim içi resmî sözlükte ara; sözlükteki örnek cümleyi mektuptaki kullanımla karşılaştır."],"warn":"Sık yapılan hata: Deyimi kelimelerin gerçek anlamıyla okumak ('eli kulağında' = eli kulağına değiyor). Deyimde kelimeler birlikte yeni bir anlam kazanır."},{"title":"Deyimli Yazı","mode":"Bireysel · 25 dk","items":["Okul gazetesi için 8–10 cümlelik bir şenlik haberi ya da kısa bir mektup yaz.","Kartlardaki deyimlerden en az 4 tanesini anlamına uygun yerde kullan.","Kullandığın deyimlerin altını çiz; deyimi çıkarıp yerine düz bir ifade koyunca cümlenin nasıl değiştiğini bir örnekle göster."],"warn":"Sık yapılan hata: Deyimleri anlamı oturmayan cümlelere zorla yerleştirmek. Her deyim, cümledeki duruma gerçekten uymalı."},{"title":"Dijital Deyim Panosu","mode":"Grup · 20 dk","items":["Grupça mektupta olmayan 4 yeni deyim bulun ve sözlükten anlamlarını doğrulayın.","NavigAItor Stüdyo'da her deyim için bir kart hazırlayın: deyim, anlam, kendi örnek cümleniz ve uygun bir emoji.","Kartları sınıf panosunda paylaşın; başka grubun kartlarından birinin anlamını tahmin etmeye çalışın."]}],"checklist":["Mektuptaki deyimleri buldum ve ipuçlarını işaretledim.","Her deyimin anlamını önce kendim tahmin ettim.","Tahminimi kart ve sözlükle kontrol ettim.","Yazımda en az 4 deyimi anlamına uygun kullandım.","Deyimli ve deyimsiz cümleyi karşılaştırdım.","Grubumla dijital panoya yeni deyim kartları ekledim."],"rubric":[{"k":"Bağlamdan Tahmin","d":"Çevre kelimelerden deyimin anlamını çıkarma","l4":"Tüm tahminler ipucuyla gerekçelendirildi, çoğu doğru","l3":"Tahminlerin yarısından fazlası doğru ve gerekçeli","l2":"Tahminler gerekçesiz","l1":"Tahmin yapılmadan sözlüğe bakıldı"},{"k":"Deyim Kullanımı","d":"Deyimleri yazıda anlamına uygun kullanma","l4":"4+ deyim doğal ve doğru yerde","l3":"4 deyim var, biri zorlama","l2":"2–3 deyim, bazıları yanlış bağlamda","l1":"Deyim kullanılmadı ya da hepsi yanlış"},{"k":"Yazının Bütünlüğü","d":"Metnin konu ve akış bakımından tutarlılığı","l4":"Konu tutarlı, akış doğal, yazım hatası yok denecek kadar az","l3":"Akış iyi, birkaç yazım hatası","l2":"Deyimler için konu dağılmış","l1":"Cümleler birbirinden kopuk"},{"k":"Dijital Sözlük ve Pano","d":"Resmî sözlüğü kullanma ve içerik üretme","l4":"Deyimler sözlükle doğrulandı, kartlar özgün örnekli","l3":"Kartlar doğru, örnekler sözlükten alınmış","l2":"Kartlarda anlam hatası var","l1":"Kart hazırlanmadı"}],"navi":["'Şenlik eli kulağında' cümlesinden hemen sonra 'herkes dört gözle bekliyor' deniyor; bu ikinci cümle birinci hakkında sana ne fısıldıyor?","Deyimi çıkarıp yerine düz bir kelime koyduğunda cümlenin rengi nasıl değişiyor?"],"diff":{"destek":"Her deyim için iki seçenekli anlam kartı verilir; öğrenci ipucuna göre seçim yapar ve yazısında 2 deyim kullanır.","ileri":"Aynı anlama gelen bir atasözü ile bir deyimi karşılaştırır ve ikisini de kullanan kısa bir diyalog yazar."},"misconception":"Öğrenciler deyimleri kelimelerin gerçek anlamlarının toplamı olarak yorumlar; oysa deyim, kelimelerin birlikte kazandığı mecaz bir anlam taşır."},{"id":"tur-6-07","course":"TUR","grade":6,"themeNo":2,"themeName":"Bağımsızlık Yolu","title":"Karlı Yolda Bir Kağnı","subtitle":"Sesli anlatıyı dinleme, görseli okuma ve üst düzey çıkarım","kazanim":["Görselle iletilen anlamı belirleyebilme","Dinlediğinin/izlediğinin derin anlamını belirlemeye yönelik üst düzey çıkarımlar yapabilme"],"skills21":["Eleştirel Düşünme","Vatanseverlik","Sistematik Düşünme","Medya Okuryazarlığı"],"digital":["Dijital Tarih Araştırması","Dijital Etik"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor ses oynatıcı","kulaklık","dijital harita uygulaması","Kâğıt-kalem"],"scenario":"Okul radyosu, Millî Mücadele yıllarında cepheye cephane taşıyan köylüleri anlatan kurgusal bir sesli öykü yayımlayacak. Öyküde adı Zehra olan bir köylü kadın, karlı bir gecede kağnısıyla limandan iç bölgelere doğru yol alıyor; anlatıcı ise hiçbir yerde 'bu yolculuk neden önemliydi' demiyor. Yayın ekibi, dinleyicilere sunulacak tanıtım notunu senden bekliyor. Bir anlatıcı bir şeyi açıkça söylemediğinde, sen onu neye bakarak anlayabilirsin?","visual":{"type":"map","params":{"region":"turkiye","pins":[{"label":"İnebolu (liman)","x":41,"y":4},{"label":"Kastamonu","x":41,"y":11},{"label":"Ankara","x":36,"y":34}]},"caption":"Öğrenci haritadaki iğneleri birleştirerek kağnının yolunu çizer ve yolun uzunluğu ile arazinin anlatıya ne kattığını düşünür."},"steps":[{"title":"Görseli Oku","mode":"Bireysel · 10 dk","items":["Haritadaki üç noktayı ve aralarındaki yolu incele; yolun dağlık mı düz mü olduğunu dijital harita uygulamasındaki arazi görünümünden kontrol et.","Görselin sana söylediği üç bilgiyi yaz (ör. yolun yönü, uzunluğu, deniz-kara ilişkisi).","Bu bilgilerden yola çıkarak dinleyeceğin anlatıda nasıl zorluklar olabileceğini tahmin et."]},{"title":"Dinle ve İpuçlarını Topla","mode":"Bireysel · 20 dk","items":["Sesli öyküyü bir kez baştan sona dinle.","İkinci dinleyişte ipucu tablosu doldur: 'Duyduğum ses/söz' → 'Bana düşündürdüğü'. (ör. tekerlek gıcırtısı, çocuğun öksürüğü, 'bir sandık daha sığar mı?' sorusu)","Anlatıcının açıkça söylemediği ama ses efektleri ve konuşmalarla hissettirdiği en az 3 şey yaz."],"warn":"Sık yapılan hata: Yalnızca anlatıcının cümlelerini dinlemek. Ses efektleri, duraklamalar ve kahramanın ses tonu da anlam taşır."},{"title":"Derin Anlamı Çıkar","mode":"Grup · 25 dk","items":["Grupça şu soruları tartışın: Zehra neden kendi çocuğunu üşümesin diye kağnının üzerindeki örtüyle değil, sandıkları örtüyle örtüyor olabilir? Bu seçim neyi gösterir?","Her çıkarımınızı en az iki ipucuna dayandırın: 'Bunu düşünüyoruz, çünkü hem ... hem de ... duyduk.'","Haritadaki yolun uzunluğu ve arazisi, çıkarımlarınızı nasıl güçlendiriyor? Bir cümleyle bağlayın."],"warn":"Sık yapılan hata: Kanıtsız büyük yargılar ('Herkes çok kahramandı.'). Üst düzey çıkarım, metindeki ipuçlarının birleşmesinden doğar; her yargıya kanıt göster."},{"title":"Yayın Tanıtım Notu","mode":"Bireysel · 20 dk","items":["Radyo için 5–6 cümlelik bir tanıtım notu yaz: Öyküde ne anlatılıyor, dinleyici neye kulak vermeli, öykünün söylemeden söylediği şey ne?","Notta öykünün kurgusal olduğunu, ancak gerçek bir tarihî döneme dayandığını belirt.","Kullandığın tarihî bilgiyi güvenilir bir kaynaktan (ör. resmî müze ya da kurum sayfası) doğrula ve kaynağını not et."]},{"title":"Öz Yansıtma","mode":"Bireysel · 5 dk","items":["İkinci dinleyişte ilkinde fark etmediğin neyi fark ettin?","Bir sonraki dinleme çalışmanda hangi stratejiyi yeniden kullanacaksın?"]}],"checklist":["Haritadan en az üç bilgi çıkardım ve dinleme öncesi tahmin yaptım.","Anlatıyı en az iki kez dinledim.","Ses efektlerinden ve konuşmalardan ipucu topladım.","Her çıkarımımı en az iki ipucuna dayandırdım.","Tanıtım notumda kurgu ile tarihî gerçeği ayırdım.","Tarihî bilgiyi güvenilir bir kaynaktan doğruladım."],"rubric":[{"k":"Görseli Anlamlandırma","d":"Haritadan bilgi çıkarıp anlatıyla ilişkilendirme","l4":"Görselden çıkan bilgiler çıkarımlara açıkça bağlandı","l3":"Bilgiler doğru, bağlantı kısmen","l2":"Görsel yalnızca betimlendi","l1":"Görsel kullanılmadı"},{"k":"Üst Düzey Çıkarım","d":"Açıkça söylenmeyeni ipuçlarını birleştirerek bulma","l4":"3+ çıkarım, her biri iki ipucuyla desteklendi","l3":"Çıkarımlar doğru, bazıları tek ipuçlu","l2":"Çıkarım yerine yüzey bilgi tekrarı","l1":"Çıkarım yok"},{"k":"Dinleme Stratejisi","d":"Not alma ve tekrar dinlemeyi amaçlı kullanma","l4":"İpucu tablosu ayrıntılı, ses ögeleri dahil","l3":"Tablo dolu, ses ögeleri az","l2":"Notlar dağınık","l1":"Not alınmadı"},{"k":"Doğru Bilgi Etiği","d":"Kurgu-gerçek ayrımı ve kaynak doğrulama","l4":"Ayrım açık, kaynak güvenilir ve belirtilmiş","l3":"Ayrım açık, kaynak belirsiz","l2":"Kurgu gerçek gibi sunuldu","l1":"Kaynak ve ayrım yok"}],"navi":["Zehra'nın yolculuğu boyunca anlatıda en sık tekrar eden ses hangisiydi? Bu tekrar sana ne hissettirdi?","Haritada yolun bir ucu denizde, diğer ucu karanın ortasında; sandıkların neden denizden geldiğini düşünüyorsun?"],"diff":{"destek":"Anlatı üç bölüme ayrılarak dinletilir; her bölümden sonra tek bir yönlendirici soru sorulur ve öğrenci bir çıkarım yazar.","ileri":"Öykünün son sahnesini Zehra'nın gözünden 6–8 cümlelik bir iç ses olarak yazar ve yazısındaki örtük anlamları bir arkadaşına buldurur."},"misconception":"Öğrenciler derin anlamın metinde bir yerde açıkça yazdığını sanıp onu arar; oysa üst düzey çıkarım birden fazla ipucunu birleştirerek yapılır."},{"id":"tur-6-08","course":"TUR","grade":6,"themeNo":3,"themeName":"Farklı Dünyalar","title":"İki Sofra, Bir Sabah","subtitle":"Karşılaştırmalı bilgilendirici yazı","kazanim":["Yazısında karşılaştırma yapabilme","Yazısında düşünceyi geliştirme yollarını kullanabilme"],"skills21":["Kültürlerarası Yetkinlik","Açık Fikirlilik","Karşılaştırma","İş Birliği"],"digital":["Dijital Kültür Okuryazarlığı","Sanal Gezi"],"duration":"120 dk (3 ders)","format":"Bireysel + Grup","tools":["sanal müze ve gezi siteleri","NavigAItor Stüdyo","Kâğıt-kalem"],"scenario":"Okulunuza kardeş okul olarak bağlanan yurt dışındaki bir okulun öğrencileri, Türkiye'de sabahların nasıl başladığını merak ediyor. Senden kendi kahvaltı sofranı, seçtiğin başka bir ülkenin kahvaltı sofrasıyla karşılaştıran bir yazı istiyorlar. Yazın yalnızca 'onlar şunu yer, biz bunu yeriz' listesi olmamalı; benzerliklerin ve farklılıkların ardındaki nedenleri de göstermeli. İki sofrayı karşılaştırırken hangi ölçütleri seçersin?","visual":{"type":"organizer","params":{"kind":"venn","slots":["Bizim sofra","Ortak noktalar","Diğer ülkenin sofrası"]},"caption":"Öğrenci iki kahvaltı geleneğinin özelliklerini sürükleyerek Venn şemasının doğru bölgesine yerleştirir."},"steps":[{"title":"Araştır ve Seç","mode":"Bireysel · 25 dk","items":["Bir ülke seç ve o ülkenin kahvaltı geleneğini sanal gezi ya da güvenilir kültür sitelerinden araştır.","En az 3 karşılaştırma ölçütü belirle: yiyecekler, sofranın saati ve süresi, kimlerin bir arada olduğu, iklimin etkisi gibi.","Her ölçüt için iki ülkeden birer bilgi not et ve kaynağını yaz."]},{"title":"Venn Şemasını Doldur","mode":"İkili · 20 dk","items":["Notlarını Venn şemasına yerleştir.","Ortak noktalar bölümünü arkadaşınla tartış; gerçekten ortak mı, yoksa yalnızca benzer mi?","Her farklılığın yanına olası bir nedenini yaz (iklim, tarım ürünleri, çalışma saatleri vb.)."],"warn":"Sık yapılan hata: Yalnızca farklılıkları yazmak. Karşılaştırma, benzerlikleri de göstermeyi gerektirir."},{"title":"Yazıyı Planla ve Yaz","mode":"Bireysel · 40 dk","items":["Yazını 'ölçüt ölçüt' düzenle: Her paragraf bir ölçütü ele alsın ve iki ülkeyi o ölçütte karşılaştırsın.","Karşılaştırma ifadeleri kullan: 'buna karşın', 'benzer şekilde', '-den farklı olarak', 'her ikisinde de'.","Düşünceni geliştirmek için en az bir örnek, bir tanım ve bir sayısal bilgi kullan (ör. kahvaltı saati, sofradaki yiyecek sayısı).","Yazını farklı kültürlere saygılı bir sonuç cümlesiyle bitir."],"warn":"Sık yapılan hata: Önce bir ülkeyi baştan sona, sonra diğerini anlatmak. Bu durumda okur karşılaştırmayı kendisi yapmak zorunda kalır; her paragrafta iki ülkeyi yan yana getir."},{"title":"Akran Okuması ve Dijital Sunum","mode":"Grup · 30 dk","items":["Yazını grubundan biriyle değiştir; arkadaşın karşılaştırma ifadelerinin ve örneklerin altını çizsin.","Aldığın geri bildirime göre yazını düzelt.","NavigAItor Stüdyo'da yazının özetini 3 görsel ve kısa açıklamalarla kardeş okul için bir sayfaya dönüştür; kullandığın görsellerin kullanım izni olduğundan emin ol."]},{"title":"Öz Yansıtma","mode":"Bireysel · 5 dk","items":["Araştırma sırasında seni en çok şaşırtan bilgi neydi?","Yazma sürecinde en çok hangi adımda zorlandın, bir dahaki sefere neyi farklı yaparsın?"]}],"checklist":["En az 3 karşılaştırma ölçütü belirledim.","Bilgilerimi güvenilir kaynaklardan aldım ve kaynakları not ettim.","Hem benzerlikleri hem farklılıkları gösterdim.","Her paragrafta iki ülkeyi aynı ölçütte karşılaştırdım.","Örnek, tanım ve sayısal bilgiyle düşüncemi geliştirdim.","Görselleri kullanım iznine dikkat ederek seçtim."],"rubric":[{"k":"Karşılaştırma","d":"Ölçüte dayalı benzerlik ve farklılık gösterme","l4":"3+ ölçüt, benzerlik ve farklılık dengeli, nedenler açık","l3":"Ölçütler var, nedenler kısmen","l2":"Yalnızca farklılık listesi","l1":"Karşılaştırma yok, iki ayrı tanıtım var"},{"k":"Düşünceyi Geliştirme","d":"Örnek, tanım, sayısal veri gibi yolların kullanımı","l4":"Üç yol da yerinde ve etkili","l3":"İki yol kullanıldı","l2":"Tek yol, yüzeysel","l1":"Destekleyici ayrıntı yok"},{"k":"Yapı ve Bağlantı İfadeleri","d":"Paragraf düzeni ve karşılaştırma ifadeleri","l4":"Ölçüt ölçüt düzen ve çeşitli bağlantı ifadeleri","l3":"Düzen iyi, ifadeler tekrarlı","l2":"Ülke ülke anlatım, az ifade","l1":"Dağınık metin"},{"k":"Kültürel Saygı","d":"Farklılıkları yargılamadan aktarma","l4":"Dil tamamen saygılı, genellemelerden kaçınılmış","l3":"Saygılı, bir genelleme var","l2":"'Garip', 'tuhaf' gibi yargılayıcı ifadeler var","l1":"Küçümseyici dil"}],"navi":["Bir paragrafı okuyan biri, iki ülkeden hangisinin anlatıldığını her cümlede anlayabiliyor mu?","İki sofrada farklı yiyecekler olmasının ardında, o ülkenin coğrafyasıyla ilgili bir neden olabilir mi?"],"diff":{"destek":"Ülke ve ölçütler hazır verilir; öğrenci her ölçüt için tamamlanacak cümle kalıplarıyla ('Türkiye'de ..., buna karşın ...') 3 paragraf yazar.","ileri":"Üçüncü bir ülkeyi ekleyerek üçlü bir karşılaştırma tablosu hazırlar ve en çok benzeyen iki ülkeyi gerekçesiyle belirler."},"misconception":"Öğrenciler iki şeyi ayrı ayrı anlatmanın karşılaştırma olduğunu sanır; oysa karşılaştırma, aynı ölçütte yan yana değerlendirme gerektirir."},{"id":"tur-6-09","course":"TUR","grade":6,"themeNo":5,"themeName":"Bilim Ve Teknoloji","title":"2050'nin Okul Çantası","subtitle":"Tahmine dayalı sözlü sunum","kazanim":["Sözlü sunum yapabilme","Konuşmasında tahminlerinden yararlanabilme"],"skills21":["Eleştirel Düşünme","Merak","Yaratıcılık","Bilgi Okuryazarlığı"],"digital":["Dijital Araştırma","Dijital Modelleme / Tasarım"],"duration":"120 dk (3 ders)","format":"Grup","tools":["ücretsiz bir sunum aracı","NavigAItor Stüdyo","Kâğıt-kalem","zamanlayıcı"],"scenario":"Bölgedeki bilim şenliğinde 'Geleceğin Okulu' yarışması düzenleniyor ve TÜBİTAK destekli jüri, öğrencilerden 2050 yılında bir okul çantasında neler olacağını anlatan 4 dakikalık sunumlar bekliyor. Jüri, hayal gücünü seviyor ama yalnızca bugünkü teknolojik gelişmelere dayanan tahminlere puan veriyor. Grubunla birlikte çantanın içindeki üç yeniliği tasarlayacak ve jüriyi ikna edecek bir sunum yapacaksın. Bir tahmini 'hayal'den 'güçlü tahmin'e dönüştüren şey nedir?","visual":{"type":"flow","params":{"kind":"zincir","steps":["Dikkat çekici giriş","Bugün ne var?","Tahminimiz","Tahminin dayanağı","Olası sorunlar","Etkileyici kapanış"]},"caption":"Öğrenci sunumun bölümlerini zincir hâlinde sıralar ve her halkaya konuşacağı ana cümleyi yazar."},"steps":[{"title":"Bugünden Geleceğe","mode":"Grup · 30 dk","items":["Okul hayatıyla ilgili bugün var olan 3 teknolojiyi araştırın (ör. akıllı tahta, dijital ders kitabı, sesli asistan).","Her biri için güvenilir bir kaynaktan nasıl geliştiğini gösteren bir bilgi bulun.","Bu bilgilere dayanarak 2050'nin çantası için 3 yenilik tahmin edin ve her tahmini 'Bugün ... olduğuna göre, 2050'de ... olabilir.' kalıbıyla yazın."],"warn":"Sık yapılan hata: Dayanaksız tahmin ('Çanta uçacak!'). Jüri tahmini değil, tahminin bugünle bağını puanlıyor."},{"title":"Sunumu Kur","mode":"Grup · 30 dk","items":["Zincirdeki altı bölümü sunumunuza uygulayın; her bölümü bir grup üyesine verin.","En fazla 6 slayt hazırlayın; slaytlarda uzun cümle değil, anahtar kelime ve görsel olsun.","Çantanın görselini NavigAItor Stüdyo'da tasarlayın ya da çizip fotoğrafını ekleyin; yapay zekâ ile görsel ürettiyseniz bunu slaytta belirtin.","Jürinin sorabileceği 2 soruyu ve cevaplarınızı hazırlayın."]},{"title":"Prova","mode":"Grup · 25 dk","items":["Sunumu zamanlayıcıyla prova edin; toplam 4 dakikayı aşmayın.","Bir üye 'gözlemci' olsun: Ses yüksekliği, göz teması, slayttan okuma ve süre için not tutsun.","Tahmin cümlelerinde 'kesinlikle' yerine 'büyük olasılıkla', 'bu gidişle' gibi ölçülü ifadeler kullanın."],"warn":"Sık yapılan hata: Slayttaki metni sırtı dinleyiciye dönük okumak. Slayt yalnızca ipucudur; konuşmayı dinleyiciye bakarak yap."},{"title":"Şenlik Sunumu","mode":"Grup · 30 dk","items":["Sunumu sınıfa yapın; diğer gruplar jüri rolünde puan kartı doldursun.","Jüri sorularını yanıtlarken tahmininizin dayanağına geri dönün."]},{"title":"Öz Yansıtma","mode":"Bireysel · 5 dk","items":["Sunumunda en güçlü olduğun an hangisiydi?","Gözlemcinin notlarından hangisini bir sonraki sunumunda düzelteceksin?"]}],"checklist":["Bugünkü teknolojileri güvenilir kaynaklardan araştırdım.","Her tahminimi bugünkü bir gelişmeye dayandırdım.","Sunumun altı bölümünü sırayla kurduk.","Slaytlarda anahtar kelime ve görsel kullandım.","Süreye uyarak prova yaptım ve gözlemci notlarını dikkate aldım.","Jüri sorularını tahminin dayanağıyla yanıtladım."],"rubric":[{"k":"Tahminin Dayanağı","d":"Tahminleri bugünkü bilgilere bağlama","l4":"Üç tahminin her biri kaynaklı bir bilgiye dayanıyor","l3":"İki tahmin dayanaklı","l2":"Tahminler ilginç ama dayanaksız","l1":"Tahmin yok ya da konu dışı"},{"k":"Sunum Yapısı","d":"Giriş-gelişme-sonuç düzeni ve geçişler","l4":"Altı bölüm akıcı geçişlerle sunuldu","l3":"Yapı var, bir geçiş kopuk","l2":"Bölümler eksik ya da karışık","l1":"Yapı yok"},{"k":"Konuşma Becerisi","d":"Ses, göz teması, beden dili ve süre","l4":"Akıcı, dinleyiciye dönük, süreye uygun","l3":"Genelde akıcı, kısa süre slayttan okundu","l2":"Çoğunlukla slayttan okundu ya da süre aşıldı","l1":"Sunum tamamlanamadı"},{"k":"Görsel Destek","d":"Slayt ve tasarımın konuşmayı desteklemesi","l4":"Sade, anahtar kelimeli, kaynaklı ve özgün görseller","l3":"Slaytlar anlaşılır, biraz kalabalık","l2":"Slaytlar metin yığını","l1":"Görsel destek yok"}],"navi":["Tahmininizi duyan biri 'Bunu neye dayanarak söylüyorsunuz?' diye sorsa, elinizde hangi bilgi var?","Sunumun ilk 15 saniyesinde dinleyicinin dikkatini ne çekecek?"],"diff":{"destek":"Öğrenciye hazır bir 'bugün-tahmin' eşleştirme tablosu verilir; sunumda yalnızca bir yeniliği 1 dakikada anlatır.","ileri":"Tahmin ettiği yeniliğin olası bir olumsuz etkisini (ör. mahremiyet, ekran süresi) ekleyip buna çözüm önerir ve jüri sorularını yanıtlar."},"misconception":"Öğrenciler tahminin yalnızca hayal gücü olduğunu düşünür; oysa güçlü bir tahmin bugünkü verilere ve gelişmelere dayanır."},{"id":"tur-6-10","course":"TUR","grade":6,"themeNo":6,"themeName":"Lider Ruhlar","title":"Kermesin Kayıp Gelirleri","subtitle":"Metindeki probleme çözüm üretme ve çözüm önerisi yazma","kazanim":["Metindeki probleme çözüm üretebilme","Problem çözümüne yönelik yazabilme"],"skills21":["Girişimcilik","Finansal Okuryazarlık","Sorumluluk","Öz Yönetim"],"digital":["Finansal Okuryazarlık","Dijital Tasarım"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Kâğıt-kalem","NavigAItor okuma ekranı","ücretsiz bir sunum aracı"],"scenario":"Okulun doğa kulübü, ağaç dikme projesi için kermes düzenledi ama kulüp başkanının yazdığı rapora göre gelirin bir kısmı nereye harcandığı belirsiz kaldı ve fidan alımı yapılamadı. Kulüp öğretmeni, raporu okuyup sorunun asıl kaynağını bulacak ve bir dahaki kermes için uygulanabilir bir çözüm önerisi yazacak gönüllüler arıyor. Sen de bu ekiptesin. Bir sorunu çözmeye başlamadan önce sorunun gerçekte ne olduğunu nasıl anlarsın?","visual":{"type":"budget","params":{"items":[{"label":"Fidanlar (plan)","value":"1/2"},{"label":"Afiş ve malzeme","value":"1/4"},{"label":"Kayıtsız harcama","value":"1/4"}],"total":"1"},"caption":"Öğrenci kermes gelirini kavanozlara bölüştürür ve 'kayıtsız harcama' kavanozunu ortadan kaldıracak yeni bir dağılım dener."},"steps":[{"title":"Raporu Oku","mode":"Bireysel · 15 dk","items":["Rapor: 'Kermeste kurabiye ve kitap satarak bir miktar gelir elde ettik. Paranın yarısını fidanlara ayırmıştık. Afiş ve malzeme için çeyreği harcandı. Kalan kısmı farklı arkadaşlar ihtiyaç oldukça aldı ama kimse not tutmadı. Fidan zamanı geldiğinde kasada para kalmamıştı.'","Raporda olayları sırayla listele.","Raporun hangi cümlesinin sorunun asıl kaynağını gösterdiğini işaretle."]},{"title":"Sorunu Tanımla","mode":"İkili · 15 dk","items":["Sorunu tek cümleyle yazın: 'Asıl sorun ... çünkü ...'","Sorunun belirtisi (para bitti) ile nedenini (kayıt tutulmadı, sorumlu yok) ayırın.","Bütçe kavanozları görselinde hangi kavanozun sorun yarattığını gösterin."],"warn":"Sık yapılan hata: Belirtiyi sorun sanmak. 'Para yetmedi' bir sonuçtur; neden yetmediğini bulmadan önerilen çözüm sorunu tekrar yaşatır."},{"title":"Çözüm Seçenekleri Üret","mode":"Grup · 20 dk","items":["Grupça en az 3 çözüm önerisi üretin (ör. harcama defteri, tek bir sorumlu sayman, harcama öncesi onay).","Her öneriyi iki ölçütle puanlayın: Uygulaması kolay mı? Sorunun nedenini ortadan kaldırıyor mu?","En yüksek puanı alan çözümü seçin ve neden seçtiğinizi yazın."],"warn":"Sık yapılan hata: Uygulanamayacak kadar büyük çözümler ('Okula banka kuralım'). Çözüm, kulübün kendi imkânlarıyla yapılabilmeli."},{"title":"Çözüm Önerisi Yaz","mode":"Bireysel · 25 dk","items":["Kulüp öğretmenine 2–3 paragraflık bir çözüm önerisi yaz: 1) Sorun ve nedeni, 2) Önerilen çözüm ve nasıl uygulanacağı, 3) Beklenen sonuç.","Önerini somut adımlarla yaz (kim, ne zaman, nasıl).","Önerinin özetini tek sayfalık bir dijital poster olarak tasarla.","Yazım ve noktalama kontrolünü yaparak metni teslim et."]},{"title":"Öz Yansıtma","mode":"Bireysel · 5 dk","items":["Grupta seçilen çözüm senin ilk düşündüğün çözümden farklı mıydı? Neden?","Bir lider olarak bu süreçte hangi sorumluluğu üstlenirdin?"]}],"checklist":["Raporu okuyup olayları sıraladım.","Sorunun belirtisi ile nedenini ayırdım.","En az 3 çözüm seçeneğini ölçütlere göre karşılaştırdım.","Çözüm önerimi sorun-çözüm-sonuç düzeninde yazdım.","Önerime kim, ne zaman, nasıl sorularının cevabını ekledim.","Yazım ve noktalama kontrolünü yaptım."],"rubric":[{"k":"Problemi Belirleme","d":"Metindeki asıl sorunu ve nedenini bulma","l4":"Neden ve belirti açıkça ayrıldı, metinden kanıtlandı","l3":"Neden bulundu, kanıt zayıf","l2":"Belirti sorun olarak yazıldı","l1":"Sorun belirlenmedi"},{"k":"Çözümün Niteliği","d":"Çözümün uygulanabilirliği ve nedene yönelikliği","l4":"Uygulanabilir, nedeni ortadan kaldırıyor, adımları somut","l3":"Uygulanabilir, adımlar kısmen somut","l2":"Çözüm genel ya da uygulanamaz","l1":"Çözüm önerilmedi"},{"k":"Metin Yapısı","d":"Sorun-çözüm-sonuç düzeni","l4":"Üç bölüm açık ve bağlantılı","l3":"Bölümler var, geçişler zayıf","l2":"Bir bölüm eksik","l1":"Düzen yok"},{"k":"Dil ve Yazım","d":"Açık anlatım, yazım ve noktalama","l4":"Açık, hatasız denecek kadar özenli","l3":"Birkaç küçük hata","l2":"Hatalar anlamı zorlaştırıyor","l1":"Anlatım bozuk"}],"navi":["Raporda 'kimse not tutmadı' cümlesi olmasaydı, sorunun ne olduğunu bulabilir miydin?","Önerdiğin çözüm bir sonraki kermeste uygulansa, para yine bitebilir mi? Hangi durumda?"],"diff":{"destek":"Öğrenciye 'sorun - neden - çözüm' boşluklu şablonu ve üç hazır çözüm seçeneği verilir; birini seçip gerekçesiyle tek paragraf yazar.","ileri":"Kulüp için bir sayfalık 'harcama kuralları' yönergesi yazar ve kurallarını eski rapordaki olaylara uygulayarak sorunu önleyip önlemediğini gösterir."},"misconception":"Öğrenciler sorunun görünen sonucunu (para bitmesi) asıl sorun sanar; bu yüzden nedenini değil belirtisini gideren çözümler üretir."},{"id":"tur-7-11","course":"TUR","grade":7,"themeNo":1,"themeName":"Hayat Boyu Gelişim","title":"Bir Haftalık Ben","subtitle":"Kişisel gelişim blog yazısı ve yazma sürecine öz yansıtma","kazanim":["Yazısında içerik ve yapıya yönelik seçimlerini yönetebilme","Yazma sürecine yönelik öz yansıtma yapabilme/kendini uyarlayabilme"],"skills21":["Öz Düzenleme","Zaman Yönetimi","Sorumluluk","Esneklik"],"digital":["Dijital planlama araçları","Dijital günlük ile öz yansıtma"],"duration":"80 dk (2 ders)","format":"Bireysel","tools":["Defter ve kalem","Dijital takvim veya görev listesi uygulaması","NavigAItor Stüdyo (blog editörü)"],"scenario":"Okulun 'Gelişim Köşesi' adlı blogu, öğrencilerden yeni bir alışkanlık edinme deneyimlerini anlatan yazılar istiyor. Sen bir hafta boyunca küçük bir hedef koydun: her gün 20 dakika kitap okumak ya da ekrana bakmadan yürüyüş yapmak gibi. Bazı günler başardın, bazı günler planın bozuldu. Okurlar 'mükemmel bir hafta' değil, gerçek bir deneyim okumak istiyor. Bu deneyimi okuyanın da işine yarayacak şekilde nasıl anlatırsın?","visual":{"type":"routine","params":{"items":[{"time":"07:30","t":"Kahvaltı ve hazırlık"},{"time":"16:00","t":"Ödev zamanı"},{"time":"17:30","t":"Yeni alışkanlık: 20 dk okuma"},{"time":"19:00","t":"Akşam yemeği ve aile"},{"time":"21:30","t":"Günün kısa notu"}]},"caption":"Kendi gün planını düzenle, yeni alışkanlığın için zaman dilimini yerleştir ve her güne 'oldu / olmadı' işareti koy."},"steps":[{"title":"Haftanı Planla ve Kaydet","mode":"Bireysel · 15 dk","items":["Edinmek istediğin tek bir alışkanlık seç ve ölçülebilir yaz (ör. 'her gün 20 dakika okuma').","Görseldeki gün planına alışkanlığının saatini yerleştir.","Yedi gün için kısa notlar al: Ne oldu? Neden oldu ya da olmadı? Nasıl hissettim?"],"warn":"Sık yapılan hata: Hedefi 'daha çok kitap okuyacağım' gibi belirsiz yazmak. Belirsiz bir hedefin başarılıp başarılmadığını nasıl anlarsın?"},{"title":"Yazının İskeletini Kur","mode":"Bireysel · 15 dk","items":["Notlarından en önemli üç anı seç; hepsini yazmak zorunda değilsin.","Yapını belirle: giriş (neden bu hedef?), gelişme (zorlandığım ve başardığım anlar), sonuç (ne öğrendim, okura önerim).","Okurunu düşün: Bu blogu kimler okuyacak? Diline ve uzunluğa (250–350 kelime) buna göre karar ver."],"warn":"Sık yapılan hata: Yedi günü sırayla tek tek anlatmak. Bu yazıyı günlük gibi değil, okura yol gösteren bir deneyim yazısı gibi kurgulamak neyi değiştirir?"},{"title":"Taslağı Yaz","mode":"Bireysel · 25 dk","items":["Taslağını NavigAItor Stüdyo blog editöründe yaz.","Dikkat çekici bir başlık ve ilk cümle seç.","Her paragrafın tek bir ana fikri olsun; paragraflar arasında geçiş ifadeleri kullan (ilk günlerde, buna rağmen, sonunda vb.)."]},{"title":"Yazma Sürecime Ayna Tut","mode":"Bireysel · 25 dk","items":["Taslağını yüksek sesle oku; akışı bozan cümleleri işaretle ve düzelt.","Yazım ve noktalama kontrolü yap.","Yazının sonuna 'Yazarken fark ettiklerim' başlıklı 3 cümlelik bir not ekle: Nerede zorlandım? Hangi kararı değiştirdim? Bir sonraki yazımda neyi farklı yapacağım?"]}],"checklist":["Ölçülebilir bir alışkanlık hedefi belirledim.","Yedi günlük notlarımdan en önemli anları seçtim.","Yazımı giriş, gelişme ve sonuç bölümleriyle kurdum.","Paragraflar arasında geçiş ifadeleri kullandım.","Yazım ve noktalama kontrolünü yaptım.","Yazma sürecime yönelik öz yansıtma notumu ekledim."],"rubric":[{"k":"Yapı ve Düzen","d":"Giriş, gelişme ve sonuç belirgin; paragraflar tek ana fikir etrafında","l4":"Bölümler belirgin, paragraflar odaklı ve akıcı bağlanmış","l3":"Bölümler var, bir paragrafta odak dağılıyor","l2":"Bölümler belirsiz, anlatım günlük sırasına kaymış","l1":"Düzen yok, cümleler dağınık"},{"k":"İçerik Seçimi","d":"Okura yararlı, seçilmiş ve gerekçelendirilmiş anlar","l4":"En anlamlı anlar seçilmiş, okura somut öneri var","l3":"Anlar seçilmiş, öneri genel kalmış","l2":"Anlar seçilmeden sıralanmış","l1":"Deneyim anlatılmamış"},{"k":"Dil ve Yazım","d":"Geçiş ifadeleri, yazım ve noktalama","l4":"Geçişler çeşitli, yazım hatası yok denecek kadar az","l3":"Geçişler var, birkaç yazım hatası","l2":"Geçiş az, hatalar anlamı etkiliyor","l1":"Geçiş yok, çok sayıda hata"},{"k":"Öz Yansıtma","d":"Yazma sürecindeki karar ve değişiklikleri fark etme","l4":"Somut zorluk, değişiklik ve gelecek planı açıkça yazılmış","l3":"Zorluk ve değişiklik var, plan genel","l2":"Sadece 'iyi geçti' türü yorum","l1":"Öz yansıtma notu yok"}],"navi":["Yazını hiç tanımadığın bir yedinci sınıf öğrencisi okusa, bitirdiğinde aklında hangi tek cümle kalsın istersin?","Planının bozulduğu gün, yazının en ilginç bölümü olabilir mi? Neden?","Taslağında sildiğin bir cümle var mı? Onu neden çıkardın?"],"diff":{"destek":"Her bölüm için başlangıç cümleleri verilir (ör. 'Bu hafta kendime küçük bir söz verdim...'); hedef uzunluk 150–200 kelimeye indirilir.","ileri":"Yazıya, haftalık başarı oranını gösteren küçük bir tablo veya grafik ekle ve okura 'kendi alışkanlık planını kurma' için üç adımlı bir rehber yaz."},"misconception":"İyi bir kişisel yazının yaşanan her şeyi sırayla anlatmak olduğu sanılır; oysa yazar okurun ihtiyacına göre içerik seçer ve düzenler."},{"id":"tur-7-12","course":"TUR","grade":7,"themeNo":2,"themeName":"Bir Hilal Uğruna","title":"Cepheden Gelen Ses","subtitle":"Anma podcast'ini medya içeriği olarak dinleme ve söz sanatlarını çözümleme","kazanim":["Medya içeriğini değerlendirebilme","Dinlediğindeki/izlediğindeki söz sanatlarını belirlemeye yönelik çözümleme yapabilme"],"skills21":["Eleştirel Düşünme","Vatanseverlik","Medya Okuryazarlığı","İletişim"],"digital":["Medya okuryazarlığı","Dijital hikâye anlatıcılığı"],"duration":"80 dk (2 ders)","format":"İkili","tools":["Kulaklık","NavigAItor ses oynatıcı","Defter ve kalem","Ücretsiz bir ses kayıt uygulaması"],"scenario":"Okul radyosu 18 Mart Çanakkale Zaferi anması için hazırlanan 4 dakikalık bir podcast bölümünü yayınlamadan önce dinleyici kuruluna gönderdi. Bölümde hayalî bir askerin annesine yazdığı mektup, müzik ve anlatıcı sesi yer alıyor. Kurul olarak senden iki şey isteniyor: bölümün etkili dil kullanımını ortaya koymak ve yayına uygun olup olmadığını gerekçeleriyle değerlendirmek. Bu bölüm dinleyiciyi hangi yollarla etkiliyor ve bu yollar bilgiyle duyguyu dengeli kullanıyor mu?","visual":{"type":"news","params":{"headline":"Okul Radyosunda Yeni Bölüm: 'Siperden Bir Mektup'","lead":"Anma haftası için hazırlanan bölüm, hayalî bir askerin mektubunu anlatıcı sesi ve müzikle dinleyiciye sunuyor. Yayından önce dinleyici kurulunun görüşü bekleniyor.","tags":["podcast","anma","dinleyici kurulu","medya değerlendirme"]},"caption":"Haber kartındaki bilgileri oku, bölümü dinlemeden önce içerikle ilgili tahminini kartın altına yaz."},"steps":[{"title":"Dinlemeye Hazırlan","mode":"İkili · 10 dk","items":["Haber kartını oku ve bölümde neler duyacağınızı tahmin edin.","Görev paylaşımı yapın: biriniz dil ve söz sanatlarını, diğeriniz ses, müzik ve yapım öğelerini not alacak.","Not tablosu hazırlayın: 'Duyduğum ifade / Ne yapıyor? / Dinleyicide uyandırdığı etki'."]},{"title":"Dinle ve Çözümle","mode":"İkili · 25 dk","items":["Bölümü bir kez kesintisiz dinleyin; ilk izleniminizi tek cümleyle yazın.","İkinci dinlemede durdurarak not alın: benzetme, kişileştirme, abartma gibi söz sanatlarını ve geçtikleri cümleleri yazın.","Müziğin yükseldiği ya da sesin yavaşladığı anları işaretleyin; bu anlarda hangi cümlelerin söylendiğine bakın."],"warn":"Sık yapılan hata: Duygulandıran her cümleyi söz sanatı saymak. Bir ifadenin söz sanatı olduğunu hangi özelliğine bakarak gösterebilirsin?"},{"title":"Medya İçeriğini Değerlendir","mode":"İkili · 25 dk","items":["Şu soruları yanıtlayın: Bölümün amacı ne? Hedef dinleyici kim? Hangi bilgiler tarihsel, hangileri kurgusal?","Bölüm, mektubun hayalî olduğunu dinleyiciye açıkça söylüyor mu? Söylememesi neden sorun olabilir?","Bölümün güçlü iki yönünü ve geliştirilmesi gereken bir yönünü kanıtlarla yazın."],"warn":"Sık yapılan hata: 'Çok duygusaldı, o yüzden iyiydi' gibi tek ölçütle karar vermek. Bir medya içeriğini değerlendirirken başka hangi ölçütlere bakılabilir?"},{"title":"Kurul Görüşünü Kaydet","mode":"İkili · 20 dk","items":["Değerlendirmenizi 90 saniyelik bir ses kaydı olarak hazırlayın.","Kayıtta en az iki söz sanatı örneğini ve etkisini anlatın.","Yayın kararınızı (yayınlanabilir / düzeltmeyle yayınlanabilir) gerekçesiyle bitirin."]}],"checklist":["Dinlemeden önce içerik tahminimi yazdım.","Bölümü en az iki kez, farklı amaçlarla dinledim.","En az iki söz sanatını cümlesiyle birlikte not ettim.","Tarihsel bilgi ile kurgusal öğeyi ayırt ettim.","Değerlendirmemi güçlü ve geliştirilmesi gereken yönlerle gerekçelendirdim.","Kurul görüşümüzü sesli olarak kaydettik."],"rubric":[{"k":"Söz Sanatlarını Çözümleme","d":"Söz sanatını doğru adlandırma ve etkisini açıklama","l4":"En az 3 sanat doğru adlandırılmış, etkileri açıklanmış","l3":"2 sanat doğru, etki kısmen açıklanmış","l2":"1 sanat doğru ya da adlandırma karışık","l1":"Söz sanatı belirlenmemiş"},{"k":"Medya Değerlendirmesi","d":"Amaç, hedef kitle, kurgu-gerçek ayrımı","l4":"Tüm boyutlar kanıtla değerlendirilmiş","l3":"İki boyut kanıtla değerlendirilmiş","l2":"Değerlendirme izlenime dayalı","l1":"Değerlendirme yok"},{"k":"Dinleme Stratejisi","d":"Not alma ve çoklu dinleme kullanımı","l4":"Not tablosu düzenli, ikinci dinleme amaçlı kullanılmış","l3":"Notlar var, düzen kısmi","l2":"Notlar dağınık","l1":"Not alınmamış"},{"k":"Sözlü Sunum","d":"Ses kaydında açıklık, gerekçe ve süre","l4":"Açık, gerekçeli, süreye uygun","l3":"Gerekçeli ama süre veya akış sorunlu","l2":"Karar var, gerekçe zayıf","l1":"Kayıt eksik"}],"navi":["Müzik olmadan aynı cümleleri dinleseydin etkisi değişir miydi? Bu sana ne söylüyor?","Bir cümleyi 'süslü' bulduğunda, onu sıradan bir cümleden ayıran şey tam olarak ne?","Hayalî bir mektup, gerçek bir anmayı güçlendirebilir mi, yoksa yanıltabilir mi? Hangi koşulda?"],"diff":{"destek":"Bölümün yazılı dökümü verilir; öğrenci söz sanatlarını metin üzerinde renkli kalemle işaretler ve hazır etki kartlarından (duygu uyandırma, canlandırma, vurgulama) seçer.","ileri":"Bölüm için 60 saniyelik yeni bir açılış metni yaz: tarihsel bir bilgiyi doğru kaynağını belirterek ver ve en az iki söz sanatını bilinçli olarak kullan."},"misconception":"Bir medya içeriğinin ne kadar duygulandırdığı, ne kadar doğru ve nitelikli olduğunun ölçüsü sanılır."},{"id":"tur-7-13","course":"TUR","grade":7,"themeNo":3,"themeName":"İletişim Ve Sosyal İlişkiler","title":"Sınıf Grubunda Fırtına","subtitle":"Çevrim içi nezaket üzerine sözlü tartışma ve beden dili","kazanim":["Sözlü olarak tartışmaya katılabilme","Konuşmasında beden dilini ve mekânı etkili kullanabilme"],"skills21":["İletişim","Saygı","Nezaket","Problem Çözme","Sosyal Farkındalık"],"digital":["Dijital görgü kuralları","Dijital empati"],"duration":"80 dk (2 ders)","format":"Grup","tools":["Tartışma rol kartları","Defter ve kalem","Video kayıt için tablet (isteğe bağlı)"],"scenario":"Sınıfınızın mesajlaşma grubunda bir öğrencinin paylaştığı fotoğraf alay konusu oldu; bazıları bunun 'sadece şaka' olduğunu söylüyor. Öğretmeniniz konunun bir sonraki sınıf saatinde tartışılmasını istedi ve sizin grubunuzu tartışmayı yürütmekle görevlendirdi. Amaç kimseyi suçlamak değil, sınıf grubu için herkesin uyacağı kurallar çıkarmak. Farklı görüşleri kırmadan dinleyip ortak bir karara nasıl ulaşırsınız?","visual":{"type":"chat","params":{"lines":[{"who":"Deniz","t":"Bu fotoğrafta saçın çok komik olmuş 😂"},{"who":"Mert","t":"Hahaha, profil fotoğrafı yapalım bunu!"},{"who":"Elif","t":"Bence silelim, izin almadan paylaşılmış."},{"who":"Mert","t":"Abartma ya, şaka sadece."},{"who":"Can","t":"..."}]},"caption":"Mesajları oku, her balonun yanına yazanın ve okuyanın ne hissetmiş olabileceğini not et."},"steps":[{"title":"Durumu Anla","mode":"Grup · 15 dk","items":["Görseldeki konuşmayı okuyun; her kişinin ne demek istediğini ve konuşmanın kimi nasıl etkilediğini tartışın.","Can'ın '...' mesajı ne anlama gelebilir? En az iki olasılık yazın.","Tartışma sorusunu netleştirin: 'Sınıf grubunda şaka ile zorbalık arasındaki sınırı nasıl belirleriz?'"]},{"title":"Rolleri Dağıt ve Hazırlan","mode":"Grup · 15 dk","items":["Rolleri paylaşın: oturum yöneticisi, 'şakadır' görüşünü savunan, 'izinsiz paylaşım yanlıştır' görüşünü savunan, zaman tutucu ve gözlemci.","Her konuşmacı en az iki gerekçe ve bir örnek hazırlasın.","Mekânı düzenleyin: herkesin birbirini görebileceği yarım daire oturma düzeni kurun."],"warn":"Sık yapılan hata: Tartışmayı kazanılacak bir yarış gibi görmek. Bu tartışmada 'başarı' neye benzemeli?"},{"title":"Tartışmayı Yürüt","mode":"Grup · 30 dk","items":["Her konuşmacı 2 dakika konuşsun; söz almak için el kaldırma kuralına uyun.","Karşı görüşe yanıt vermeden önce onu kendi cümlelerinizle özetleyin ('Yani sen ... diyorsun, doğru mu?').","Gözlemci; göz teması, ses tonu, el hareketleri ve oturuş biçimini gözlem formuna yazsın."],"warn":"Sık yapılan hata: Söz yerinde olmasa da kollarını kavuşturmak, başını çevirmek ya da telefona bakmak. Sessiz dururken bile beden dilin ne söylüyor olabilir?"},{"title":"Ortak Kurallar ve Değerlendirme","mode":"Grup · 20 dk","items":["Tartışmadan çıkan en az 4 grup kuralını yazın (ör. 'Bir arkadaşımızın fotoğrafını paylaşmadan önce izin isteriz.').","Gözlemci, beden dili ve mekân kullanımıyla ilgili iki güçlü yön ve bir öneri paylaşsın.","Her üye tartışmadaki kendi katkısını tek cümleyle değerlendirsin."]}],"checklist":["Mesajlaşmadaki kişilerin duygularını farklı açılardan düşündüm.","Görüşümü gerekçe ve örnekle destekledim.","Karşı görüşü yanıtlamadan önce kendi cümlelerimle özetledim.","Konuşurken göz teması kurdum ve ses tonumu ayarladım.","Ortak grup kurallarının yazılmasına katkı verdim.","Tartışmadaki kendi katkımı değerlendirdim."],"rubric":[{"k":"Gerekçelendirme","d":"Görüşü gerekçe ve örnekle destekleme","l4":"En az iki güçlü gerekçe ve uygun örnek","l3":"İki gerekçe, örnek zayıf","l2":"Tek gerekçe","l1":"Gerekçesiz görüş"},{"k":"Saygılı Etkileşim","d":"Dinleme, özetleme, söz hakkına uyma","l4":"Karşı görüşü doğru özetleyip nazikçe yanıtlıyor","l3":"Söz hakkına uyuyor, özetleme kısmi","l2":"Zaman zaman sözü kesiyor","l1":"Karşı görüşü dinlemiyor"},{"k":"Beden Dili ve Mekân","d":"Göz teması, jest, duruş ve oturma düzeni","l4":"Beden dili konuşmayı destekliyor, mekân etkili kullanılıyor","l3":"Beden dili çoğunlukla uygun","l2":"Beden dili ile söz çelişiyor","l1":"Beden diline dikkat edilmemiş"},{"k":"Çözüm Üretme","d":"Ortak ve uygulanabilir kurallar","l4":"4+ açık, uygulanabilir kural","l3":"3 kural, biri belirsiz","l2":"Kurallar genel ('kibar olalım')","l1":"Kural yok"}],"navi":["Aynı cümleyi yüz yüze ve mesajla söylemek arasında ne fark olabilir?","Karşındaki kişi seni dinlediğini sana nasıl hissettirdi? Sen ona nasıl hissettirdin?","Bir şakanın şaka olup olmadığına kim karar vermeli?"],"diff":{"destek":"Hazır cümle başlatıcıları verilir ('Ben ... düşünüyorum çünkü...', 'Senin ... dediğini anladım, ama...'); öğrenci gözlemci rolüyle başlayıp ikinci turda konuşmacı olur.","ileri":"Tartışmanın sonucunu sınıfa 2 dakikalık bir 'Dijital Nezaket Bildirgesi' konuşmasıyla sun; bildirgede bir çevrim içi zorbalık durumunda ne yapılacağına dair adımlar yer alsın."},"misconception":"Tartışmanın amacının karşı tarafı susturmak olduğu ve beden dilinin yalnızca konuşan kişi için önemli olduğu sanılır."},{"id":"tur-7-14","course":"TUR","grade":7,"themeNo":4,"themeName":"Türk Sanatı","title":"Su Üstünde Renkler","subtitle":"Ebru üzerine iki metni ve bir sanal sergi sayfasını karşılaştırma","kazanim":["Metinler arası karşılaştırma yapabilme","Çoklu ortam ögelerine yönelik çözümleme yapabilme"],"skills21":["Estetik Duyarlılık","Kültürel Farkındalık","Eleştirel Düşünme","Yaratıcılık"],"digital":["Dijital sanat okuryazarlığı","Çoklu ortam üretimi"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor metin okuyucu","Sanal müze veya dijital sergi sayfası","Ücretsiz bir sunum aracı"],"scenario":"Şehrinizdeki kültür merkezi 'Geleneksel Sanatlar Haftası' için öğrencilerden dijital sergi rehberi istiyor. Elinde ebru sanatıyla ilgili iki metin var: biri tekniği adım adım anlatan bilgilendirici bir yazı, diğeri bir ebru ustasının atölyesini anlatan kısa bir anı. Ayrıca fotoğraf, kısa video ve açıklama yazılarından oluşan bir sanal sergi sayfası incelemen gerekiyor. Aynı sanatı anlatan bu üç kaynak, okura neyi ortak, neyi farklı biçimde sunuyor?","visual":{"type":"organizer","params":{"kind":"venn","slots":["Bilgilendirici yazı","Anı metni","Her ikisinde ortak"]},"caption":"İki metnin konu, amaç, dil ve anlatım özelliklerini Venn şemasında doğru bölgeye yerleştir."},"steps":[{"title":"İki Metni Oku","mode":"Bireysel · 20 dk","items":["Önce bilgilendirici yazıyı oku; ebru yapım aşamalarını numaralayarak not al.","Sonra anı metnini oku; yazarın duygularını ve betimlemelerini yansıtan ifadelerin altını çiz.","Her metin için 'Yazar bu metni neden yazmış olabilir?' sorusunu tek cümleyle yanıtla."]},{"title":"Metinleri Karşılaştır","mode":"Bireysel · 20 dk","items":["Venn şemasını doldur: konu, amaç, anlatıcı, dil (terimli / mecazlı), okurda uyandırdığı etki.","Ortak bölgeye en az 2, her ayrı bölgeye en az 3 madde yaz.","Hangi metnin ebruyu 'öğrenmek', hangisinin 'hissetmek' isteyene uygun olduğunu kanıtla açıkla."],"warn":"Sık yapılan hata: Sadece konuyu karşılaştırıp 'ikisi de ebruyu anlatıyor' demek. Aynı konu iki metinde başka hangi açılardan farklılaşabilir?"},{"title":"Sanal Sergiyi Çözümle","mode":"Grup · 20 dk","items":["Sanal sergi sayfasındaki fotoğraf, video, ses ve açıklama yazılarını listeleyin.","Her ögenin işlevini belirleyin: bilgi veriyor mu, duygu uyandırıyor mu, yönlendiriyor mu?","Bir ögeyi çıkarsaydınız sayfanın anlamı nasıl değişirdi? Tartışın."],"warn":"Sık yapılan hata: Görselleri yalnızca süs olarak görmek. Bir fotoğrafın açıklama yazısı, fotoğrafı nasıl okuduğumuzu nasıl etkiler?"},{"title":"Dijital Rehber Kartı Hazırla","mode":"Grup · 20 dk","items":["Ücretsiz bir sunum aracıyla tek sayfalık 'Ebruya Giriş' rehber kartı tasarlayın.","Kartta bilgilendirici metinden bir bilgi, anı metninden bir duygu cümlesi ve bir görsel bulunsun.","Kart altına seçtiğiniz ögelerin neden birlikte kullanıldığını açıklayan bir cümle ekleyin."]}],"checklist":["İki metni farklı amaçlarla okudum ve not aldım.","Venn şemasını konu dışındaki ölçütlerle de doldurdum.","Metinlerin amaç farkını kanıtla açıkladım.","Sanal sergideki çoklu ortam ögelerinin işlevini belirledim.","Rehber kartında metin ve görseli bilinçli biçimde birleştirdim.","Kullandığım görselin kaynağını belirttim."],"rubric":[{"k":"Metinler Arası Karşılaştırma","d":"Ortak ve farklı yönleri çok ölçütlü belirleme","l4":"4+ ölçüt, her biri metinden kanıtlı","l3":"3 ölçüt, kanıt kısmi","l2":"Yalnızca konu ve tür karşılaştırılmış","l1":"Karşılaştırma yok"},{"k":"Amaç ve Dil Farkı","d":"Bilgilendirici ve öyküleyici anlatımı ayırt etme","l4":"Amaç ve dil farkı örnek cümlelerle açıklanmış","l3":"Fark doğru, örnek az","l2":"Fark sezilmiş ama açıklanamamış","l1":"Fark görülmemiş"},{"k":"Çoklu Ortam Çözümlemesi","d":"Ögelerin işlevini ve etkileşimini açıklama","l4":"Her ögenin işlevi ve birbirine katkısı açıklanmış","l3":"Ögelerin işlevi belirlenmiş","l2":"Ögeler yalnızca listelenmiş","l1":"Çözümleme yok"},{"k":"Rehber Kartı Tasarımı","d":"Bilgi, duygu ve görselin dengeli birleşimi","l4":"Üç öge uyumlu, gerekçe cümlesi net","l3":"Üç öge var, gerekçe zayıf","l2":"Bir öge eksik","l1":"Kart tamamlanmamış"}],"navi":["Ebruyu hiç görmemiş biri bu iki metinden hangisini okuduktan sonra ebru yapmayı denemeye cesaret eder? Neden?","Anı metnindeki bir betimlemeyi bilgilendirici yazının diline çevirseydin neyi kaybeder, neyi kazanırdın?","Sergi sayfasında seni ilk durduran öge hangisiydi? Seni orada durduran ne?"],"diff":{"destek":"Venn şeması için hazır ölçüt etiketleri (amaç, anlatıcı, terim kullanımı, duygu dili) verilir; metinler kısaltılmış biçimde sunulur.","ileri":"Hat ya da minyatür hakkında benzer iki kaynak bul, aynı ölçütlerle karşılaştır ve iki sanatı birlikte tanıtan bir dijital sergi kartı tasarla."},"misconception":"Aynı konuyu anlatan metinlerin aynı amaçla yazıldığı ve görsellerin anlama katkısı olmayan süsler olduğu sanılır."},{"id":"tur-7-15","course":"TUR","grade":7,"themeNo":5,"themeName":"Okuma Kültürü","title":"Rafların Sessizliği","subtitle":"Okul kütüphanesi raporunu değerlendirme ve okuma sorununa çözüm üretme","kazanim":["Okuduğunu değerlendirebilme","Metindeki probleme çözüm üretebilme"],"skills21":["Bilgi Okuryazarlığı","Eleştirel Düşünme","Sistematik Düşünme","Öğrenmeyi Öğrenme"],"digital":["Dijital kütüphane","Eleştirel okuryazarlık"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor metin okuyucu","Okul kütüphanesinin çevrim içi kataloğu","Defter ve kalem"],"scenario":"Okul kütüphanesi kulübü, son altı ayın ödünç alma verilerini ve öğrenci anketinden alıntıları içeren kısa bir rapor yayımladı. Raporda 'Öğrenciler artık kitap okumuyor' sonucuna varılıyor ve kütüphanenin yarısının ders çalışma salonuna dönüştürülmesi öneriliyor. Sen kulübün okur temsilcisisin ve yönetime görüş sunacaksın. Rapordaki veriler bu sonucu gerçekten destekliyor mu, yoksa sorun başka bir yerde olabilir mi?","visual":{"type":"bars","params":{"title":"Aylara Göre Ödünç Alınan Basılı Kitap","labels":["Eylül","Ekim","Kasım","Aralık","Ocak","Şubat"],"values":[142,128,96,74,61,88],"unit":"kitap","editable":false},"caption":"Grafiği incele; düşüşün en belirgin olduğu ayları ve Şubat'taki değişimi işaretle."},"steps":[{"title":"Raporu Oku ve Ayrıştır","mode":"Bireysel · 20 dk","items":["Raporu oku; rapordaki 'veri', 'yorum' ve 'öneri' cümlelerini üç farklı renkle işaretle.","Grafikteki değişimi kendi cümlelerinle özetle.","Anket alıntılarından en sık tekrar eden üç şikâyeti listele (ör. 'kitaplar eski', 'açılış saatleri uygun değil')."]},{"title":"Raporu Değerlendir","mode":"Bireysel · 20 dk","items":["Şu soruları yanıtla: Rapor yalnızca basılı kitapları mı sayıyor? Dijital okuma ya da e-kitap verisi var mı?","Kasım–Ocak arasındaki düşüşü açıklayabilecek başka nedenler neler olabilir (sınav dönemi, tatil vb.)?","'Öğrenciler artık kitap okumuyor' sonucunu güçlü, kısmen haklı ya da zayıf olarak derecelendir ve gerekçeni yaz."],"warn":"Sık yapılan hata: Bir grafikteki düşüşü görür görmez raporun sonucunu doğru kabul etmek. Veri ile o veriden çıkarılan yorum arasındaki farkı nasıl ayırt edersin?"},{"title":"Çözüm Önerisi Geliştir","mode":"Grup · 25 dk","items":["Gruplar halinde asıl sorunu tek cümleyle yeniden tanımlayın.","En az üç çözüm üretin; her biri için maliyetsiz uygulanabilirlik, etkilenecek öğrenci sayısı ve olası engel yazın.","Çevrim içi kataloğu inceleyin: öğrencilerin yeni kitaplardan haberdar olmasını kolaylaştıracak bir fikir ekleyin."],"warn":"Sık yapılan hata: Sorunu doğru tanımlamadan çözüm listelemek. Sorunu farklı tanımlarsan çözümlerin nasıl değişir?"},{"title":"Yönetime Görüş Sun","mode":"Grup · 15 dk","items":["En uygulanabilir çözümü seçin ve 120–150 kelimelik bir görüş yazısı hazırlayın.","Yazıda raporun güçlü ve zayıf yönlerini ve önerinizi gerekçesiyle belirtin.","Görüşünüzü sınıfa 2 dakikada sunun."]}],"checklist":["Rapordaki veri, yorum ve öneri cümlelerini ayırdım.","Grafikteki değişimi doğru yorumladım.","Rapordaki sonucun gücünü gerekçesiyle değerlendirdim.","Sorunu kendi cümlelerimle yeniden tanımladım.","En az üç çözüm üretip birini gerekçesiyle seçtim.","Görüş yazımızın sunumuna katkı verdim."],"rubric":[{"k":"Metni Değerlendirme","d":"Veri ile yorumu ayırma, sonucun dayanağını sorgulama","l4":"Veri-yorum ayrımı net, eksik veriyi fark etmiş","l3":"Ayrım doğru, eksik veri belirtilmemiş","l2":"Ayrım karışık","l1":"Rapor sorgulanmadan kabul edilmiş"},{"k":"Grafik Okuma","d":"Değişimi ve olası nedenleri yorumlama","l4":"Değişim doğru, birden çok olası neden önerilmiş","l3":"Değişim doğru, tek neden","l2":"Değişim kısmen doğru","l1":"Grafik yanlış okunmuş"},{"k":"Çözüm Üretme","d":"Sorunu tanımlama ve uygulanabilir çözüm","l4":"Sorun net, 3+ çözüm ölçütlerle karşılaştırılmış","l3":"Sorun net, çözümler karşılaştırılmamış","l2":"Çözümler sorunla ilişkisiz","l1":"Çözüm yok"},{"k":"Görüş Yazısı ve Sunum","d":"Gerekçeli, düzenli ve kısa anlatım","l4":"Güçlü-zayıf yön ve öneri gerekçeli, akıcı","l3":"Öneri gerekçeli, düzen kısmi","l2":"Gerekçe zayıf","l1":"Yazı tamamlanmamış"}],"navi":["Raporu yazan kişi hangi soruyu sormayı unutmuş olabilir?","Şubat ayında artış olduysa o ay ne değişmiş olabilir? Bunu nasıl öğrenebilirsin?","Kütüphaneyi en az kullanan öğrencilerin görüşü raporda var mı? Olmalı mı?"],"diff":{"destek":"Rapor cümleleri önceden 'veri / yorum' olarak karışık kartlara bölünür; öğrenci kartları iki kutuya ayırır ve hazır neden listesinden seçim yapar.","ileri":"Kendi sınıfında 5 soruluk kısa bir okuma alışkanlığı anketi tasarla, sonuçları rapordaki verilerle karşılaştır ve çözüm önerini bu yeni veriyle güçlendir."},"misconception":"Bir metinde sayısal veri bulunmasının, metindeki sonucun doğru ve tartışmasız olduğunu gösterdiği sanılır."},{"id":"tur-8-16","course":"TUR","grade":8,"themeNo":1,"themeName":"İletişim Ve Sosyal İlişkiler","title":"Bu Ses Gerçek mi?","subtitle":"Sesli mesajları dinleyerek yüzey ve derin anlamı belirleme, yapay zekâ ile üretilmiş içeriği sorgulama","kazanim":["Dinlediğinin/izlediğinin yüzey anlamını belirleyebilme","Dinlediğinin/izlediğinin derin anlamını belirlemeye yönelik basit çıkarımlar yapabilme"],"skills21":["Dijital Vatandaşlık","Eleştirel Düşünme","Medya Okuryazarlığı","Güvenlik"],"digital":["Yapay zekâ okuryazarlığı","Dijital ayak izi"],"duration":"40 dk","format":"İkili","tools":["Kulaklık","NavigAItor ses oynatıcı","Defter ve kalem"],"scenario":"Okul öğrenci meclisinin sosyal medya hesabından iki sesli mesaj yayıldı: birinde meclis başkanı yarınki gezinin iptal edildiğini, diğerinde gezinin yalnızca saatinin değiştiğini söylüyor. Sesler birbirine çok benziyor ve öğrenciler kafası karışmış durumda. Sen ve arkadaşın, meclisin 'doğrulama ekibi' olarak mesajları dinleyip kime, neye inanılması gerektiğini belirleyeceksiniz. Bir sesin tanıdık gelmesi, söylediklerinin doğru olduğunu gösterir mi?","visual":{"type":"sort","params":{"bins":["Güvenilirliği artırır","Şüphe uyandırır","Karar için yetersiz"],"items":[{"t":"Mesajda tarih ve saat açıkça söyleniyor","b":0},{"t":"Ses tonu cümle sonlarında tekdüze ve robotik","b":1},{"t":"Mesaj 'hemen herkese iletin' diye bitiyor","b":1},{"t":"Okulun resmî duyuru sayfasında aynı bilgi var","b":0},{"t":"Konuşmacının sesi tanıdık geliyor","b":2},{"t":"Arka planda okul zili sesi duyuluyor","b":2},{"t":"Mesaj, öğretmenin adını yanlış söylüyor","b":1}]},"caption":"Dinlediğin ipuçlarını güvenilirlik kutularına sürükle ve her kararını bir cümleyle gerekçelendir."},"steps":[{"title":"Yüzey Anlamı Belirle","mode":"İkili · 10 dk","items":["İki mesajı sırayla dinleyin.","Her mesaj için 5N1K tablosu doldurun: Kim konuşuyor? Ne söylüyor? Ne zaman, nerede? Nasıl? Neden?","İki mesaj arasındaki bilgi farklarını listeleyin."],"warn":"Sık yapılan hata: Dinlerken bilgiyi kendi beklentinle tamamlamak. Mesajda gerçekten söylenen ile senin anladığını tahmin ettiğin şeyi nasıl ayırırsın?"},{"title":"Satır Aralarını Dinle","mode":"İkili · 15 dk","items":["Mesajları tekrar dinleyin; ses tonu, vurgu, duraklama ve aciliyet ifadelerine dikkat edin.","Her mesajın dinleyiciden ne yapmasını istediğini çıkarın.","Görseldeki ipuçlarını kutulara yerleştirin ve gerekçelendirin."],"warn":"Sık yapılan hata: 'Ses aynı, o hâlde gerçek' diye düşünmek. Yapay zekâ araçlarının ses taklidi yapabildiğini bildiğine göre başka hangi kanıtlara ihtiyaç var?"},{"title":"Doğrulama Kararı ve Uyarı Mesajı","mode":"İkili · 15 dk","items":["Hangi mesajın daha güvenilir olduğuna dair kararınızı en az iki kanıtla yazın.","Kararı kesinleştirmek için hangi resmî kaynağa başvurulacağını belirtin.","Öğrencilere yönelik 60 kelimelik bir 'Paylaşmadan önce dur' uyarı mesajı yazın; kişileri suçlamayan bir dil kullanın."]}],"checklist":["Her iki mesajın yüzey anlamını 5N1K ile belirledim.","Mesajlar arasındaki bilgi farklarını listeledim.","Ses tonu ve aciliyet ifadelerinden çıkarım yaptım.","İpuçlarını güvenilirlik kutularına gerekçeyle yerleştirdim.","Kararımı kanıtlarla ve resmî kaynak önerisiyle yazdım.","Suçlamayan bir dille uyarı mesajı hazırladım."],"rubric":[{"k":"Yüzey Anlam","d":"Açıkça söylenen bilgileri eksiksiz belirleme","l4":"5N1K eksiksiz, bilgi farkları doğru","l3":"Bir eksik bilgi","l2":"Birden çok eksik ya da karışık bilgi","l1":"Yüzey anlam belirlenmemiş"},{"k":"Basit Çıkarım","d":"Ton, vurgu ve amaçtan anlam çıkarma","l4":"Amaç ve ton doğru çıkarılmış, kanıtla desteklenmiş","l3":"Çıkarım doğru, kanıt sınırlı","l2":"Çıkarım tahmine dayalı","l1":"Çıkarım yok"},{"k":"Doğrulama Muhakemesi","d":"Kanıta dayalı güvenilirlik kararı","l4":"2+ kanıt ve resmî kaynak önerisi","l3":"Kanıtlı karar, kaynak önerisi yok","l2":"Karar tek ipucuna dayalı","l1":"Karar gerekçesiz"},{"k":"Dijital Sorumluluk","d":"Uyarı mesajında dil ve etik","l4":"Açık, suçlamayan, uygulanabilir öneri","l3":"Açık ama öneri genel","l2":"Dil yer yer suçlayıcı","l1":"Mesaj yazılmamış"}],"navi":["Mesajda söylenmeyen ama senin 'duyduğunu' sandığın bir bilgi var mı?","Bir mesaj seni acele ettiriyorsa, bu durum onun hakkında ne düşündürebilir?","Bu mesajı sen yanlışlıkla paylaşmış olsaydın, dijital ayak izinde nasıl bir iz kalırdı?"],"diff":{"destek":"Mesajların yazılı dökümü verilir; 5N1K tablosu kısmen doldurulmuş olarak sunulur ve ipucu sayısı 4'e indirilir.","ileri":"Ses taklidi yapan içeriklerin fark edilmesi için arkadaşlarına yönelik 5 maddelik bir kontrol listesi hazırla ve her maddeyi bu etkinlikteki bir örnekle açıkla."},"misconception":"Tanıdık bir sesin ya da resmî görünen bir hesabın, mesajın doğru olduğunun kanıtı olduğu sanılır."},{"id":"tur-8-17","course":"TUR","grade":8,"themeNo":3,"themeName":"Doğa Ve İnsan","title":"Boş Arsanın Geleceği","subtitle":"Veriye dayalı ikna edici mektup ve bağlantı ifadeleri","kazanim":["İkna edici yazı yazabilme","Uygun bağlantı ifadelerini kullanabilme"],"skills21":["Sürdürülebilirlik","Eleştirel Düşünme","Veri Okuryazarlığı","Problem Çözme"],"digital":["Dijital çevre okuryazarlığı","Dijital savunuculuk"],"duration":"80 dk (2 ders)","format":"Bireysel","tools":["NavigAItor Stüdyo (metin editörü)","Defter ve kalem","Ücretsiz bir grafik oluşturma aracı"],"scenario":"Mahallendeki boş arsa için belediye iki seçeneği değerlendiriyor: 60 araçlık bir otopark ya da küçük bir mahalle ormanı ve oyun alanı. Mahalle sakinleriyle yapılan ankette görüşler bölünmüş durumda; yaz aylarında mahallede ölçülen sıcaklıklar ise çevredeki parklı mahallelerden daha yüksek çıkmış. Belediye, karar toplantısından önce gençlerin de görüşünü yazılı olarak almak istiyor. Seçtiğin görüşü hem verilerle hem de karşı tarafı dinleyerek nasıl savunursun?","visual":{"type":"pie","params":{"labels":["Mahalle ormanı ve oyun alanı","Otopark","Kararsız"],"values":[46,31,23]},"caption":"Anket sonuçlarını incele; kararsızların oranının mektubunda neden önemli olabileceğini not et."},"steps":[{"title":"Veriyi Oku, Tarafını Seç","mode":"Bireysel · 15 dk","items":["Pasta grafiği ve verilen sıcaklık ölçümlerini incele; üç önemli bulgu yaz.","Hangi seçeneği savunacağına karar ver ve tezini tek cümleyle yaz.","Karşı görüşün en güçlü gerekçesini dürüstçe yaz (ör. 'Mahallede park yeri sorunu var.')."],"warn":"Sık yapılan hata: Yalnızca kendi tarafını destekleyen veriyi kullanmak. Kararsız %23'ü ikna etmek için hangi veriyi görmezden gelmemen gerekir?"},{"title":"Mektubun Planını Kur","mode":"Bireysel · 15 dk","items":["Planı oluştur: giriş ve tez, birinci gerekçe ve veri, ikinci gerekçe ve örnek, karşı görüş ve yanıt, çağrı.","Her bölüm için kullanacağın bağlantı ifadelerini seç: ilk olarak, bunun yanı sıra, örneğin, buna karşın, her ne kadar... da, sonuç olarak.","Hedef okurunu düşün: belediye meclisi üyeleri ve mahalle sakinleri."]},{"title":"İkna Edici Mektubu Yaz","mode":"Bireysel · 30 dk","items":["250–300 kelimelik mektubunu NavigAItor Stüdyo'da yaz.","En az bir sayısal veriyi, kaynağını belirterek kullan.","En az beş farklı bağlantı ifadesi kullan ve her birinin işlevine (ekleme, karşıtlık, örnekleme, sonuç) uygun olmasına dikkat et."],"warn":"Sık yapılan hata: Bağlantı ifadelerini anlamına bakmadan art arda dizmek (ör. iki benzer düşünceyi 'ancak' ile bağlamak). Bir bağlacı çıkardığında cümleler arasındaki ilişki değişiyor mu?"},{"title":"Gözden Geçir ve Dijital Çağrıya Dönüştür","mode":"Bireysel · 20 dk","items":["Mektubundaki bağlantı ifadelerini renklendir; işlevini yanlarına yaz ve uygun olmayanları değiştir.","Yazım ve noktalama denetimi yap.","Mektubunun ana fikrini, okul panosunda paylaşılabilecek 40 kelimelik bir dijital afiş metnine ve basit bir grafiğe dönüştür."]}],"checklist":["Tezimi tek ve açık bir cümleyle yazdım.","En az bir veriyi kaynağıyla kullandım.","Karşı görüşü dürüstçe aktarıp yanıtladım.","En az beş farklı bağlantı ifadesini işlevine uygun kullandım.","Yazım ve noktalama kontrolünü yaptım.","Mektubumu kısa bir dijital afiş metnine dönüştürdüm."],"rubric":[{"k":"Tez ve Gerekçeler","d":"Açık tez, veriyle desteklenmiş gerekçeler","l4":"Tez net, iki gerekçe veri ve örnekle güçlü","l3":"Tez net, bir gerekçe zayıf","l2":"Tez belirsiz ya da gerekçe tek","l1":"Tez yok"},{"k":"Karşı Görüş","d":"Karşı görüşü adil aktarıp yanıtlama","l4":"Karşı görüş güçlü aktarılmış, ikna edici yanıt","l3":"Karşı görüş var, yanıt yüzeysel","l2":"Karşı görüş küçümsenmiş","l1":"Karşı görüş yok"},{"k":"Bağlantı İfadeleri","d":"Çeşitli ve işlevine uygun bağlantılar","l4":"5+ farklı bağlantı, tümü işlevine uygun","l3":"4–5 bağlantı, biri yanlış işlevde","l2":"Az ve tekrarlı bağlantı","l1":"Bağlantı ifadesi yok"},{"k":"Dil, Yazım ve Okura Uygunluk","d":"Hedef okura uygun, kurallara uygun dil","l4":"Saygılı, akıcı, hatasız denecek kadar temiz","l3":"Uygun dil, birkaç hata","l2":"Dil yer yer kaba ya da hatalar fazla","l1":"Okura uygun değil"}],"navi":["Otoparkı savunan bir komşun mektubunu okusaydı, hangi cümlende 'Evet, beni anlamış' derdi?","Sıcaklık verisi tek başına bir karar için yeterli mi? Başka hangi bilgi işine yarardı?","'Ancak' yerine 'üstelik' yazsaydın, okur o iki cümle arasındaki ilişkiyi nasıl anlardı?"],"diff":{"destek":"Bölüm başlıklı bir mektup şablonu ve işlevlerine göre gruplanmış bağlantı ifadesi bankası verilir; hedef uzunluk 150 kelimeye indirilir.","ileri":"Mektubuna iki seçeneğin uzun vadeli etkilerini karşılaştıran küçük bir tablo ekle ve 'ortak çözüm' içeren üçüncü bir seçenek öner."},"misconception":"İkna edici yazının yalnızca kendi görüşünü güçlü sözcüklerle tekrarlamak olduğu ve bağlantı ifadelerinin cümleleri süslemek için kullanıldığı sanılır."},{"id":"tur-8-18","course":"TUR","grade":8,"themeNo":4,"themeName":"Türk Hikâye Geleneği Ve Destanları","title":"Ozanın Kayıp Defteri","subtitle":"Destan tadında bir hikâyede hikâye unsurlarını çözümleme ve yeni bir bölüm yazma","kazanim":["Öyküleyici metinde hikâye unsurlarını belirlemeye yönelik çözümleme yapabilme","Yaratıcı yazı yazabilme"],"skills21":["Yaratıcılık","Kültürel Farkındalık","Eleştirel Düşünme","İletişim"],"digital":["Dijital hikâye anlatıcılığı","Dijital sanat"],"duration":"120 dk (3 ders)","format":"Bireysel + Grup","tools":["NavigAItor metin okuyucu","Ücretsiz bir dijital çizgi roman aracı","Defter ve kalem"],"scenario":"Bir köy evinin tavan arasında, eski bir ozana ait olduğu düşünülen bir defter bulundu. Defterde, kuraklık çeken bir obayı kurtarmak için 'Dokuz Pınar'ın kaynağını arayan genç bir kızın hikâyesi yazıyor; ancak son sayfalar yırtılmış. Belediyenin kültür birimi, hikâyeyi dijital çizgi roman olarak yayımlamak ve eksik sonu gençlere yazdırmak istiyor. Hikâyenin dünyasına sadık kalarak onu nasıl tamamlarsın?","visual":{"type":"organizer","params":{"kind":"hikaye","slots":["Kahraman","Yardımcılar ve karşıtlar","Yer","Zaman","Çatışma","Olay örgüsü","Çözüm (yırtık sayfa)"]},"caption":"Hikâye haritasını metinden bulduğun bilgilerle doldur; 'Çözüm' kutusunu kendi yazacağın son için boş bırak."},"steps":[{"title":"Hikâyeyi Oku ve Haritala","mode":"Bireysel · 25 dk","items":["Ozanın defterindeki hikâyeyi oku.","Hikâye haritasını doldur: kahraman, yardımcı ve karşıt kişiler, yer, zaman, çatışma ve olay örgüsü.","Her kutu için metinden bir kanıt cümlesi yaz."],"warn":"Sık yapılan hata: Zaman unsurunu yalnızca 'eskiden' diye geçmek. Metindeki hangi ipuçları (mevsim, gün ışığı, yolculuğun süresi) zamanı daha açık gösteriyor?"},{"title":"Destan İzlerini Bul","mode":"Grup · 20 dk","items":["Hikâyede geleneksel anlatılara özgü ögeleri arayın: olağanüstü olaylar, sembolik sayılar, yol gösteren yaşlı bilge, sınav ya da yolculuk motifi.","Bulduğunuz ögelerin hikâyedeki işlevini tartışın.","Çatışmanın türünü belirleyin: insan–doğa, insan–insan, insanın kendisiyle mücadelesi."],"warn":"Sık yapılan hata: Çatışmayı yalnızca 'kötü karakterle kavga' olarak düşünmek. Bu hikâyede kahramanın asıl mücadelesi neyle?"},{"title":"Yırtık Sayfaları Yaz","mode":"Bireysel · 40 dk","items":["Hikâyenin sonunu 200–250 kelimeyle yaz; kahramanın karakterine ve hikâyenin diline sadık kal.","En az bir geleneksel anlatı motifi kullan ve çatışmayı mantıklı bir biçimde çöz.","Sonunu yazmadan önce iki farklı son taslağı düşün ve neden birini seçtiğini bir cümleyle not et."]},{"title":"Dijital Çizgi Romana Dönüştür","mode":"Grup · 35 dk","items":["Gruptaki sonlardan birini seçin ve ücretsiz bir dijital çizgi roman aracıyla 4–6 karelik bir sahne dizisi hazırlayın.","Her karede anlatıcı kutusu ya da konuşma balonu kullanın.","Çizgi romanı sınıfla paylaşın ve hangi hikâye unsurunu görselle nasıl anlattığınızı açıklayın."]}],"checklist":["Hikâye haritasının tüm kutularını metinden kanıtla doldurdum.","Hikâyedeki geleneksel anlatı ögelerini ve işlevlerini belirledim.","Çatışmanın türünü doğru adlandırdım.","Hikâyenin sonunu karakter ve dile sadık kalarak yazdım.","Yazdığım sonda en az bir geleneksel motif kullandım.","Çizgi roman karelerine katkı verdim ve sunumda açıklama yaptım."],"rubric":[{"k":"Hikâye Unsurlarını Çözümleme","d":"Unsurları metinden kanıtla belirleme","l4":"Tüm unsurlar kanıtlı ve doğru","l3":"Bir unsur eksik ya da kanıtsız","l2":"Birden çok unsur eksik","l1":"Harita doldurulmamış"},{"k":"Geleneksel Anlatı Farkındalığı","d":"Motifleri ve işlevlerini tanıma","l4":"3+ motif ve işlevleri açıklanmış","l3":"2 motif, işlev kısmen","l2":"Motif adı var, işlev yok","l1":"Motif belirlenmemiş"},{"k":"Yaratıcı Yazı","d":"Tutarlı, özgün ve hikâyeye uygun son","l4":"Özgün, karakterle tutarlı, çatışma mantıklı çözülmüş","l3":"Tutarlı ama öngörülebilir","l2":"Hikâyeyle kısmen uyumsuz","l1":"Son yazılmamış"},{"k":"Dijital Hikâyeleme","d":"Unsurların görsel anlatıma aktarımı","l4":"Kareler akışı ve unsurları açıkça taşıyor","l3":"Akış var, bir unsur belirsiz","l2":"Kareler kopuk","l1":"Çizgi roman tamamlanmamış"}],"navi":["Kahramanın başından beri taşıdığı bir eşya ya da söylediği bir söz, sonda bir anlam kazanabilir mi?","Ozan bu hikâyeyi bir obanın ortasında anlatsaydı, dinleyenler hangi anda en çok heyecanlanırdı?","Senin sonun, hikâyenin başındaki soruna gerçekten yanıt veriyor mu?"],"diff":{"destek":"Hikâye haritası için kutulara göre yönlendirici sorular verilir; son yazma için 3 olası başlangıç cümlesinden biri seçilir ve uzunluk 120 kelimeye indirilir.","ileri":"Hikâyeyi yan karakterlerden birinin bakış açısıyla yeniden anlatan kısa bir bölüm yaz ve bakış açısı değişince hangi unsurların değiştiğini açıkla."},"misconception":"Çatışmanın yalnızca kahraman ile kötü karakter arasındaki kavga olduğu ve zamanın her zaman açık bir tarihle verildiği sanılır."},{"id":"tur-8-19","course":"TUR","grade":8,"themeNo":5,"themeName":"Sanat Ve Estetik","title":"Sanal Müzede Sesli Rehber","subtitle":"İki sanat eserini karşılaştırarak sözlü eleştiri yapma","kazanim":["Eleştirisini sözlü olarak ifade edebilme","Konuşmasında karşılaştırma yapabilme"],"skills21":["Estetik","Eleştirel Düşünme","Kültürel Farkındalık","İletişim"],"digital":["Sanal müze gezisi","Dijital sergi"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Sanal müze turu sunan ücretsiz bir web sitesi","Ücretsiz bir ses kayıt uygulaması","Defter ve kalem"],"scenario":"Okulunuz, 'Sanatla Bak' adlı dijital sergisi için öğrencilerden sesli rehber kayıtları istiyor. Sanal müze gezisinde biri geleneksel Türk sanatından, diğeri farklı bir kültürden ya da dönemden iki eser seçeceksin. Ziyaretçiler yalnızca 'bu eser güzel' değil, eserlere neden ve nasıl bakmaları gerektiğini duymak istiyor. İki eseri yan yana koyduğunda, onları değerlendirmek için hangi ölçütleri kullanırsın?","visual":{"type":"cards","params":{"items":[{"w":"Kompozisyon","tr":"Eserdeki ögelerin yerleşim düzeni","ic":"🧩"},{"w":"Kontrast","tr":"Renk, ışık ya da biçimdeki belirgin karşıtlık","ic":"🌗"},{"w":"Simetri","tr":"Bir eksenin iki yanındaki denge ve benzerlik","ic":"🪞"},{"w":"Motif","tr":"Tekrarlanan süsleme ya da biçim birimi","ic":"🌷"},{"w":"Perspektif","tr":"Derinlik ve uzaklık duygusu yaratma yolu","ic":"🛤️"},{"w":"Ritim","tr":"Ögelerin tekrarıyla oluşan görsel akış","ic":"🎵"}]},"caption":"Kartları çevirerek sanat terimlerinin anlamlarını öğren; sesli rehberinde en az üçünü kullanacağın kartları işaretle."},"steps":[{"title":"Sanal Müzeyi Gez ve Seç","mode":"Bireysel · 20 dk","items":["Sanal müze turunda en az beş eseri incele ve karşılaştırılabilecek iki eser seç.","Her eser için künye bilgilerini (eser adı, tür, yaklaşık dönem, bulunduğu müze) not al.","İlk izlenimini her eser için üç sözcükle yaz."]},{"title":"Karşılaştırma Tablosu Kur","mode":"Bireysel · 20 dk","items":["İki eseri aynı ölçütlerle karşılaştır: konu, renk kullanımı, kompozisyon, motif, uyandırdığı duygu.","Her ölçütte benzerlik ve farkı ayrı ayrı yaz.","Eleştirini oluştur: Her eserin güçlü bir yönünü ve tartışmaya açık bir yönünü gerekçesiyle belirt."],"warn":"Sık yapılan hata: Eleştiriyi yalnızca olumsuz yorum yapmak sanmak. Bir eseri gerekçeli olarak takdir etmek de eleştiri midir?"},{"title":"Sesli Rehberi Yapılandır ve Kaydet","mode":"Bireysel · 20 dk","items":["2 dakikalık konuşmanı planla: dikkat çeken giriş, iki eserin tanıtımı, karşılaştırma, kişisel eleştiri, ziyaretçiye bir bakma önerisi.","Karşılaştırma ifadelerini kullan: her ikisinde de, buna karşılık, öte yandan, benzer biçimde.","Kartlardaki terimlerden en az üçünü yerinde kullanarak kaydını yap."],"warn":"Sık yapılan hata: Eserleri sırayla ayrı ayrı anlatıp karşılaştırmayı hiç yapmamak. Dinleyici iki eser arasındaki ilişkiyi konuşmanın hangi anında duymalı?"},{"title":"Dinle, Sor, Geliştir","mode":"Grup · 20 dk","items":["Dörtlü gruplarda kayıtları dinleyin.","Her dinleyici bir takdir cümlesi ve bir soru yazsın (ör. 'Bu eserde ritmi nerede görüyorsun?').","Gelen sorulardan birine yanıt veren 20 saniyelik bir ek kayıt hazırlayın ve dijital sergi sayfasına yükleyin."]}],"checklist":["İki eserin künye bilgilerini doğru not aldım.","Eserleri aynı ölçütlerle karşılaştırdım.","Her eser için gerekçeli bir güçlü ve bir tartışmaya açık yön belirttim.","Konuşmamda karşılaştırma ifadeleri kullandım.","En az üç sanat terimini doğru anlamıyla kullandım.","Arkadaşlarımın sorusuna yanıt veren ek kaydı hazırladım."],"rubric":[{"k":"Karşılaştırma","d":"Ortak ölçütlerle benzerlik ve farkları ortaya koyma","l4":"4+ ölçüt, benzerlik ve farklar dengeli","l3":"3 ölçüt, biri yüzeysel","l2":"Eserler ayrı ayrı anlatılmış","l1":"Karşılaştırma yok"},{"k":"Gerekçeli Eleştiri","d":"Takdir ve sorgulamayı gerekçelerle ifade etme","l4":"Her eser için güçlü ve tartışmalı yön gerekçeli","l3":"Gerekçe bir eserde zayıf","l2":"'Güzel/güzel değil' düzeyinde","l1":"Eleştiri yok"},{"k":"Söz Varlığı","d":"Sanat terimlerini ve karşılaştırma ifadelerini yerinde kullanma","l4":"3+ terim ve çeşitli karşılaştırma ifadeleri doğru","l3":"2 terim doğru","l2":"Terim yanlış ya da tek","l1":"Terim kullanılmamış"},{"k":"Sözlü Anlatım","d":"Yapı, ses, akıcılık ve süre","l4":"Yapı net, ses canlı, süreye uygun","l3":"Yapı net, akıcılık kısmi","l2":"Dağınık ya da süre aşılmış","l1":"Kayıt tamamlanmamış"}],"navi":["İki eseri birbirine benzetmek mi, birbirinden ayırmak mı daha kolay oldu? Neden?","Ziyaretçi senin rehberini dinledikten sonra esere ilk kez baktığında neyi fark etsin istersin?","Bir eseri beğenmemen, onun kötü bir eser olduğu anlamına mı gelir?"],"diff":{"destek":"Öğretmen iki eseri önceden seçer; öğrenciye hazır ölçüt tablosu ve konuşma için bölüm başlıklı bir şablon verilir, kayıt süresi 1 dakikaya indirilir.","ileri":"Üçüncü bir eser ekleyerek 'aynı tema, üç farklı bakış' başlıklı 3 dakikalık bir rehber hazırla ve eserlerin ortaya çıktığı dönem koşullarının bakış farkına etkisini yorumla."},"misconception":"Eleştirinin bir esere yalnızca kusur bulmak olduğu ve kişisel beğeninin gerekçe gerektirmeyen yeterli bir ölçüt olduğu sanılır."},{"id":"tur-8-20","course":"TUR","grade":8,"themeNo":6,"themeName":"Akademik Düşünme Dünyası","title":"Gürültünün İzinde","subtitle":"Bilimsel bir sohbet yayınını dinleyerek önemli bilgileri belirleme ve çözüm üretme","kazanim":["Bilgilendirici metinde metin yapılarından hareketle önemli bilgileri belirlemeye yönelik çözümleme yapabilme","Dinlediğindeki/izlediğindeki probleme çözüm üretebilme"],"skills21":["Eleştirel Düşünme","Bilgi Okuryazarlığı","Problem Çözme","Algoritmik Düşünme","Araştırma"],"digital":["Dijital raporlama","Algoritmik düşünme","Dijital etik"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Kulaklık","NavigAItor ses oynatıcı","Ücretsiz bir akış şeması aracı","Defter ve kalem"],"scenario":"Okulunuzun bilim kulübü, 'Sınıfta gürültü dikkatimizi nasıl etkiler?' konulu 6 dakikalık bir bilim sohbeti yayınını dinleyip okul için bir eylem planı hazırlamak istiyor. Yayında bir araştırmacı, problemi, yapılan ölçümleri, karşılaştırmaları ve sonuçları anlatıyor. Kulübün genç araştırmacısı olarak senden önemli bilgileri ayıklamanı ve kendi okulunuz için uygulanabilir bir çözüm tasarlamanı istiyorlar. Dinlediğin bilgilerden hangileri gerçekten önemli ve bu bilgiler hangi çözüme işaret ediyor?","visual":{"type":"flow","params":{"kind":"algoritma","steps":["Problemi tanımla","Ölçüm yap (desibel)","Eşik değeri aştı mı?","Evet: kaynağı belirle ve önlem uygula","Hayır: izlemeye devam et","Sonucu kaydet ve karşılaştır"]},"caption":"Yayında duyduğun bilgilerle akış şemasının adımlarını sırala ve karar kutusunu kendi okulun için düzenle."},"steps":[{"title":"Yayının Yapısını Yakala","mode":"Bireysel · 20 dk","items":["Yayını dinlerken notlarını 'Problem / Yöntem / Bulgular / Sonuç ve öneri' başlıklarıyla dört bölüme ayır.","'İlk olarak', 'bunun sonucunda', 'buna karşılık', 'kısacası' gibi yapı ipuçlarını duyduğunda not al; bunlar bir sonraki önemli bilginin habercisidir.","Duyduğun sayısal bilgileri (ör. ölçülen ses düzeyleri, karşılaştırılan sınıf sayısı) ayrı bir köşeye yaz."],"warn":"Sık yapılan hata: Duyduğun her cümleyi yazmaya çalışmak. Bir bilginin 'önemli' olduğunu yayının yapısındaki hangi ipuçlarından anlarsın?"},{"title":"Önemli Bilgiyi Ayıkla","mode":"Bireysel · 15 dk","items":["Notlarından en önemli beş bilgiyi seç ve her birinin yanına neden önemli olduğunu yaz.","Örnek ya da ayrıntı olan bilgileri ana bilgilerden ayır.","Araştırmacının ulaştığı sonucu 40 kelimeyle özetle; yayına kaynak olarak atıf yap."],"warn":"Sık yapılan hata: İlginç bir örneği ana bulgu sanmak. Bu bilgi çıkarılsa araştırmanın sonucu değişir miydi?"},{"title":"Akış Şemasıyla Çözüm Tasarla","mode":"Grup · 30 dk","items":["Grup olarak okulunuzdaki gürültü sorununu bir cümleyle tanımlayın (ör. teneffüs sonrası ilk 10 dakika).","Yayındaki bulgulara dayanarak üç çözüm önerin; her birinin hangi bulguya dayandığını belirtin.","Seçtiğiniz çözümü ücretsiz bir akış şeması aracıyla adım adım gösterin; en az bir karar kutusu kullanın."]},{"title":"Mini Rapor ve Öz Değerlendirme","mode":"Bireysel · 15 dk","items":["Yarım sayfalık dijital rapor hazırla: problem, yayından üç önemli bilgi, çözüm, kaynak.","Raporda kendi cümlelerini kullan; alıntı yaptığın yerleri tırnak içinde ve kaynağıyla göster.","Dinleme sürecini değerlendir: Hangi not alma yöntemi işine yaradı, bir dahaki sefere neyi değiştirirsin?"]}],"checklist":["Notlarımı yayının bölümlerine göre düzenledim.","Yapı ipuçlarını kullanarak önemli bilgileri belirledim.","Ana bilgiyi örnek ve ayrıntıdan ayırdım.","Çözüm önerimi yayındaki bulgulara dayandırdım.","Akış şemasında en az bir karar kutusu kullandım.","Raporumda kaynağı belirttim ve alıntıları doğru gösterdim."],"rubric":[{"k":"Metin Yapısını Kullanma","d":"Problem-yöntem-bulgu-sonuç yapısını ve ipuçlarını fark etme","l4":"Dört bölüm net, ipuçları bilinçli kullanılmış","l3":"Bölümler var, ipucu kullanımı sınırlı","l2":"Notlar düzensiz","l1":"Yapı fark edilmemiş"},{"k":"Önemli Bilgiyi Belirleme","d":"Ana bilgi ile ayrıntıyı ayırma ve gerekçelendirme","l4":"5 ana bilgi doğru ve gerekçeli","l3":"3–4 ana bilgi doğru","l2":"Ayrıntılar ana bilgiyle karışık","l1":"Önemli bilgi belirlenmemiş"},{"k":"Çözüm Üretme","d":"Bulgulara dayalı, uygulanabilir çözüm ve akış şeması","l4":"Çözüm bulgulara bağlı, akış şeması mantıklı ve karar içeriyor","l3":"Çözüm uygun, şemada karar eksik","l2":"Çözüm bulgularla ilişkisiz","l1":"Çözüm yok"},{"k":"Raporlama ve Akademik Etik","d":"Kendi cümleleri, kaynak gösterme, öz değerlendirme","l4":"Özgün dil, kaynak ve alıntı doğru, öz değerlendirme somut","l3":"Kaynak var, öz değerlendirme genel","l2":"Yayından cümleler kaynaksız aktarılmış","l1":"Rapor tamamlanmamış"}],"navi":["Araştırmacı bir bilgiden önce sesini değiştirdi ya da 'en önemlisi' dedi mi? Bu sana ne anlattı?","Önerdiğin çözüm işe yarayıp yaramadığını nasıl ölçerdin?","Yayında anlatılan okul seninkinden farklıysa, sonuçları olduğu gibi kullanabilir misin?"],"diff":{"destek":"Yayının yazılı dökümü ve dört başlıklı hazır not çerçevesi verilir; öğrenci beş yerine üç önemli bilgi seçer ve akış şeması için hazır adım kartlarını sıralar.","ileri":"Okulunda bir hafta boyunca ücretsiz bir ses ölçer uygulamasıyla basit ölçümler yap, verileri tabloya dök ve yayındaki bulgularla karşılaştıran kısa bir araştırma posteri hazırla."},"misconception":"Dinlenen bilgilendirici bir metinde en çok akılda kalan ya da en ilginç bilginin, en önemli bilgi olduğu sanılır."},{"id":"mat-5-01","course":"MAT","grade":5,"themeNo":1,"themeName":"Sayılar Ve Nicelikler (1)","title":"Turnuva Yolculuğu","subtitle":"Doğal sayılarla problem çözme ve dijital harita","kazanim":["Doğal sayılar ve işlemler içeren gerçek yaşam problemlerini çözebilme"],"skills21":["Problem Çözme","Analitik Düşünme","Bilgi Okuryazarlığı","Finansal Okuryazarlık","Esneklik"],"digital":["Dijital Okuryazarlık","Bilgi Okuryazarlığı","Matematiksel Araç ve Teknoloji ile Çalışma"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Dijital harita uygulaması","Hesap makinesi","Kâğıt-kalem","NavigAItor Stüdyo"],"scenario":"Okulunun voleybol takımı il dışındaki bir turnuvaya davet edildi; takım ve taraftarlarla birlikte 168 öğrenci ve 12 öğretmen yola çıkacak. Otobüsler 46 kişilik ve otobüs firması gidiş-dönüş her kilometre için otobüs başına 30 TL istiyor. Okul aile birliği yolculuk için en fazla 60 000 TL ayırabildi. Turnuva üç şehirde yapılıyor: Bursa, Eskişehir ve Ankara. Ulaşım sorumlusu sensin: Kaç otobüs gerekir ve hangi şehre gitmek bu sınırın içinde kalır?","visual":{"type":"map","params":{"region":"turkiye","pins":[{"label":"İstanbul (okul)","x":22,"y":25},{"label":"Bursa","x":22,"y":36},{"label":"Eskişehir","x":32,"y":38},{"label":"Ankara","x":42,"y":40}]},"caption":"Okulun bulunduğu şehirden her turnuva şehrine olan yolu harita üzerinde izleyip mesafeleri not edersin."},"steps":[{"title":"Problemi Parçalara Ayır","mode":"Bireysel · 15 dk","items":["Verilenleri ve istenenleri iki ayrı sütunda listele.","Toplam yolcu sayısını bul; kaç otobüs gerektiğini bölme işlemiyle hesapla.","Hesaplamadan önce tahmin yaz: Sence en uzak şehir sınırın içinde kalır mı?"],"warn":"Sık yapılan hata: 180 ÷ 46 işleminin kalanını yok saymak. Kalan yolcular da bir otobüse binmek zorunda; kalan varsa ne yapmalısın?"},{"title":"Mesafeleri Güvenilir Kaynaktan Bul","mode":"İkili · 15 dk","items":["Dijital harita uygulamasında okuldan Bursa, Eskişehir ve Ankara'ya karayolu mesafesini bul (yaklaşık değer yeterli: sırasıyla yaklaşık 155, 330 ve 450 km).","Bulduğun mesafeyi ikinci bir kaynakla karşılaştır; iki kaynak arasında büyük fark varsa nedenini tartış.","Gidiş-dönüş mesafesini her şehir için hesapla."]},{"title":"Maliyeti Hesapla ve Karşılaştır","mode":"Bireysel · 20 dk","items":["Bir otobüsün gidiş-dönüş maliyetini (km × 30 TL) her şehir için bul.","Otobüs sayısıyla çarparak toplam maliyeti bul ve 60 000 TL ile karşılaştır.","Sonuçları bir tabloya yerleştir: şehir, gidiş-dönüş km, otobüs başı maliyet, toplam maliyet, sınırın içinde mi?"],"warn":"Sık yapılan hata: Mesafeyi yalnızca gidiş için hesaplamak. Otobüs geri de dönecek; tablondaki km değerlerini kontrol et."},{"title":"Plan Değişirse?","mode":"Grup · 20 dk","items":["İki öğretmen daha katılırsa otobüs sayısı değişir mi? Neden?","Firma fiyatı km başına 25 TL'ye düşürürse hangi şehirler sınırın içine girer?","Grubunuzun önerisini NavigAItor Stüdyo'da kısa bir 'ulaşım raporu' olarak yazın ve çözüm yolunuzu gösterin."]}],"checklist":["Toplam yolcu ve otobüs sayısını hesapladım.","Mesafeleri iki farklı kaynaktan kontrol ettim.","Gidiş-dönüş maliyetlerini tabloya yazdım.","Her şehri 60 000 TL ile karşılaştırdım.","Plan değiştiğinde sonucun nasıl değiştiğini açıkladım.","İşlemlerimi tahminimle karşılaştırdım."],"rubric":[{"k":"Problemi anlama","d":"Verilen ve istenenleri doğru belirleme","l4":"Tüm verilenleri ve istenenleri eksiksiz, düzenli listeler","l3":"Çoğunu doğru belirler, bir küçük eksik vardır","l2":"Bazı önemli bilgileri atlar","l1":"Verilen ve istenenleri ayırt edemez"},{"k":"İşlem doğruluğu","d":"Bölme, çarpma ve karşılaştırma işlemleri","l4":"Kalanı yorumlar, tüm işlemler doğru","l3":"Bir küçük işlem hatası vardır","l2":"Kalan ya da gidiş-dönüş gibi önemli bir adımı atlar","l1":"İşlemlerin çoğu hatalıdır"},{"k":"Bilgiye ulaşma","d":"Mesafeleri dijital kaynaklardan bulup doğrulama","l4":"İki kaynağı karşılaştırır, farkları açıklar","l3":"Bir kaynaktan doğru bilgi bulur","l2":"Bilgiyi bulur ama kaynağını belirtmez","l1":"Bilgiyi kendi başına bulamaz"},{"k":"Karar ve esneklik","d":"Koşul değiştiğinde çözümü uyarlama","l4":"Her yeni koşulda çözümü güncelleyip gerekçelendirir","l3":"Yeni koşulların çoğunu doğru yorumlar","l2":"Yeni koşulu yalnızca kısmen ele alır","l1":"Çözümü yeni koşula uyarlayamaz"}],"navi":["Otobüse binemeyen yolcu kalırsa bu, otobüs sayısı hakkında sana ne söyler?","Toplam maliyeti bulmadan önce, hangi şehrin sınırı aşacağını sadece mesafelere bakarak tahmin edebilir misin?"],"diff":{"destek":"Yolcu sayısını 90'a, otobüs kapasitesini 45'e indir ve yalnızca Bursa için maliyet hesapla.","ileri":"Kişi başı maliyeti en düşük yapan seçeneği bul; otobüs yerine 30 kişilik midibüs seçeneği eklenirse plan nasıl değişir?"},"misconception":"Bölme işleminde kalanın problem bağlamında anlamsız olduğunu düşünüp otobüs sayısını aşağı yuvarlamak."},{"id":"mat-5-02","course":"MAT","grade":5,"themeNo":2,"themeName":"Sayılar Ve Nicelikler (2)","title":"Kim Daha Çok Yedi?","subtitle":"Kesirleri farklı gösterimlerle karşılaştırma — pizza modeli","kazanim":["Farklı gösterimlerle ifade edilen kesirlerin karşılaştırılmasına yönelik çıkarım yapabilme","Gerçek yaşam durumlarına karşılık gelen kesirleri farklı biçimlerde temsil edebilme"],"skills21":["Yaratıcılık","İletişim","İş Birliği","Sorumlu Karar Verme"],"digital":["Dijital Araç Kullanımı","Dijital Sunum"],"duration":"40 dk","format":"İkili","tools":["NavigAItor pizza modeli","Sayı doğrusu şeridi (kâğıt)","Renkli kalemler"],"scenario":"Sınıfınızın pizza gününde aynı büyüklükte iki pizza sipariş edildi. Masa A pizzasının 3/4'ünü, Masa B ise 5/8'ini yedi. Masa C'dekiler kendi pizzalarının %60'ını, Masa D'dekiler 0,7'sini yediklerini söylüyor. Artan dilimler eşit paylaşılacak ve hakem sensin. Hangi masa en çok yedi, hangi masada en çok pizza kaldı?","visual":{"type":"pizza","params":{"pizzas":2,"target":["3/4","5/8"],"maxCut":8},"caption":"İki pizzayı eş parçalara bölüp Masa A'nın 3/4'ünü ve Masa B'nin 5/8'ini boyarsın."},"steps":[{"title":"Tahmin Et","mode":"Bireysel · 5 dk","items":["Hiç hesap yapmadan 3/4, 5/8, %60 ve 0,7'yi küçükten büyüğe sırala ve defterine yaz.","Tahminini neye dayanarak yaptığını bir cümleyle açıkla."]},{"title":"Pizzaları Kes ve Boya","mode":"İkili · 15 dk","items":["Birinci pizzayı 4 eş dilime bölüp 3'ünü boya; ikinci pizzayı 8 eş dilime bölüp 5'ini boya.","Birinci pizzayı da 8 eş dilime bölersen boyalı kaç dilim olur? Bu sana 3/4 hakkında ne söyler?","Her masada artan kısmı kesir olarak yaz."],"warn":"Sık yapılan hata: '5, 3'ten büyük, o hâlde 5/8 daha büyük' demek. Dilimlerin büyüklüğü aynı mı? Pizzalara tekrar bak."},{"title":"Dört Gösterimi Tek Doğruda Buluştur","mode":"İkili · 12 dk","items":["0 ile 1 arasını 10 eş parçaya bölen bir sayı doğrusu çiz; %60 ve 0,7'yi yerleştir.","3/4 ve 5/8'in yerini pizzalarından yararlanarak yaklaşık olarak göster.","Dört değeri sırala ve ilk tahminini kontrol et."],"warn":"Sık yapılan hata: %60'ı 60 bütün sanmak. Yüzde, bir bütünün 100 eş parçasından kaçının alındığını gösterir."},{"title":"Hakem Kararını Açıkla","mode":"İkili · 8 dk","items":["Kararınızı kesir, ondalık ve yüzde kullanarak üç cümlelik bir 'hakem duyurusu' olarak yazın.","Hangi gösterimin karşılaştırmayı en kolay yaptığını tartışın ve gerekçenizi ekleyin."]}],"checklist":["Önce tahmin yaptım, sonra kontrol ettim.","İki pizzayı doğru sayıda eş parçaya böldüm.","3/4'ü sekizde birlerle ifade ettim.","Dört değeri sayı doğrusuna yerleştirdim.","Artan miktarları kesirle yazdım.","En kullanışlı gösterimi gerekçesiyle seçtim."],"rubric":[{"k":"Modelleme","d":"Pizza modelinde kesirleri doğru gösterme","l4":"İki kesri doğru böler, denk kesri modelde gösterir","l3":"Kesirleri doğru gösterir, denk kesri açıklamakta zorlanır","l2":"Dilimleri eş olmayan parçalara böler","l1":"Modeli kesirle ilişkilendiremez"},{"k":"Karşılaştırma","d":"Farklı gösterimleri sıralama","l4":"Dört değeri doğru sıralar ve gerekçelendirir","l3":"Sıralama doğru, gerekçe eksik","l2":"İki değeri doğru karşılaştırır","l1":"Pay ya da paydaya bakarak yanlış sıralar"},{"k":"Gösterimler arası geçiş","d":"Kesir, ondalık ve yüzde ilişkisini kurma","l4":"Üç gösterim arasında rahatça geçiş yapar","l3":"İki gösterim arasında geçiş yapar","l2":"Geçişi yalnızca destekle yapar","l1":"Gösterimleri ilişkilendiremez"},{"k":"İletişim","d":"Hakem duyurusunun açıklığı","l4":"Açık, matematiksel dil doğru, gerekçeli","l3":"Açık ama gerekçe kısa","l2":"Karar var, gerekçe yok","l1":"Karar anlaşılmıyor"}],"navi":["İki pizza aynı büyüklükteyse, 4'e bölünen pizzanın bir dilimi mi yoksa 8'e bölünenin bir dilimi mi daha büyüktür?","%60 ile 0,7'yi aynı biçimde yazmanın bir yolu var mı?"],"diff":{"destek":"Yalnızca 3/4 ve 5/8'i pizza modeliyle karşılaştır; yüzde ve ondalık kısmını öğretmeninle birlikte yap.","ileri":"Masa E pizzasının 2/3'ünü yedi. Bu masayı sıralamada nereye koyarsın? Pizzayı kaç parçaya bölmen gerekir?"},"misconception":"Paydası ya da payı büyük olan kesrin her zaman daha büyük olduğunu düşünmek."},{"id":"mat-5-03","course":"MAT","grade":5,"themeNo":3,"themeName":"İşlemlerle Cebirsel Düşünme","title":"Pazar Terazisi Dengede mi?","subtitle":"Eşitliğin korunumu ve işlem özellikleri — terazi modeli","kazanim":["Eşitliğin korunumuna ve işlem özelliklerine yönelik çıkarım yapabilme"],"skills21":["Sistematik Düşünme","Problem Çözme","Öz Düzenleme","Esneklik"],"digital":["Hesaplamalı Düşünme / Algoritma Okuryazarlığı","Dijital Modelleme"],"duration":"40 dk","format":"Bireysel + Grup","tools":["NavigAItor terazi modeli","Kâğıt-kalem","Renkli yapışkan notlar"],"scenario":"Mahalle pazarındaki bir tezgâhta iki kefeli eski bir terazi var. Sol kefede 8 kg ve 5 kg'lık iki torba, sağ kefede 6 kg'lık bir torba ile bilinmeyen bir torba duruyor ve terazi dengede. Tezgâh sahibi yardım istiyor: 'Bilinmeyen torba kaç kilogram? Her iki kefeye aynı ağırlığı eklersem denge bozulur mu?' Sen terazi ustasısın: Dengeyi koruyan kuralları bulabilir misin?","visual":{"type":"balance","params":{"left":"8 + 5","right":"6 + □","solution":7},"caption":"Sağ kefedeki bilinmeyen torbanın yerine değerler deneyerek teraziyi dengeye getirirsin."},"steps":[{"title":"Dengeyi Kur","mode":"Bireysel · 10 dk","items":["Terazideki durumu bir sayı cümlesi olarak yaz: 8 + 5 = 6 + □.","□ yerine değer deneyerek dengeyi bul; denediğin her değeri bir tabloya yaz.","'=' işaretinin bu cümlede ne anlama geldiğini kendi cümlenle açıkla."],"warn":"Sık yapılan hata: 8 + 5 = □ + 6 cümlesinde kutuya 13 yazmak. Eşittir işareti 'sonucu yaz' demek değil, 'iki taraf aynı' demektir."},{"title":"Dengeyi Bozmadan Değiştir","mode":"Grup · 12 dk","items":["Her iki kefeye 4 kg ekleyin; denge korunur mu? Sayı cümlesini yeniden yazın.","Yalnızca bir kefeye ekleme yaparsanız ne olur? Teraziyle deneyin.","Sol kefedeki torbaların yerini değiştirin (5 + 8). Denge değişir mi? Bu hangi işlem özelliğidir?"]},{"title":"Paketlerle Dağılma","mode":"Grup · 10 dk","items":["Tezgâhta 3 paket var; her pakette 4 kg elma ve 2 kg armut bulunuyor. Toplam ağırlığı iki farklı yolla hesaplayın: 3 × (4 + 2) ve 3 × 4 + 3 × 2.","İki yolun aynı sonucu vermesinin nedenini terazi üzerinde gösterin."],"warn":"Sık yapılan hata: 3 × (4 + 2) işlemini 3 × 4 + 2 olarak hesaplamak. Her paketteki armutlar da 3 kez sayılmalı."},{"title":"Terazi Ustasının Algoritması","mode":"Bireysel · 8 dk","items":["Bir teraziyi dengede tutmak için 3 adımlık bir kural listesi (algoritma) yaz.","Arkadaşının algoritmasını yeni bir örnekle (12 + 9 = □ + 15) dene ve geri bildirim ver."]}],"checklist":["Terazi durumunu sayı cümlesine dönüştürdüm.","Bilinmeyen değeri deneme tablosuyla buldum.","Her iki tarafa aynı işlem yapınca dengenin korunduğunu gösterdim.","Değişme özelliğini bir örnekle açıkladım.","Dağılma özelliğini iki yolla hesaplayarak gösterdim.","Kendi denge algoritmamı yazıp test ettim."],"rubric":[{"k":"Eşitlik anlayışı","d":"'=' işaretini denge olarak yorumlama","l4":"Eşitliği her durumda denge olarak açıklar","l3":"Çoğu durumda doğru yorumlar","l2":"Eşitliği zaman zaman 'sonuç' olarak görür","l1":"Eşitliği yalnızca sonuç olarak görür"},{"k":"Korunum","d":"İki tarafa aynı işlemi yapma","l4":"Kuralı genelleştirip örneklerle sınar","l3":"Kuralı doğru uygular","l2":"Kuralı yalnızca toplama için uygular","l1":"Kuralı uygulayamaz"},{"k":"İşlem özellikleri","d":"Değişme ve dağılma özelliklerini tanıma","l4":"İki özelliği terazi ve sayılarla açıklar","l3":"İki özelliği sayılarla gösterir","l2":"Bir özelliği gösterir","l1":"Özellikleri ayırt edemez"},{"k":"Algoritma","d":"Denge kuralını adım adım yazma","l4":"Açık, sıralı, yeni örnekte çalışan algoritma","l3":"Algoritma çalışır, bir adım belirsiz","l2":"Adımlar eksik ya da sırasız","l1":"Algoritma yazamaz"}],"navi":["Terazinin iki kefesi aynı ağırlıkta olduğunda, birine bir şey eklersen diğerine ne yapmalısın?","5 + 8 ile 8 + 5'i teraziye koysan hangi kefe ağır basar sence? Neden?"],"diff":{"destek":"Küçük sayılarla başla: 3 + 4 = 5 + □. Gerekirse somut nesnelerle (kalem, silgi) dengeyi kur.","ileri":"Her iki kefeden aynı miktarı çıkarmak ya da iki kefeyi aynı sayıyla çarpmak dengeyi korur mu? Örneklerle sına."},"misconception":"Eşittir işaretini iki tarafın eşitliği yerine 'işlemin sonucunu yaz' komutu olarak algılamak."},{"id":"mat-5-04","course":"MAT","grade":5,"themeNo":5,"themeName":"Geometrik Nicelikler","title":"24 Metrelik Çit","subtitle":"Dikdörtgenin çevre ve alan ilişkisi — okul bahçesi tasarımı","kazanim":["Kenar uzunlukları doğal sayı olan bir dikdörtgenin çevre uzunluğu verildiğinde kenar uzunluklarını yorumlayabilme","Kenar uzunlukları doğal sayı olan bir dikdörtgenin alanının ölçüsü verildiğinde çevre uzunluğunu, çevre uzunluğu verildiğinde alanını yorumlayabilme"],"skills21":["Eleştirel Düşünme","Analitik Düşünme","Problem Çözme","Sorumlu Karar Verme"],"digital":["Dijital Ölçme ve Simülasyon","Piksel Sanatı ve Kodlama"],"duration":"80 dk (2 ders)","format":"Grup","tools":["NavigAItor alan ızgarası","Kareli kâğıt","Ücretsiz bir sanal geometri tahtası","İp ve cetvel"],"scenario":"Okul bahçesinde dikdörtgen biçiminde bir sebze tarhı yapılacak ve elinizde toplam 24 metre uzunluğunda çit var. Kenar uzunlukları tam metre olmalı ve çitin tamamı kullanılmalı. Bahçe kulübü 'en çok sebze sığacak' tarhı istiyor; okul müdürü ise tarhın koridora 2 metreden fazla taşmamasını rica ediyor. Tasarım ekibi sizsiniz: Hangi tarhı önerirsiniz?","visual":{"type":"areagrid","params":{"rows":8,"cols":12,"shade":0,"label":"Çevresi 24 birim olan dikdörtgenleri boya"},"caption":"Izgarada çevresi 24 birim olan farklı dikdörtgenleri boyayıp her birinin birim karelerini sayarsın."},"steps":[{"title":"Tüm Olası Tarhları Bul","mode":"Grup · 20 dk","items":["Izgarada çevresi 24 birim olan bir dikdörtgen boyayın; uzun ve kısa kenarını yazın.","Kenar uzunlukları doğal sayı olan tüm seçenekleri sistemli bir tabloda listeleyin (kısa kenar 1, 2, 3 …).","Bir kenar ile komşu kenarın toplamının neden hep 12 çıktığını açıklayın."],"warn":"Sık yapılan hata: Çevreyi iki kenarın toplamı sanmak. Bir dikdörtgenin dört kenarı vardır; çiti tarhın etrafında dolaştırarak kontrol et."},{"title":"Alanları Karşılaştır","mode":"Grup · 15 dk","items":["Her seçeneğin alanını birim kareleri sayarak, sonra çarparak bulun.","Aynı çevreye sahip tarhların alanları neden farklı? Tablonuzdaki örüntüyü yazın.","En büyük ve en küçük alanlı tarhı belirleyin."],"warn":"Sık yapılan hata: 'Çevreleri eşitse alanları da eşittir' demek. Tablonuzdaki alanlara bakarak bu düşünceyi test edin."},{"title":"Ters Soru: Alan Sabitse?","mode":"Bireysel · 15 dk","items":["Alanı 24 metrekare olan, kenarları doğal sayı olan tüm dikdörtgenleri bulun.","Her birinin çevresini hesaplayın: hangisi en az çit gerektirir?","Sanal geometri tahtasında aynı alanlı iki dikdörtgenle küçük bir piksel resmi oluşturun."]},{"title":"Kararını Savun","mode":"Grup · 30 dk","items":["Bahçe kulübünün ve müdürün isteğini birlikte düşünerek bir tarh seçin.","Seçiminizi çizim, tablo ve iki cümlelik gerekçeyle bir 'tasarım kartı'na dönüştürün.","Başka bir grubun kartını inceleyip bir soru sorun."]}],"checklist":["Çevresi 24 birim olan tüm dikdörtgenleri sistemli olarak buldum.","Her dikdörtgenin alanını hesapladım.","Aynı çevreye sahip dikdörtgenlerin alanlarının farklı olabileceğini açıkladım.","Alanı 24 olan dikdörtgenlerin çevrelerini karşılaştırdım.","İki koşulu birlikte düşünerek bir tarh seçtim.","Kararımı çizim ve tabloyla destekledim."],"rubric":[{"k":"Sistemli arama","d":"Tüm olası kenar çiftlerini bulma","l4":"Tüm seçenekleri düzenli bir tabloyla bulur","l3":"Bir seçenek eksik","l2":"Seçenekleri rastgele ve eksik bulur","l1":"Tek bir seçenek bulur"},{"k":"Çevre-alan ilişkisi","d":"İki ölçünün bağımsızlığını yorumlama","l4":"İlişkiyi her iki yönde örneklerle açıklar","l3":"Bir yönde doğru açıklar","l2":"Hesaplar ama yorumlamaz","l1":"Çevre ile alanı karıştırır"},{"k":"Hesaplama","d":"Çevre ve alanın doğru hesaplanması","l4":"Tüm hesaplar doğru ve birimli","l3":"Bir küçük hata ya da birim eksik","l2":"Birkaç hesap hatalı","l1":"Hesapların çoğu hatalı"},{"k":"Karar verme","d":"Koşulları dikkate alarak gerekçeli seçim","l4":"İki koşulu dengeleyip ikna edici gerekçe sunar","l3":"Koşulları dikkate alır, gerekçe kısa","l2":"Yalnızca bir koşulu dikkate alır","l1":"Gerekçesiz seçim yapar"}],"navi":["Çiti tarhın etrafında bir tur dolaştırsan hangi kenarlardan kaç kez geçersin?","Tarh kareye yaklaştıkça alanına ne oluyor? Tablona bakınca bir örüntü görebiliyor musun?"],"diff":{"destek":"Çevreyi 12 metreye indir ve dikdörtgenleri kareli kâğıtta kesip birbirinin üstüne koyarak karşılaştır.","ileri":"Tarhın bir kenarı okul duvarına dayanırsa çit yalnızca üç kenara gerekir. 24 metreyle elde edilebilecek en büyük alan şimdi kaçtır?"},"misconception":"Çevre uzunlukları eşit olan dikdörtgenlerin alanlarının da eşit olduğunu düşünmek."},{"id":"mat-5-05","course":"MAT","grade":5,"themeNo":7,"themeName":"Veriden Olasılığa","title":"Şenlik Çarkını Tasarla","subtitle":"Olasılık spektrumu ve az/çok olasılıklı olaylar — oyun tasarımı","kazanim":["Herhangi bir olayın olasılığının 0 (imkânsız) ile 1 (kesin) arasında (0 ve 1 dâhil) olduğunu (olasılık spektrumu) yorumlayabilme","Olayları az ya da çok olasılıklı şeklinde yapılandırabilme"],"skills21":["Yaratıcılık","Oyunseverlik","Özgün Düşünme","Sorumlu Karar Verme"],"digital":["Dijital Simülasyon","Dijital Oyun Tasarımı"],"duration":"80 dk (2 ders)","format":"Grup","tools":["NavigAItor çark simülasyonu","Karton ve ataç (el yapımı çark)","Kâğıt-kalem"],"scenario":"Okul şenliğinde sınıfınız bir çark oyunu standı açacak. Taslak çark 8 eş dilimden oluşuyor: 4 kırmızı, 2 mavi, 1 sarı ve 1 yeşil; çarkta hiç mor dilim yok. Okul yönetimi, oyunun hem eğlenceli hem de adil anlatılmasını istiyor; ödül tabelasında her rengin şansı dürüstçe yazılmalı. Oyun tasarımcısı sizsiniz: Hangi renk 'kesin', hangisi 'imkânsız', hangisi 'az olasılıklı' olarak etiketlenmeli?","visual":{"type":"dice","params":{"kind":"cark","items":["kırmızı","mavi","sarı","yeşil"],"counts":[4,2,1,1]},"caption":"Çarkı defalarca çevirip her rengin kaç kez geldiğini sıklık tablosuna işlersin."},"steps":[{"title":"Olayları Listele","mode":"Grup · 10 dk","items":["Çark çevrildiğinde ne olabilir? Tüm olası sonuçları yazın.","Şu olayları tartışın: 'kırmızı gelir', 'mor gelir', 'sarı gelir', 'bir renk gelir'.","Her olay için ilk tahmininizi 'imkânsız, az olasılıklı, eşit şanslı, çok olasılıklı, kesin' olarak yazın."]},{"title":"Olasılık Şeridine Yerleştir","mode":"Grup · 15 dk","items":["Uzun bir kâğıt şeridin bir ucuna 0 (imkânsız), diğer ucuna 1 (kesin) yazın; ortasına 1/2 koyun.","Her olayı dilim sayısına bakarak kesirle ifade edin ve şeride yerleştirin.","Hiçbir olasılığın neden 0'dan küçük ya da 1'den büyük olamayacağını açıklayın."],"warn":"Sık yapılan hata: 'Çarkta 4 renk var, o hâlde her rengin şansı eşittir' demek. Renklerin kaç dilime sahip olduğuna bakın."},{"title":"Çarkı Çevir","mode":"İkili · 15 dk","items":["Simülasyonda çarkı 40 kez çevirip sonuçları sıklık tablosuna yazın.","Sonuçlar tahminlerinizle uyumlu mu? Uyumlu değilse nedenini tartışın."],"warn":"Sık yapılan hata: Sarı 3 kez üst üste gelince 'artık sarı gelmez' demek. Çark önceki sonuçları hatırlamaz."},{"title":"Kendi Çarkını Tasarla","mode":"Grup · 40 dk","items":["Büyük ödülün az olasılıklı, teselli ödülünün çok olasılıklı olduğu yeni bir çark tasarlayın.","Her ödülün olasılığını kesirle ve sözcükle yazan dürüst bir tabela hazırlayın.","Çarkınızı başka bir grubun 'oyuncularına' tanıtın ve tabelanızın anlaşılır olup olmadığını sorun."]}],"checklist":["Çarkın tüm olası sonuçlarını listeledim.","Olayları 0 ile 1 arasındaki şeride yerleştirdim.","İmkânsız ve kesin olayları örnekle açıkladım.","Simülasyon sonuçlarını tahminimle karşılaştırdım.","Kendi çarkımı az ve çok olasılıklı olaylarla tasarladım.","Ödül tabelasını dürüst ve anlaşılır yazdım."],"rubric":[{"k":"Olasılık spektrumu","d":"Olayları 0–1 aralığına yerleştirme","l4":"Tüm olayları kesirle doğru yerleştirip gerekçelendirir","l3":"Yerleştirme doğru, gerekçe kısa","l2":"Uç değerleri doğru, ara değerleri hatalı","l1":"Olayları sıralayamaz"},{"k":"Az/çok olasılıklı yapılandırma","d":"Olayları nedenleriyle sınıflandırma","l4":"Dilim sayısıyla mantıksal ilişki kurar","l3":"Doğru sınıflandırır, nedeni kısmen açıklar","l2":"Sınıflandırma kısmen doğru","l1":"Rastgele sınıflandırır"},{"k":"Deney ve yorum","d":"Simülasyon sonuçlarını yorumlama","l4":"Sonuçları tahminle karşılaştırıp farkları açıklar","l3":"Sonuçları doğru kaydeder ve kısaca yorumlar","l2":"Sonuçları kaydeder, yorumlamaz","l1":"Kayıt eksik"},{"k":"Tasarım ve dürüstlük","d":"Özgün çark ve açık tabela","l4":"Özgün, amaca uygun çark ve tamamen doğru tabela","l3":"Uygun çark, tabelada küçük eksik","l2":"Çark amaca kısmen uygun","l1":"Tasarım amaçla uyumsuz"}],"navi":["Çarkta mor dilim yoksa, mor gelme olasılığını bir sayıyla nasıl gösterirdin?","Kırmızı 8 dilimin 4'ünü kaplıyorsa, olasılık şeridinde hangi işarete yakın durmalı?"],"diff":{"destek":"4 dilimli bir çarkla (2 kırmızı, 1 mavi, 1 sarı) başla ve yalnızca 'imkânsız, kesin, eşit şanslı' etiketlerini kullan.","ileri":"Büyük ödülün olasılığı 1/10 olsun istiyorsan çarkı kaç dilime bölmelisin? İki farklı tasarım öner."},"misconception":"Sonuç sayısı eşitse (4 renk) her sonucun olasılığının da eşit olduğunu düşünmek."},{"id":"mat-6-06","course":"MAT","grade":6,"themeNo":1,"themeName":"Sayılar Ve Nicelikler (1)","title":"Otobüsler Ne Zaman Buluşur?","subtitle":"Ortak kat ve ortak bölen — durak tarifesi","kazanim":["Günlük hayat problemleri ya da matematiksel durumlar üzerinden ortak kat ve ortak böleni yorumlayabilme"],"skills21":["Analitik Düşünme","Merak","Sistematik Olma","Bilgi Okuryazarlığı"],"digital":["Dijital Oyun ve Keşif","Kodlama"],"duration":"40 dk","format":"İkili","tools":["NavigAItor sayı doğrusu","Kâğıt-kalem","Ücretsiz bir blok tabanlı kodlama aracı"],"scenario":"Okulunun önündeki duraktan iki belediye otobüsü kalkıyor: Mavi hat 12 dakikada bir, Yeşil hat 18 dakikada bir. Sabah 08.00'de iki otobüs aynı anda duraktan ayrıldı. Okulun gezi kulübü, iki hatta da aktarma yapabilmek için otobüslerin yeniden birlikte kalkacağı saatleri arıyor. Kulübün tarife danışmanı sensin: İki otobüs 10.00'a kadar hangi saatlerde yine birlikte kalkar?","visual":{"type":"numberline","params":{"min":0,"max":72,"step":6,"target":36,"label":"08.00'den sonra geçen dakika"},"caption":"İki hattın kalkış zamanlarını sayı doğrusunda işaretleyip ilk buluşma noktasını sürüklersin."},"steps":[{"title":"Tarifeyi Çıkar","mode":"Bireysel · 10 dk","items":["Mavi hattın 08.00'den sonraki kalkış dakikalarını 12'nin katları olarak yaz (12, 24, …).","Aynı şeyi Yeşil hat için 18'in katlarıyla yap.","İki listede ortak olan ilk sayıyı bul ve saate çevir."],"warn":"Sık yapılan hata: İlk buluşmayı 12 × 18 = 216 dakika sanmak. Çarpım bir ortak kattır ama en küçüğü olmayabilir; listelerine bak."},{"title":"Sayı Doğrusunda Göster","mode":"İkili · 10 dk","items":["Sayı doğrusunda Mavi hattın kalkışlarını bir renkle, Yeşil hattınkileri başka renkle işaretleyin.","Renklerin çakıştığı noktaları bulun; aralarındaki farkın neden hep aynı olduğunu tartışın.","10.00'a kadarki tüm ortak kalkış saatlerini yazın."]},{"title":"Ortak Bölen Görevi","mode":"İkili · 12 dk","items":["Kulüp gezide 36 elma ve 24 portakalı, her pakette aynı sayıda elma ve aynı sayıda portakal olacak biçimde paylaştırmak istiyor; hiç meyve artmamalı.","En çok kaç paket hazırlanabilir? Bir pakette kaç elma, kaç portakal olur?","Bu soruda neden 'kat' değil 'bölen' aradığınızı kendi cümlelerinizle açıklayın."],"warn":"Sık yapılan hata: Ortak kat ile ortak böleni karıştırmak. Kendine sor: Bir şeyi parçalara mı ayırıyorum, yoksa tekrarların buluşmasını mı bekliyorum?"},{"title":"Bir Algoritma Yaz","mode":"Bireysel · 8 dk","items":["İki sayının ilk ortak katını bulan adımları blok tabanlı bir kodlama aracında ya da akış şeması olarak yaz.","Algoritmanı 15 ve 20 sayılarıyla test et."]}],"checklist":["İki hattın kalkış dakikalarını kat listesi olarak yazdım.","İlk ortak kalkışı bulup saate çevirdim.","Ortak kalkışları sayı doğrusunda gösterdim.","Meyve paketleme sorusunu ortak bölenle çözdüm.","Ortak kat ile ortak bölen arasındaki farkı açıkladım.","Algoritmamı yeni sayılarla test ettim."],"rubric":[{"k":"Ortak kat","d":"Kat listeleriyle ortak kalkışları bulma","l4":"Tüm ortak kalkışları bulur, aradaki düzeni açıklar","l3":"İlk ortak katı ve saatleri doğru bulur","l2":"Listeleri yazar ama ortak katı yanlış seçer","l1":"Kat kavramını kullanamaz"},{"k":"Ortak bölen","d":"Eşit paylaştırma problemini çözme","l4":"En büyük ortak böleni bulur ve paket içeriğini açıklar","l3":"Doğru paket sayısını bulur","l2":"Bir ortak bölen bulur ama en büyüğünü değil","l1":"Bölen ile katı karıştırır"},{"k":"Temsil","d":"Sayı doğrusu ve tablo kullanımı","l4":"Temsil doğru ve çözümü açıkça destekliyor","l3":"Temsil doğru, bir küçük eksik","l2":"Temsil kısmen doğru","l1":"Temsil yok ya da hatalı"},{"k":"Algoritmik düşünme","d":"Ortak kat bulma adımlarını yazma","l4":"Algoritma açık ve yeni sayılarla çalışıyor","l3":"Algoritma çalışıyor, bir adım belirsiz","l2":"Adımlar eksik","l1":"Algoritma yazamıyor"}],"navi":["Mavi hattın kalkış dakikaları hangi sayının katlarıdır? Yeşil hattınkiler?","Meyveleri paketlerken bir sayıyı büyütüyor musun, yoksa küçük parçalara mı ayırıyorsun?"],"diff":{"destek":"Sayıları küçült: 4 ve 6 dakikada bir kalkan iki otobüsle başla ve sayı doğrusunda adım adım say.","ileri":"Üçüncü bir hat 8 dakikada bir kalkarsa üç otobüs ilk kez ne zaman birlikte kalkar? Yöntemin hâlâ işe yarar mı?"},"misconception":"İki sayının en küçük ortak katının her zaman bu iki sayının çarpımı olduğunu düşünmek."},{"id":"mat-6-07","course":"MAT","grade":6,"themeNo":2,"themeName":"Sayılar Ve Nicelikler (2)","title":"Kütüphane Raflarının Sırrı","subtitle":"Kesir, ondalık ve yüzde ile dört işlem problemleri","kazanim":["Gerçek yaşam durumlarında karşılaşılan kesir, ondalık ve yüzde gösterimleri ile ilgili dört işlem gerektiren problemleri çözebilme"],"skills21":["Tümevarımsal Akıl Yürütme","Değerlendirme","Finansal Okuryazarlık"],"digital":["Dijital Hesaplama Araçları"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor yüzlük kart","Hesap makinesi","Ücretsiz bir elektronik tablo","Kâğıt-kalem"],"scenario":"Okul kütüphanesinde 400 kitap var. Kütüphane görevlisi kitapların %35'inin hikâye, 1/4'ünün bilim, 0,15'inin şiir, geri kalanının tarih kitabı olduğunu söylüyor. Bu yıl okul, kitap fuarından yeni kitaplar alacak ve öğrenci kulübü hangi türe öncelik verilmesi gerektiğine karar verecek. Kulübün hesap sorumlusu sensin: Raflarda hangi tür eksik ve fuardaki indirimlerle en akıllıca alışveriş nasıl yapılır?","visual":{"type":"areagrid","params":{"rows":10,"cols":10,"shade":35,"label":"%35 hikâye"},"caption":"Yüzlük kartta her kitap türünü farklı renkle boyayarak kütüphanenin dağılımını gösterirsin."},"steps":[{"title":"Rafları Hesapla","mode":"Bireysel · 20 dk","items":["Hikâye, bilim ve şiir kitaplarının sayısını ayrı ayrı hesapla.","Tarih kitaplarının sayısını bul ve bunu kesir, ondalık ve yüzde olarak yaz.","Dört türü yüzlük kartta farklı renklerle göster."],"warn":"Sık yapılan hata: Farklı gösterimleri aynı türe çevirmeden toplamak (ör. 35 + 1/4 + 0,15). Önce hepsini aynı gösterime dönüştür."},{"title":"Yeni Kitaplar Gelince","mode":"İkili · 15 dk","items":["Fuardan 80 yeni kitap alınacak ve bunların 3/4'ü bilim, kalanı tarih olacak.","Yeni durumda bilim kitapları toplam kitapların yüzde kaçı olur? Hesap makinesiyle kontrol et.","Bilim kitaplarının oranı arttı mı, azaldı mı? Nedenini açıkla."],"warn":"Sık yapılan hata: Yeni yüzdeyi hesaplarken eski toplamı (400) kullanmaya devam etmek. Kitap sayısı değişti mi?"},{"title":"Fuar İndirimleri","mode":"Grup · 25 dk","items":["Fuarda 60 TL'lik bir kitapta '%20 indirim', başka bir standda aynı kitapta '1/4 indirim' var. Hangisi daha ucuz?","Bir standda 'ikinci kitaba ek %50 indirim' kampanyası var. İki kitap için ödenen tutarı diğer seçeneklerle karşılaştırın.","Hesaplarınızı elektronik tabloya girin ve formülle kontrol edin."]},{"title":"Öneri Raporu","mode":"Grup · 20 dk","items":["Hangi türe öncelik verilmesi gerektiğini verilere dayanarak 4–5 cümleyle yazın.","En az bir kesir, bir ondalık ve bir yüzde gösterimi kullanın; hesaplarınızı tabloyla destekleyin."]}],"checklist":["Her türün kitap sayısını doğru hesapladım.","Tarih kitaplarını üç farklı gösterimle yazdım.","Yeni kitaplar gelince oranları yeniden hesapladım.","İndirim seçeneklerini karşılaştırdım.","Hesaplarımı hesap makinesi ya da elektronik tabloyla kontrol ettim.","Önerimi verilerle gerekçelendirdim."],"rubric":[{"k":"Gösterimler arası dönüşüm","d":"Kesir, ondalık ve yüzde arasında geçiş","l4":"Tüm dönüşümleri doğru ve gerekçeli yapar","l3":"Dönüşümlerin çoğu doğru","l2":"Bir gösterimde sürekli hata yapar","l1":"Dönüşüm yapamaz"},{"k":"Problem çözme","d":"Çok adımlı işlemleri planlama ve uygulama","l4":"Tüm adımlar doğru, strateji açık","l3":"Bir adımda küçük hata","l2":"Değişen toplamı dikkate almaz","l1":"İşlemleri planlayamaz"},{"k":"Finansal değerlendirme","d":"İndirim seçeneklerini karşılaştırma","l4":"Tüm seçenekleri karşılaştırıp en uygununu gerekçelendirir","l3":"Doğru seçimi yapar, gerekçe kısa","l2":"Bir seçeneği hatalı hesaplar","l1":"Karşılaştırma yapamaz"},{"k":"Raporlama","d":"Önerinin verilerle desteklenmesi","l4":"Açık, üç gösterimi de kullanan, tabloyla desteklenmiş rapor","l3":"Rapor açık, bir gösterim eksik","l2":"Öneri var, veri desteği zayıf","l1":"Öneri verilere dayanmıyor"}],"navi":["%35, 1/4 ve 0,15'i aynı dilde konuşturabilmek için hangi gösterimi ortak seçerdin?","Kitap sayısı 400'den 480'e çıktığında 'bütün' değişmiş olur mu? Bu yüzdeleri nasıl etkiler?"],"diff":{"destek":"Kütüphanede 100 kitap olduğunu varsay; böylece yüzdeler doğrudan kitap sayısına dönüşür. İndirim kısmında yalnızca %20'yi hesapla.","ileri":"Önce %20, sonra kalan fiyata %10 indirim yapmak ile tek seferde %30 indirim aynı mıdır? Örneklerle sına ve genelle."},"misconception":"Bütün değiştiğinde de aynı yüzdenin aynı miktarı gösterdiğini düşünmek."},{"id":"mat-6-08","course":"MAT","grade":6,"themeNo":3,"themeName":"İşlemlerle Cebirsel Düşünme Ve Değişimler","title":"Kantin Masaları Algoritması","subtitle":"Bilinen niceliklerden bilinmeyene: cebirsel ifade ve akış şeması","kazanim":["Gerçek yaşam durumlarında bilinen niceliklerden bilinmeyen niceliklere ilişkin muhakeme yapabilme","Cebirsel ifadeler içeren durumlardaki algoritmaları yorumlayabilme"],"skills21":["Soyutlama","Genelleme","İletişim","Problem Çözme"],"digital":["Algoritma Tasarımı","Dijital Temsil"],"duration":"40 dk","format":"Bireysel + Grup","tools":["NavigAItor akış şeması","Kare kâğıt parçaları (masa modeli)","Ücretsiz bir elektronik tablo"],"scenario":"Okul kantininde kare masalar var ve her masanın her kenarına bir kişi oturabiliyor. Kalabalık günlerde masalar yan yana birleştirilerek uzun bir sıra yapılıyor. Kantin görevlisi bir 'sandalye hesaplayıcı' istiyor: Kaç masa birleştirilirse kaç sandalye gerekir? Sen bu hesaplayıcının tasarımcısısın: Sınıfındaki 30 kişi aynı sırada oturacaksa kaç masa birleştirilmeli?","visual":{"type":"flow","params":{"kind":"algoritma","steps":["Başla","Masa sayısını al: n","n'yi 2 ile çarp","Sonuca 2 ekle","Sandalye sayısını yaz","Bitir"]},"caption":"Akış şemasını farklı masa sayılarıyla adım adım çalıştırıp çıkan sandalye sayılarını tabloya yazarsın."},"steps":[{"title":"Model Kur","mode":"Bireysel · 10 dk","items":["Kâğıt karelerle 1, 2, 3 ve 4 masa birleştir; her durumda sandalye sayısını say.","Sonuçları 'masa sayısı – sandalye sayısı' tablosuna yaz.","Bir masa eklendiğinde sandalye sayısının neden 4 değil 2 arttığını açıkla."],"warn":"Sık yapılan hata: n masa için 4 × n sandalye yazmak. Birleşen kenarlara kimse oturamaz; modeline tekrar bak."},{"title":"Akış Şemasını Çalıştır","mode":"Bireysel · 10 dk","items":["Akış şemasını n = 5, 10 ve 20 için çalıştır ve tabloya ekle.","Şemadaki adımları tek bir cebirsel ifadeyle yaz.","İfadedeki '2' sayılarının her birinin masa düzeninde neyi temsil ettiğini açıkla."]},{"title":"Bilinmeyeni Bul","mode":"Grup · 12 dk","items":["30 kişinin oturması için kaç masa birleştirilmesi gerektiğini tablonuzu genişleterek ya da ifadeyi kullanarak bulun.","47 kişilik bir grup için kaç masa gerekir? Boş sandalye kalır mı?","Elektronik tabloda bir sütuna masa sayılarını, diğerine formülü yazarak sonuçlarınızı kontrol edin."],"warn":"Sık yapılan hata: 47 kişi için hesap kesirli çıkınca sonucu aşağı yuvarlamak. Masa yetmezse ne olur?"},{"title":"Yeni Düzen, Yeni İfade","mode":"Grup · 8 dk","items":["Altıgen masalar yan yana birleştirilirse sandalye sayısı nasıl değişir? Yeni bir akış şeması çizin.","Yeni ifadenizi bir başka gruba anlatın; onlar ifadenizi n = 3 için test etsin."]}],"checklist":["Masa modeliyle tablo oluşturdum.","Akış şemasını farklı değerlerle çalıştırdım.","Durumu cebirsel ifadeyle yazdım.","İfadedeki sayıların anlamını açıkladım.","Sandalye sayısından masa sayısını buldum.","Yeni masa düzeni için ifade geliştirdim."],"rubric":[{"k":"Örüntü ve tablo","d":"Nicelikler arasındaki ilişkiyi tabloyla belirleme","l4":"Tablo eksiksiz, artış miktarını açıklar","l3":"Tablo doğru, açıklama kısa","l2":"Tabloda hatalar var","l1":"Tablo oluşturamaz"},{"k":"Cebirsel ifade","d":"İlişkiyi değişkenle ifade etme","l4":"Doğru ifadeyi yazar ve her terimi anlamlandırır","l3":"Doğru ifadeyi yazar","l2":"İfade kısmen doğru (ör. 4n)","l1":"İfade yazamaz"},{"k":"Algoritma yorumlama","d":"Akış şemasını çalıştırma ve dönüştürme","l4":"Şemayı ifadeye ve yeni duruma uyarlar","l3":"Şemayı doğru çalıştırır","l2":"Şemayı adım atlayarak çalıştırır","l1":"Şemayı çalıştıramaz"},{"k":"Bilinmeyeni bulma","d":"Sonuçtan girdiye akıl yürütme","l4":"Her iki soruyu çözer, artık sandalyeyi yorumlar","l3":"30 kişilik soruyu doğru çözer","l2":"Deneme-yanılmayla kısmen çözer","l1":"Çözemez"}],"navi":["İki masa birleştiğinde hangi kenarlar ortadan kayboluyor? Bu, sandalye sayısını nasıl etkiliyor?","Akış şemasını tersten çalıştırsaydın, sandalye sayısından masa sayısına nasıl ulaşırdın?"],"diff":{"destek":"Yalnızca 1–6 masa için model kur ve tabloyu doldur; 30 kişilik soruyu tabloyu uzatarak çöz.","ileri":"Masalar düz sıra yerine iki sıra hâlinde dikdörtgen biçiminde birleştirilirse sandalye sayısını veren ifade ne olur?"},"misconception":"Birleşen kenarları hesaba katmadan, birleştirilen masa sayısını tek masanın sandalye sayısıyla çarpmak."},{"id":"mat-6-09","course":"MAT","grade":6,"themeNo":5,"themeName":"Geometrik Nicelikler","title":"Tekerlek Kaç Tur Atar?","subtitle":"Çember uzunluğu ile çap arasındaki ilişki — ölçüm deneyi","kazanim":["Çemberin uzunluğu ile çap uzunluğu arasındaki ilişkiye yönelik çıkarım yapabilme","Çap veya yarıçap uzunluğu verilen bir çemberin uzunluğu ile ilgili problemleri çözebilme"],"skills21":["Analojik Akıl Yürütme","Tümevarımsal Akıl Yürütme","Problem Çözme"],"digital":["Dijital Pi Simülasyonu","Alan Hesaplama Yazılımları"],"duration":"80 dk (2 ders)","format":"Grup","tools":["İp ve cetvel / mezura","Yuvarlak nesneler (bardak, tabak, kova kapağı)","Ücretsiz bir elektronik tablo","NavigAItor çember modeli"],"scenario":"Okulun bisiklet kulübü, okuldan sahil parkına kadar olan 1100 metrelik bisiklet yolunu ölçmek istiyor ama ellerinde uzun bir şerit metre yok. Bir öğrenci, bisiklet tekerleğinin kaç tur attığını sayan küçük bir sayaç taktı. Tekerleğin çapı 70 cm. Kulübün ölçüm uzmanı sensin: Tekerleğin bir turda aldığı yol nasıl bulunur ve sayaç parkta kaç turu göstermelidir?","visual":{"type":"shapes","params":{"kind":"daire","labels":true},"caption":"Çemberin çapını ve çevresini işaretleyip çap uzunluğunun çevre üzerine kaç kez sığdığını gözlemlersin."},"steps":[{"title":"Yuvarlakları Ölç","mode":"Grup · 25 dk","items":["En az 4 yuvarlak nesnenin çevresini iple, çapını cetvelle ölçün.","Ölçümleri elektronik tabloya girin ve her nesne için çevre ÷ çap oranını hesaplayın.","Oranlarda gördüğünüz örüntüyü bir cümleyle yazın."],"warn":"Sık yapılan hata: Çapı ölçerken cetveli çemberin merkezinden geçirmemek. Çap, en uzun kiriştir; cetveli kaydırarak en uzun yeri bul."},{"title":"Örüntüyü Genelle","mode":"Grup · 15 dk","items":["Sınıftaki tüm grupların oranlarını tek tabloda toplayın; oranlar hangi sayının etrafında toplanıyor?","Bu sabit sayının adı pi'dir (π). Çember uzunluğunu çap ve π ile ifade eden bir kural yazın.","Kuralı yarıçapla da yazın; iki yazımın neden aynı olduğunu açıklayın."],"warn":"Sık yapılan hata: Çevreyi 'yarıçap × π' olarak hesaplamak. Çap mı, yarıçap mı kullandığını her seferinde kontrol et."},{"title":"Tekerlek Problemi","mode":"Bireysel · 20 dk","items":["π yerine 22/7 kullanarak 70 cm çaplı tekerleğin bir turda aldığı yolu hesapla.","1100 metreyi santimetreye çevir ve tekerleğin kaç tur atması gerektiğini bul.","Sayaç 520 turu gösterirse yol tahmin edilenden uzun mu, kısa mı? Yaklaşık kaç metre?"]},{"title":"Benzer Durumlar","mode":"Grup · 20 dk","items":["Daha küçük (çapı 35 cm) bir çocuk bisikleti aynı yolu giderse tur sayısı nasıl değişir? Önce tahmin edin, sonra hesaplayın.","Çap iki katına çıktığında çevrenin ne olduğunu bir genellemeyle açıklayın."]}],"checklist":["En az dört yuvarlak nesneyi ölçtüm.","Çevre ÷ çap oranlarını tabloda hesapladım.","Oranların yaklaşık aynı sayıya yakın olduğunu fark ettim.","Çember uzunluğu kuralını kendi cümlelerimle yazdım.","Tekerlek problemini birim dönüşümüyle çözdüm.","Çap değiştiğinde çevrenin nasıl değiştiğini açıkladım."],"rubric":[{"k":"Ölçme","d":"Çevre ve çapı dikkatli ölçme","l4":"Tüm ölçümler özenli, birimli ve tutarlı","l3":"Ölçümler çoğunlukla doğru","l2":"Ölçümlerde belirgin hatalar var","l1":"Ölçüm yapamaz"},{"k":"Tümevarım","d":"Oranlardan genellemeye ulaşma","l4":"Örüntüyü fark edip π ile kural yazar","l3":"Örüntüyü fark eder, kural kısmen doğru","l2":"Oranları hesaplar, örüntü görmez","l1":"Oran hesaplayamaz"},{"k":"Problem çözme","d":"Tekerlek problemini çözme","l4":"Birim dönüşümüyle doğru tur sayısını bulur ve yorumlar","l3":"Doğru sonuç, yorum eksik","l2":"Birim dönüşümünde hata","l1":"Çözüm yolu yok"},{"k":"Analojik akıl yürütme","d":"Çap–çevre ilişkisini yeni duruma aktarma","l4":"Çap ile çevre arasındaki orantıyı genelleyip açıklar","l3":"Yeni durumu doğru hesaplar","l2":"Yalnızca tahmin eder","l1":"İlişki kuramaz"}],"navi":["Farklı büyüklükteki nesnelerde çevre ÷ çap oranı neden birbirine bu kadar yakın çıkıyor olabilir?","Tekerlek bir tur döndüğünde yere değen nokta ne kadar yol alır? Bu, çemberin hangi uzunluğuna eşittir?"],"diff":{"destek":"π yerine 3 kullanarak yaklaşık hesap yap; tekerlek problemini 110 metrelik bir koridor için çöz.","ileri":"Ölçüm hatası 1 cm olsaydı 1100 metrelik yol için tur sayısı ne kadar değişirdi? Sonucu tartış."},"misconception":"Çember uzunluğunu yarıçap ile π'nin çarpımı olarak hesaplamak."},{"id":"mat-6-10","course":"MAT","grade":6,"themeNo":6,"themeName":"İstatistiksel Araştırma Süreci","title":"Okula Kaç Dakikada Geliyoruz?","subtitle":"Nicel veriyle çalışma, ortalama-ortanca-tepe değer ve veriye dayalı karar","kazanim":["Kategorik veya nicel (kesikli) veri ile çalışabilme ve veriye dayalı karar verebilme"],"skills21":["Eleştirel Düşünme","Veri Okuryazarlığı","İş Birliği","Sorumlu Karar Verme"],"digital":["Dijital Veri Analizi","Kök-Yaprak Gösterimi","Dijital Etik"],"duration":"80 dk (2 ders)","format":"Grup","tools":["Ücretsiz bir elektronik tablo","NavigAItor grafik aracı","Kâğıt-kalem"],"scenario":"Okul yönetimi, sabah etüdünü 15 dakika erken başlatmayı düşünüyor ve öğrenci meclisinden görüş istiyor. Meclis, adları gizli tutulan 15 öğrencinin okula geliş sürelerini (dakika) topladı: 5, 8, 10, 10, 12, 12, 12, 15, 15, 18, 20, 22, 25, 30, 41. Bir meclis üyesi 'Ortalama 17 dakika, yani herkes kolayca gelir' diyor. Meclisin veri analisti sensin: Bu yorum doğru mu ve yönetime hangi öneriyi sunarsın?","visual":{"type":"bars","params":{"title":"Okula geliş süresi","labels":["0–9 dk","10–19 dk","20–29 dk","30–39 dk","40–49 dk"],"values":[2,8,3,1,1],"unit":"öğrenci","editable":true},"caption":"Veriyi gruplara ayırıp sütun yüksekliklerini kendin ayarlayarak sıklık grafiğini oluşturursun."},"steps":[{"title":"Veriyi Düzenle","mode":"Grup · 15 dk","items":["Veriyi elektronik tabloya girin ve küçükten büyüğe sıralayın.","Onlar basamağını kök, birler basamağını yaprak alarak bir kök-yaprak gösterimi oluşturun.","Veriyi 10'ar dakikalık gruplara ayırıp sıklık grafiğini çizin ve verilen grafikle karşılaştırın."],"warn":"Sık yapılan hata: Kök-yaprak gösteriminde aynı değeri (ör. 12'yi üç kez) yalnızca bir kez yazmak. Her veri ayrı bir yapraktır."},{"title":"Merkezi Eğilim Ölçüleri","mode":"Grup · 20 dk","items":["Ortalamayı, ortancayı ve tepe değeri önce elle, sonra elektronik tablo formülleriyle bulun.","41 dakikalık değer olmasaydı ortalama ve ortanca nasıl değişirdi? Hesaplayın.","Hangi ölçünün 'tipik bir öğrenciyi' daha iyi anlattığını tartışın."],"warn":"Sık yapılan hata: Ortancayı sıralamadan, listenin ortasındaki sayıyı alarak bulmak. Önce sıralandığından emin ol."},{"title":"Yorumu Sorgula","mode":"Grup · 20 dk","items":["'Ortalama 17 dakika, yani herkes kolayca gelir' cümlesini verilerle değerlendirin: Kaç öğrenci 20 dakikadan uzun sürede geliyor?","15 öğrencilik verinin tüm okulu temsil edip etmediğini tartışın; daha güvenilir sonuç için ne yapılmalı?","Kişisel verilerin neden adsız toplanması gerektiğini açıklayın."]},{"title":"Meclise Öneri","mode":"Grup · 25 dk","items":["Grafik, kök-yaprak gösterimi ve üç merkezi eğilim ölçüsünü içeren tek sayfalık bir öneri hazırlayın.","Önerinizde uzun yoldan gelen öğrencileri de düşündüğünüzü gösterin.","Önerinizi diğer gruplara sunun ve en az bir karşı görüşe yanıt verin."]}],"checklist":["Veriyi sıralayıp kök-yaprak gösterimi oluşturdum.","Sıklık grafiğini çizdim.","Ortalama, ortanca ve tepe değeri hesapladım.","Uç değerin ortalamayı nasıl etkilediğini açıkladım.","Verilen yorumu verilerle sorguladım.","Kişisel veri gizliliğine dikkat ettim ve önerimi gerekçelendirdim."],"rubric":[{"k":"Veri temsili","d":"Kök-yaprak gösterimi ve sıklık grafiği","l4":"İki temsil eksiksiz ve doğru","l3":"Temsillerde bir küçük hata","l2":"Yalnızca bir temsil doğru","l1":"Temsil oluşturamaz"},{"k":"Merkezi eğilim","d":"Ölçüleri hesaplama ve yorumlama","l4":"Üç ölçüyü doğru hesaplar, uç değerin etkisini açıklar","l3":"Hesaplar doğru, yorum kısa","l2":"Bir ölçü hatalı","l1":"Ölçüleri karıştırır"},{"k":"Eleştirel değerlendirme","d":"Verilen yorumu ve örneklemi sorgulama","l4":"Yorumu ve temsil gücünü verilerle sorgular","l3":"Yorumun eksik yanını belirtir","l2":"Yorumu kanıtsız reddeder ya da kabul eder","l1":"Değerlendirme yapmaz"},{"k":"Veriye dayalı karar","d":"Gerekçeli ve sorumlu öneri","l4":"Tüm öğrencileri gözeten, verilerle desteklenmiş öneri","l3":"Verilere dayalı öneri, bir eksik","l2":"Öneri zayıf biçimde destekleniyor","l1":"Öneri verilerle ilişkisiz"}],"navi":["15 öğrenciden kaçı gerçekten 17 dakikaya yakın sürede geliyor? Ortalama herkesin durumunu anlatıyor mu?","Tek bir çok büyük değer ortalamayı mı yoksa ortancayı mı daha çok etkiler? Nasıl test edebilirsin?"],"diff":{"destek":"İlk 9 veriyle çalış ve yalnızca tepe değer ile ortancayı bul; grafiği hazır şablonla tamamla.","ileri":"Sınıfınızdan adsız yeni veri toplayıp iki veri grubunu karşılaştırın; hangi farkların anlamlı olduğunu tartışın."},"misconception":"Ortalamanın her zaman verinin 'tipik' değerini en iyi temsil ettiğini düşünmek ve uç değerlerin etkisini göz ardı etmek."},{"id":"mat-7-11","course":"MAT","grade":7,"themeNo":1,"themeName":"Sayılar Ve Nicelikler (1)","title":"Pizza Gecesi Muhasebecisi","subtitle":"Rasyonel sayılarla işlemler ve karşılaştırma — Pizza modeli","kazanim":["Rasyonel sayılar ve işlemler içeren gerçek yaşam problemlerini çözebilme","Rasyonel sayıların karşılaştırma ve sıralama ilişkilerini yorumlayabilme"],"skills21":["Sistematik Olma","Merak","Problem Çözme"],"digital":["Dijital Sayı Doğrusu","Hesap Makinesi ile Keşif"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor Stüdyo pizza modeli","Hesap makinesi","Defter ve renkli kalem"],"scenario":"Sınıfın dönem sonu kutlamasında aynı büyüklükte iki pizza var: biri 8, diğeri 12 eşit dilime kesilmiş. Deniz birinci pizzanın 3/8'ini, Elif ikinci pizzanın 5/12'sini yedi. Kalan dilimler 4 arkadaş arasında eşit paylaşılacak ve herkes \"Kim daha çok yedi?\" diye tartışıyor. Kutlamanın hesap sorumlusu sensin: Kim daha fazla yedi, geriye ne kaldı ve her arkadaşa pizzanın ne kadarı düşer?","visual":{"type":"pizza","params":{"pizzas":2,"target":["3/8","5/12"],"maxCut":12},"caption":"Öğrenci iki pizzayı 8 ve 12 dilime keser, Deniz ile Elif'in yediği kısımları boyayıp karşılaştırır."},"steps":[{"title":"Pizzaları Kes ve Boya","mode":"Bireysel · 15 dk","items":["Modelde birinci pizzayı 8, ikinci pizzayı 12 eşit dilime ayır.","Deniz'in yediği 3/8'i ve Elif'in yediği 5/12'yi farklı renklerle boya.","Göz kararı tahmin et: Kim daha çok yedi? Tahminini deftere yaz."],"warn":"Sık yapılan hata: Payı büyük olan kesrin her zaman büyük olduğunu düşünmek. 5 > 3 olduğu için 5/12 > 3/8 demek yeterli mi? Dilimlerin büyüklüğünü kontrol et."},{"title":"Önce Matematik Yap","mode":"Bireysel · 20 dk","items":["3/8 ile 5/12'yi ortak paydada yazarak karşılaştır; hangi ortak paydayı neden seçtiğini açıkla.","İki kişinin toplam yediği miktarı bul ve sadeleştir.","İki pizzadan geriye kalan miktarı bul; sonucu tam sayılı kesir olarak da yaz.","Kalan miktarı 4 arkadaşa eşit böl; her birine düşen payı hesapla."],"warn":"Sık yapılan hata: Paydaları eşitlemeden payları ve paydaları ayrı ayrı toplamak (3/8 + 5/12 = 8/20 gibi). Bu sonucun bir pizzadan bile az olup olmadığını modelle kontrol et."},{"title":"Sayı Doğrusunda Sırala","mode":"Bireysel · 15 dk","items":["3/8, 5/12, toplam yenen miktar ve kişi başı pay değerlerini hesap makinesiyle ondalık gösterime çevir.","Hangisinin devirli ondalık çıktığını belirle ve devreden kısmı işaretle.","Dört değeri dijital sayı doğrusunda göster ve küçükten büyüğe sırala."]},{"title":"Hesap Raporu","mode":"Grup · 30 dk","items":["Grubunla çözümleri karşılaştır; farklı yollar kullanan varsa ikisini de tahtaya yaz.","Aynı sorunun 'pizzalar farklı büyüklükte olsaydı' hâlini tartışın: Kesirleri karşılaştırmak yine anlamlı olur muydu?","Bir kâğıda kısa bir 'Pizza Hesap Raporu' yazın: soru, işlem, sonuç, kontrol."]}],"checklist":["İki pizzayı doğru sayıda dilime ayırıp boyadım.","Kesirleri ortak paydada yazarak karşılaştırdım.","Kalan miktarı ve kişi başı payı hesapladım.","Değerleri ondalık gösterime çevirip devirli olanı belirledim.","Dört değeri sayı doğrusunda sıraladım.","Sonucumu modelle kontrol ettim."],"rubric":[{"k":"İşlem doğruluğu","d":"Ortak payda, toplama, çıkarma ve bölme adımları","l4":"Tüm işlemler doğru ve sadeleştirilmiş","l3":"Küçük bir hata dışında doğru","l2":"İşlemlerin yarısı doğru","l1":"İşlemler büyük ölçüde hatalı"},{"k":"Karşılaştırma ve sıralama","d":"Kesirleri gerekçeyle karşılaştırma, sayı doğrusunda sıralama","l4":"Doğru sıralama ve iki farklı gerekçe","l3":"Doğru sıralama, tek gerekçe","l2":"Sıralamada bir hata var","l1":"Gerekçesiz veya hatalı sıralama"},{"k":"Model ile bağlantı","d":"Pizza modeli ile işlemleri ilişkilendirme","l4":"Her işlemi modelde gösterebiliyor","l3":"Çoğu işlemi modelle açıklıyor","l2":"Modeli yalnızca boyama için kullanıyor","l1":"Model ile işlem arasında bağ kurmuyor"},{"k":"Sistematik sunum","d":"Raporda adımların düzenli ve kontrol edilebilir olması","l4":"Soru-işlem-sonuç-kontrol eksiksiz","l3":"Bir bölüm kısa ama düzenli","l2":"Adımlar karışık","l1":"Yalnızca sonuç yazılmış"}],"navi":["Bir dilim 1/8 mi yoksa 1/12 mi daha büyük? Bu, pay sayısını karşılaştırırken neyi değiştirir?","Kalan miktar 1'den büyük çıktıysa bu pizzalar için ne anlama geliyor?","Ondalık gösterimde bir rakam sürekli tekrar ediyorsa, kesrin paydasında ne olabilir?"],"diff":{"destek":"Önce yalnızca birinci pizza ile çalış: 3/8 yenince kalan kısmı bul, sonra 12 dilimli pizzaya geç; ortak payda için 24 dilimli bir pizza modeli kullan.","ileri":"Üçüncü bir pizzanın 7/10'u yenmiş olsun. Üç kişinin yediklerini sırala ve kalan tüm pizzayı 6 kişiye bölünce kişi başı payın 1/4'ten büyük olup olmadığını gerekçelendir."},"misconception":"Kesirleri karşılaştırırken yalnızca paylara bakmak veya toplarken payları ve paydaları ayrı ayrı toplamak."},{"id":"mat-7-12","course":"MAT","grade":7,"themeNo":2,"themeName":"Sayılar Ve Nicelikler (2)","title":"Limonata Standı Tarif Büyütücü","subtitle":"Oran, orantı ve doğru orantı — Tarif ölçekleme","kazanim":["Gerçek yaşam durumları üzerinden orantılı durumları yorumlayabilme","Gerçek yaşam durumları üzerinden doğru orantılı durumlara ilişkin problemleri çözebilme"],"skills21":["Analitik Düşünme","Gerçeği Arama","Yaratıcılık"],"digital":["Dijital Oran Tabloları"],"duration":"80 dk (2 ders)","format":"İkili","tools":["Ücretsiz bir elektronik tablo uygulaması","Hesap makinesi","Defter"],"scenario":"Okulun bilim şenliğinde misafirlere ikram edilecek limonatanın tarifi sende. Ninenin tarifi 4 bardak için: 2 limon, 800 mL su ve 6 tatlı kaşığı şeker. Şenliğe 60 kişi gelecek ve her misafire bir bardak verilecek. Ayrıca tarifte \"buzlu sürahiyi 20 dakika dinlendir\" notu var. Hangi miktarlar misafir sayısıyla orantılı artar, hangileri artmaz ve 60 bardak için tam olarak ne gerekir?","visual":{"type":"organizer","params":{"kind":"tablo","slots":["Bardak sayısı","Limon (adet)","Su (mL)","Şeker (tatlı kaşığı)","Dinlenme süresi (dk)"]},"caption":"Öğrenci 4, 8, 12, 60 bardak için tabloyu doldurur ve hangi sütunun orantılı değiştiğini işaretler."},"steps":[{"title":"Oranları Keşfet","mode":"İkili · 15 dk","items":["Tarifteki her malzeme için 'bardak başına' miktarı bul (birim oran).","Su ile limon arasındaki oranı, şeker ile su arasındaki oranı yaz ve sadeleştir.","Oran ile kesir arasındaki benzerliği ve farkı kendi cümlelerinle açıkla."]},{"title":"Tabloyu Doldur","mode":"İkili · 25 dk","items":["Elektronik tabloda 4, 8, 12, 20 ve 60 bardak için satırlar oluştur.","Her malzemeyi formülle hesaplat (ör. birim oran × bardak sayısı).","Dinlenme süresi sütununu da doldur ve bu sütunun neden farklı davrandığını tartış.","Bardak sayısı ile limon sayısını gösteren bir grafik çiz; noktalar nasıl diziliyor?"],"warn":"Sık yapılan hata: Her şeyi aynı sayıyla artırmak yerine aynı sayıyı eklemek (4 bardak → 2 limon ise 8 bardak → 6 limon demek). Ekleme ile katlama arasındaki farkı tablonda göster."},{"title":"Gerçek Hayat Kontrolü","mode":"İkili · 20 dk","items":["60 bardak için 30 limon çıktıysa, limonların yarısı küçükse sonucu nasıl yorumlarsın?","Dinlenme süresi, sürahi sayısı ve misafir sayısından hangileri doğru orantılıdır? Her biri için gerekçe yaz.","Şekeri %25 azaltan 'daha sağlıklı' bir tarif öner ve yeni oranı yaz."],"warn":"Sık yapılan hata: İki çokluk birlikte artıyorsa mutlaka doğru orantılı olduğunu sanmak. Oranlarının sabit kalıp kalmadığını kontrol et."},{"title":"Tarif Kartı","mode":"İkili · 20 dk","items":["60 kişilik tarif kartını hazırla: malzemeler, miktarlar, hazırlık adımları.","Kartın altına 'Bu tarif kaç kişiye kadar ölçeklenebilir?' sorusuna kısa bir not ekle.","Kartını başka bir ikiliyle değiştir ve hesaplarını kontrol edin."]}],"checklist":["Her malzeme için birim oranı buldum.","Tabloyu formülle doldurdum.","Doğru orantılı olan ve olmayan çoklukları ayırdım.","Grafikteki noktaların dizilişini yorumladım.","60 kişilik tarif kartını hazırladım.","Başka bir ikilinin hesabını kontrol ettim."],"rubric":[{"k":"Birim oran","d":"Bardak başına miktarları doğru bulma","l4":"Tüm birim oranlar doğru ve sadeleştirilmiş","l3":"Bir küçük hata","l2":"Birim oran kavramı kısmen kullanılmış","l1":"Birim oran bulunamamış"},{"k":"Orantı muhakemesi","d":"Doğru orantılı olan/olmayan durumları ayırt etme","l4":"Tüm durumlar doğru ve sabit oranla gerekçelendirilmiş","l3":"Doğru ayrım, gerekçe kısmen","l2":"Bir durumda karışıklık","l1":"Ayrım yapılamamış"},{"k":"Tablo ve grafik","d":"Elektronik tabloda formül ve grafik kullanımı","l4":"Formüller ve grafik doğru, yorumlu","l3":"Formül doğru, grafik yorumu kısa","l2":"Değerler elle yazılmış","l1":"Tablo eksik"},{"k":"Yaratıcı uyarlama","d":"Yeni tarif önerisi ve oran güncellemesi","l4":"Yeni oran doğru ve mantıklı gerekçeli","l3":"Yeni oran doğru","l2":"Öneri var, oran hatalı","l1":"Öneri yok"}],"navi":["Tarifteki her sayıyı aynı sayıyla çarpsan ne olur, aynı sayıyı eklesen ne olur?","Dinlenme süresi 60 bardak için de 20 dakika mı kalmalı? Bunu nasıl anlarsın?","Grafikteki noktaları birleştirsen doğru hangi noktadan geçer?"],"diff":{"destek":"Yalnızca limon ve bardak sütunlarıyla başla; 4'ün katlarıyla (8, 12, 16) ilerleyip 60'a ulaş.","ileri":"Limonatayı 250 mL'lik bardaklar yerine 200 mL'lik bardaklarla vermek istersen 60 kişi için suyu ve limonu nasıl ayarlarsın? Ters orantılı bir ilişki var mı tartış."},"misconception":"Birlikte artan her iki çokluğun doğru orantılı olduğunu düşünmek veya ölçeklemede katlamak yerine sabit sayı eklemek."},{"id":"mat-7-13","course":"MAT","grade":7,"themeNo":3,"themeName":"İşlemlerle Cebirsel Düşünme Ve Değişimler","title":"Kütüphane Kolileri ve Asansör Sınırı","subtitle":"Denklem ve eşitsizlik kurma — Terazi modeli ve akış şeması","kazanim":["Birinci dereceden bir bilinmeyenli denklem ve birinci dereceden bir bilinmeyenli eşitsizlik içeren gerçek yaşam problemlerini çözebilme","Temel aritmetik ve cebirsel ifadelerle işlem içeren durumlardaki süreci algoritma ifade yöntemlerini kullanarak yapılandırabilme"],"skills21":["Eleştirel Düşünme","Soyutlama","Yaratıcılık","İspat Yapma"],"digital":["Algoritma Tasarımı","Cebirsel Modelleme Yazılımları"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor Stüdyo terazi modeli","Ücretsiz bir akış şeması aracı","Defter"],"scenario":"Okul kütüphanesine kitap bağışı geldi: 3 özdeş koli ve 12 kg'lık bir sözlük paketi baskülde toplam 48 kg geliyor. Kolileri üst kattaki kütüphaneye taşımak için en fazla 150 kg taşıyabilen yük asansörü kullanılacak ve asansöre kolilerle birlikte 70 kg'lık bir görevli binecek. Kütüphane gönüllüsü olarak senden iki şey isteniyor: Bir kolinin kütlesini bul ve tek seferde en çok kaç koli taşınabileceğini hesapla. Bu iki soruyu çözmek için hangi matematiksel cümleleri kurarsın?","visual":{"type":"balance","params":{"left":"3x + 12","right":"48","solution":12},"caption":"Öğrenci teraziyi dengede tutarak her iki kefeden aynı işlemi yapar ve bir kolinin kütlesini bulur."},"steps":[{"title":"Teraziyi Dengele","mode":"Bireysel · 15 dk","items":["Bir kolinin kütlesine x de ve durumu denklem olarak yaz.","Terazi modelinde önce iki kefeden 12 kg çıkar, sonra kalan kısmı 3'e böl.","Her adımda terazinin neden hâlâ dengede olduğunu bir cümleyle açıkla."],"warn":"Sık yapılan hata: Yalnızca bir kefeden işlem yapmak (sol taraftan 12 çıkarıp sağı aynen bırakmak). Terazi dengede kalır mı?"},{"title":"Eşitsizliği Kur","mode":"Bireysel · 20 dk","items":["Asansöre binen koli sayısına n de; görevli ve kolilerin toplam kütlesini n ile ifade et.","'En fazla 150 kg' ifadesini eşitsizlik olarak yaz ve çöz.","Bulduğun sonuç ondalıklı çıkarsa gerçek durumda koli sayısını nasıl yorumlarsın?","Çözüm kümesini sayı doğrusunda göster."],"warn":"Sık yapılan hata: Eşitsizlikte çıkan 6,6 gibi sonucu yukarı yuvarlayıp 7 koli demek. 7 koli asansör sınırını aşar mı? Yerine koyarak kontrol et."},{"title":"Çözümün Algoritması","mode":"Bireysel · 20 dk","items":["Denklem çözme sürecini başla-bitir kutuları olan bir akış şeması ile göster.","Eşitsizlik için ayrı bir dal ekle: 'Sonuç tam sayı mı?' karar kutusu kullan.","Akış şemanı 5x + 7 = 42 denklemiyle test et; her kutuda ne olduğunu yaz."]},{"title":"Problem Tasarla","mode":"Grup · 25 dk","items":["Grupça okula ait yeni bir taşıma problemi yazın (servis, dolap, raf vb.).","Problemde bir denklem ve bir eşitsizlik olsun; çözümü başka bir gruba verin.","Diğer grubun çözümünü akış şemanıza göre kontrol edip geri bildirim yazın."]}],"checklist":["Koli problemini denklem olarak yazdım ve çözdüm.","Terazi modelinde her iki kefeye aynı işlemi uyguladım.","Asansör durumunu eşitsizlik olarak kurdum.","Ondalıklı sonucu gerçek duruma göre yorumladım.","Çözüm sürecini akış şemasıyla gösterdim.","Grubumla özgün bir problem tasarladım."],"rubric":[{"k":"Matematiksel model","d":"Durumu denklem ve eşitsizlikle ifade etme","l4":"Her iki model de doğru ve değişkenler tanımlı","l3":"Modeller doğru, değişken tanımı eksik","l2":"Bir model hatalı","l1":"Model kurulamamış"},{"k":"Çözüm ve kontrol","d":"İşlemlerin doğruluğu ve yerine koyma ile kontrol","l4":"Doğru çözüm ve iki kontrol","l3":"Doğru çözüm, tek kontrol","l2":"Çözümde hata, kontrol yok","l1":"Çözüm yok"},{"k":"Bağlama göre yorum","d":"Ondalık sonucun gerçek durumda yorumlanması","l4":"Tam sayı kısıtını gerekçeyle açıklıyor","l3":"Doğru yorum, gerekçe kısa","l2":"Yuvarlama yönü hatalı","l1":"Yorum yok"},{"k":"Algoritma","d":"Akış şemasının açıklığı ve doğruluğu","l4":"Karar kutusu dahil eksiksiz ve test edilmiş","l3":"Doğru ama test edilmemiş","l2":"Adımlar eksik","l1":"Akış şeması yok"}],"navi":["Terazinin bir kefesinden bir şey alırsan dengenin bozulmaması için ne yapman gerekir?","Asansöre 6 koli koysan toplam kaç kg olur, 7 koli koysan kaç kg?","Akış şemanda 'sonuç tam sayı değilse' ne yapılmalı?"],"diff":{"destek":"Önce sözlük paketini çıkar: '3 koli 36 kg ise bir koli kaç kg?' sorusuyla başla, sonra 12 kg'ı geri ekleyip denklemi yaz.","ileri":"Asansöre ikinci bir görevli (65 kg) de binerse ve her seferde en az 2 koli taşınması gerekiyorsa, toplam 20 koli için en az kaç sefer gerekir? Çözümünü eşitsizlikle göster."},"misconception":"Eşitsizlik sonucunu bağlamdan bağımsız olarak yukarı yuvarlamak veya denklemde işlemi yalnızca bir tarafa uygulamak."},{"id":"mat-7-14","course":"MAT","grade":7,"themeNo":5,"themeName":"Geometrik Nicelikler (1)","title":"Sınıf Akvaryumu Tasarımı","subtitle":"Dikdörtgenler prizmasında hacim, yüzey alanı ve birim dönüşümü","kazanim":["Günlük hayat durumlarında dikdörtgenler prizmaları ile modellenen cisimlerin yüzey alanı ve hacmine yönelik problem çözebilme","Hacim ölçme birimleri arasındaki ilişkileri değerlendirebilme"],"skills21":["Çözümleme","Değerlendirme","Odaklanma"],"digital":["3D Modelleme","Hacim Simülasyonları"],"duration":"80 dk (2 ders)","format":"Grup","tools":["NavigAItor Stüdyo birim küp modeli","Ücretsiz bir 3B modelleme aracı","Cetvel ve kareli kâğıt"],"scenario":"Sınıfınız fen köşesi için üstü açık, dikdörtgenler prizması biçiminde bir akvaryum yaptıracak. İlk taslakta akvaryumun boyutları 6 dm × 3 dm × 4 dm. Balıkların sağlığı için suyun en az 60 litre olması, ama camın da olabildiğince az kullanılması gerekiyor. Tasarım ekibi olarak bu taslağı değerlendirin: Kaç litre su alır, kaç dm² cam gerekir ve daha az camla aynı su miktarını sağlayan başka bir tasarım var mı?","visual":{"type":"cubes","params":{"l":6,"w":3,"h":4},"caption":"Öğrenci sürgülerle boyutları değiştirerek prizmayı 1 dm³'lük birim küplerle doldurur ve hacmin nasıl değiştiğini izler."},"steps":[{"title":"Küplerle Doldur","mode":"Grup · 15 dk","items":["Modelde 6 × 3 × 4'lük prizmayı birim küplerle katman katman doldur.","Bir katmanda kaç küp olduğunu ve kaç katman olduğunu yaz; hacmi bul.","1 dm³ = 1 L ilişkisini kullanarak akvaryumun kaç litre su alacağını hesapla."],"warn":"Sık yapılan hata: dm³ ile cm³'ü karıştırmak. 1 dm³ kaç cm³'tür? Bir kenarı 10 cm olan küpü düşünerek kontrol et."},{"title":"Cam Hesabı","mode":"Grup · 20 dk","items":["Akvaryumun açınımını kareli kâğıda çiz; üst yüzün olmadığını unutma.","Her yüzün alanını hesapla ve toplam cam alanını bul.","Akvaryumu ağzına kadar değil, üstten 0,5 dm boş bırakarak doldurursanız su kaç litre olur?"],"warn":"Sık yapılan hata: Üstü açık kutuda da 6 yüzü saymak. Hangi yüzü çıkarman gerektiğini açınımda işaretle."},{"title":"Alternatif Tasarımlar","mode":"Grup · 30 dk","items":["3B modelleme aracında hacmi 72 dm³ olan en az üç farklı prizma tasarla (ör. 4 × 3 × 6, 6 × 6 × 2).","Her tasarım için gereken cam alanını tabloya yaz.","Balıklar için çok sığ veya çok dar tasarımların neden uygun olmayabileceğini tartışın.","En az camla en uygun tasarımı seçin."]},{"title":"Tasarım Önerisi","mode":"Grup · 15 dk","items":["Seçtiğiniz tasarımı boyutları, hacmi ve cam alanıyla bir tasarım kartında sunun.","Neden bu tasarımı seçtiğinizi en az iki ölçütle gerekçelendirin.","Diğer grupların önerilerini cam alanına göre sıralayın."]}],"checklist":["Prizmayı birim küplerle doldurarak hacmi buldum.","Hacmi litreye çevirdim.","Üstü açık akvaryumun cam alanını açınımla hesapladım.","Aynı hacimde en az üç farklı tasarım oluşturdum.","Tasarımları cam alanına göre karşılaştırdım.","Seçtiğim tasarımı iki ölçütle gerekçelendirdim."],"rubric":[{"k":"Hacim ve birim","d":"Hacim hesabı ve dm³–L–cm³ ilişkileri","l4":"Tüm hesaplar ve dönüşümler doğru","l3":"Bir dönüşümde küçük hata","l2":"Hacim doğru, dönüşüm hatalı","l1":"Hacim hesaplanamamış"},{"k":"Yüzey alanı","d":"Açınım ve üstü açık kutunun alanı","l4":"Açınım doğru, alan doğru","l3":"Alan doğru, açınım eksik","l2":"Fazladan yüz sayılmış","l1":"Alan hesaplanamamış"},{"k":"Tasarım karşılaştırması","d":"Aynı hacimli farklı prizmaları değerlendirme","l4":"Üç+ tasarım, tablo ve gerekçeli seçim","l3":"Üç tasarım, kısa gerekçe","l2":"İki tasarım","l1":"Tek tasarım"},{"k":"Odaklı iş birliği","d":"Grupta görev paylaşımı ve süreye uyum","l4":"Görevler net, süre içinde tamamlandı","l3":"Küçük gecikmeler","l2":"Görev paylaşımı belirsiz","l1":"Grup çalışması dağınık"}],"navi":["Tabandaki küp sayısını bildiğinde kaç katman olduğunu bilmek hacim için neden yeterli?","Hacim aynı kalırken yüzey alanı değişebilir mi? Hangi şekiller daha az cam ister?","Litre ile desimetreküp arasındaki ilişkiyi bir şişe suyla nasıl hayal edebilirsin?"],"diff":{"destek":"Önce 3 × 2 × 2'lik küçük bir kutuyla çalış; küpleri tek tek say, sonra çarpma ile kontrol et.","ileri":"Cam kalınlığı 0,1 dm olsaydı iç hacim ne kadar azalırdı? 60 L şartı hâlâ sağlanır mı?"},"misconception":"Hacmi aynı olan prizmaların yüzey alanlarının da eşit olduğunu düşünmek."},{"id":"mat-7-15","course":"MAT","grade":7,"themeNo":8,"themeName":"İstatistiksel Araştırma Süreci","title":"Okul Meclisinde Veri Savunması","subtitle":"Kategorik ve sürekli veriyle karar verme — Yanıltıcı iddiaları sorgulama","kazanim":["Kategorik veya nicel (sürekli) veri ile çalışabilme ve veriye dayalı karar verebilme","Başkaları tarafından oluşturulan kategorik veya nicel (sürekli) veriye dayalı istatistiksel sonuç veya yorumları tartışabilme"],"skills21":["Eleştirel Düşünme","Veri Okuryazarlığı","Sistematik Olma","Dürüstlük"],"digital":["Dijital Veri Analizi","Dijital Etik"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Ücretsiz bir elektronik tablo uygulaması","Hesap makinesi","Defter"],"scenario":"Okul meclisi, bahçedeki boş alanın neye dönüşeceğine karar verecek. Bir temsilci iki 7. sınıfta yapılan 30 kişilik ankete bakıp \"Öğrencilerin çoğu basketbol sahası istiyor!\" diyor. Ayrıca iki sınıfın teneffüste aktif oynadıkları süreler de ölçülmüş. Meclisin veri sorumlusu olarak bu iddiayı ve verileri inceleyeceksin: Bu iddia doğru mu, ve bahçe için veriye dayalı en adil öneri ne olur?","visual":{"type":"pie","params":{"labels":["Basketbol sahası","Okuma köşesi","Akıl oyunları alanı","Sebze bahçesi"],"values":[9,7,6,8]},"caption":"Öğrenci daire grafiğindeki dilimleri inceler, her dilimin yüzdesini bulur ve 'çoğu' iddiasını test eder."},"steps":[{"title":"İddiayı Test Et","mode":"Bireysel · 15 dk","items":["Grafikteki her seçeneğin toplam içindeki yüzdesini hesapla.","'Çoğu' kelimesinin matematiksel olarak yüzde kaçtan fazla demek olduğunu tartış.","Basketbol en çok tercih edilen seçenek mi, yoksa öğrencilerin çoğunluğu mu? Farkı açıkla."],"warn":"Sık yapılan hata: 'En çok seçilen' ile 'çoğunluğun seçtiği' ifadelerini aynı sanmak. %30 bir çoğunluk mudur?"},{"title":"Süreleri Çözümle","mode":"Bireysel · 25 dk","items":["7A sınıfının aktif oyun süreleri (dk): 4, 6, 8, 10, 12. 7B sınıfınınki: 2, 3, 8, 13, 14. Bu veriler elektronik tabloya gir.","Her sınıf için ortalamayı, açıklığı ve ortalama mutlak sapmayı hesapla.","Ortalamaları aynı olan iki sınıfı ne ayırıyor? Sonucu kendi cümlelerinle yorumla."],"warn":"Sık yapılan hata: Ortalamalar eşit diye iki veri grubunun aynı olduğunu düşünmek. Yayılım ölçüleri neyi gösteriyor?"},{"title":"Adil Öneri","mode":"Grup · 25 dk","items":["Anket yalnızca iki sınıfla yapıldı: Bu sonuçlar tüm okulu temsil eder mi? Tartışın.","Verilere dayanarak bahçe için bir öneri hazırlayın (ör. alanı bölmek, sırayla kullanmak).","Önerinizi destekleyen bir grafik oluşturun; grafiğin ekseni veya ölçeğiyle oynamadığınızdan emin olun."]},{"title":"Meclis Konuşması","mode":"Grup · 15 dk","items":["1 dakikalık bir meclis konuşması yazın: iddia, veri, düzeltme, öneri.","Konuşmada veriyi olduğundan farklı gösterecek ifadelerden kaçının.","Bir diğer grubun konuşmasını 'veriye sadakat' açısından değerlendirin."]}],"checklist":["Daire grafiğindeki her seçeneğin yüzdesini buldum.","'Çoğu' iddiasını matematiksel olarak sınadım.","İki sınıfın ortalama, açıklık ve ortalama mutlak sapmasını hesapladım.","Örneklemin temsil gücünü tartıştım.","Veriye dayalı ve dürüst bir öneri hazırladım.","Grafiğimin yanıltıcı olmadığını kontrol ettim."],"rubric":[{"k":"İstatistiksel hesaplama","d":"Yüzde, ortalama, açıklık ve ortalama mutlak sapma","l4":"Tüm değerler doğru","l3":"Bir değerde küçük hata","l2":"Yayılım ölçülerinde hata","l1":"Hesaplamalar eksik"},{"k":"İddiayı sorgulama","d":"Başkasının yorumunu veriyle tartışma","l4":"İddianın hatasını yüzde ve örneklemle gösteriyor","l3":"Hatanın bir yönünü gösteriyor","l2":"Hata fark ediliyor ama gerekçesiz","l1":"İddia sorgulanmıyor"},{"k":"Veriye dayalı karar","d":"Önerinin verilerle desteklenmesi","l4":"Öneri iki veri setine de dayanıyor","l3":"Öneri bir veri setine dayanıyor","l2":"Öneri veriyle zayıf bağlantılı","l1":"Öneri kişisel görüş"},{"k":"Dürüst sunum","d":"Grafik ve konuşmada veriye sadakat","l4":"Grafik ve dil tamamen dürüst ve açık","l3":"Küçük bir belirsizlik","l2":"Abartılı bir ifade var","l1":"Veri çarpıtılmış"}],"navi":["30 kişiden kaçı bir seçeneği seçerse o seçenek gerçekten 'çoğunluk' olur?","İki sınıfın ortalaması aynıysa, öğrencilerin teneffüs deneyimleri de aynı mıdır?","Anketi yalnızca iki sınıfla yapmak, okulun geri kalanı hakkında ne söylemeni engeller?"],"diff":{"destek":"Yüzde hesabı için 10 × 10'luk bir yüzlük tabloda 30 öğrenciyi 30 kare olarak boya; ortalama mutlak sapmada her sayının ortalamaya uzaklığını önce sayı doğrusunda göster.","ileri":"Okuma köşesi ile akıl oyunlarını isteyenler 'sessiz alan' olarak birleşirse sonuç nasıl değişir? Kategorileri birleştirmenin kararları nasıl etkileyebileceğini bir örnekle tartış."},"misconception":"En çok seçilen kategoriyi otomatik olarak çoğunluk saymak ve ortalaması eşit veri gruplarını özdeş kabul etmek."},{"id":"mat-8-16","course":"MAT","grade":8,"themeNo":1,"themeName":"Sayılar Ve Nicelikler","title":"Kare Bahçenin Gizemli Kenarı","subtitle":"Kareköklü ifadeler ve gerçek sayıların sayı doğrusunda yeri","kazanim":["Karşılaştığı problem durumlarında kareköklü ifadeler ile ilgili muhakeme yapabilme","Gerçek sayıları ve aralıklarını sayı doğrusunda yorumlayabilme"],"skills21":["Analitik Düşünme","Muhakeme","Merak","Gerçeği Arama"],"digital":["Dijital Bilimsel Hesaplama","Dinamik Sayı Doğrusu"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor Stüdyo sayı doğrusu","Bilimsel hesap makinesi","Kareli kâğıt"],"scenario":"Okulun bahçesinde alanı tam 50 m² olan kare biçimli bir sebze parseli ayrıldı. Bahçe kulübü parselin çevresine çit çekecek, ama çit teli yalnızca tam metre uzunluğunda satılıyor. Kulüp başkanı \"Kenar 7 metre, 28 metre tel yeter\" diyor; başka bir üye ise \"Bu kenar hiçbir zaman tam olarak yazılamaz\" diye itiraz ediyor. Kulübün matematik danışmanı olarak karar senin: Kim haklı ve en az kaç metre tel almak gerekir?","visual":{"type":"numberline","params":{"min":0,"max":10,"step":1,"target":7.07,"label":"√50"},"caption":"Öğrenci √50'yi önce iki tam sayı arasına, sonra onda birlik aralığa yerleştirerek noktayı sayı doğrusunda sürükler."},"steps":[{"title":"Kenarı Kıstır","mode":"Bireysel · 20 dk","items":["Alanı 50 m² olan karenin kenarını karekök olarak yaz.","√50'nin hangi iki ardışık tam sayı arasında olduğunu tam kare sayılarla göster.","7,0 ile 7,1 arasındaki onda birlikleri tek tek kareleyerek aralığı daralt.","Sayı doğrusunda √50'yi işaretle."],"warn":"Sık yapılan hata: √50'yi 25 sanmak (50'yi 2'ye bölmek). Karekök almak ile ikiye bölmek arasındaki farkı 5² ve 25'i karşılaştırarak açıkla."},{"title":"Kim Haklı?","mode":"Bireysel · 15 dk","items":["√50'yi a√b biçiminde yaz ve bu gösterimin neden 'tam' bir değer olduğunu açıkla.","Hesap makinesinde √50'nin ondalık gösterimine bak: Basamaklar bir düzen içinde tekrar ediyor mu?","Başkanın '7 metre' iddiasını kontrol et: 7 × 7 kaç m² eder, eksik alan ne kadar?"],"warn":"Sık yapılan hata: Hesap makinesinin gösterdiği 7,0710678 değerini tam değer sanmak. Ekranın sığmadığı basamaklar ne olur?"},{"title":"Çit Kararı","mode":"Grup · 25 dk","items":["Çevreyi kareköklü ifade olarak yazın ve yaklaşık değerini hesaplayın.","Tel tam metre satıldığına göre kaç metre alınmalı? Aşağı yuvarlamanın sonucunu tartışın.","Kapı için 1 m boşluk bırakılırsa kararınız değişir mi?"]},{"title":"Rasyonel mi İrrasyonel mi?","mode":"Grup · 20 dk","items":["Alanları 36, 45, 49, 72 ve 81 m² olan kare parsellerin kenarlarını yazın.","Hangi kenarların rasyonel, hangilerinin irrasyonel olduğunu sınıflandırın.","Hepsini aynı sayı doğrusunda gösterip küçükten büyüğe sıralayın."]}],"checklist":["Kenar uzunluğunu kareköklü ifade olarak yazdım.","√50'yi iki ardışık tam sayı ve onda birlikler arasına yerleştirdim.","√50'yi a√b biçiminde yazdım.","Gereken tel uzunluğunu bağlama göre yuvarlayarak buldum.","Beş parselin kenarlarını rasyonel/irrasyonel olarak sınıflandırdım.","Değerleri sayı doğrusunda sıraladım."],"rubric":[{"k":"Kareköklü muhakeme","d":"Kareköklü ifadeyi tahmin etme ve sadeleştirme","l4":"Tahmin ve a√b dönüşümü doğru, gerekçeli","l3":"Doğru ama gerekçe kısa","l2":"Tahmin doğru, dönüşüm hatalı","l1":"Karekök kavramı karışık"},{"k":"Sayı doğrusu","d":"Gerçek sayıları doğru konumlandırma","l4":"Tüm değerler doğru aralıkta ve sıralı","l3":"Bir değer kaymış","l2":"Yalnızca tam kareler doğru","l1":"Konumlandırma yapılmamış"},{"k":"Bağlama dayalı karar","d":"Yaklaşık değeri gerçek duruma uygun yuvarlama","l4":"Yuvarlama yönü ve kapı durumu gerekçeli","l3":"Yuvarlama doğru","l2":"Aşağı yuvarlanmış","l1":"Karar yok"},{"k":"Sınıflandırma","d":"Rasyonel ve irrasyonel ayrımı","l4":"Tüm sayılar doğru ve ölçütle","l3":"Bir hata","l2":"İki hata","l1":"Ayrım yapılamamış"}],"navi":["Hangi tam kare sayılar 50'ye en yakın? Bu sana kenar hakkında ne söyler?","Bir sayının ondalık basamakları hiç bitmiyor ve tekrar etmiyorsa onu kesir olarak yazabilir misin?","Teli eksik alırsan ne olur, fazla alırsan ne olur? Hangisi daha kabul edilebilir?"],"diff":{"destek":"Önce 1'den 10'a kadar sayıların karelerini tablo yap; 50'nin hangi iki kare arasında olduğunu tablodan bul.","ileri":"Alanı 50 m² olan parseli kare yerine kenarları oranı 1:2 olan bir dikdörtgen yaparsan çevre nasıl değişir? Hangisi daha az tel ister, kareköklü ifadelerle göster."},"misconception":"Karekök almayı sayıyı ikiye bölmek sanmak veya hesap makinesinin gösterdiği yaklaşık değeri tam değer kabul etmek."},{"id":"mat-8-17","course":"MAT","grade":8,"themeNo":2,"themeName":"Cebirsel Düşünme Ve Değişimler","title":"Fidan Yarışı","subtitle":"Doğrusal fonksiyonlar ve iki doğrunun kesişimi — Grafikle karar","kazanim":["Gerçek yaşam durumlarındaki doğrusal ilişkileri doğrusal fonksiyonlarla temsil edebilme","Dik koordinat sisteminde iki doğrusal fonksiyonun birbirine göre durumuna ilişkin çıkarım yapabilme"],"skills21":["Sistematik Olma","Temsil","Karar Verme","Görsel Okuryazarlık"],"digital":["Fonksiyon Grafik Çizim Yazılımları","Algoritma Tasarımı"],"duration":"80 dk (2 ders)","format":"İkili","tools":["Ücretsiz bir fonksiyon grafiği çizim aracı","Kareli kâğıt","Cetvel"],"scenario":"Okulun hatıra ormanına iki farklı türde fidan dikildi. A fidanı 30 cm boyunda dikildi ve her hafta 2 cm uzuyor; B fidanı 10 cm boyunda dikildi ama her hafta 4 cm uzuyor. Okul gazetesi \"Hangi fidan ne zaman öne geçecek?\" başlıklı bir haber hazırlıyor ve bilgiyi senden istiyor. Bu iki fidanın büyümesini nasıl modellersin ve B fidanı A'yı hangi haftada yakalar?","visual":{"type":"coord","params":{"points":[[0,10],[1,14],[2,18],[3,22],[5,30]],"line":{"m":4,"b":10}},"caption":"Öğrenci B fidanının verilerini koordinat sistemine yerleştirir, doğruyu çizer ve A fidanının doğrusunu ekleyerek kesişimi bulur."},"steps":[{"title":"Tablodan Fonksiyona","mode":"İkili · 20 dk","items":["Her iki fidan için 0–12. haftaları kapsayan bir tablo hazırla.","Boy ile hafta arasındaki ilişkiyi y = mx + n biçiminde yaz; m ve n'nin bu durumdaki anlamını açıkla.","Hangi fidanın büyüme hızının daha fazla olduğunu fonksiyondan söyle."],"warn":"Sık yapılan hata: Başlangıç boyunu (n) eğim, haftalık büyümeyi (m) sabit terim sanmak. 0. haftada boy kaçtır? Bu sana hangisinin sabit terim olduğunu gösterir."},{"title":"Grafikte Karşılaştır","mode":"İkili · 20 dk","items":["İki fonksiyonu aynı koordinat sisteminde kareli kâğıda çiz.","Grafik aracında da çizip kesişim noktasını bul; noktanın koordinatlarını gerçek durumda yorumla.","Kesişimden önce ve sonra hangi fidanın daha uzun olduğunu grafikten oku."],"warn":"Sık yapılan hata: Doğruların eksenlerle kesiştiği noktayı iki fidanın eşit olduğu an sanmak. Hangi nokta her iki doğrunun da üzerindedir?"},{"title":"Ya Böyle Olsaydı?","mode":"İkili · 20 dk","items":["C fidanı 20 cm dikilip haftada 2 cm uzasaydı A ile karşılaştırıldığında grafikte ne görürdün? Bu iki fidan hiç eşit olur mu?","Grafik aracında eğimi ve başlangıç değerini değiştirerek kesişimin nasıl kaydığını gözle.","Gözlemlerini 'Eğimler eşitse… / Eğimler farklıysa…' cümleleriyle yaz."]},{"title":"Gazete Kutusu","mode":"İkili · 20 dk","items":["Okul gazetesi için grafik + 3 cümlelik açıklamadan oluşan bir bilgi kutusu hazırla.","Gerçek hayatta fidanların sonsuza kadar doğrusal büyüyüp büyüyemeyeceğini bir cümleyle tartış.","Kesişim noktasını bulma adımlarını sıralı bir algoritma olarak yaz."]}],"checklist":["İki fidan için hafta–boy tablosu hazırladım.","Her fidanı doğrusal fonksiyon olarak yazdım.","Eğimin ve sabit terimin anlamını açıkladım.","İki doğruyu aynı grafikte çizip kesişimi yorumladım.","Paralel doğrular durumunu inceledim.","Gazete için grafikli bilgi kutusu hazırladım."],"rubric":[{"k":"Temsil","d":"Tablo, denklem ve grafik arasında geçiş","l4":"Üç temsil tutarlı ve doğru","l3":"İki temsil doğru","l2":"Bir temsil doğru","l1":"Temsiller hatalı"},{"k":"Eğim ve sabit terim","d":"m ve n'nin bağlamdaki anlamı","l4":"İkisi de doğru ve bağlamla açıklanmış","l3":"Doğru, açıklama kısa","l2":"Biri karıştırılmış","l1":"Anlam açıklanmamış"},{"k":"İki doğrunun durumu","d":"Kesişen ve paralel doğrular hakkında çıkarım","l4":"Kesişim ve paralellik gerekçeli","l3":"Kesişim doğru, paralellik eksik","l2":"Kesişim okunmuş ama yorumsuz","l1":"Çıkarım yok"},{"k":"Görsel iletişim","d":"Gazete kutusunun açıklığı","l4":"Grafik etiketli, açıklama doğru ve anlaşılır","l3":"Küçük eksik","l2":"Etiketler eksik","l1":"Kutu hazırlanmamış"}],"navi":["0. haftada iki fidan arasındaki fark kaç cm? Her hafta bu fark nasıl değişiyor?","Grafikte iki doğrunun aynı noktada olması fidanlar için ne anlama gelir?","Eğimleri aynı olan iki doğru hiç buluşur mu? Neden?"],"diff":{"destek":"Yalnızca tabloyla başla: Her hafta iki fidanın boyunu yan yana yaz ve farkın kapanmasını izle; sonra noktaları grafiğe taşı.","ileri":"A fidanı 8. haftadan sonra haftada 3 cm uzamaya başlarsa iki parçalı bir grafik çiz. Kesişim haftası değişir mi?"},"misconception":"Eğim ile sabit terimi karıştırmak ve iki doğrunun kesişimini eksenlerle kesişim noktalarıyla karıştırmak."},{"id":"mat-8-18","course":"MAT","grade":8,"themeNo":3,"themeName":"Geometrik Şekiller","title":"Gölgelik Yelkeni Mühendisleri","subtitle":"Üçgen eşitsizliği, açı-kenar ilişkisi ve Pisagor bağıntısı","kazanim":["Üçgende açı-kenar ilişkisi, üçgen eşitsizliği ve Pisagor bağıntısını içeren problemleri çözebilme","Kenar uzunlukları a²+ b²= c² eşitliğini sağlayan üçgenleri oluşturarak dik üçgen olduklarını; dik üçgenlerde dik kenar uzunluklarının kareleri toplamının hipotenüs uzunluğunun karesine eşit olduğunu yorumlayabilme"],"skills21":["Çıkarım Yapma","Problem Çözme","İspat","Yaratıcılık"],"digital":["Dinamik Geometri Yazılımları","Dijital İspat"],"duration":"120 dk (3 ders)","format":"Grup","tools":["Ücretsiz bir dinamik geometri yazılımı","Pipet veya çubuk, ip, makas","Cetvel ve iletki"],"scenario":"Okul bahçesindeki oturma alanına üçgen biçiminde gölgelik yelkenleri gerilecek. Tedarik listesinde dört kenar seti var (metre): (3, 4, 8), (6, 8, 10), (5, 12, 13) ve (7, 8, 11). Ayrıca yelkenin bir köşesi 3 m'lik direğin tepesine bağlanacak, ip ise direğin dibinden 4 m uzaktaki kazığa gerilecek. Tasarım ekibi olarak karar vermelisiniz: Hangi setlerle gerçekten üçgen yelken yapılabilir, hangileri dik köşeli olur ve gergi ipi en az kaç metre olmalı?","visual":{"type":"shapes","params":{"kind":"ucgen","labels":true},"caption":"Öğrenci üçgenin kenar uzunluklarını değiştirerek üçgenin oluşup oluşmadığını, en büyük açının hangi kenarın karşısında olduğunu ve dik açının ne zaman oluştuğunu inceler."},"steps":[{"title":"Çubuklarla Dene","mode":"Grup · 25 dk","items":["Her seti ölçekli çubuklarla (1 m = 2 cm) oluşturmayı deneyin.","Oluşmayan set için iki kısa kenarın toplamını en uzun kenarla karşılaştırın.","Gözleminizi genel bir kural olarak yazın."],"warn":"Sık yapılan hata: Üçgen eşitsizliğini yalnızca bir kenar için kontrol etmek. Hangi kenarı kontrol etmek yeterlidir, neden?"},{"title":"Dik mi Değil mi?","mode":"Grup · 30 dk","items":["Üçgen oluşturan setlerde iki kısa kenarın kareleri toplamını en uzun kenarın karesiyle karşılaştırın.","Dinamik geometri yazılımında üçgenleri çizip en büyük açıyı ölçün; sonucu hesabınızla eşleştirin.","Kareler toplamı büyükse ya da küçükse en büyük açının nasıl olduğunu tablo halinde yazın."],"warn":"Sık yapılan hata: Pisagor bağıntısında hipotenüs yerine herhangi bir kenarı c almak. Hipotenüs her zaman hangi açının karşısındadır?"},{"title":"Açı-Kenar İlişkisi","mode":"Grup · 20 dk","items":["(7, 8, 11) üçgeninde açıları ölçmeden büyükten küçüğe sıralayın.","Yazılımda ölçerek tahmininizi doğrulayın.","Bu ilişkiyi yelkenin en geniş köşesinin nereye bağlanması gerektiği kararında kullanın."]},{"title":"Gergi İpi ve Sunum","mode":"Grup · 45 dk","items":["Direk, zemin ve ipin oluşturduğu dik üçgeni çizin ve ipin uzunluğunu hesaplayın.","Düğümler için her uca 0,5 m pay ekleyerek alınması gereken ipi bulun.","Seçtiğiniz yelken seti, ip uzunluğu ve gerekçelerinizle bir tasarım posteri hazırlayın.","Posterde her kararınızı bir matematiksel ilkeyle eşleştirin."]}],"checklist":["Dört seti üçgen eşitsizliğiyle sınadım.","Üçgen oluşturan setlerin dik olup olmadığını Pisagor bağıntısıyla kontrol ettim.","Hesaplarımı dinamik geometri yazılımında doğruladım.","Bir üçgende açıları kenarlara göre sıraladım.","Gergi ipinin uzunluğunu düğüm payıyla hesapladım.","Kararlarımı gerekçeli bir posterde sundum."],"rubric":[{"k":"Üçgen eşitsizliği","d":"Kenar setlerinin üçgen oluşturma koşulu","l4":"Tüm setler doğru, genel kural gerekçeli","l3":"Doğru sınıflandırma, kural kısa","l2":"Bir set hatalı","l1":"Koşul uygulanmamış"},{"k":"Pisagor bağıntısı","d":"Dik üçgen tespiti ve ip hesabı","l4":"Tespit ve hesap doğru, hipotenüs doğru seçilmiş","l3":"Bir küçük hata","l2":"Hipotenüs karıştırılmış","l1":"Bağıntı kullanılmamış"},{"k":"Açı-kenar ilişkisi","d":"Kenarlardan açı sıralaması","l4":"Doğru sıralama ve ölçümle doğrulama","l3":"Doğru sıralama","l2":"Kısmen doğru","l1":"Sıralama yok"},{"k":"Gerekçeli tasarım","d":"Posterde kararların ilkelerle eşleşmesi","l4":"Her karar ilkeye bağlı ve özgün","l3":"Çoğu karar gerekçeli","l2":"Gerekçeler sınırlı","l1":"Gerekçe yok"}],"navi":["İki kısa çubuğu uç uca koyduğunda en uzun çubuktan kısa kalıyorlarsa köşeler buluşabilir mi?","Bir üçgende en uzun kenarın karşısındaki açı hakkında ne söyleyebilirsin?","Kareler toplamı en uzun kenarın karesinden büyük çıkarsa, en büyük açı dik açıdan büyük mü küçük mü olur?"],"diff":{"destek":"Önce yalnızca (6, 8, 10) setiyle kareli kâğıtta çalış: Kenarlara kareler çizip karelerin alanlarını karşılaştır.","ileri":"Direk 2,4 m, kazık uzaklığı 1,8 m olursa ip kaç metre olur? Bu üçlünün (3, 4, 5) ile ilişkisini benzerlik açısından açıkla ve kendi Pisagor üçlünü üret."},"misconception":"Herhangi üç uzunlukla üçgen oluşturulabileceğini düşünmek veya Pisagor bağıntısında hipotenüs dışındaki bir kenarı c olarak almak."},{"id":"mat-8-19","course":"MAT","grade":8,"themeNo":6,"themeName":"İstatistiksel Araştırma Süreci","title":"Bisiklet Parkı Gerekli mi?","subtitle":"Evren-örneklem, veri toplama ve yanıltıcı yorumları sorgulama","kazanim":["Kategorik veya nicel (kesikli-sürekli) veri ile çalışabilme ve veriye dayalı karar verebilme","Başkaları tarafından oluşturulan kategorik veya nicel (kesikli-sürekli) veriye dayalı istatistiksel sonuç veya yorumları tartışabilme"],"skills21":["Eleştirel Düşünme","Veri Okuryazarlığı","İş Birliği","Sorumlu Karar Verme"],"digital":["Dijital Anket","Dijital Veri Analizi ve Raporlama","Dijital Etik"],"duration":"120 dk (3 ders)","format":"Grup","tools":["Ücretsiz bir çevrim içi anket aracı","Ücretsiz bir elektronik tablo uygulaması","Ücretsiz bir infografik aracı"],"scenario":"Okul yönetimi bahçeye bisiklet parkı yapılmasını düşünüyor. Bir öğrenci grubu yalnızca 8. sınıflardan 60 kişiye \"Okula nasıl geliyorsun?\" diye sormuş ve sonuçlara bakıp \"Okulda bisikletle gelen yok denecek kadar az, bisiklet parkı gereksiz\" demiş. Siz okulun veri ekibisiniz ve yönetim bu yorumu sizin incelemenizi istiyor. Bu sonuç güvenilir mi ve doğru kararı vermek için nasıl bir araştırma yapmalısınız?","visual":{"type":"bars","params":{"title":"Okula geliş şekli (örneklem: 8. sınıflar, 60 kişi)","labels":["Yürüyerek","Servis","Toplu taşıma","Aile aracı","Bisiklet"],"values":[22,14,10,10,4],"unit":"öğrenci","editable":false},"caption":"Öğrenci sütun grafiğini okuyarak iddiayı inceler ve grafiğin hangi soruya cevap verip hangisine vermediğini belirler."},"steps":[{"title":"Grafiği Sorgula","mode":"Grup · 25 dk","items":["Grafikteki her kategorinin yüzdesini hesaplayın.","Anketin evrenini ve örneklemini yazın; örneklem evreni temsil ediyor mu?","Anket sorusu 'şu an nasıl geliyorsun?' iken 'bisiklet parkı gereksiz' sonucuna varılabilir mi? Tartışın."],"warn":"Sık yapılan hata: Mevcut davranışı gösteren veriden gelecekteki ihtiyaç hakkında kesin sonuç çıkarmak. Park olmadığı için bisikletle gelmeyenler olabilir mi?"},{"title":"Araştırmayı Tasarla","mode":"Grup · 30 dk","items":["Araştırma sorunuzu yazın ve evren ile örneklemi belirleyin (her sınıf düzeyinden kaç kişi?).","Çevrim içi anket aracında en az 5 soruluk bir anket hazırlayın; kategorik, kesikli ve sürekli veri toplayan birer soru olsun (ör. ev-okul arası mesafe).","Anketi kimlik bilgisi istemeyecek şekilde düzenleyin ve katılımın gönüllü olduğunu belirtin."],"warn":"Sık yapılan hata: Yönlendirici soru yazmak ('Bisiklet parkı harika olmaz mı?'). Sorularınızı tarafsız hâle getirin."},{"title":"Veriyi Çözümle","mode":"Grup · 35 dk","items":["Toplanan veriyi (veya öğretmenin verdiği örnek veri setini) elektronik tabloya aktarın.","Kategorik veriler için sütun ya da daire grafiği, sürekli veriler için uygun bir grafik oluşturun.","Mesafe verisi için ortalama, ortanca ve açıklığı hesaplayıp yorumlayın.","Grafiklerinizin ekseninin sıfırdan başladığını ve ölçeğin yanıltıcı olmadığını kontrol edin."]},{"title":"Yönetime Rapor","mode":"Grup · 30 dk","items":["Bulgularınızı tek sayfalık bir infografikle özetleyin.","İlk iddiaya veriye dayalı ve saygılı bir cevap yazın.","Önerinizi ve araştırmanın sınırlılıklarını açıkça belirtin."]}],"checklist":["Grafikteki verilerin yüzdelerini hesapladım.","Evren ve örneklemi belirleyip temsil gücünü tartıştım.","Tarafsız sorulardan oluşan bir anket hazırladım.","Kişisel bilgileri korumaya dikkat ettim.","Verileri uygun grafiklerle gösterip yorumladım.","Yanıltıcı olmayan bir infografik rapor hazırladım."],"rubric":[{"k":"Eleştirel inceleme","d":"Başkasının yorumundaki örneklem ve soru sorunlarını bulma","l4":"İki sorunu da gerekçeyle açıklıyor","l3":"Bir sorunu iyi açıklıyor","l2":"Sorunu sezmiş ama açıklayamıyor","l1":"Yorum sorgulanmıyor"},{"k":"Araştırma tasarımı","d":"Soru, evren-örneklem ve anket kalitesi","l4":"Temsilî örneklem, tarafsız ve çeşitli veri türleri","l3":"Küçük eksikler","l2":"Örneklem veya sorular sorunlu","l1":"Tasarım yok"},{"k":"Veri analizi","d":"Grafik seçimi ve merkezi eğilim/yayılım","l4":"Doğru grafikler ve yorumlu hesaplar","l3":"Hesaplar doğru, yorum kısa","l2":"Grafik türü uygunsuz","l1":"Analiz eksik"},{"k":"Sorumlu raporlama","d":"Veri etiği ve dürüst sunum","l4":"Gizlilik korunmuş, sınırlılıklar açık","l3":"Gizlilik korunmuş","l2":"Sınırlılıklar yok","l1":"Yanıltıcı sunum"}],"navi":["Bu ankete katılanlar okulun tamamını temsil ediyor mu? Kimlerin sesi eksik?","'Nasıl geliyorsun?' sorusu ile 'Nasıl gelmek isterdin?' sorusunun cevapları neden farklı olabilir?","Bir grafiğin dikey ekseni 0 yerine 3'ten başlarsa okuyucu ne düşünebilir?"],"diff":{"destek":"Hazır bir 4 soruluk anket taslağıyla başla; her sorunun hangi veri türünü topladığını eşleştir.","ileri":"Okulda 480 öğrenci varsa sınıf düzeylerine göre orantılı bir örneklem planlayın ve örneklem büyüklüğünün sonuçların güvenilirliğini nasıl etkilediğini tartışın."},"misconception":"Küçük veya tek gruptan alınan örneklemin tüm evreni temsil ettiğini ve mevcut durumun ihtiyacı gösterdiğini varsaymak."},{"id":"mat-8-20","course":"MAT","grade":8,"themeNo":7,"themeName":"Veriden Olasılığa","title":"Şenlik Torbası: Şans mı Hesap mı?","subtitle":"Öznel, deneysel ve teorik olasılık — Simülasyonla karar","kazanim":["Gerçek yaşamda karşılaşabileceği bir olayın olasılığına ilişkin farklı olasılık yaklaşımlarından (öznel, deneysel, teorik) uygun olanı belirleyerek karar verebilme"],"skills21":["Sistematik Olma","Eleştirel Bakma","Karar Verme","Öz Farkındalık"],"digital":["Dijital Simülasyon","Veri Görselleştirme"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor Stüdyo torba simülasyonu","Ücretsiz bir elektronik tablo uygulaması","Defter"],"scenario":"Okul şenliğinde bir oyun standı kuruluyor: Torbada 5 kırmızı, 3 mavi ve 2 yeşil top var. Yeşil top çeken öğrenci çıkartma kazanacak. Stant görevlisi \"Yeşil çok az, bence neredeyse hiç kimse kazanamaz\" diyor; arkadaşın ise \"10 kişiden 2'si kesin kazanır\" diye iddia ediyor. Standın sorumlusu olarak kaç çıkartma hazırlanması gerektiğine sen karar vereceksin: Hangi olasılık yaklaşımına güvenmelisin?","visual":{"type":"dice","params":{"kind":"torba","items":["kırmızı","mavi","yeşil"],"counts":[5,3,2]},"caption":"Öğrenci torbadan geri koyarak top çeker, sonuçları sıklık tablosuna işler ve çekiliş sayısını artırarak deneysel olasılığın değişimini izler."},"steps":[{"title":"Önce Tahmin Et","mode":"Bireysel · 10 dk","items":["100 öğrenci oynasa kaç kişinin yeşil çekeceğini tahmin et ve bunu bir öznel olasılık olarak yaz.","Tahminini neye dayandırdığını bir cümleyle açıkla.","Görevlinin ve arkadaşının iddialarının hangi olasılık yaklaşımına benzediğini belirt."]},{"title":"Teorik Olasılık","mode":"Bireysel · 15 dk","items":["Tüm olası çıktıları ve yeşil çekme olayını yaz.","Yeşil, kırmızı ve mavi çekmenin teorik olasılıklarını hesapla; toplamlarını kontrol et.","Arkadaşının '10 kişiden 2'si kesin kazanır' iddiasını değerlendir."],"warn":"Sık yapılan hata: Teorik olasılığın küçük denemelerde kesinlikle gerçekleşeceğini sanmak. Olasılığın 2/10 olması 10 çekilişte tam 2 yeşil çıkacağı anlamına gelir mi?"},{"title":"Dene ve Kaydet","mode":"Grup · 25 dk","items":["Simülasyonda geri koyarak 20 çekiliş yapın ve sıklık tablosuna işleyin.","Aynı deneyi 100 ve 1000 çekilişle tekrarlayın.","Her deney için yeşilin deneysel olasılığını hesaplayın ve teorik olasılıkla karşılaştıran bir grafik çizin."],"warn":"Sık yapılan hata: Birkaç kez üst üste yeşil gelmediyse sıradaki çekilişte yeşil gelme olasılığının arttığını düşünmek. Torbadaki toplar değişti mi?"},{"title":"Karar ve Öz Değerlendirme","mode":"Grup · 30 dk","items":["Şenliğe 250 öğrencinin katılacağını varsayarak kaç çıkartma hazırlanması gerektiğine karar verin.","Kararda hangi yaklaşımı kullandığınızı ve neden daha güvenilir olduğunu yazın.","Biraz fazla çıkartma hazırlamanın gerekip gerekmediğini deneysel sonuçlardaki dalgalanmaya bakarak tartışın.","İlk tahminin ile sonuç arasındaki farkı düşün: Tahminlerini neler etkiledi?"]}],"checklist":["Kendi öznel tahminimi gerekçesiyle yazdım.","Her renk için teorik olasılığı hesapladım.","20, 100 ve 1000 çekilişlik deneyleri kaydettim.","Deneysel ve teorik olasılığı grafikte karşılaştırdım.","Çıkartma sayısı için gerekçeli bir karar verdim.","İlk tahminimle sonucu karşılaştırıp kendimi değerlendirdim."],"rubric":[{"k":"Olasılık yaklaşımları","d":"Öznel, deneysel ve teorik yaklaşımları ayırt etme","l4":"Üçünü de örnekle doğru ayırt ediyor","l3":"Üçünü ayırt ediyor, örnek eksik","l2":"İki yaklaşımı karıştırıyor","l1":"Ayrım yapılamıyor"},{"k":"Sistematik deney","d":"Deneylerin kaydı ve hesaplama","l4":"Tüm deneyler eksiksiz ve doğru","l3":"Bir deneyde küçük eksik","l2":"Kayıtlar düzensiz","l1":"Deney yapılmamış"},{"k":"Veriye dayalı karar","d":"Çıkartma sayısı kararının gerekçesi","l4":"Teorik ve deneysel sonuçları birlikte kullanıyor","l3":"Tek yaklaşımla doğru karar","l2":"Karar zayıf gerekçeli","l1":"Karar yok"},{"k":"Öz farkındalık","d":"Tahmin ile sonuç arasındaki farkı yorumlama","l4":"Önyargılarını somut olarak fark ediyor","l3":"Farkı açıklıyor","l2":"Farkı yalnızca belirtiyor","l1":"Değerlendirme yok"}],"navi":["Torbadaki 10 toptan kaçı yeşil? Bu, her çekilişte yeşil gelme şansın hakkında ne söylüyor?","20 çekilişlik sonucunla 1000 çekilişlik sonucun teorik değere uzaklığı neden farklı?","Hiç deneme yapma imkânın olmasaydı hangi yaklaşıma güvenirdin, torbanın içini bilmeseydin hangisine?"],"diff":{"destek":"Torbayı 2 kırmızı ve 1 yeşil topla sadeleştir; 30 çekiliş yaparak sıklık tablosunu doldur ve teorik değerle karşılaştır.","ileri":"Oyunu 'iki top çek, ikisi de yeşilse büyük ödül' olarak değiştirin (geri koymadan). Bu olayın teorik olasılığını bulun ve 1000 tekrarlı simülasyonla karşılaştırın."},"misconception":"Teorik olasılığın az sayıda denemede kesin sonuç vereceğini sanmak veya önceki sonuçların bağımsız bir çekilişin olasılığını değiştirdiğini düşünmek."},{"id":"fen-5-01","course":"FEN","grade":5,"themeNo":1,"themeName":"Gökyüzündeki Komşularımız Ve Biz","title":"Kayıp Ay Takvimi","subtitle":"Ay'ın evreleri ve bilimsel model oluşturma","kazanim":["Ay’ın evrelerini temsil eden bilimsel model oluşturabilme"],"skills21":["Merak","Sistematik düşünme","İş birliği","İletişim"],"digital":["Dijital Modelleme","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["El feneri","Top veya portakal","Kâğıt-kalem","NavigAItor Stüdyo"],"scenario":"Köydeki dedenin eski bir defteri var: 29 gece boyunca Ay'ın şeklini çizmiş ama sayfalar karışmış. Deden, \"Bu defter tarlayı ne zaman sulayacağımı gösteriyordu, sırasını bulabilir misin?\" diye soruyor. Sen gökyüzü dedektifisin ve elinde yalnızca bir el feneri, bir top ve kendi başın var. Ay'ın şekli gerçekten değişiyor mu, yoksa biz onu farklı açılardan mı görüyoruz?","visual":{"type":"solar","params":{"mode":"ay-evreleri"},"caption":"Animasyonu oynatıp durdurarak her konumda Dünya'dan görülen Ay şeklini kendi çizimlerinle karşılaştırırsın."},"steps":[{"title":"Önce Gökyüzünü Hatırla","mode":"Bireysel · 10 dk","items":["Son bir haftada Ay'ı gördüğün bir geceyi düşün; nasıl göründüğünü defterine çiz.","Dedenin defterinden karışan 6 çizimi (dolunay, ilk dördün, hilal vb.) tahminine göre sırala.","Sıralamanı neye göre yaptığını bir cümleyle yaz."]},{"title":"Modeli Kur","mode":"Grup · 25 dk","items":["Karanlık bir köşede el feneri Güneş, senin başın Dünya, elindeki top Ay olsun.","Topu kolun uzanmış hâlde başının çevresinde yavaşça döndür ve 8 farklı noktada dur.","Her noktada topun aydınlık kısmından ne kadarını gördüğünü bir tabloya çiz.","Grup arkadaşın aynı anda fenerin topa nereden vurduğunu gözlemleyip not etsin."],"warn":"Sık yapılan hata: Ay'ın karanlık kısmını Dünya'nın gölgesi sanmak. Modelinde başının gölgesi topun üzerine düşüyor mu? Kontrol et."},{"title":"Simülasyonla Karşılaştır","mode":"İkili · 20 dk","items":["NavigAItor Stüdyo'daki animasyonu oynat; her evrede durdur.","Kendi tablondaki çizimlerle animasyondaki görüntüleri eşleştir; farklı olanları işaretle.","Ay'ın Güneş'e bakan yüzünün her zaman aydınlık olduğunu gösteren bir kanıt yaz."],"warn":"Sık yapılan hata: Animasyonu yalnızca izleyip geçmek. Her durdurduğun karede 'Dünya'dan bakınca ne görürdüm?' sorusunu sor."},{"title":"Dedenin Takvimini Tamamla","mode":"Bireysel · 25 dk","items":["Dedenin 6 çizimini doğru sıraya koy ve aralarındaki yaklaşık gün sayısını yaz.","Ay takvimini dijital bir afiş olarak hazırla: her evrenin adı, çizimi ve Ay-Dünya-Güneş konumu.","Afişin altına modelinin bir sınırlılığını yaz (örneğin topun boyutu, mesafeler)."]}],"checklist":["Ay'ın 8 konumunu modelimle gözlemleyip tabloya çizdim.","Her evrenin adını doğru yazdım.","Ay'ın ışığını Güneş'ten aldığını kanıtla açıkladım.","Dedenin çizimlerini doğru sıraya koydum.","Afişimde modelimin bir sınırlılığını belirttim.","Çalışmamı NavigAItor'a yükledim."],"rubric":[{"k":"Model kurma","d":"Güneş-Dünya-Ay rollerini doğru konumlandırma","l4":"Model tüm konumlarda doğru ve tutarlı çalışıyor","l3":"Model çoğu konumda doğru","l2":"Roller doğru ama konumlar karışık","l1":"Model kurulmamış ya da roller yanlış"},{"k":"Gözlem kaydı","d":"8 konumun tabloya çizilmesi","l4":"8 konum eksiksiz ve özenli çizilmiş","l3":"6–7 konum doğru çizilmiş","l2":"3–5 konum çizilmiş","l1":"Kayıt yok ya da çok eksik"},{"k":"Bilimsel açıklama","d":"Evrelerin nedenini açıklama","l4":"Görme açısı ve aydınlanmayı kanıtla açıklıyor","l3":"Nedeni doğru ama kanıt zayıf","l2":"Kısmen doğru, gölge yanılgısı izleri var","l1":"Açıklama yok ya da yanlış"},{"k":"Ürün ve iletişim","d":"Ay takvimi afişi","l4":"Afiş düzenli, sıralama doğru, sınırlılık yazılmış","l3":"Afiş anlaşılır, küçük eksikler var","l2":"Afiş eksik bilgi içeriyor","l1":"Afiş hazırlanmamış"}],"navi":["Topu döndürürken fener hiç yerinden oynadı mı? Öyleyse değişen ne?","Topun yarısı hep aydınlıksa, sen neden bazen yalnızca ince bir şerit görüyorsun?"],"diff":{"destek":"8 yerine 4 ana evreyle (yeni ay, ilk dördün, dolunay, son dördün) çalışır ve hazır şablona çizer.","ileri":"Ay'ın bize hep aynı yüzünü göstermesini, dönme ve dolanma sürelerini modele ekleyerek açıklar."},"misconception":"Ay'ın evrelerinin, Dünya'nın gölgesinin Ay'ın üzerine düşmesiyle oluştuğunu düşünmek."},{"id":"fen-5-02","course":"FEN","grade":5,"themeNo":2,"themeName":"Kuvveti Tanıyalım","title":"Kaymayan Okul Koridoru","subtitle":"Sürtünme kuvveti ve tümevarımsal akıl yürütme","kazanim":["Sürtünme kuvvetinin çeşitli ortamlardaki etkilerine yönelik tümevarımsal akıl yürütebilme"],"skills21":["Analitik düşünme","Problem çözme","İş birliği","Öz yansıtma"],"digital":["Dijital Simülasyon","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Grup","tools":["Ev yapımı dinamometre veya lastik","Küçük kutu","Farklı zemin parçaları (halı, karton, zımpara)","Hesap tablosu"],"scenario":"Okul müdürü yağmurlu günlerde koridorda öğrencilerin kaydığını fark etti; ama temizlik görevlisi ağır dolapları itmekte zorlanıyor. Müdür sizin gruptan bir rapor istiyor: \"Hangi zemin hem kaymayı önler hem de taşımayı zorlaştırmaz?\" Sen okulun Sürtünme Araştırma Ekibi'nin bir üyesisin. Farklı zeminlerde topladığın ölçümlerden genel bir kural çıkarabilir misin?","visual":{"type":"force","params":{"obj":"kutu","forces":[{"dir":"sag","n":10},{"dir":"sol","n":4}]},"caption":"Kutuyu iten kuvveti ve zemindeki sürtünme okunu değiştirerek kutunun hareketinin nasıl etkilendiğini gözlemlersin."},"steps":[{"title":"Tahmin Et","mode":"Bireysel · 10 dk","items":["Halı, parke, karton ve zımpara zeminlerini kutuyu çekmenin zorluğuna göre sırala.","Sıralamanın nedenini 'Çünkü yüzey...' diye başlayan bir cümleyle yaz."]},{"title":"Ölç ve Kaydet","mode":"Grup · 30 dk","items":["Kutuyu dinamometreyle her zeminde sabit yavaşlıkta çek; göstergeyi oku.","Her zemin için 3 ölçüm yap ve hesap tablosuna yaz.","Aynı kutuyu ıslak bir bez üzerinde de çek, sonucu ayrı satıra ekle."],"warn":"Sık yapılan hata: Her ölçümde farklı hızda çekmek. Hız değişirse karşılaştırma adil olmaz; tek değişken zemin olmalı."},{"title":"Kuralı Bul","mode":"Grup · 20 dk","items":["Tablodaki ölçümleri en küçükten en büyüğe sırala ve ilk tahminlerinle karşılaştır.","Örüntüyü bir genel kural olarak yaz: 'Yüzey ... olduğunda sürtünme ...'.","Simülasyonda sürtünme okunu küçültüp büyüterek kuralını test et."],"warn":"Sık yapılan hata: Tek bir ölçümden genel kural çıkarmak. Kuralın en az 4 farklı zeminde geçerli mi?"},{"title":"Müdüre Rapor","mode":"Grup · 20 dk","items":["Koridor için bir zemin önerisi ve bir çubuk grafikle kısa bir dijital rapor hazırla.","Sürtünmenin yararlı ve zararlı olduğu birer okul örneği ekle.","Raporun sonunda ekibinin en çok zorlandığı anı ve nasıl aştığını yaz."]}],"checklist":["Ölçüm öncesi tahminimi yazdım.","Her zeminde 3 ölçüm yapıp tabloya kaydettim.","Ölçümleri sabit hızla yaptım.","Verilerden genel bir kural çıkardım.","Raporda grafik ve zemin önerisi var.","Sürtünmenin hem yararlı hem zararlı örneğini yazdım."],"rubric":[{"k":"Adil deney","d":"Değişkenlerin kontrolü","l4":"Yalnızca zemin değişiyor, ölçümler tekrarlanmış","l3":"Değişken kontrolü çoğunlukla sağlanmış","l2":"Birden fazla değişken değişmiş","l1":"Deney planı yok"},{"k":"Veri kaydı","d":"Tablo ve grafik","l4":"Tablo eksiksiz, grafik doğru ve okunaklı","l3":"Tablo tam, grafikte küçük hata","l2":"Veriler eksik","l1":"Veri kaydı yok"},{"k":"Tümevarımsal çıkarım","d":"Örneklerden genel kurala ulaşma","l4":"Kural tüm verilerle destekleniyor ve test edilmiş","l3":"Kural doğru ama testi sınırlı","l2":"Kural tek örneğe dayanıyor","l1":"Kural yok"},{"k":"Öneri ve öz yansıtma","d":"Müdüre rapor","l4":"Öneri veriye dayalı, yansıtma içten ve somut","l3":"Öneri mantıklı, yansıtma kısa","l2":"Öneri verisiz","l1":"Rapor yok"}],"navi":["Dinamometrenin gösterdiği sayıyı değiştiren tek şeyin zemin olduğundan nasıl emin olursun?","Hiç sürtünmesiz bir koridorda yürümeye çalışsaydın ne olurdu?"],"diff":{"destek":"İki zeminle (halı ve karton) başlar; ölçümleri hazır tabloya yazar.","ileri":"Kutuya ağırlık ekleyerek sürtünmenin cismin ağırlığıyla ilişkisi için ikinci bir kural dener."},"misconception":"Sürtünme kuvvetinin her zaman zararlı olduğunu ve yalnızca katı yüzeylerde oluştuğunu düşünmek."},{"id":"fen-5-03","course":"FEN","grade":5,"themeNo":3,"themeName":"Canlıların Yapısına Yolculuk","title":"Yaprağın İçine Yolculuk","subtitle":"Hücreden organizmaya: yapılanma basamakları","kazanim":["Hücre-doku-organ-sistem-organizma kavramlarını yapılandırabilme","Bitki ve hayvan hücrelerini temel kısımları ve özellikleri açısından karşılaştırabilme"],"skills21":["Sınıflandırma","Sistematik olma","Sorumluluk","Sağlık bilinci"],"digital":["Dijital Mikroskopi","Sanat Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor Stüdyo","Renkli kartonlar","Makas ve yapıştırıcı"],"scenario":"Bir bilim müzesi, çocuklar için \"Küçülme Makinesi\" adlı bir sergi hazırlıyor ve senden rehber metni istiyor. Ziyaretçiler önce koca bir ağacı görecek, sonra bir yaprağa, en sonunda da yaprağı oluşturan minik yapılara yaklaşacak. Bir de karşılaştırma köşesi olacak: aynı yolculuk bir insanda yapılsaydı ne görürdük? Sen sergi rehberisin: bir canlı, en küçük parçasından bütününe nasıl kurulur?","visual":{"type":"zoom","params":{"preset":"bitki"},"caption":"Bitkiden yaprağa, yapraktan hücreye tıklayarak yakınlaşır ve her basamağa doğru adı (hücre, doku, organ, sistem, organizma) yerleştirirsin."},"steps":[{"title":"Yakınlaş ve Adlandır","mode":"Bireysel · 15 dk","items":["Zoom görselinde her yakınlaşmada gördüğün yapıyı defterine çiz.","Her çizimin yanına 'hücre, doku, organ, sistem, organizma' sözcüklerinden uygun olanı yaz.","Hangi basamakta 'bunu çıplak gözle göremem' dediğini işaretle."],"warn":"Sık yapılan hata: Doku ile organı aynı şey sanmak. Organ, birden fazla dokunun birlikte görev yapmasıyla oluşur."},{"title":"Hücreleri Karşılaştır","mode":"İkili · 20 dk","items":["Yaprak hücresini ve bir hayvan hücresi görselini yan yana koy.","Venn şemasında ortak kısımları (zar, sitoplazma, çekirdek) ortaya, farkları kenarlara yaz.","Bitki hücresinin köşeli, hayvan hücresinin daha yuvarlak görünmesinin nedenini tartış."],"warn":"Sık yapılan hata: Hücre duvarını yalnızca 'kalın bir zar' sanmak. Hücre zarı her iki hücrede de vardır; duvar ek bir yapıdır."},{"title":"Merdiveni Kur","mode":"Grup · 30 dk","items":["Kartonlardan 5 basamaklı bir 'yapılanma merdiveni' hazırlayın: bitki ve insan için iki ayrı sütun.","Her basamağa bir örnek yazın (ör. kas hücresi → kas dokusu → kalp → dolaşım sistemi → insan).","Basamaklardan birini çıkarırsak ne olacağını bir cümleyle yazın."]},{"title":"Sergi Metnini Yaz","mode":"Bireysel · 15 dk","items":["Ziyaretçiler için 5 cümlelik bir rehber metni yaz; her cümle bir basamağı anlatsın.","Hücrelerimizin sağlığı için yapılabilecek bir öneriyle (beslenme, uyku) metni bitir.","Metnini ve merdiven fotoğrafını NavigAItor'a yükle."]}],"checklist":["Zoom görselindeki her basamağı çizip adlandırdım.","Bitki ve hayvan hücresini Venn şemasıyla karşılaştırdım.","Hücre duvarı ve kloroplastın yalnızca bitki hücresinde olduğunu yazdım.","Grubumla 5 basamaklı merdiveni iki canlı için kurduk.","Sergi metnimi 5 cümleyle yazdım.","Çalışmamı yükledim."],"rubric":[{"k":"Kavram sıralaması","d":"Hücre-doku-organ-sistem-organizma dizilişi","l4":"Sıra ve örnekler iki canlı için de doğru","l3":"Sıra doğru, bir örnek hatalı","l2":"Doku-organ karışıklığı var","l1":"Sıra kurulmamış"},{"k":"Hücre karşılaştırması","d":"Ortak ve farklı kısımlar","l4":"Tüm ortak ve farklı kısımlar doğru yerleştirilmiş","l3":"Bir kısım eksik","l2":"Ortaklar doğru, farklar karışık","l1":"Karşılaştırma yok"},{"k":"Model ürünü","d":"Yapılanma merdiveni","l4":"Özenli, anlaşılır ve örnekli","l3":"Anlaşılır, küçük eksikler","l2":"Eksik basamaklar var","l1":"Model yok"},{"k":"Bilimsel iletişim","d":"Sergi rehber metni","l4":"Açık, doğru ve sağlık önerisiyle bağlanmış","l3":"Doğru ama kısa","l2":"Kavram hataları var","l1":"Metin yok"}],"navi":["Yaprak tek bir hücre mi, yoksa birçok hücrenin birlikte çalışması mı? Bunu görselde nasıl anlarsın?","Bir hayvan hücresinin hücre duvarı olsaydı, hayvan hareket ederken ne olurdu sence?"],"diff":{"destek":"Merdivende yalnızca bitki sütununu doldurur; kavram kartlarını sürükleyerek eşleştirir.","ileri":"Destek ve hareket sistemi için de aynı merdiveni kurar ve kemik dokusuna bir örnek ekler."},"misconception":"Büyük canlıların hücrelerinin de büyük olduğunu, örneğin filin hücrelerinin farenin hücrelerinden büyük olduğunu düşünmek."},{"id":"fen-5-04","course":"FEN","grade":5,"themeNo":5,"themeName":"Maddenin Doğası","title":"Sıcak Çorba Görevi","subtitle":"Isı iletimi ve ısı yalıtımı modeli","kazanim":["Maddeleri ısı iletimi bakımından sınıflandırabilme","Isı yalıtımını gösteren bilimsel model oluşturabilme"],"skills21":["Analitik düşünme","Deney tasarlama","İş birliği","Yaratıcılık"],"digital":["Dijital Simülasyon","Veri Okuryazarlığı","Dijital Modelleme"],"duration":"120 dk (3 ders)","format":"Grup","tools":["Termometre","Cam kavanozlar","Yalıtım malzemeleri (yün, köpük, alüminyum folyo, gazete)","Hesap tablosu"],"scenario":"Sınıfınız kış gezisinde huzurevine sıcak çorba götürecek, ama yol 40 dakika sürüyor ve termos yok. Öğretmenin size kavanozlar ve evde bulunan malzemeler veriyor. Görevin, çorbayı en az ısı kaybıyla taşıyacak bir 'kavanoz montu' tasarlamak. Hangi malzeme ısıyı tutar, hangisi kaçırır ve bunu nasıl kanıtlarsın?","visual":{"type":"heat","params":{"materials":["metal","tahta","plastik"]},"caption":"Isı iletimi yarışını başlatır, hangi çubuğun ucunun önce ısındığını tahmin edip sonucu gözlemlersin."},"steps":[{"title":"Yarışı Tahmin Et","mode":"Bireysel · 15 dk","items":["Görseldeki metal, tahta ve plastik çubuktan hangisinin ucu önce ısınır? Tahminini yaz.","Animasyonu izle ve tahminini kontrol et.","Evindeki eşyaları 'ısıyı iyi iletir / az iletir' diye iki sütunda sınıflandır (en az 8 eşya)."],"warn":"Sık yapılan hata: Metalin 'soğuk bir madde' olduğunu düşünmek. Metal elinden ısıyı hızla aldığı için soğuk hissedilir."},{"title":"Deneyi Planla","mode":"Grup · 20 dk","items":["Her kavanoz aynı miktar ılık su alacak; değişen tek şey sarılan malzeme olacak.","Bir kavanozu hiç sarmadan karşılaştırma kavanozu olarak bırakın.","Ölçüm aralığını (örneğin her 10 dakikada bir) ve toplam süreyi kararlaştırın."],"warn":"Sık yapılan hata: Kavanozlara farklı miktarda ya da farklı sıcaklıkta su koymak. Başlangıç koşulları aynı olmalı."},{"title":"Ölç ve Grafikle","mode":"Grup · 45 dk","items":["Sıcak su yerine ılık musluk suyu kullanın; kaynar suyla çalışmayın.","40 dakika boyunca sıcaklıkları hesap tablosuna kaydedin.","Her kavanozun sıcaklık düşüşünü bir çizgi grafikte gösterin."]},{"title":"Kavanoz Montunu Tasarla","mode":"Grup · 40 dk","items":["Verilerinize göre en iyi iki malzemeyi birleştiren bir 'kavanoz montu' tasarlayın.","Tasarımın çizimini dijital olarak hazırlayın ve malzemelerin görevlerini etiketleyin.","Yünün ısı üretmediğini, ısının kaçmasını yavaşlattığını tasarım notunuza yazın."]}],"checklist":["Isı iletimi tahminimi yazıp animasyonla karşılaştırdım.","Eşyaları ısı iletimine göre sınıflandırdım.","Deneyde yalnızca sarılan malzemeyi değiştirdim.","Sıcaklık verilerini tabloya ve grafiğe aktardım.","Verilere dayanan bir yalıtım modeli tasarladım.","Güvenlik kuralına uyup kaynar su kullanmadım."],"rubric":[{"k":"Sınıflandırma","d":"Isı iletkeni ve yalıtkan maddeler","l4":"8+ eşya doğru sınıflandırılmış, gerekçeli","l3":"Çoğu doğru","l2":"Yarısı doğru","l1":"Sınıflandırma yok"},{"k":"Deney tasarımı","d":"Değişken kontrolü ve karşılaştırma kavanozu","l4":"Tüm koşullar eşit, karşılaştırma kavanozu var","l3":"Küçük bir kontrol eksikliği","l2":"Birden çok değişken değişmiş","l1":"Plan yok"},{"k":"Veri analizi","d":"Tablo, grafik, yorum","l4":"Grafik doğru ve yorum veriye dayalı","l3":"Grafik doğru, yorum kısa","l2":"Grafik hatalı","l1":"Veri yok"},{"k":"Yalıtım modeli","d":"Tasarım ve açıklama","l4":"Model verilere dayalı ve bilimsel açıklamalı","l3":"Model mantıklı, açıklama eksik","l2":"Model veriyle ilişkisiz","l1":"Model yok"}],"navi":["Yün atkı sana sıcaklık mı veriyor, yoksa senin sıcaklığının kaçmasını mı engelliyor? Bunu nasıl test edebilirsin?","Hiç sarılmamış kavanoz olmasaydı, diğer sonuçların iyi olduğunu neye göre söylerdin?"],"diff":{"destek":"İki malzemeyle (yün ve folyo) ve hazır tabloyla çalışır; ölçüm aralığı öğretmence verilir.","ileri":"Aynı malzemeden iki ve dört kat sararak kalınlığın etkisini ayrıca araştırır."},"misconception":"Yün, köpük gibi malzemelerin kendiliğinden ısı ürettiğini, metalin ise doğası gereği soğuk olduğunu düşünmek."},{"id":"fen-5-05","course":"FEN","grade":5,"themeNo":6,"themeName":"Yaşamımızdaki Elektrik","title":"Karanlık Çadır Feneri","subtitle":"Ampul parlaklığını etkileyen değişkenler ve hipotez","kazanim":["Bir elektrik devresindeki ampul parlaklığını etkileyen değişkenlerin neler olduğuna ilişkin hipotez oluşturabilme"],"skills21":["Sistematik olma","Problem çözme","İş birliği","Oyunseverlik"],"digital":["Dijital Devre Simülasyonları","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"İkili","tools":["Dijital devre simülasyonu","Pil, ampul, bağlantı kablosu (öğretmen gözetiminde)","Kâğıt-kalem"],"scenario":"İzci kampında çadırınızın feneri çok sönük yanıyor ve elinizde birkaç pil, birkaç ampul ve kablo var. Arkadaşın \"Pili ampule yaklaştıralım, daha parlak yanar\" diyor, sen pek emin değilsin. İkiniz kampın 'Işık Mühendisleri' olarak fikirleri test edeceksiniz. Ampulün parlaklığını gerçekte neler değiştirir ve bunu nasıl sınarsınız?","visual":{"type":"circuit","params":{"bulbs":2,"series":true,"material":false},"caption":"Ampul ve pil sayısını değiştirip anahtarı açıp kapatarak parlaklığın nasıl değiştiğini gözlemlersin."},"steps":[{"title":"Hipotezlerini Yaz","mode":"İkili · 15 dk","items":["Parlaklığı etkileyebileceğini düşündüğünüz en az 3 değişken listeleyin (pil sayısı, ampul sayısı, kablo uzunluğu, pilin konumu...).","Her biri için 'Eğer ... artarsa parlaklık ... çünkü ...' biçiminde bir hipotez yazın.","Arkadaşının 'pili yaklaştırma' fikrini de hipotez olarak listeye ekleyin."],"warn":"Sık yapılan hata: Hipotezi soru gibi yazmak. Hipotez, test edilebilen bir tahmin cümlesidir."},{"title":"Simülasyonda Sına","mode":"İkili · 30 dk","items":["Her denemede yalnızca bir değişkeni değiştirin, diğerlerini sabit tutun.","Parlaklığı 1 (çok sönük) ile 5 (çok parlak) arası bir ölçekle tabloya kaydedin.","Devre şemasını sembollerle çizin."],"warn":"Sık yapılan hata: Aynı anda hem pil hem ampul sayısını değiştirmek. O zaman hangisinin etki ettiğini bilemezsiniz."},{"title":"Gerçek Devrede Doğrula","mode":"İkili · 20 dk","items":["Öğretmenin gözetiminde yalnızca pille çalışın; prize asla kablo takmayın.","Simülasyonda en etkili bulduğunuz değişkeni gerçek devrede deneyin.","Sonuç simülasyonla aynı mı? Farklıysa olası nedenini yazın."]},{"title":"Kamp Raporu","mode":"İkili · 15 dk","items":["Hangi hipotezler desteklendi, hangileri çürütüldü? İki sütunlu tabloyla gösterin.","Çadır feneri için en iyi devre önerisini çizin ve gerekçesini yazın.","Devre elemanlarını eşleştiren 6 kartlık küçük bir oyun tasarlayın."]}],"checklist":["En az 3 test edilebilir hipotez yazdım.","Her denemede yalnızca bir değişkeni değiştirdim.","Parlaklık ölçeğiyle sonuçları tabloya kaydettim.","Devre şemasını sembollerle çizdim.","Hipotezlerin desteklenip desteklenmediğini belirttim.","Güvenlik kuralına uyup yalnızca pil kullandım."],"rubric":[{"k":"Hipotez kurma","d":"Test edilebilir, gerekçeli tahminler","l4":"3+ hipotez açık, test edilebilir ve gerekçeli","l3":"Hipotezler doğru biçimde, gerekçe kısa","l2":"Hipotezler soru ya da belirsiz","l1":"Hipotez yok"},{"k":"Değişken kontrolü","d":"Tek değişken ilkesi","l4":"Tüm denemelerde tek değişken","l3":"Bir denemede hata","l2":"Değişkenler sık karışmış","l1":"Kontrol yok"},{"k":"Şema ve kayıt","d":"Sembollerle devre şeması, tablo","l4":"Şema doğru, tablo eksiksiz","l3":"Küçük sembol hatası","l2":"Şema ya da tablo eksik","l1":"Kayıt yok"},{"k":"Sonuç ve öneri","d":"Hipotez değerlendirmesi ve fener önerisi","l4":"Kanıta dayalı karar ve özgün öneri","l3":"Doğru karar, öneri sade","l2":"Karar kanıtsız","l1":"Sonuç yok"}],"navi":["Pilin ampule uzaklığını değiştirdiğinde devredeki başka bir şey de değişti mi?","İki ampul aynı pile bağlandığında pilin 'gücü' nasıl paylaşılıyor olabilir?"],"diff":{"destek":"Yalnızca iki değişkenle (pil sayısı, ampul sayısı) çalışır; hipotez cümle kalıbı hazır verilir.","ileri":"Kablo uzunluğunu ve kalınlığını da değişken olarak ekler, sonuçları grafikle gösterir."},"misconception":"Akımın pilden çıkıp ampulde 'tükendiğini' ya da pile yakın olan ampulün daha parlak yanacağını düşünmek."},{"id":"fen-6-06","course":"FEN","grade":6,"themeNo":1,"themeName":"Güneş Sistemi Ve Tutulmalar","title":"Gölge Avcıları","subtitle":"Güneş ve Ay tutulmasının modeli","kazanim":["Güneş ve Ay tutulması ile ilgili bilimsel model oluşturabilme","Güneş ve Ay tutulması ile ilgili bilimsel çıkarım yapabilme"],"skills21":["Modelleme","İş birliği","Merak","Sistematik düşünme"],"digital":["Dijital Planetaryum","Bilgi Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Grup","tools":["El feneri","Büyük ve küçük top","Gökyüzü simülasyon uygulaması","Kâğıt-kalem"],"scenario":"Mahallenizde bir haber yayılıyor: \"Yarın gece Ay kızıla dönecek, Güneş kararıp kaybolacak!\" Bazı komşular endişeli. Belediyenin gökyüzü etkinliği için sizden, iki tutulma türünü herkesin anlayacağı bir modelle anlatmanız isteniyor. Sen ekibin 'Gölge Avcısı'sın. Güneş tutulması ile Ay tutulmasını ayıran şey nedir ve neden her ay tutulma olmaz?","visual":{"type":"solar","params":{"mode":"tutulma"},"caption":"Animasyonda Güneş, Dünya ve Ay'ı hizalayarak hangi dizilişte hangi tutulmanın oluştuğunu bulursun."},"steps":[{"title":"Dizilişleri Keşfet","mode":"İkili · 15 dk","items":["Animasyonu oynat; Güneş-Ay-Dünya ve Güneş-Dünya-Ay dizilişlerinde durdur.","Her dizilişte gölgenin nereye düştüğünü çiz ve tutulmanın adını yaz.","Tutulmanın hangi Ay evresinde gerçekleşebileceğini not et."],"warn":"Sık yapılan hata: Ay tutulmasını Ay'ın Güneş'in önüne geçmesi sanmak. Ay tutulmasında gölgeyi düşüren Dünya'dır."},{"title":"Fenerle Model Kur","mode":"Grup · 30 dk","items":["Fener Güneş, büyük top Dünya, küçük top Ay olsun; her iki tutulmayı canlandırın.","Ay'ın yörüngesini biraz eğik tutun ve her dolunayda tutulma olup olmadığını gözleyin.","Tam ve parçalı gölge bölgelerini kâğıda işaretleyin."],"warn":"Sık yapılan hata: Modelde Ay'ı Dünya ile tam aynı düzlemde döndürmek. O zaman her ay tutulma olur gibi görünür."},{"title":"Söylentiyi Sorgula","mode":"Grup · 15 dk","items":["Güvenilir bir resmî kurum sitesinden yaklaşan tutulma tarihlerini araştırın.","'Güneş kararıp kaybolacak' ifadesindeki bilimsel hatayı bulun ve düzeltin."]},{"title":"Etkinlik Kartı Hazırla","mode":"Bireysel · 20 dk","items":["İki tutulmayı karşılaştıran bir bilgi kartı hazırla: diziliş, Ay evresi, kimler görebilir.","Kartına 'Güneş'e asla çıplak gözle bakma' güvenlik uyarısını ekle.","Modelinin gerçeği nerede yansıtmadığını (boyut, uzaklık) bir cümleyle yaz."]}],"checklist":["İki tutulmanın dizilişini doğru çizdim.","Tutulmaların hangi Ay evresinde olduğunu yazdım.","Grubumla fener modelini kurup iki tutulmayı canlandırdık.","Neden her ay tutulma olmadığını açıkladım.","Söylentideki hatayı bilimsel olarak düzelttim.","Bilgi kartıma güvenlik uyarısını ekledim."],"rubric":[{"k":"Bilimsel model","d":"Fener modeliyle tutulmaları gösterme","l4":"İki tutulma ve eğik yörünge doğru gösterilmiş","l3":"İki tutulma doğru, yörünge eğikliği yok","l2":"Yalnızca biri doğru","l1":"Model yok"},{"k":"Bilimsel çıkarım","d":"Evre ve sıklık ilişkisi","l4":"Evre ve sıklık nedeniyle açıklanmış","l3":"Evre doğru, sıklık açıklaması zayıf","l2":"Kısmen doğru","l1":"Çıkarım yok"},{"k":"Bilgi okuryazarlığı","d":"Güvenilir kaynak ve söylenti analizi","l4":"Resmî kaynak kullanılmış, hata net düzeltilmiş","l3":"Kaynak var, düzeltme kısa","l2":"Kaynak belirsiz","l1":"Araştırma yok"},{"k":"İletişim","d":"Bilgi kartı","l4":"Karşılaştırmalı, güvenli ve sınırlılığı belirtilmiş","l3":"Anlaşılır, bir öğe eksik","l2":"Bilgi hataları var","l1":"Kart yok"}],"navi":["Ay her ay Güneş ile Dünya'nın arasından geçiyorsa, neden her ay Güneş tutulması görmüyoruz?","Ay tutulmasında Ay tamamen kaybolmuyor da kızıl görünüyorsa, ona hâlâ ışık nereden geliyor olabilir?"],"diff":{"destek":"Yalnızca iki dizilişi hazır şablona çizer; modeli öğretmenle birlikte kurar.","ileri":"Tam ve parçalı tutulmanın Dünya'nın farklı bölgelerinden neden farklı görüldüğünü modelde gösterir."},"misconception":"Ay tutulmasının, Ay'ın Güneş'in önüne geçmesiyle oluştuğunu ya da her dolunayda tutulma olduğunu düşünmek."},{"id":"fen-6-07","course":"FEN","grade":6,"themeNo":3,"themeName":"Canlılarda Sistemler","title":"Okul Bahçesi Tohum Laboratuvarı","subtitle":"Tohumun çimlenmesine etki eden faktörler","kazanim":["Tohumun çimlenmesine etki eden faktörlere ilişkin hipotez oluşturabilme"],"skills21":["Gözlem","Hipotez kurma","Sorumluluk","Sağlık bilinci"],"digital":["Veri Okuryazarlığı","Dijital Poster/Afiş"],"duration":"120 dk (3 ders)","format":"Grup","tools":["Fasulye veya nohut tohumu","Pamuk ve plastik kaplar","Hesap tablosu","Kâğıt-kalem"],"scenario":"Okul bahçesine ekilen fasulyelerin bir kısmı çimlendi, bir kısmı hiç çıkmadı. Bahçe kulübü 'tohumlar bozuktu' diyor, sen ise koşulların farklı olduğunu fark ettin: bir köşe gölgede, bir köşe hiç sulanmamış, bir köşe çok soğuk. Kulübün 'Tohum Araştırmacısı' olarak bir haftalık deney yapacaksın. Bir tohumun uyanması için gerçekten neye ihtiyacı var?","visual":{"type":"bars","params":{"title":"7. günde çimlenen tohum sayısı (10 tohumdan)","labels":["Sulu + ılık","Susuz","Sulu + soğuk","Sulu + karanlık"],"values":[0,0,0,0],"unit":"tohum","editable":true},"caption":"Her deney kabında çimlenen tohum sayısını çubuklara girerek koşulları karşılaştırırsın."},"steps":[{"title":"Hipotez Kur","mode":"Bireysel · 15 dk","items":["Su, sıcaklık ve ışığın çimlenmeye etkisi için birer hipotez yaz.","Her hipotezin yanına 'bunu doğrulamak için hangi kabı karşılaştırmalıyım?' notunu ekle.","Çubuk grafiğe tahminî değerlerini kurşun kalemle işaretle."],"warn":"Sık yapılan hata: Işığın çimlenme için şart olduğunu baştan doğru kabul etmek. Hipotez, deneyle sınanacak bir tahmindir."},{"title":"Deneyi Kur","mode":"Grup · 30 dk","items":["Dört kaba nemli pamuk ve 10'ar tohum koyun; kapları etiketleyin.","Kaplardan biri kuru kalsın, biri buzdolabına, biri karanlık dolaba, biri ılık ve aydınlık bir yere konsun.","Görev çizelgesi hazırlayın: kim hangi gün sulayıp sayım yapacak?"],"warn":"Sık yapılan hata: Kaplara farklı sayıda tohum ya da farklı tür tohum koymak. Karşılaştırma ancak eşit koşulla adil olur."},{"title":"Bir Hafta Gözlem","mode":"Grup · her gün 5 dk","items":["Her gün çimlenen tohumları sayıp hesap tablosuna yazın.","3. ve 7. günde birer fotoğraf çekin.","Karanlıkta çimlenen fidelerin rengini ve boyunu not edin."]},{"title":"Sonuçları Yorumla","mode":"Grup · 40 dk","items":["7. gün verilerini çubuk grafiğe girin ve hipotezlerinizle karşılaştırın.","Çimlenme ile sonraki büyüme için gereken koşullar arasındaki farkı tartışın.","Bahçe kulübü için 'Tohum Ekim Rehberi' adlı dijital bir afiş hazırlayın."]}],"checklist":["Su, sıcaklık ve ışık için birer hipotez yazdım.","Kaplarda tohum sayısı ve türünü eşit tuttum.","Bir hafta boyunca günlük sayım yaptım.","Verileri çubuk grafikte gösterdim.","Hangi hipotezlerin desteklendiğini açıkladım.","Ekim rehberi afişini hazırladım."],"rubric":[{"k":"Hipotez kurma","d":"Her faktör için test edilebilir tahmin","l4":"Üç hipotez açık ve karşılaştırılacak kaplar belirlenmiş","l3":"Hipotezler doğru, eşleştirme eksik","l2":"Hipotezler belirsiz","l1":"Hipotez yok"},{"k":"Deney düzeneği","d":"Kontrol kabı ve değişken kontrolü","l4":"Tek değişken ilkesine tam uygun","l3":"Küçük bir kontrol eksikliği","l2":"Birden çok değişken karışmış","l1":"Düzenek kurulmamış"},{"k":"Veri kaydı","d":"Günlük sayım ve grafik","l4":"7 günlük kayıt eksiksiz, grafik doğru","l3":"1–2 gün eksik","l2":"Kayıtlar düzensiz","l1":"Kayıt yok"},{"k":"Bilimsel çıkarım","d":"Hipotezlerin değerlendirilmesi","l4":"Kanıtla değerlendirilmiş, çimlenme-büyüme ayrımı yapılmış","l3":"Değerlendirme doğru ama kısa","l2":"Veriyle çelişen yorum","l1":"Çıkarım yok"}],"navi":["Toprağın altındaki bir tohum ışık görmüyorsa, çimlenmek için ışığa ihtiyacı olabilir mi?","Karanlıkta çimlenen fide, sonra karanlıkta kalırsa ne olabilir? Çimlenmek ve büyümek aynı şey mi?"],"diff":{"destek":"İki kapla (sulu ve susuz) çalışır; günlük sayımı hazır tabloya işaretler.","ileri":"Tuzlu su ile sulanan beşinci bir kap ekler ve toprak tuzlanmasının etkisini araştırır."},"misconception":"Tohumun çimlenebilmesi için ışığın mutlaka gerekli olduğunu düşünmek."},{"id":"fen-6-08","course":"FEN","grade":6,"themeNo":4,"themeName":"Işığın Yansıması Ve Renkler","title":"Periskop Ustası","subtitle":"Yansıma kanunu ve kanıt kullanma","kazanim":["Işığın yansımasında gelen ışın, yansıyan ışın ve yüzeyin normali arasındaki ilişki ile ilgili kanıt kullanabilme"],"skills21":["Gözlem","Çıkarım yapma","İş birliği","Yaratıcılık"],"digital":["Dijital Simülasyon","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"İkili","tools":["Küçük düz aynalar","Açıölçer","Karton kutu","NavigAItor Stüdyo"],"scenario":"Okulun tiyatro gösterisinde perdenin arkasındaki ışıkçı sahneyi göremiyor; ona bir periskop yapmanız gerekiyor. Ama aynaları rastgele yerleştirince görüntü hep yanlış yere gidiyor. Sen ve arkadaşın 'Işık Yolu Mühendisleri'siniz. Işığın aynaya çarpınca nereye gideceğini önceden kestirebilir misiniz?","visual":{"type":"light","params":{"mode":"yansima"},"caption":"Gelen ışının açısını sürgüyle değiştirir, yansıyan ışın ve normal arasındaki açıyı ölçüp kaydedersin."},"steps":[{"title":"Açıları Ölç","mode":"İkili · 20 dk","items":["Simülasyonda gelen ışını 20°, 35°, 50° ve 65° yapın; her seferinde yansıma açısını ölçün.","Açıları normale göre ölçtüğünüzden emin olun ve tabloya yazın.","Gelen ışın, yansıyan ışın ve normalin aynı düzlemde olup olmadığını gözleyin."],"warn":"Sık yapılan hata: Açıyı aynanın yüzeyinden ölçmek. Gelme ve yansıma açıları yüzeyin normalinden ölçülür."},{"title":"Kanıtı Topla","mode":"İkili · 15 dk","items":["Tablodaki her satırda gelme ve yansıma açılarını karşılaştırın.","Ortaya çıkan ilişkiyi tek cümleyle yazın ve en az 3 veri satırını kanıt olarak gösterin.","Gerçek bir ayna ve fenerle en az bir ölçümü tekrarlayın."]},{"title":"Periskopu Tasarla","mode":"İkili · 30 dk","items":["Kutunun iki ucuna aynaları hangi açıyla yerleştireceğinizi önce çizerek hesaplayın.","Işığın yolunu oklarla gösteren periskop şeması çizin.","Periskopu yapın ve perdenin arkasından test edin."],"warn":"Sık yapılan hata: Aynaları paralel değil, rastgele açılarla yerleştirmek. Çiziminizdeki açılar kanuna uyuyor mu?"},{"title":"Işıkçıya Kılavuz","mode":"İkili · 15 dk","items":["Periskobun nasıl çalıştığını yansıma kanunuyla açıklayan kısa bir kılavuz yazın.","Yaptığınız bir hatayı ve nasıl düzelttiğinizi ekleyin."]}],"checklist":["4 farklı açıda ölçüm yapıp tabloya yazdım.","Açıları normale göre ölçtüm.","Gelme ve yansıma açısı ilişkisini verilerle kanıtladım.","Periskop şemasında ışık yolunu oklarla gösterdim.","Periskobu yapıp test ettim.","Kılavuzumda yansıma kanununu kullandım."],"rubric":[{"k":"Ölçüm doğruluğu","d":"Normale göre açı ölçme","l4":"Tüm ölçümler normale göre ve doğru","l3":"Bir ölçümde küçük hata","l2":"Yüzeyden ölçme hataları","l1":"Ölçüm yok"},{"k":"Kanıt kullanma","d":"Verilerle ilişkiyi destekleme","l4":"İlişki net, 3+ veriyle desteklenmiş","l3":"İlişki doğru, kanıt az","l2":"Kanıtsız iddia","l1":"İlişki yazılmamış"},{"k":"Tasarım","d":"Periskop şeması ve ürün","l4":"Şema ve ürün doğru, test başarılı","l3":"Ürün çalışıyor, şema eksik","l2":"Ürün kısmen çalışıyor","l1":"Ürün yok"},{"k":"İletişim ve yansıtma","d":"Kılavuz","l4":"Açık, bilimsel ve hata analizli","l3":"Açık ama kısa","l2":"Kavram hataları var","l1":"Kılavuz yok"}],"navi":["Açıyı aynanın yüzeyinden mi, yoksa yüzeye dik çizgiden mi ölçtün? İkisi aynı sonucu verir mi?","Gelme açısını büyüttüğünde yansıyan ışın hangi yöne kaydı? Bu bir rastlantı olabilir mi?"],"diff":{"destek":"İki açıyla ölçüm yapar; normal çizgisi hazır çizilmiş şablon kullanır.","ileri":"Pürüzlü bir yüzeyde (buruşuk folyo) dağınık yansımayı gözlemler ve kanunun yine geçerli olup olmadığını tartışır."},"misconception":"Yansıma açısının aynanın yüzeyinden ölçüldüğünü ya da ışığın aynadan rastgele yönlere yansıdığını düşünmek."},{"id":"fen-6-09","course":"FEN","grade":6,"themeNo":5,"themeName":"Maddenin Ayırt Edici Özellikleri","title":"Gizemli Metal Dedektifi","subtitle":"Yoğunluk hesaplama ve veriye dayalı tahmin","kazanim":["Yoğunluğa ilişkin hesaplamalar yaparak bilimsel veriye dayalı tahmin edebilme"],"skills21":["Deney tasarlama","Analitik düşünme","Sistematik olma","Problem çözme"],"digital":["Veri Okuryazarlığı","Dijital Simülasyon"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Terazi","Dereceli silindir","Hesap makinesi","Hesap tablosu"],"scenario":"Bir hurda toplama merkezine üç parça gümüş renkli metal getirildi; etiketleri düşmüş. Görevli \"Hepsi aynı metal, boyutları farklı o kadar\" diyor. Sen merkezin genç malzeme dedektifisin ve elinde yalnızca terazi ile dereceli silindir var. Bir maddenin kimliğini, büyüklüğü değişse bile değişmeyen bir özellikten bulabilir misin?","visual":{"type":"coord","params":{"points":[[2,5.4],[4,10.8],[6,16.2]],"line":{"m":2.7,"b":0}},"caption":"Hacim-kütle noktalarını koordinat sistemine yerleştirir, doğrunun eğiminden yoğunluğu bulursun."},"steps":[{"title":"Veriyi Oku","mode":"Bireysel · 15 dk","items":["Görseldeki üç noktanın hacim (cm³) ve kütle (g) değerlerini tabloya yaz.","Her parça için kütleyi hacme bölerek yoğunluğu hesapla.","Üç sonucu karşılaştır: görevlinin iddiası doğru olabilir mi?"],"warn":"Sık yapılan hata: Hacmi kütleye bölmek. Yoğunluk = kütle ÷ hacim; birimi g/cm³ olmalı."},{"title":"Laboratuvarda Ölç","mode":"Grup · 30 dk","items":["Öğretmeninin verdiği iki farklı boyutta cismin kütlesini terazide ölçün.","Hacmini dereceli silindirde suyun yükselme miktarından bulun.","Yoğunlukları hesaplayıp hesap tablosuna kaydedin."],"warn":"Sık yapılan hata: Silindirin ölçeğini su yüzeyinin kenarından okumak. Göz hizasından, yüzeyin ortasından okunmalı."},{"title":"Tahmin Et ve Sına","mode":"Grup · 20 dk","items":["Kütle-hacim grafiğinizi çizin; noktalar bir doğru üzerinde mi?","Grafiğe bakarak 10 cm³'lük bir parçanın kütlesini tahmin edin.","Bulduğunuz yoğunluğu öğretmeninin verdiği tablodaki maddelerle eşleştirin."]},{"title":"Dedektif Raporu","mode":"Bireysel · 15 dk","items":["Üç metal parçasının aynı madde olup olmadığını verilerle gerekçelendir.","Yoğunluğun neden ayırt edici bir özellik olduğunu bir örnekle açıkla."]}],"checklist":["Üç parçanın yoğunluğunu doğru formülle hesapladım.","Birimleri (g, cm³, g/cm³) eksiksiz yazdım.","Laboratuvarda kütle ve hacim ölçtüm.","Kütle-hacim grafiği çizip yorumladım.","Grafikten veriye dayalı bir tahmin yaptım.","Raporumu kanıtlarla destekledim."],"rubric":[{"k":"Hesaplama","d":"Yoğunluk formülü ve birim","l4":"Tüm hesaplar ve birimler doğru","l3":"Bir hesap ya da birim hatası","l2":"Formül ters kullanılmış","l1":"Hesap yok"},{"k":"Ölçme becerisi","d":"Terazi ve dereceli silindir kullanımı","l4":"Ölçümler dikkatli ve tekrarlı","l3":"Ölçümler doğru, tekrar yok","l2":"Okuma hataları var","l1":"Ölçüm yapılmamış"},{"k":"Veriye dayalı tahmin","d":"Grafik ve tahmin","l4":"Grafik doğru, tahmin grafikle tutarlı","l3":"Tahmin doğru, grafik eksik","l2":"Tahmin veriyle ilişkisiz","l1":"Tahmin yok"},{"k":"Gerekçelendirme","d":"Dedektif raporu","l4":"Karar net ve kanıtlı, ayırt edici özellik açıklanmış","l3":"Karar doğru, açıklama kısa","l2":"Karar kanıtsız","l1":"Rapor yok"}],"navi":["Bir metal parçasını ikiye kesersen kütlesi ve hacmi ne olur? Peki ikisinin oranı?","Grafikteki noktalar aynı doğru üzerinde olmasaydı bu sana ne söylerdi?"],"diff":{"destek":"Tam sayılı değerlerle (ör. 2 cm³ – 6 g) ve hesap makinesiyle çalışır; formül kartı verilir.","ileri":"Farklı yoğunlukta ikinci bir maddenin doğrusunu aynı grafiğe ekler ve eğimleri karşılaştırır."},"misconception":"Büyük ya da ağır cisimlerin yoğunluğunun her zaman daha büyük olduğunu düşünmek."},{"id":"fen-6-10","course":"FEN","grade":6,"themeNo":7,"themeName":"Sürdürülebilir Yaşam Ve Etkileşim","title":"Sazlıktaki Sessizlik","subtitle":"Biyoçeşitlilik ve onu tehdit eden faktörler","kazanim":["Biyoçeşitliliğin doğal yaşam için önemini sorgulayabilme","Biyoçeşitliliği tehdit eden faktörleri araştırma verilerine dayalı tahmin edebilme"],"skills21":["Sorgulama","Tartışma","Sorumluluk","Eleştirel düşünme"],"digital":["Dijital Araştırma","Dijital İçerik Üretimi"],"duration":"120 dk (3 ders)","format":"Grup","tools":["Ücretsiz bir sunum aracı","Resmî kurum web siteleri","Kâğıt-kalem"],"scenario":"İlçenizin kenarındaki sazlık alan, yeni bir otopark için kurutulmak isteniyor. Yaşlı balıkçılar son yıllarda kurbağa seslerinin azaldığını, balıkçılların artık gelmediğini anlatıyor. Belediye meclisi bir öğrenci görüşü istiyor ve sizin grup 'Doğa Danışmanları' olarak seçildi. Bu sazlıktan tek bir canlı türü kaybolursa, geriye kalanlar için ne değişir?","visual":{"type":"flow","params":{"steps":["Sazlık bitkileri","Çekirge","Kurbağa","Balıkçıl"],"kind":"zincir"},"caption":"Besin zincirinden bir halkayı çıkarır ve diğer canlıların nasıl etkileneceğini zincir üzerinde işaretlersin."},"steps":[{"title":"Zinciri Sorgula","mode":"Grup · 20 dk","items":["Görseldeki zincirden kurbağayı çıkarın: çekirge ve balıkçıl sayısı nasıl değişir? Tahmininizi yazın.","Sazlıkta yaşayabilecek 4 canlı daha ekleyerek zinciri bir besin ağına dönüştürün.","Ağda tür sayısı arttıkça bir halkanın kaybının etkisi nasıl değişir? Tartışın."],"warn":"Sık yapılan hata: Bir türün yok olmasının yalnızca onu yiyen canlıyı etkilediğini düşünmek. Etki zincirin her iki yönüne yayılır."},{"title":"Tehditleri Araştır","mode":"Grup · 30 dk","items":["Resmî kurum sitelerinden sulak alanlarla ilgili güvenilir veriler bulun.","Biyoçeşitliliği tehdit eden en az 4 faktörü (kurutma, kirlilik, istilacı tür, aşırı avlanma...) listeleyin.","Her faktör için bu sazlıkta olma olasılığını 'yüksek/orta/düşük' diye tahmin edin ve gerekçesini yazın."],"warn":"Sık yapılan hata: Kaynağı belirsiz sosyal medya paylaşımlarını veri olarak kullanmak. Kaynağın kim olduğunu ve tarihini kontrol edin."},{"title":"Görüşleri Tartış","mode":"Grup · 30 dk","items":["Grubu ikiye ayırın: otopark isteyen esnaf ve sazlığı korumak isteyen balıkçılar.","Her taraf kanıta dayalı 3 gerekçe sunsun; sonra rolleri değiştirin.","Her iki tarafın ihtiyacını gözeten bir uzlaşı önerisi geliştirin."]},{"title":"Meclise Sunum","mode":"Grup · 40 dk","items":["Ücretsiz bir sunum aracıyla 4 slaytlık bir sunum hazırlayın: besin ağı, tehditler, tartışma, öneri.","Önerinizin kısa bir sosyal sorumluluk afişini ekleyin.","Sunumu sınıfa yapın ve bir soruyu yanıtlayın."]}],"checklist":["Besin zincirini en az 8 canlılık bir besin ağına genişlettim.","Bir türün kaybının etkisini iki yönlü açıkladım.","En az 4 tehdit faktörünü güvenilir verilerle tahmin ettim.","Tartışmada iki tarafın rolünü de üstlendim.","Uzlaşı önerimi gerekçelendirdim.","Sunumu ve afişi hazırlayıp sundum."],"rubric":[{"k":"Biyoçeşitliliği sorgulama","d":"Besin ağı ve tür kaybı analizi","l4":"Ağ zengin, etkiler iki yönlü ve doğru","l3":"Ağ doğru, etki tek yönlü","l2":"Yalnızca zincir düzeyinde","l1":"Analiz yok"},{"k":"Veriye dayalı tahmin","d":"Tehdit faktörleri","l4":"4+ faktör güvenilir verilerle derecelendirilmiş","l3":"Faktörler doğru, veri sınırlı","l2":"Kaynaksız tahmin","l1":"Tahmin yok"},{"k":"Tartışma","d":"Kanıt kullanma ve karşı görüşü dinleme","l4":"Her iki rolde kanıtlı ve saygılı","l3":"Kanıtlı, bir rolde zayıf","l2":"Kanıtsız görüş","l1":"Katılım yok"},{"k":"Çözüm ve ürün","d":"Uzlaşı önerisi ve sunum","l4":"Uygulanabilir, iki tarafı gözeten, özgün","l3":"Uygulanabilir ama tek taraflı","l2":"Belirsiz öneri","l1":"Öneri yok"}],"navi":["Kurbağalar azaldığında çekirgeler çoğalırsa, sazlık bitkilerine ne olabilir?","Otopark ve sazlık bir arada var olabilir mi? Bunu sağlayan koşullar neler olurdu?"],"diff":{"destek":"4 halkalı zincirle çalışır, tehdit faktörlerini hazır kartlardan seçer.","ileri":"Bir istilacı türün sazlığa eklenmesi durumunda besin ağının nasıl değişeceğini modeller."},"misconception":"Bir canlı türü yok olduğunda diğer türlerin onun yerini hemen doldurduğunu ve ekosistemin değişmeden kaldığını düşünmek."},{"id":"fen-7-12","course":"FEN","grade":7,"themeNo":2,"themeName":"Kuvvet Ve Enerjiyi Keşfedelim","title":"Hız Treni Mühendisi","subtitle":"Kinetik ve potansiyel enerjinin karşılaştırılması — Tasarım görevi","kazanim":["Enerji çeşitlerinden kinetik ve potansiyel enerjiyi karşılaştırabilme"],"skills21":["Karşılaştırma","Çıkarım yapma","Analitik düşünme","İş birliği"],"digital":["Dijital Simülasyon","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"İkili","tools":["NavigAItor Stüdyo enerji grafiği","Ücretsiz bir enerji simülasyonu","Cetvel, kâğıt, misket ve karton oluk"],"scenario":"Bir lunapark, çocuklar için güvenli ve heyecanlı yeni bir hız treni yaptırmak istiyor ve seni genç mühendis olarak ekibe aldı. Tren rayın en yüksek noktasından harekete başlıyor, inişler ve tepeler boyunca ilerliyor. Yönetici senden şunu istiyor: \"Trenin hangi noktada en hızlı, hangi noktada en yavaş olacağını enerjiyle açıkla.\" Trenin yüksekliği ve hızı değiştikçe sahip olduğu enerji türleri nasıl değişiyor?","visual":{"type":"bars","params":{"title":"Rayın 5 noktasında trenin enerjisi","labels":["A (en tepe)","B (iniş)","C (en alçak)","D (ikinci tepe)","E (varış)"],"values":[0,0,0,0,0],"unit":"enerji birimi","editable":true},"caption":"Her nokta için trenin kinetik ve potansiyel enerjisini tahmin edip çubukların boyunu ayarla."},"steps":[{"title":"Misket Rayını Dene","mode":"İkili · 20 dk","items":["Karton oluktan bir tepe, bir çukur ve ikinci daha alçak bir tepe olan bir ray yapın.","Misketi en yüksek noktadan bırakın; misketin en hızlı ve en yavaş göründüğü noktaları işaretleyin.","Aynı rayda misketi daha alçak bir noktadan bırakın. Hızındaki farkı gözleyip not edin."],"warn":"Sık yapılan hata: Misketi iterek bırakmak. İterseniz misket başlangıçta da kinetik enerjiye sahip olur ve karşılaştırma bozulur."},{"title":"Enerjiyi Grafikle","mode":"İkili · 25 dk","items":["Görseldeki A–E noktaları için trenin yüksekliğine bakarak potansiyel enerjiyi, hızına bakarak kinetik enerjiyi tahmin edin.","Çubuk grafiği önce potansiyel enerji için, sonra kinetik enerji için ayrı ayrı düzenleyin.","Simülasyonda aynı rayı deneyip tahminlerinizi kontrol edin; farklı olan noktaları kırmızıyla işaretleyin."],"warn":"Sık yapılan hata: Kinetik enerjiyi yalnızca kütleye bağlamak. Kinetik enerji hem kütleye hem sürate bağlıdır; potansiyel enerji ise kütleye ve yüksekliğe."},{"title":"Karşılaştır ve Karar Ver","mode":"İkili · 20 dk","items":["Kinetik ve potansiyel enerjiyi 'neye bağlıdır, ne zaman artar, ne zaman azalır' başlıklarıyla bir tabloda karşılaştırın.","Trende yolcular binince (kütle artınca) her iki enerji türü nasıl etkilenir? Tahminlerinizi gerekçelendirin.","İkinci tepe neden ilk tepeden alçak olmalı? Enerji açısından açıklayın."]},{"title":"Mühendis Raporu","mode":"Bireysel · 15 dk","items":["Lunapark yönetimine 5–6 cümlelik bir rapor yaz: Tren nerede en hızlı, nerede en yavaş ve neden?","Raporuna grafiğinin ekran görüntüsünü ekleyip NavigAItor'a yükle."]}],"checklist":["Misket deneyini yapıp en hızlı ve en yavaş noktaları işaretledim.","Her nokta için kinetik ve potansiyel enerji tahminimi grafikte gösterdim.","Simülasyonla tahminlerimi karşılaştırıp farkları işaretledim.","İki enerji türünün bağlı olduğu değişkenleri tabloda karşılaştırdım.","Mühendis raporumu gerekçelerle yazdım ve grafiği ekledim."],"rubric":[{"k":"Deney ve Gözlem","d":"Misket deneyini kontrollü yapma ve kaydetme","l4":"Değişkeni kontrol eder, iki bırakma yüksekliğini sistemli karşılaştırır.","l3":"Deneyi yapar, gözlemleri kaydeder.","l2":"Deneyi yapar ama kayıt eksik.","l1":"Deney yapılmamış."},{"k":"Kavramsal Karşılaştırma","d":"Kinetik ve potansiyel enerjinin bağlı olduğu değişkenler","l4":"Kütle, sürat ve yükseklik ilişkisini eksiksiz ve doğru karşılaştırır.","l3":"Değişkenleri çoğunlukla doğru karşılaştırır.","l2":"Bir değişkeni eksik veya yanlış ilişkilendirir.","l1":"Karşılaştırma yapamaz."},{"k":"Veri Görselleştirme","d":"Grafikteki tahminlerin tutarlılığı","l4":"Tüm noktalarda tutarlı grafik, farkları yorumlar.","l3":"Grafik büyük ölçüde tutarlı.","l2":"Grafikte birkaç tutarsızlık var.","l1":"Grafik hazırlanmamış."},{"k":"Bilimsel İletişim","d":"Raporun açıklığı ve gerekçesi","l4":"Rapor açık, enerji kavramlarıyla gerekçeli ve kanıta dayalı.","l3":"Rapor açık, gerekçe kısmen var.","l2":"Rapor yüzeysel.","l1":"Rapor yok."}],"navi":["Tren en tepedeyken yavaşsa, sahip olduğu enerji kaybolmuş mu olur, yoksa başka bir türde mi bekler?","Aynı hızla giden boş bir tren ile dolu bir tren arasında hangi enerji türü farklıdır? Neden?"],"diff":{"destek":"Yalnızca üç noktayla (tepe, iniş, en alçak) çalış; her nokta için 'yüksek / orta / düşük' etiketleriyle tahmin yap.","ileri":"Sürtünme olsaydı E noktasında trenin enerjisi nasıl olurdu? Grafiğe 'sürtünmeli' ikinci bir senaryo ekle."},"misconception":"Öğrenciler kinetik enerjinin yalnızca cismin kütlesine bağlı olduğunu, ağır cismin her zaman daha fazla kinetik enerjiye sahip olduğunu düşünür."},{"id":"fen-7-11","course":"FEN","grade":7,"themeNo":3,"themeName":"Vücudumuzdaki Sistemler","title":"Bir Damla Kanın Yolculuğu","subtitle":"Dolaşım sistemi ve kanın yapısı — Yakınlaşan model ile gözlem","kazanim":["Dolaşım sistemini oluşturan yapı ve organların görevlerini model üzerinde bilimsel olarak gözlemleyebilme","Kan bağışının toplumsal dayanışma açısından önemini tartışabilme"],"skills21":["Gözlem","Bilgi toplama","Tartışma","Sağlık bilinci","Empati"],"digital":["Dijital Modelleme","Bilgi Okuryazarlığı","Dijital Poster/Afiş"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor Stüdyo yakınlaşan kan modeli","Ücretsiz bir afiş tasarım aracı","Defter ve renkli kalemler"],"scenario":"Okulunda bir kan bağışı farkındalık haftası düzenleniyor ve sen 'Kan Elçisi' seçildin. Küçük kardeşi ameliyat olacak bir arkadaşın sana soruyor: \"Hastaneye neden kan lazım? Kanın içinde ne var ki başka birinin kanı işe yarıyor?\" Arkadaşına cevap verebilmek için kolundaki bir damardan başlayıp bir damla kanın içine kadar yolculuk yapacaksın. Kanın içindeki her yapı hangi görevi üstleniyor ve bağışlanan kan bir başkasının hayatını nasıl kurtarıyor?","visual":{"type":"zoom","params":{"preset":"kan"},"caption":"Vücuttan kola, koldan damara, damardan kanın içine tıklayarak yakınlaş; alyuvar, akyuvar ve kan pulcuğunu bulup her birinin görevini not et."},"steps":[{"title":"Yakınlaş ve Gözlemle","mode":"Bireysel · 20 dk","items":["Modelde vücuttan başla; kol → damar → kan sırasıyla her sahnede durup gördüğün yapıları defterine çiz.","Damar sahnesinde damarın duvarına ve içindeki akışa dikkat et: Kan hangi yöne akıyor olabilir? Tahminini yaz.","Kan sahnesinde üç farklı hücre/parçacık türünü bul. Her birinin şeklini, rengini ve sayıca çok mu az mı göründüğünü bir tabloya kaydet.","Tablona bir sütun daha ekle: 'Bu yapı ne iş yapıyor olabilir?' Gözlemine dayanarak tahmin et."],"warn":"Sık yapılan hata: Kanı tek bir sıvı sanmak. Kan; sıvı kısım (kan plazması) ve içinde yüzen farklı görevli hücrelerden oluşur. Gözlemlediğin yapıları tek tek ayırarak yaz."},{"title":"Görevleri Eşleştir","mode":"İkili · 15 dk","items":["Arkadaşınla tahminlerinizi karşılaştırın; NavigAItor'daki güvenilir kaynak kartlarından alyuvar, akyuvar ve kan pulcuğunun görevlerini kontrol edin.","Her yapı için bir 'iş tanımı kartı' yazın: Adı, görevi, vücutta bu görev olmasa ne olurdu?","Atardamar, toplardamar ve kılcal damarı karşılaştıran 3 satırlık bir tablo hazırlayın: Kanı nereden nereye taşır, duvarı nasıldır?"],"warn":"Sık yapılan hata: 'Atardamarlarda her zaman temiz kan, toplardamarlarda her zaman kirli kan akar' demek. Damarı adlandırırken kanın temizliğine değil, kalpten mi çıktığına yoksa kalbe mi geldiğine bak."},{"title":"Dayanışmayı Tartış","mode":"Grup · 20 dk","items":["Grupça şu soruyu tartışın: Bağışlanan kandaki hangi yapılar, ameliyat olan bir hastanın hangi ihtiyacını karşılar?","Kan bağışının yalnızca bireysel değil, toplumsal bir dayanışma olduğunu gösteren en az iki gerekçe yazın.","Kan bağışı için yaş ve sağlık şartları neden var? Bağışçının ve alıcının sağlığını birlikte düşünerek açıklayın."]},{"title":"Kan Elçisi Afişi","mode":"Grup · 25 dk","items":["Ücretsiz bir afiş aracında 'Bir Damla Kanın Yolculuğu' afişi hazırlayın: Vücut → damar → kan hücreleri yolculuğunu görselleştirin.","Afişte her kan hücresinin görevini tek cümleyle yazın ve kan bağışının neden önemli olduğunu anlatan bir slogan ekleyin.","Afişi 'KanYolculugu_GrupAdi' adıyla kaydedip NavigAItor'a yükleyin."]}],"checklist":["Modelde dört sahneyi de gezip her sahnede gördüklerimi çizdim.","Alyuvar, akyuvar ve kan pulcuğunun görevlerini kendi cümlelerimle yazdım.","Atardamar, toplardamar ve kılcal damarı karşılaştıran tabloyu tamamladım.","Kan bağışının toplumsal dayanışmadaki önemine en az iki gerekçe yazdım.","Afişte bilimsel bilgiyi doğru ve anlaşılır biçimde gösterdim.","Dosyamı doğru adla kaydedip yükledim."],"rubric":[{"k":"Bilimsel Gözlem","d":"Model sahnelerindeki yapıları ayırt edip kaydetme","l4":"Tüm sahneleri ayrıntılı çizer, üç kan yapısını şekil ve sayı farkıyla ayırt eder.","l3":"Sahneleri çizer, üç kan yapısını doğru ayırt eder.","l2":"Bazı sahneleri atlar veya kan yapılarını karıştırır.","l1":"Gözlem kaydı eksik ya da yok."},{"k":"Kavramsal Doğruluk","d":"Kan hücreleri ve damarların görevlerini açıklama","l4":"Tüm görevleri doğru açıklar, damarları kanın yönüne göre adlandırır.","l3":"Görevlerin çoğunu doğru açıklar.","l2":"Görevleri kısmen doğru, damarlarda yanılgı var.","l1":"Görevler büyük ölçüde yanlış."},{"k":"Tartışma ve Empati","d":"Kan bağışını toplumsal dayanışma açısından değerlendirme","l4":"Bağışçı ve alıcı açısından gerekçeli, empatik argümanlar sunar.","l3":"En az iki geçerli gerekçe sunar.","l2":"Tek gerekçe sunar, açıklama yüzeyseldir.","l1":"Gerekçe sunmaz."},{"k":"Dijital Ürün","d":"Afişin bilimsel ve görsel niteliği","l4":"Yolculuğu açık şekilde görselleştirir, bilgiler doğru, slogan etkili.","l3":"Afiş doğru ve düzenli.","l2":"Afişte eksik ya da hatalı bilgi var.","l1":"Afiş tamamlanmamış."}],"navi":["Kan sahnesinde en çok gördüğün hücre hangisi? Vücutta bu kadar çok olmasının hangi işle ilgisi olabilir?","Bir damara 'atardamar' demek için neye bakman gerekir: içindeki kanın rengine mi, kanın gittiği yöne mi?","Ameliyatta çok kan kaybeden birinin vücudunda hangi görev aksar? Bağışlanan kan bu eksikliği nasıl kapatır?"],"diff":{"destek":"Yalnızca alyuvar ve akyuvara odaklan; görevleri hazır kelime kartlarından (taşıma, savunma, pıhtılaşma) seçerek eşleştir.","ileri":"Kan gruplarının neden önemli olduğunu araştır ve bağışta kimin kime kan verebileceğini gösteren basit bir şema çiz."},"misconception":"Öğrenciler atardamarlarda her zaman temiz kan, toplardamarlarda her zaman kirli kan aktığını düşünür; oysa damarlar kanın kalbe göre akış yönüne göre adlandırılır."},{"id":"fen-7-13","course":"FEN","grade":7,"themeNo":4,"themeName":"Işığın Kırılması Ve Mercekler","title":"Havuzdaki Kayıp Anahtar","subtitle":"Ortam değiştiren ışığın yolu — Kırılma dedektifliği","kazanim":["Ortam değiştiren ışığın izlediği yolu gözlemleyerek kırılma olayına yönelik bilimsel çıkarım yapabilme"],"skills21":["Gözlem","Çıkarım yapma","İş birliği","Sınıflandırma"],"digital":["Dijital Simülasyon","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Grup","tools":["NavigAItor Stüdyo ışın modeli","Şeffaf bardak, su, kalem ve bozuk para","Açıölçer ve defter"],"scenario":"Yaz kampında bir arkadaşın anahtarını havuza düşürdü. Kenardan bakıp tam üzerine uzandığı hâlde eli anahtarı her seferinde ıskalıyor. Arkadaşın \"Havuz beni kandırıyor!\" diyor. Sen de kampın 'bilim dedektifi' olarak olayı çözmeye karar veriyorsun. Işık sudan havaya geçerken ne oluyor da anahtar olduğu yerden farklı görünüyor?","visual":{"type":"light","params":{"mode":"kirilma"},"caption":"Geliş açısı sürgüsünü değiştirerek ışının hava ile su arasında nasıl yön değiştirdiğini gözle ve açıları kaydet."},"steps":[{"title":"Bardakta Gözlem","mode":"Grup · 20 dk","items":["Boş bir bardağın dibine bozuk para koyun; paranın tam görünmez olduğu noktaya kadar geri çekilin. Sonra bir arkadaşınız bardağa yavaşça su doldursun. Ne gözlediniz?","Su dolu bardağa bir kalem daldırın ve yandan bakın. Kalemin görünümünü çizin.","İki gözlemi 'ne gördüm / neden olabilir' tablosuna yazın."],"warn":"Sık yapılan hata: Kalemin gerçekten büküldüğünü ya da paranın yukarı kalktığını düşünmek. Değişen nesne değil, ışığın gözümüze gelen yoludur."},{"title":"Işını Takip Et","mode":"Grup · 25 dk","items":["Görselde ışığı havadan suya gönderin; geliş açısını 0°, 20°, 40° ve 60° yaparak kırılma açısını tabloya kaydedin.","Her denemede ışının normale yaklaştığını mı uzaklaştığını mı belirleyin.","Işığı bu kez sudan havaya gönderin ve aynı ölçümleri tekrarlayın."],"warn":"Sık yapılan hata: Açıları yüzeyden ölçmek. Geliş ve kırılma açıları her zaman yüzeye dik çizilen normal çizgisinden ölçülür."},{"title":"Çıkarım Yap","mode":"Grup · 20 dk","items":["Tablonuzdan iki genelleme çıkarın: Işık hangi durumda normale yaklaşır, hangi durumda uzaklaşır?","Geliş açısı 0° iken ne oldu? Bu durumu kendi cümlelerinizle açıklayın.","Havuzdaki anahtarın neden olduğundan daha yakında (yüzeye yakın) göründüğünü bir ışın çizimiyle gösterin."]},{"title":"Dedektif Raporu","mode":"Bireysel · 15 dk","items":["Arkadaşına 'Havuz seni kandırmıyor, çünkü…' diye başlayan kısa bir açıklama yaz.","Anahtarı almak için elini nereye uzatması gerektiğini ışın çizimine dayanarak öner ve raporunu yükle."]}],"checklist":["Bardak ve kalem gözlemlerimi tabloya yazdım.","Dört farklı geliş açısı için kırılma açılarını kaydettim.","Açıları normale göre ölçtüm.","Işığın normale yaklaştığı ve uzaklaştığı durumlarla ilgili genelleme yazdım.","Havuz olayını ışın çizimiyle açıkladım.","Dedektif raporumu yükledim."],"rubric":[{"k":"Gözlem ve Kayıt","d":"Deney ve simülasyon verilerini düzenli kaydetme","l4":"Tüm ölçümler eksiksiz, normale göre ve birimleriyle kaydedilmiş.","l3":"Ölçümlerin çoğu doğru kaydedilmiş.","l2":"Kayıtlar eksik veya açılar yüzeyden ölçülmüş.","l1":"Kayıt yok."},{"k":"Bilimsel Çıkarım","d":"Verilerden kırılma kuralına ulaşma","l4":"Yaklaşma/uzaklaşma ve dik gelme durumunu verilerle gerekçelendirir.","l3":"İki genellemeyi doğru yapar.","l2":"Tek genelleme yapar veya gerekçe zayıf.","l1":"Çıkarım yapamaz."},{"k":"Modelleme","d":"Işın çiziminin doğruluğu","l4":"Gerçek ve görünen konumu, normali ve ışın yönünü doğru çizer.","l3":"Çizim büyük ölçüde doğru.","l2":"Çizimde yön veya normal hatası var.","l1":"Çizim yok."},{"k":"İletişim","d":"Raporun açıklığı","l4":"Günlük olayı bilimsel kavramlarla açık ve ikna edici açıklar.","l3":"Açıklama anlaşılır.","l2":"Açıklama eksik.","l1":"Rapor yok."}],"navi":["Işık hiç eğilmeden, yüzeye dik gelseydi anahtar yine yer değiştirmiş gibi görünür müydü?","Gözün, ışığın hep düz bir çizgide geldiğini varsayıyorsa, kırılan bir ışını hangi noktadan geliyormuş gibi algılar?"],"diff":{"destek":"Yalnızca havadan suya geçişte iki açıyla (0° ve 40°) çalış; 'yaklaştı / uzaklaştı / kırılmadı' seçeneklerinden birini işaretle.","ileri":"Suyun yerine cam bloğu seçerek aynı geliş açılarında kırılma açılarını karşılaştır; hangi ortamın ışığı daha çok kırdığını tartış."},"misconception":"Öğrenciler ışığın her ortam değişiminde mutlaka kırıldığını düşünür; oysa yüzeye dik gelen ışın yön değiştirmeden geçer."},{"id":"fen-7-14","course":"FEN","grade":7,"themeNo":5,"themeName":"Maddenin Doğasına Yolculuk","title":"Atomun İçine Bilet","subtitle":"Atomun yapısı ve temel parçacıklar — Model inşa etme","kazanim":["Atomun yapısını ve yapısındaki temel parçacıkları çözümleyebilme"],"skills21":["Analitik düşünme","Modelleme","Sınıflandırma","Sistematik olma"],"digital":["Dijital Simülasyon","Dijital Modelleme"],"duration":"40 dk","format":"Bireysel","tools":["NavigAItor Stüdyo atom modeli","Renkli hamur veya boncuk","Defter"],"scenario":"Bir bilim müzesi, ziyaretçilerin 'atomun içine girdiğini' hissedeceği yeni bir salon açıyor ve rehber metinleri yazma görevi sana verildi. Salonun ilk durağında bir karbon atomu modeli var. Ziyaretçiler en çok şunu soruyor: \"Atomun içinde ne var, her parça nerede duruyor ve hangisi ne yüklü?\" Ziyaretçilere doğru bir yolculuk yaşatmak için atomun parçalarını nasıl çözümleyeceksin?","visual":{"type":"atom","params":{"element":"C"},"caption":"Karbon atomu modelinde proton, nötron ve elektronları bul; her birinin yerini, yükünü ve sayısını etiketle."},"steps":[{"title":"Modeli İncele","mode":"Bireysel · 10 dk","items":["Atom modelinde çekirdeği ve katmanları bul. Çekirdekte hangi parçacıklar, katmanlarda hangi parçacıklar var?","Proton, nötron ve elektron sayılarını say ve bir tabloya yaz.","Her parçacığın yükünü (+, −, yüksüz) tabloya ekle."],"warn":"Sık yapılan hata: Nötronu negatif yüklü sanmak. Nötron yüksüzdür; negatif yük elektrona aittir."},{"title":"Kendi Modelini Kur","mode":"Bireysel · 15 dk","items":["Hamur ya da boncuklarla karbon atomunun modelini yap; her parçacık türü için farklı renk kullan ve bir renk anahtarı çiz.","Modelini oksijen atomu için de kurmayı dene: Neyi değiştirmen gerekti?","Proton sayısı ile elektron sayısı arasındaki ilişkiyi her iki atomda karşılaştır."],"warn":"Sık yapılan hata: Elektronları çekirdeğin içine yerleştirmek. Elektronlar çekirdeğin etrafındaki katmanlarda bulunur; çekirdek atomun çok küçük bir bölümünü kaplar."},{"title":"Müze Rehber Metni","mode":"Bireysel · 15 dk","items":["'Atomun içine hoş geldiniz' diye başlayan 5–6 cümlelik bir rehber metni yaz: Parçacıklar, yerleri ve yükleri.","Metnine, atomun neden toplamda yüksüz (nötr) olduğunu açıklayan bir cümle ekle.","Modelinin fotoğrafını ve metnini NavigAItor'a yükle."]}],"checklist":["Karbon atomunda üç parçacık türünün sayısını doğru yazdım.","Her parçacığın yükünü ve atomdaki yerini belirttim.","Renk anahtarlı bir atom modeli yaptım.","Karbon ile oksijen atomunu karşılaştırdım.","Atomun neden nötr olduğunu açıkladım."],"rubric":[{"k":"Parçacık Çözümlemesi","d":"Proton, nötron, elektronu yer ve yükleriyle belirleme","l4":"Üç parçacığı yer, yük ve sayıyla hatasız çözümler.","l3":"Küçük bir hata dışında doğru çözümler.","l2":"Yer veya yükte birkaç hata var.","l1":"Parçacıkları ayırt edemez."},{"k":"Model Oluşturma","d":"Fiziksel modelin doğruluğu","l4":"Model doğru, renk anahtarı açık, ikinci atoma uyarlanmış.","l3":"Model doğru, renk anahtarı var.","l2":"Modelde yerleşim hataları var.","l1":"Model yok."},{"k":"Karşılaştırma","d":"İki atom arasındaki farkı açıklama","l4":"Proton sayısının atomu belirlediğini fark eder ve açıklar.","l3":"Farkları doğru listeler.","l2":"Karşılaştırma yüzeysel.","l1":"Karşılaştırma yok."},{"k":"İletişim","d":"Rehber metninin doğruluğu ve anlaşılırlığı","l4":"Metin doğru, akıcı, ziyaretçiye uygun.","l3":"Metin doğru ve anlaşılır.","l2":"Metinde kavram hataları var.","l1":"Metin yok."}],"navi":["Atomun içindeki pozitif ve negatif yükler eşit sayıda olsaydı, atom dışarıdan nasıl görünürdü: yüklü mü, yüksüz mü?","Karbonu oksijene dönüştürmek için modelde hangi parçacığın sayısını değiştirmek şart?"],"diff":{"destek":"Yalnızca karbon atomuyla çalış; parçacık adlarını, yükleri ve yerleri hazır etiketlerden seçerek yerleştir.","ileri":"Bir atomun çekirdeği bir futbol topu kadar olsaydı atom ne kadar büyük olurdu? Araştır ve 'atomun çoğu boşluktur' fikrini rehber metnine ekle."},"misconception":"Öğrenciler atomun içinin parçacıklarla tamamen dolu olduğunu ve elektronların da çekirdekte bulunduğunu düşünür."},{"id":"fen-7-15","course":"FEN","grade":7,"themeNo":6,"themeName":"Elektriklenme","title":"Yük Kontrol Merkezi","subtitle":"Cisimlerin elektrik yükleri — Sınıflandırma ve kanıt","kazanim":["Cisimlerin elektrik yüklerini sınıflandırabilme"],"skills21":["Sınıflandırma","Bilgi toplama","Deney tasarlama","İş birliği"],"digital":["Dijital Simülasyon","Veri Okuryazarlığı"],"duration":"40 dk","format":"İkili","tools":["NavigAItor Stüdyo sınıflandırma panosu","Balon, yün kumaş, plastik tarak, kâğıt parçaları","Defter"],"scenario":"Kışın kazağını çıkarırken çıtırtılar duyuyor, kapı koluna dokununca küçük bir çarpılma hissediyorsun. Okulun bilim kulübü, bu olayları inceleyen bir 'Yük Kontrol Merkezi' kurdu ve seni yük analistliğine atadı. Masana farklı cisimlerin proton ve elektron sayılarını gösteren kartlar geliyor. Her cismin yükünü doğru sınıflandırmak için neye bakmalısın?","visual":{"type":"sort","params":{"bins":["Pozitif yüklü","Negatif yüklü","Nötr"],"items":[{"t":"12 proton, 9 elektron","b":0},{"t":"7 proton, 10 elektron","b":1},{"t":"15 proton, 15 elektron","b":2},{"t":"Yün kumaşa sürtülüp elektron alan balon","b":1},{"t":"Balona elektron veren yün kumaş","b":0},{"t":"Hiç sürtülmemiş kuru kâğıt parçası","b":2},{"t":"4 elektron kaybetmiş, önceden nötr cisim","b":0},{"t":"6 proton, 8 elektron","b":1}]},"caption":"Her kartı proton ve elektron sayısını karşılaştırarak doğru yük kutusuna sürükle."},"steps":[{"title":"Mini Deney","mode":"İkili · 10 dk","items":["Balonu yün kumaşa sürtün ve küçük kâğıt parçalarına yaklaştırın. Ne oluyor?","Aynı şekilde sürtülmüş iki balonu ipten asıp birbirine yaklaştırın. Gözleminizi yazın.","Sürtünme sırasında hangi parçacığın yer değiştirdiğini tahmin edin."],"warn":"Sık yapılan hata: Sürtünmede protonların da bir cisimden diğerine geçtiğini düşünmek. Elektriklenmede yer değiştiren yalnızca elektronlardır."},{"title":"Kartları Sınıflandır","mode":"İkili · 15 dk","items":["Görseldeki 8 kartı üç kutuya yerleştirin.","Her yerleştirme için bir cümlelik kanıt yazın: 'Bu cisim … çünkü proton sayısı … elektron sayısından …'","Sürtünme deneyinizdeki balonu ve kumaşı da tablonuza ekleyin."],"warn":"Sık yapılan hata: Nötr cismin hiç yükü olmadığını sanmak. Nötr cisimde de proton ve elektron vardır; yalnızca sayıları eşittir."},{"title":"Kural Yaz","mode":"Bireysel · 15 dk","items":["Üç yük durumunu tanımlayan kendi sınıflandırma kuralını yaz.","Kazak çıkarırken duyulan çıtırtıyı bu kurala dayanarak 3–4 cümleyle açıkla.","Kuralını ve sınıflandırma ekranının görüntüsünü NavigAItor'a yükle."]}],"checklist":["Balon deneyini yapıp gözlemlerimi yazdım.","Sekiz kartın hepsini bir yük kutusuna yerleştirdim.","Her yerleştirme için proton–elektron karşılaştırmasıyla kanıt yazdım.","Nötr cisimde de yük bulunduğunu açıkladım.","Kendi sınıflandırma kuralımı yazdım."],"rubric":[{"k":"Sınıflandırma Doğruluğu","d":"Kartları doğru yük kutusuna yerleştirme","l4":"8 kartın tamamı doğru.","l3":"6–7 kart doğru.","l2":"4–5 kart doğru.","l1":"3 veya daha az kart doğru."},{"k":"Kanıta Dayalı Gerekçe","d":"Proton–elektron karşılaştırmasıyla açıklama","l4":"Her karar için doğru ve tutarlı kanıt yazar.","l3":"Kararların çoğu için kanıt yazar.","l2":"Kanıtlar eksik veya karışık.","l1":"Kanıt yok."},{"k":"Deney ve Gözlem","d":"Balon deneyini yapma ve yorumlama","l4":"Çekme/itmeyi gözler ve elektron geçişiyle açıklar.","l3":"Gözlemi doğru kaydeder.","l2":"Gözlem eksik.","l1":"Deney yapılmamış."},{"k":"Genelleme","d":"Sınıflandırma kuralı ve günlük olay açıklaması","l4":"Kural eksiksiz, günlük olayı doğru açıklar.","l3":"Kural doğru, açıklama kısmen.","l2":"Kural eksik.","l1":"Kural yok."}],"navi":["Bir cisim elektron kaybettiğinde proton sayısı değişir mi? O hâlde hangi yük baskın hâle gelir?","Nötr bir cisimde hiç yük yoksa, sürtünce birden yük nereden gelir?"],"diff":{"destek":"Önce yalnızca proton ve elektron sayısı verilen 4 kartla çalış; sayıları karşılaştırırken >, <, = işaretlerini kullan.","ileri":"Yüklü balonu kâğıt parçalarına yaklaştırınca neden çektiğini (kâğıt nötr olduğu hâlde) araştır ve etki ile elektriklenmeyi açıklayan bir çizim yap."},"misconception":"Öğrenciler nötr cisimlerde hiç elektrik yükü bulunmadığını ve elektriklenmede protonların da yer değiştirdiğini düşünür."},{"id":"fen-8-16","course":"FEN","grade":8,"themeNo":1,"themeName":"Mevsimler Ve İklim","title":"Ocak'ta Neden Üşüyoruz?","subtitle":"Eksen eğikliği ve mevsimler — Yanılgı avı","kazanim":["Dünya’nın Güneş etrafındaki hareketi ve eksen eğikliğinin sonuçları ile ilgili bilimsel çıkarım yapabilme"],"skills21":["Çıkarım yapma","Karşılaştırma","Merak","İş birliği"],"digital":["Dijital Simülasyon","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Grup","tools":["NavigAItor Stüdyo mevsim animasyonu","El feneri, top ve kareli kâğıt","Dijital hesap tablosu"],"scenario":"Bir sosyal medya hesabında şu paylaşım hızla yayılıyor: \"Yazın sıcak olmasının nedeni Dünya'nın Güneş'e yaklaşması!\" Bilim kulübü olarak bu iddiayı test etmeye karar verdiniz. Araştırmanızda ilginç bir bilgiye ulaşıyorsunuz: Dünya, Güneş'e yılın en yakın konumuna ocak ayı başlarında geliyor. O hâlde Türkiye'de ocakta neden kış yaşanıyor ve mevsimleri asıl ne oluşturuyor?","visual":{"type":"solar","params":{"mode":"mevsimler"},"caption":"Animasyonu oynatıp durdurarak Dünya'nın dört konumunda eksen eğikliğini ve Güneş ışınlarının Kuzey Yarım Küre'ye geliş açısını incele."},"steps":[{"title":"İddiayı Sorgula","mode":"Grup · 15 dk","items":["Paylaşımdaki iddia doğru olsaydı, Kuzey ve Güney Yarım Küre'de aynı anda hangi mevsim yaşanırdı? Tahmininizi yazın.","Güvenilir bir kaynaktan aralık ayında Avustralya'da hangi mevsimin yaşandığını araştırın.","İddia ile bulduğunuz bilgi uyuşuyor mu? Tartışıp kararınızı yazın."],"warn":"Sık yapılan hata: Mevsimleri Dünya'nın Güneş'e olan uzaklığıyla açıklamak. Uzaklık yıl içinde çok az değişir ve iki yarım kürede zıt mevsim yaşanmasını açıklayamaz."},{"title":"Işığın Açısını Ölç","mode":"Grup · 25 dk","items":["El fenerini kareli kâğıda önce dik, sonra eğik tutun. Işığın aydınlattığı alandaki kare sayısını her iki durumda sayın.","Aynı miktar ışığın daha geniş alana yayıldığı durumda birim alana düşen enerjinin nasıl değiştiğini tartışın.","Animasyonda 21 Haziran ve 21 Aralık konumlarında ışınların Türkiye'ye geliş açısını karşılaştırın."],"warn":"Sık yapılan hata: Eksen eğikliğinin yıl boyunca yön değiştirdiğini sanmak. Eksen hep aynı yöne eğiktir; Dünya'nın yörüngedeki konumu değiştiği için ışınların geliş açısı değişir."},{"title":"Veriyle Karşılaştır","mode":"Grup · 20 dk","items":["Hesap tablosunda kendi ilinizin ocak ve temmuz aylarındaki yaklaşık gündüz sürelerini güvenilir bir kaynaktan bularak karşılaştırın.","Gündüz süresi ile ışınların geliş açısının sıcaklığa birlikte nasıl etki ettiğini açıklayın.","21 Mart ve 23 Eylül'de gece ile gündüz süresinin neden yaklaşık eşit olduğunu animasyona dayanarak açıklayın."]},{"title":"Yanılgı Avcısı Paylaşımı","mode":"Bireysel · 20 dk","items":["Yanlış paylaşıma kibar ve bilimsel bir yanıt yazın: en fazla 5 cümle, en az bir kanıt.","Yanıtınıza el feneri deneyinizi özetleyen basit bir çizim ekleyip NavigAItor'a yükleyin."]}],"checklist":["Yaygın iddiayı iki yarım küre bilgisiyle sınadım.","El feneri deneyinde iki durum için aydınlanan kare sayısını kaydettim.","Animasyonda Haziran ve Aralık konumlarını karşılaştırdım.","Gündüz süresi verilerini tabloya aktardım.","Kanıta dayalı, kibar bir yanıt metni yazdım."],"rubric":[{"k":"Bilimsel Çıkarım","d":"Mevsimlerin nedenini eksen eğikliği ve dolanmayla açıklama","l4":"Geliş açısı, gündüz süresi ve iki yarım küreyi birlikte kullanarak çıkarım yapar.","l3":"Eksen eğikliğini doğru neden olarak açıklar.","l2":"Açıklamada uzaklık yanılgısı kısmen sürer.","l1":"Mevsimleri uzaklıkla açıklar."},{"k":"Deney ve Veri","d":"El feneri deneyi ve gündüz süresi verileri","l4":"Ölçümler eksiksiz, veriler yorumlanmış.","l3":"Ölçümler ve veriler doğru kaydedilmiş.","l2":"Veriler eksik.","l1":"Deney/veri yok."},{"k":"Kaynak Değerlendirme","d":"İddiayı güvenilir kaynakla sınama","l4":"Güvenilir kaynak kullanır, iddiayı kanıtla çürütür.","l3":"Kaynak kullanır, iddiayı değerlendirir.","l2":"Kaynak zayıf veya belirsiz.","l1":"Kaynak kullanmaz."},{"k":"İletişim","d":"Yanıt metninin bilimsel ve saygılı oluşu","l4":"Kısa, kanıtlı, saygılı ve ikna edici.","l3":"Doğru ve saygılı.","l2":"Kanıt eksik.","l1":"Metin yok."}],"navi":["Dünya Güneş'e ocakta en yakın konumdaysa ama biz üşüyorsak, sıcaklığı uzaklıktan daha çok etkileyen başka ne olabilir?","El fenerini eğdiğinde ışık aynı kalırken neden aydınlattığı alan değişti? Bu, bir metrekareye düşen enerji için ne anlama gelir?"],"diff":{"destek":"Yalnızca 21 Haziran ve 21 Aralık konumlarını karşılaştır; 'ışınlar dik / eğik', 'gündüz uzun / kısa' tablosunu doldur.","ileri":"Dünya'nın ekseni hiç eğik olmasaydı Türkiye'de yıl boyunca hava nasıl olurdu? Gerekçeli bir senaryo yaz."},"misconception":"Öğrenciler mevsimlerin Dünya'nın Güneş'e yaklaşıp uzaklaşmasından kaynaklandığını düşünür."},{"id":"fen-8-17","course":"FEN","grade":8,"themeNo":2,"themeName":"Yaşamı Kolaylaştıran Kuvvet","title":"Bahçe Kayası Operasyonu","subtitle":"Kaldıraç ile iş kolaylığı — Model tasarlama","kazanim":["Günlük yaşamda iş kolaylığı sağlayacak bilimsel model oluşturabilme"],"skills21":["Model oluşturma","Problem çözme","Yaratıcılık","İş birliği"],"digital":["Dijital Simülasyon","Dijital Modelleme"],"duration":"120 dk (3 ders)","format":"Grup","tools":["NavigAItor Stüdyo kaldıraç modeli","Cetvel, kalem, silgi, bozuk paralar","Ücretsiz bir çizim aracı"],"scenario":"Okul bahçesine yeni bir sebze tarhı yapılacak ama tam ortada ağır bir kaya duruyor. Bahçe ekibinizdeki kimse kayayı tek başına kaldıramıyor ve iş makinesi kullanmak mümkün değil. Hademe amcanız elinde uzun, sağlam bir demir çubukla geliyor: \"Bunu doğru kullanırsak çocuklar bile yapabilir\" diyor. Destek noktasını nereye koyarsanız kayayı en az kuvvetle kaldırabilirsiniz ve bu size gerçekten 'bedava' bir kolaylık mı sağlar?","visual":{"type":"lever","params":{"kind":"kaldirac"},"caption":"Destek noktası sürgüsünü hareket ettirerek kayayı kaldırmak için gereken kuvvetin nasıl değiştiğini gözle."},"steps":[{"title":"Simülasyonda Keşfet","mode":"Grup · 25 dk","items":["Destek noktasını kayaya yakın, ortada ve kuvvete yakın olmak üzere üç konuma getirin; her konumda gereken kuvveti tabloya yazın.","Her konumda kuvvet kolu ve yük kolu uzunluklarını da kaydedin.","Kuvvetin en az olduğu durumda, kuvvet uyguladığınız ucun ne kadar yol aldığını gözleyin."],"warn":"Sık yapılan hata: Kuvvet kolunu destek noktasından değil çubuğun ucundan ölçmek. Kuvvet kolu ve yük kolu her zaman destek noktasından ölçülür."},{"title":"Masada Kaldıraç","mode":"Grup · 30 dk","items":["Cetveli bir kalemin üzerine yerleştirip kaldıraç yapın; bir ucuna 4 bozuk para (yük) koyun.","Diğer uca kaç bozuk para koyunca dengeye geldiğini, destek noktasını üç farklı yere kaydırarak bulun.","Bulgularınızı simülasyon tablosuyla karşılaştırıp bir örüntü yazın."],"warn":"Sık yapılan hata: Basit makinelerin işi azalttığını düşünmek. Kaldıraç kuvvetten kazanç sağlar ama kuvvet uygulanan uç daha uzun yol alır; yapılan iş azalmaz."},{"title":"Modelini Tasarla","mode":"Grup · 40 dk","items":["Kaya problemi için kendi kaldıraç düzeneğinizi ücretsiz bir çizim aracında tasarlayın: çubuğun boyu, destek noktasının yeri, kuvvetin yönü.","Tasarımınızın güvenli olması için en az iki önlem ekleyin (ör. kaymayan destek, ayak güvenliği).","Tasarımın neden iş kolaylığı sağladığını, kuvvet ve yol ilişkisiyle açıklayan 3 cümle yazın."]},{"title":"Sun ve Geliştir","mode":"Grup · 25 dk","items":["Tasarımınızı başka bir gruba 2 dakikada sunun; onlardan bir iyileştirme önerisi alın.","Öneriyi değerlendirip modelinizin ikinci sürümünü hazırlayın ve 'Kaldirac_GrupAdi_v2' adıyla yükleyin."]}],"checklist":["Destek noktasının üç konumu için kuvvet ve kol uzunluklarını kaydettim.","Cetvel kaldıracında denge deneylerini yaptım.","Kuvvet kolu ile gereken kuvvet arasındaki örüntüyü yazdım.","Kaya problemi için güvenlik önlemleri içeren bir model çizdim.","Kaldıracın işi azaltmadığını, kuvvetten kazandırıp yoldan kaybettirdiğini açıkladım.","Geri bildirime göre modelimin ikinci sürümünü yükledim."],"rubric":[{"k":"Veri ve Örüntü","d":"Deney ve simülasyon verilerinden ilişki çıkarma","l4":"Kuvvet kolu–kuvvet ilişkisini verilerle tutarlı biçimde ifade eder.","l3":"Örüntüyü doğru yazar.","l2":"Örüntü kısmen doğru.","l1":"Örüntü yok."},{"k":"Bilimsel Model","d":"Kaldıraç tasarımının doğruluğu ve uygulanabilirliği","l4":"Destek, kollar ve kuvvet yönü doğru; güvenli ve uygulanabilir.","l3":"Model doğru ve uygulanabilir.","l2":"Modelde kavramsal hata var.","l1":"Model yok."},{"k":"Kavramsal Anlama","d":"İş, kuvvet ve yol ilişkisi","l4":"Kuvvetten kazanç–yoldan kayıp ilişkisini doğru ve örnekle açıklar.","l3":"İlişkiyi doğru açıklar.","l2":"İşin azaldığını düşünür.","l1":"Açıklama yok."},{"k":"İş Birliği ve Revizyon","d":"Geri bildirimi kullanma","l4":"Öneriyi gerekçeli değerlendirip modeli belirgin geliştirir.","l3":"Öneriyi uygular.","l2":"Öneriyi kısmen uygular.","l1":"Revizyon yok."}],"navi":["Kayayı daha az kuvvetle kaldırdığında, elinin çubuğun ucunda aldığı yol nasıl değişti? Bu bir 'bedel' olabilir mi?","Destek noktasını kayaya yaklaştırmak hangi kolu uzatır, hangisini kısaltır?"],"diff":{"destek":"Yalnızca simülasyonda iki konumu (kayaya yakın ve uzak) karşılaştır; 'daha az / daha çok kuvvet' sonucunu yaz ve hazır şablon üzerinde modelini tamamla.","ileri":"Aynı kayayı eğik düzlem veya makara ile taşımak için alternatif bir model tasarla ve kaldıraçla avantaj–dezavantaj tablosunda karşılaştır."},"misconception":"Öğrenciler basit makinelerin yapılan işi azalttığını düşünür; oysa basit makineler kuvvetten kazanç sağlarken yoldan kaybettirir ve işten kazanç sağlamaz."},{"id":"fen-8-18","course":"FEN","grade":8,"themeNo":3,"themeName":"Yaşamın Gizemi","title":"Çiçek Rengi Tahmin Laboratuvarı","subtitle":"Tek karakter çaprazlaması — Olasılıkla kalıtım","kazanim":["Tek karakter çaprazlamaları ile ilgili problemler çözerek sonuçlarına ilişkin bilimsel çıkarım yapabilme"],"skills21":["Yapılandırma","Karşılaştırma","Eleştirel düşünme","Tartışma"],"digital":["Dijital Modelleme","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"İkili","tools":["NavigAItor Stüdyo torba simülasyonu","İki kâğıt torba ve iki renk boncuk","Dijital hesap tablosu"],"scenario":"Okulunuzun serasında mor çiçekli iki bezelye bitkisi var ve sera sorumlusu bu bitkilerin tohumlarından yeni fideler yetiştirecek. Ekibinizden biri \"İkisi de mor, yavrular da kesin mor olur\" diyor. Ama geçen yıl aynı tür mor çiçekli bitkilerin bazı yavruları beyaz açmıştı. Mor rengin baskın, beyaz rengin çekinik olduğunu biliyorsanız, yeni fidelerde beyaz çiçek görme olasılığı var mı ve bunu nasıl hesaplarsınız?","visual":{"type":"dice","params":{"kind":"torba","items":["Mor alel (M)","Beyaz alel (m)"],"counts":[1,1]},"caption":"Her ebeveyn torbasından birer alel çekerek yavrunun genotipini oluştur ve sonuçları sıklık tablosuna işle."},"steps":[{"title":"Genotipleri Belirle","mode":"İkili · 15 dk","items":["Mor çiçekli bir bitkinin olası iki genotipini yazın.","Geçen yıl beyaz yavru veren mor bitkilerin genotipi ne olmalıydı? Gerekçenizi yazın.","Seradaki iki bitkinin Mm genotipli olduğunu varsayarak her birinin oluşturabileceği üreme hücrelerini listeleyin."],"warn":"Sık yapılan hata: Fenotipi mor olan bitkinin genotipini her zaman MM sanmak. Baskın özelliği gösteren bir bireyde çekinik alel gizli kalabilir."},{"title":"Torba Deneyi","mode":"İkili · 25 dk","items":["Görseldeki iki torbanın her birinde bir M ve bir m alel var. Her torbadan birer alel çekerek 40 yavru oluşturun.","Her çekilişten sonra alelleri torbaya geri koyun ve sonucu MM, Mm, mm olarak hesap tablosuna işleyin.","Aynı deneyi gerçek torba ve boncuklarla 20 kez tekrarlayın; iki sonucu karşılaştırın."],"warn":"Sık yapılan hata: Çekilen aleli torbaya geri koymamak. Her yavru için olasılık aynı kalmalıdır; geri koymazsanız sonraki çekilişi değiştirirsiniz."},{"title":"Punnett Karesiyle Karşılaştır","mode":"İkili · 20 dk","items":["Mm × Mm çaprazlaması için Punnett karesi çizin; beklenen genotip ve fenotip oranlarını yazın.","Deneyinizdeki oranları beklenen oranlarla karşılaştırın. Neden tam olarak aynı çıkmadı?","Sınıftaki tüm ikililerin sonuçlarını toplayın: Toplam sayı arttıkça oran nasıl değişti?"]},{"title":"Sera Raporu","mode":"Bireysel · 20 dk","items":["Sera sorumlusuna, yeni fidelerde beyaz çiçek görme olasılığını ve bunun ne anlama geldiğini açıklayan kısa bir rapor yazın.","Raporunuzda '4 fideden tam 1'i beyaz olur' ifadesinin neden doğru olmadığını açıklayın ve NavigAItor'a yükleyin."]}],"checklist":["Mor çiçekli bitkinin olası genotiplerini yazdım.","40 çekilişlik torba deneyini yapıp sonuçları tabloya işledim.","Punnett karesini doğru çizdim.","Deney sonuçlarını beklenen oranlarla karşılaştırdım.","Olasılığın kesinlik olmadığını raporumda açıkladım."],"rubric":[{"k":"Çaprazlama Çözümü","d":"Punnett karesi ve oranlar","l4":"Genotip ve fenotip oranlarını hatasız bulur, gösterimi düzenli.","l3":"Oranları doğru bulur.","l2":"Oranlarda hata var.","l1":"Çaprazlama yapamaz."},{"k":"Deney ve Veri","d":"Simülasyon verisini kaydetme ve toplama","l4":"Veriler eksiksiz, sınıf verisiyle birleştirilmiş ve yorumlanmış.","l3":"Veriler eksiksiz kaydedilmiş.","l2":"Veriler eksik.","l1":"Veri yok."},{"k":"Bilimsel Çıkarım","d":"Beklenen ve gözlenen sonuçları yorumlama","l4":"Örneklem büyüklüğünün etkisini fark eder ve olasılığı doğru yorumlar.","l3":"Farkın nedenini kısmen açıklar.","l2":"Farkı fark eder ama açıklayamaz.","l1":"Yorum yok."},{"k":"İletişim","d":"Raporun doğruluğu ve açıklığı","l4":"Rapor bilimsel, açık ve yanılgıyı düzeltir.","l3":"Rapor doğru ve anlaşılır.","l2":"Raporda kavram hatası var.","l1":"Rapor yok."}],"navi":["İki mor ebeveynden beyaz bir yavru doğduysa, beyaz rengi belirleyen alel o ebeveynlerde nerede 'saklanıyordu'?","Bir madeni parayı 4 kez attığında tam 2 yazı gelmesi kesin mi? Bu, çaprazlama oranları için ne düşündürüyor?"],"diff":{"destek":"Punnett karesinin boş şablonunu kullan; yalnızca 20 çekiliş yap ve sonuçları MM, Mm, mm olarak işaretle.","ileri":"Mm × mm çaprazlamasını da modelle; hangi çaprazlamanın bir bitkinin genotipini (MM mi Mm mi) belirlemek için kullanılabileceğini açıkla."},"misconception":"Öğrenciler 3:1 gibi oranların her dört yavruda kesin olarak gerçekleşeceğini düşünür; oysa bu oranlar her yavru için geçerli olasılıklardır."},{"id":"fen-8-19","course":"FEN","grade":8,"themeNo":5,"themeName":"Periyodik Tablo Ve Maddenin Etkileşimi","title":"Mutfak pH Cetveli","subtitle":"Asitlik ve bazlık — pH değerlerinden genelleme","kazanim":["Maddelerin asitlik ve bazlık durumlarına ilişkin “pH” değerlerini kullanarak tümevarımsal akıl yürütebilme"],"skills21":["Sınıflandırma","Tahmin etme","Karşılaştırma","Sistematik olma"],"digital":["Veri Okuryazarlığı","Dijital Simülasyon"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor Stüdyo pH cetveli","Mor lahana suyu ayıracı, şeffaf bardaklar","Ücretsiz bir sanal laboratuvar"],"scenario":"Bir yemek yarışması programı, yarışmacılara 'mutfaktaki gizli kimyayı' anlatan kısa bir bölüm hazırlamak istiyor ve bilim danışmanı olarak seni seçti. Elinde limon suyu, sirke, saf su, kabartma tozu çözeltisi ve sabunlu su var. Yapımcı soruyor: \"Bu maddeleri asitten baza doğru sıralayabilir misin ve pH sayısı bize ne anlatıyor?\" Birkaç ölçümden yola çıkarak pH hakkında genel bir kural bulabilir misin?","visual":{"type":"numberline","params":{"min":0,"max":14,"step":1,"target":3,"label":"pH cetveli: Sirkeyi doğru yere yerleştir"},"caption":"Her mutfak maddesini tahmini pH değerine göre sayı doğrusu üzerinde doğru noktaya sürükle."},"steps":[{"title":"Renk Ayıracıyla Test","mode":"Grup · 25 dk","items":["Öğretmeninin hazırladığı mor lahana suyunu beş bardağa eşit miktarda koyun ve her bardağa farklı bir mutfak maddesi ekleyin.","Her bardaktaki renk değişimini fotoğraflayıp tabloya yazın.","Renkleri en kırmızımsıdan en yeşilimsiye doğru sıralayın."],"warn":"Sık yapılan hata: Maddeleri tadına ya da kokusuna bakarak sınıflandırmaya çalışmak. Laboratuvarda maddeler asla tadılmaz; yalnızca ayıraçla ve gözlemle karar verilir."},{"title":"pH Değerlerini Yerleştir","mode":"Bireysel · 20 dk","items":["Sanal laboratuvarda aynı maddelerin yaklaşık pH değerlerini ölçün ve tabloya ekleyin.","Görseldeki pH cetvelinde her maddeyi doğru noktaya sürükleyin.","Renk sıralamanız ile pH sıralamanız uyuşuyor mu? Kontrol edin."],"warn":"Sık yapılan hata: pH değeri büyüdükçe asitliğin arttığını düşünmek. pH 7'den küçüldükçe asitlik artar, 7'den büyüdükçe bazlık artar."},{"title":"Kuralı Keşfet","mode":"Grup · 20 dk","items":["Verilerinize bakarak 'pH 7'den küçükse…, 7 ise…, 7'den büyükse…' cümlelerini tamamlayın.","Kuralınızı test etmek için verilerinizde olmayan iki yeni madde seçin; önce tahmin edin, sonra sanal laboratuvarda kontrol edin.","Kuralınız yeni maddelerde de işledi mi? Gerekirse kuralı düzeltin."]},{"title":"Program Metni","mode":"Bireysel · 15 dk","items":["Yarışmacılara pH'ı anlatan, 6–8 cümlelik kısa bir sunucu metni yaz.","Metninde bir güvenlik uyarısı ve pH cetvelinin ekran görüntüsünü ekleyip NavigAItor'a yükle."]}],"checklist":["Beş maddeyi ayıraçla test edip renkleri kaydettim.","Maddelerin yaklaşık pH değerlerini tabloya yazdım.","Her maddeyi pH cetvelinde doğru yere yerleştirdim.","Verilerden pH ile ilgili genel bir kural çıkardım.","Kuralımı yeni maddelerle test ettim.","Güvenlik uyarısı içeren sunucu metnimi yükledim."],"rubric":[{"k":"Gözlem ve Veri","d":"Ayıraç renkleri ve pH değerlerinin kaydı","l4":"Tüm veriler eksiksiz, fotoğraflı ve düzenli.","l3":"Veriler doğru kaydedilmiş.","l2":"Veriler eksik.","l1":"Veri yok."},{"k":"Tümevarımsal Akıl Yürütme","d":"Verilerden kural çıkarma","l4":"Kuralı verilerden çıkarır, yeni maddelerle sınar ve gerekirse düzeltir.","l3":"Doğru kural çıkarır.","l2":"Kural eksik veya kısmen yanlış.","l1":"Kural yok."},{"k":"Sınıflandırma","d":"Maddeleri asidik–nötr–bazik sıralama","l4":"Tüm maddeleri doğru sıralar ve gerekçelendirir.","l3":"Maddelerin çoğunu doğru sıralar.","l2":"Sıralamada birkaç hata var.","l1":"Sıralayamaz."},{"k":"İletişim ve Güvenlik","d":"Metnin doğruluğu ve güvenlik bilinci","l4":"Metin açık, doğru ve uygun bir güvenlik uyarısı içerir.","l3":"Metin doğru, uyarı var.","l2":"Metinde hata veya uyarı eksik.","l1":"Metin yok."}],"navi":["Renk sıralaman ile pH sıralaman aynı yöne mi ilerliyor? Bu sana ayıraç hakkında ne söylüyor?","Saf su cetvelde neden tam ortada? Ortanın iki yanındaki maddeler hangi bakımdan birbirine zıt?"],"diff":{"destek":"Yalnızca üç maddeyle (limon suyu, saf su, sabunlu su) çalış ve pH cetvelinde 'asidik / nötr / bazik' bölgelerini renklendir.","ileri":"Mide özsuyu ve deniz suyunun yaklaşık pH değerlerini güvenilir kaynaktan araştırıp cetveline ekle; vücudun neden farklı bölgelerde farklı pH değerlerine ihtiyaç duyduğunu tartış."},"misconception":"Öğrenciler pH değeri büyüdükçe maddenin daha asidik olduğunu düşünür."},{"id":"fen-8-20","course":"FEN","grade":8,"themeNo":6,"themeName":"Elektriğin Yolculuğu","title":"Kamp Feneri Tasarımcısı","subtitle":"Ampullerin bağlanma şekli ve parlaklık — Deney tasarımı","kazanim":["Ampullerin bağlanma durumunun ampul parlaklığına etkisine yönelik deney yapabilme"],"skills21":["Deney tasarlama","Model oluşturma","Tartışma","Sorumluluk"],"digital":["Dijital Simülasyon","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Grup","tools":["NavigAItor Stüdyo devre modeli","Pil, iki özdeş ampul, bağlantı kabloları, anahtar","Defter"],"scenario":"İzci kampı için iki ampullü bir kamp feneri tasarlayacaksınız. Fener hem çadırın içini iyi aydınlatmalı hem de bir ampul bozulduğunda karanlıkta kalmamalısınız. Ekipte iki fikir var: Ampulleri art arda bağlamak ya da ayrı kollara bağlamak. Hangi bağlanma şekli daha parlak ve güvenilir bir fener sağlar ve bunun bir bedeli var mı?","visual":{"type":"circuit","params":{"bulbs":2,"series":true,"material":false},"caption":"Ampulleri önce seri, sonra paralel bağlayıp anahtarı aç; parlaklıkları ve bir ampul söküldüğünde olanları karşılaştır."},"steps":[{"title":"Deneyi Planla","mode":"Grup · 15 dk","items":["Araştırma sorunuzu yazın: Ampullerin bağlanma şekli parlaklığı nasıl etkiler?","Bağımsız, bağımlı ve kontrol edilen değişkenleri belirleyin.","Karşılaştırma için tek ampullü bir 'referans devre' kurmanın neden gerekli olduğunu tartışın."],"warn":"Sık yapılan hata: Farklı pil veya farklı ampuller kullanarak karşılaştırma yapmak. Adil bir deney için yalnızca bağlanma şekli değişmeli, diğer her şey aynı kalmalı."},{"title":"Devreleri Kur","mode":"Grup · 30 dk","items":["Önce tek ampullü devreyi, sonra iki ampullü seri devreyi, ardından iki ampullü paralel devreyi kurun.","Her devrede ampullerin parlaklığını referans ampulle karşılaştırarak 'daha parlak / aynı / daha sönük' olarak kaydedin.","Seri ve paralel devrede birer ampulü sökün; diğer ampulde ne olduğunu not edin.","Aynı deneyleri simülasyonda tekrarlayıp sonuçları karşılaştırın."],"warn":"Sık yapılan hata: Seri devrede akımın ilk ampulde 'harcandığını' ve ikinci ampulün daha sönük yanacağını düşünmek. Seri devrede iki özdeş ampul aynı parlaklıkta yanar."},{"title":"Sonuçları Tartış","mode":"Grup · 20 dk","items":["Verilerinizden iki sonuç cümlesi yazın: biri parlaklık, biri bir ampul bozulduğundaki durum hakkında.","Paralel bağlı fenerin pili daha mı çabuk, daha mı geç tüketeceğini tartışın ve gerekçelendirin.","Kamp feneri için hangi bağlanmayı seçtiğinizi avantaj ve bedeliyle açıklayın."]},{"title":"Fener Kartı","mode":"Bireysel · 15 dk","items":["Tasarladığınız fenerin devre şemasını çizip altına 3 cümlelik 'neden bu tasarım' açıklaması yazın.","Pil atıklarının doğru şekilde atılması için bir sorumluluk notu ekleyip NavigAItor'a yükleyin."]}],"checklist":["Deneyin bağımsız, bağımlı ve kontrol edilen değişkenlerini yazdım.","Tek ampullü, seri ve paralel devreleri kurdum.","Parlaklıkları referans ampulle karşılaştırarak kaydettim.","Bir ampul söküldüğünde iki devrede olanları not ettim.","Seçtiğim bağlanma şeklini avantaj ve bedeliyle açıkladım.","Devre şemamı ve açıklamamı yükledim."],"rubric":[{"k":"Deney Tasarımı","d":"Değişkenleri belirleme ve adil test","l4":"Tüm değişkenleri doğru belirler, referans devrenin gerekçesini açıklar.","l3":"Değişkenleri doğru belirler.","l2":"Değişkenlerde karışıklık var.","l1":"Plan yok."},{"k":"Uygulama ve Veri","d":"Devreleri kurma ve gözlemleri kaydetme","l4":"Üç devreyi kurar, tüm gözlemleri karşılaştırmalı kaydeder.","l3":"Devreleri kurar, gözlemlerin çoğunu kaydeder.","l2":"Bir devre eksik veya kayıtlar eksik.","l1":"Deney yapılmamış."},{"k":"Bilimsel Sonuç","d":"Bağlanma şekli ile parlaklık ilişkisini açıklama","l4":"Parlaklık, bozulma durumu ve pil ömrünü verilerle tutarlı açıklar.","l3":"Parlaklık ilişkisini doğru açıklar.","l2":"Sonuç kısmen doğru.","l1":"Sonuç yok."},{"k":"Model ve Sorumluluk","d":"Fener şeması ve sorumluluk notu","l4":"Şema doğru, seçim gerekçeli, sorumluluk notu uygun.","l3":"Şema doğru, gerekçe var.","l2":"Şemada hata var.","l1":"Şema yok."}],"navi":["Seri devrede bir ampulü söktüğünde diğeri neden söndü? Elektrik akımının izleyebileceği kaç yol kalmıştı?","Paralel bağlı iki ampul, tek ampul kadar parlak yanıyorsa, pilden çekilen toplam enerji için ne düşünürsün?"],"diff":{"destek":"Yalnızca simülasyonda tek ampul ve iki ampullü seri devreyi karşılaştır; parlaklığı hazır ifadelerden seçerek kaydet.","ileri":"Bir ampulü seri, iki ampulü paralel bağlayan karma bir devre tasarla; ampullerin parlaklık sıralamasını önce tahmin et, sonra simülasyonda test et."},"misconception":"Öğrenciler seri bağlı devrede akımın ilk ampulde harcandığını ve sonraki ampulün daha sönük yandığını düşünür."},{"id":"sos-5-01","course":"SOS","grade":5,"themeNo":1,"themeName":"Birlikte Yaşamak","title":"Yeni Arkadaş, Yeni Sofra","subtitle":"Kültürel Farklılıklara Saygı ve Birlikte Yaşam","kazanim":["Kültürel özelliklere saygı duymanın birlikte yaşamaya etkisini yorumlayabilme"],"skills21":["Empati","Kültürlerarası yetkinlik","İletişim","Sosyal farkındalık"],"digital":["Bilgi Okuryazarlığı","Dijital İçerik Üretimi"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Kâğıt-kalem","NavigAItor Stüdyo","Ücretsiz bir afiş/sunum aracı"],"scenario":"Sınıfınıza başka bir bölgeden yeni bir öğrenci geldi. İlk gün konuşma şekli ve beslenme çantasındaki yöresel yiyecek bazı arkadaşlarının dikkatini çekti; kimisi merakla soru sordu, kimisi gülümsedi. Sınıf başkanı olarak öğretmenin senden bir \"Hoş Geldin Haftası\" planı istiyor. Farklılıklara saygı duyulan bir sınıf ile duyulmayan bir sınıf arasında ne fark olur?","visual":{"type":"chat","params":{"lines":[{"who":"Deniz","t":"Bu ne yiyorsun, ilk defa görüyorum!"},{"who":"Yağmur","t":"Bizim oralarda annem sabahları bunu yapar. Tadına bakmak ister misin?"},{"who":"Kerem","t":"Konuşman da biraz farklı, bazı kelimeleri anlamadım."},{"who":"Yağmur","t":"İstersen sana bizim yöredeki kelimeleri öğretebilirim."},{"who":"Deniz","t":"Olur! Ben de sana bizim mahalledeki oyunları anlatırım."}]},"caption":"Diyaloğu oku; saygılı ve saygısız olabilecek ifadeleri işaretle, Kerem'in cümlesini daha nazik biçimde yeniden yaz."},"steps":[{"title":"Diyaloğu Çözümle","mode":"Bireysel · 15 dk","items":["Diyalogda merak gösteren, kırıcı olabilecek ve köprü kuran cümleleri üç farklı renkle işaretle.","Kerem'in cümlesini, Yağmur'un kendini dışlanmış hissetmeyeceği şekilde yeniden yaz.","Yağmur'un yerinde olsaydın ilk gün neler hissederdin? 3 duygu yaz ve nedenini açıkla."],"warn":"Sık yapılan hata: Farklı olanı \"tuhaf\" ya da \"yanlış\" diye nitelemek. Farklı demek yanlış demek değildir; bir özelliği tanımlarken yargı bildiren kelimeleri ayıkla."},{"title":"Kendi Kültür Kartını Hazırla","mode":"Bireysel · 15 dk","items":["Ailenin yemek, bayram, oyun, söz/deyim ve giyim geleneklerinden birer örnek içeren bir kart hazırla.","Bu bilgileri ailenden ya da güvenilir bir dijital kaynaktan topla; kaynağını kartın altına yaz.","Kartında başkalarıyla ortak olabileceğini düşündüğün bir özelliği yıldızla."]},{"title":"Kartları Karşılaştır","mode":"Grup · 20 dk","items":["Grubunuzdaki kartları masaya koyun. Kaç ortak, kaç farklı özellik buldunuz? Tabloya yazın.","Farklılıkların sınıf hayatına katkısını (yeni oyunlar, yeni tatlar, yeni kelimeler) en az 3 örnekle tartışın.","Saygı gösterilmediğinde sınıfta neler yaşanabileceğini neden-sonuç zinciriyle yazın."],"warn":"Sık yapılan hata: Saygıyı yalnızca \"kavga etmemek\" olarak düşünmek. Saygı; dinlemeyi, merak etmeyi ve alay etmemeyi de kapsar."},{"title":"Hoş Geldin Haftası Afişi","mode":"Grup · 30 dk","items":["Ücretsiz bir afiş aracında ya da NavigAItor Stüdyo'da 5 günlük bir \"Hoş Geldin Haftası\" planı tasarlayın (ör. Kelime Günü, Oyun Günü).","Afişe, kültürel özelliklere saygının birlikte yaşamayı nasıl kolaylaştırdığını anlatan bir slogan ekleyin.","Afişi sınıfa sunun; diğer grupların planlarından bir fikri kendi planınıza ekleyin ve nedenini söyleyin."]}],"checklist":["Diyalogdaki cümleleri üç kategoriye ayırdım.","Kerem'in cümlesini saygılı bir dille yeniden yazdım.","Kendi kültür kartımı kaynağıyla birlikte hazırladım.","Ortak ve farklı özellikleri tabloya yazdım.","Saygının birlikte yaşamaya etkisini en az 3 örnekle açıkladım.","Hoş Geldin Haftası afişini sloganıyla birlikte tamamladım."],"rubric":[{"k":"Yorumlama","d":"Saygının birlikte yaşamaya etkisini açıklama","l4":"Etkiyi neden-sonuç zinciriyle ve 3+ özgün örnekle yorumlar","l3":"Etkiyi 2 örnekle açıklar","l2":"Etkiyi tek örnekle, yüzeysel anlatır","l1":"Etki ile saygı arasında bağ kuramaz"},{"k":"Empati","d":"Farklı bakış açısını anlama","l4":"Yeni öğrencinin duygularını gerekçeleriyle ayrıntılı ifade eder","l3":"Duyguları doğru adlandırır","l2":"Duyguları kısmen ifade eder","l1":"Kendi bakış açısının dışına çıkamaz"},{"k":"İletişim Dili","d":"Yargısız, saygılı ifade kullanımı","l4":"Tüm metinlerde yargısız ve kapsayıcı dil kullanır","l3":"Çoğunlukla saygılı dil kullanır","l2":"Yer yer yargı bildiren ifadeler kullanır","l1":"Kırıcı ifadeleri fark etmez"},{"k":"Ürün ve İş Birliği","d":"Afiş planının özgünlüğü ve grup katkısı","l4":"Uygulanabilir, özgün 5 günlük plan; herkes görev almış","l3":"Plan uygulanabilir, katkı dengeli","l2":"Plan eksik ya da katkı dengesiz","l1":"Plan oluşturulmamış"}],"navi":["Sen yeni bir okula gitseydin, ilk gün sana hangi soruyu sorulmasını isterdin, hangisini istemezdin?","Sınıfınızdaki herkes aynı oyunu oynasa, aynı yemeği yese sınıf hayatı nasıl olurdu? Bu sana farklılıkların değeri hakkında ne söylüyor?"],"diff":{"destek":"Diyalogda yalnızca kırıcı olabilecek cümleyi bul ve hazır verilen üç nazik cümle seçeneğinden en uygununu seç; kültür kartında 3 başlığı doldur.","ileri":"Sınıfta saygısızlık yaşandığında uygulanabilecek 3 adımlı bir \"Arabulucu Kılavuzu\" yaz ve bir örnek durumu bu kılavuzla çöz."},"misconception":"Birlikte yaşamak için herkesin aynı gelenekleri benimsemesi, yani benzeşmesi gerektiğini düşünmek."},{"id":"sos-5-02","course":"SOS","grade":5,"themeNo":2,"themeName":"Evimiz Dünya","title":"Sarsıntıya Hazır Mahalle","subtitle":"Afet Farkındalığı ve Eyleme Dönüşen Fikir","kazanim":["Yaşadığı ilde meydana gelebilecek afetlerin etkilerini azaltmaya yönelik farkındalık etkinliği fikrini eyleme dönüştürebilme"],"skills21":["Planlama","Uygulama","Problem çözme","Sorumluluk"],"digital":["Dijital Harita ve Navigasyon","Dijital Sunum"],"duration":"120 dk (3 ders)","format":"Bireysel + Grup","tools":["Dijital harita uygulaması","Ücretsiz bir afiş/sunum aracı","Kâğıt-kalem"],"scenario":"Okulunun bulunduğu mahallede yapılan bir ankete göre ailelerin yarısından azı en yakın toplanma alanının yerini biliyor. Okul müdürü öğrencilerden bir \"Afet Farkındalık Haftası\" fikri bekliyor ve en iyi fikir gerçekten uygulanacak. Sen bu ekibin planlama sorumlususun. Mahallendeki insanları gerçekten harekete geçirecek bir fikri nasıl tasarlarsın?","visual":{"type":"sort","params":{"bins":["Deprem öncesi","Deprem sırasında","Deprem sonrasında"],"items":[{"t":"Afet çantası hazırlamak","b":0},{"t":"Dolapları duvara sabitlemek","b":0},{"t":"Aile buluşma noktası belirlemek","b":0},{"t":"Çök-kapan-tutun hareketini yapmak","b":1},{"t":"Pencere ve camlardan uzak durmak","b":1},{"t":"Merdivene ve asansöre koşmamak","b":1},{"t":"Toplanma alanına gitmek","b":2},{"t":"Hasarlı binaya geri girmemek","b":2},{"t":"Gaz ve elektrik tesisatını kontrol ettirmek","b":2}]},"caption":"Davranış kartlarını depremin hangi aşamasına aitse o kutuya sürükle."},"steps":[{"title":"Bilgini Sınıflandır","mode":"Bireysel · 15 dk","items":["Görseldeki davranış kartlarını doğru aşamaya yerleştir.","Yaşadığın ilde hangi afetlerin (deprem, sel, heyelan, çığ, orman yangını vb.) görülebileceğini araştır ve ikisini seç.","Seçtiğin her afet için öncesinde yapılabilecek bir önlem yaz."],"warn":"Sık yapılan hata: Afet ile tehlikeyi karıştırmak. Deprem doğal bir olaydır; can ve mal kaybına yol açtığında afete dönüşür. Önlemler bu dönüşümü azaltır."},{"title":"Mahalleni Haritada İncele","mode":"İkili · 25 dk","items":["Dijital harita uygulamasında okulunu bul; en yakın toplanma alanı, sağlık kuruluşu ve geniş açık alanları işaretle.","Okuldan toplanma alanına güvenli bir yürüyüş rotası çiz; yol üzerindeki riskli noktaları (dar sokak, yüksek duvar vb.) not et.","Bulgularını \"Güçlü yön / Riskli nokta\" tablosuna yaz."]},{"title":"Fikri Tasarla","mode":"Grup · 35 dk","items":["Hedef kitleni seç: aileler, küçük kardeşler ya da yaşlı komşular.","Bu kitleye uygun bir farkındalık fikri geliştir (ör. toplanma alanı yürüyüşü, afet çantası kontrol kartı, okul panosu).","Fikrin için bir eylem planı yaz: Ne yapılacak? Kim yapacak? Ne zaman? Hangi malzeme gerekir? Başarıyı nasıl anlayacağız?"],"warn":"Sık yapılan hata: \"İnsanları bilinçlendireceğiz\" gibi genel bir hedef yazmak. Hedef ölçülebilir olmalı: \"30 aileye toplanma alanı haritası ulaştıracağız.\""},{"title":"Eyleme Dönüştür ve Değerlendir","mode":"Grup · 45 dk","items":["Ücretsiz bir afiş aracında fikrinizin ana ürününü (afiş, broşür veya harita kartı) hazırlayın.","Ürünü okul içinde paylaşın; en az 10 kişiden kısa geri bildirim toplayın.","Geri bildirimlere göre planınızda değiştireceğiniz bir şeyi ve gerekçesini yazın."]}],"checklist":["Davranış kartlarını doğru aşamalara yerleştirdim.","İlimde görülebilecek iki afeti ve önlemlerini yazdım.","Haritada toplanma alanına güvenli bir rota çizdim.","Ölçülebilir hedefi olan bir eylem planı hazırladım.","Farkındalık ürününü tamamlayıp paylaştım.","Geri bildirime göre planımı geliştirdim."],"rubric":[{"k":"Afet Bilgisi","d":"Afet öncesi-sırası-sonrası davranışları ayırt etme","l4":"Tüm davranışları doğru sınıflar ve ilindeki afetlerle ilişkilendirir","l3":"Davranışların çoğunu doğru sınıflar","l2":"Aşamaları karıştırır","l1":"Davranışları sınıflandıramaz"},{"k":"Mekânsal Analiz","d":"Haritada güvenli rota ve riskleri belirleme","l4":"Rota ve riskleri gerekçeleriyle eksiksiz gösterir","l3":"Rotayı doğru çizer, bazı riskleri belirtir","l2":"Rota eksik ya da riskler belirtilmemiş","l1":"Haritayı kullanamaz"},{"k":"Eylem Planı","d":"Planın somutluğu ve uygulanabilirliği","l4":"Ölçülebilir hedef, görev dağılımı ve takvim eksiksiz","l3":"Plan uygulanabilir, bir öğesi eksik","l2":"Plan genel ifadelerden oluşuyor","l1":"Plan yok"},{"k":"Uygulama ve Yansıtma","d":"Ürünü paylaşma ve geri bildirimle geliştirme","l4":"Ürünü paylaşır, geri bildirimi analiz edip planı geliştirir","l3":"Ürünü paylaşır, geri bildirim toplar","l2":"Ürünü hazırlar ama paylaşmaz","l1":"Ürün hazırlanmamış"}],"navi":["Bir afiş gördüğünde onu gerçekten okumanı ya da bir şey yapmanı sağlayan ne olur?","Planındaki fikrin işe yarayıp yaramadığını bir hafta sonra nasıl anlayabilirsin?"],"diff":{"destek":"Tek bir afet (deprem) üzerinde çalış; eylem planını Ne-Kim-Ne zaman başlıklı hazır şablonla doldur.","ileri":"Hedef kitlende engelli ya da yaşlı bireylerin ihtiyaçlarını da düşünerek planına erişilebilirlik önlemleri ekle ve bunları gerekçelendir."},"misconception":"Afetlerin tamamen kaderle ilgili olduğunu ve insanların etkilerini azaltmak için yapabileceği bir şey olmadığını düşünmek."},{"id":"sos-5-03","course":"SOS","grade":5,"themeNo":3,"themeName":"Ortak Mirasımız","title":"İki Nehir, Bir Yarımada","subtitle":"Mezopotamya ve Anadolu Medeniyetlerini Karşılaştırma","kazanim":["Mezopotamya ve Anadolu medeniyetlerinin ortak mirasa katkılarını karşılaştırabilme"],"skills21":["Karşılaştırma","Analitik düşünme","Tarihsel empati","Sistematik olma"],"digital":["Sanal Müze / Dijital Kültür","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Sanal müze turu","Ücretsiz bir infografik aracı","Kâğıt-kalem"],"scenario":"Bir müzede \"Bugünü Kim Mümkün Kıldı?\" adlı yeni bir salon açılacak ve salonun bir yanı Mezopotamya'ya, diğer yanı Anadolu'ya ayrılmış. Küratör olarak sen, ziyaretçilerin iki bölgenin insanlığa katkılarını karşılaştırabileceği bir duvar tasarlayacaksın. Yer sınırlı; yalnızca en önemli buluşlar ve fikirler sergilenebilecek. Hangi katkılar bugün hâlâ hayatımızın içinde?","visual":{"type":"organizer","params":{"kind":"venn","slots":["Mezopotamya","İkisinde de","Anadolu"]},"caption":"Katkı kartlarını Mezopotamya, Anadolu veya ortak alana yerleştir."},"steps":[{"title":"Katkıları Topla","mode":"Bireysel · 20 dk","items":["Sanal müze turunda ya da güvenilir dijital kaynaklarda şu katkıları ara: yazı, kanunlar, takvim, para, antlaşmalar, su kanalları, tapınak mimarisi.","Her katkının hangi medeniyete ait olduğunu ve bugün nerede karşımıza çıktığını not et.","Kaynağının güvenilir olup olmadığını \"Kim yazmış? Ne zaman? Resmî mi?\" sorularıyla kontrol et."],"warn":"Sık yapılan hata: Mezopotamya ve Anadolu'yu tek bir devlet sanmak. İkisi de birçok farklı medeniyetin yaşadığı bölgelerdir; katkıyı hangi topluluğun yaptığını adıyla yaz."},{"title":"Venn Şemasını Doldur","mode":"Bireysel · 15 dk","items":["Bulduğun katkıları görseldeki Venn şemasına yerleştir.","Ortak alana iki bölgede de görülen özellikleri yaz (ör. tarım, şehir yaşamı, yazılı belgeler).","Her bölge için \"en büyük katkı\" seçimini bir cümleyle gerekçelendir."]},{"title":"Ölçütlerle Karşılaştır","mode":"Grup · 20 dk","items":["Grubunuzla şu ölçütleri içeren bir karşılaştırma tablosu hazırlayın: Yönetim, Hukuk, Ekonomi, Bilim, Mimari.","Hangi ölçütte iki bölgenin benzer, hangisinde farklı yollar izlediğini tartışın.","Bu farkların coğrafi nedenlerini (nehirler, dağlar, ticaret yolları) en az bir örnekle açıklayın."],"warn":"Sık yapılan hata: Karşılaştırmayı \"hangisi daha iyi\" yarışına çevirmek. Karşılaştırma, benzerlik ve farkları ölçütlere göre ortaya koymaktır."},{"title":"Müze Duvarını Tasarla","mode":"Grup · 25 dk","items":["Ücretsiz bir infografik aracında iki sütunlu bir müze duvarı hazırlayın; ortada ortak mirası gösterin.","Her katkı için \"Bugün nerede?\" etiketi ekleyin.","Ziyaretçiye tek cümlelik bir mesaj yazın: Ortak mirasın bize bıraktığı sorumluluk nedir?"]}],"checklist":["En az 6 katkıyı medeniyet adıyla topladım.","Kaynaklarımın güvenilirliğini kontrol ettim.","Venn şemasını eksiksiz doldurdum.","Beş ölçütlü karşılaştırma tablosunu tamamladım.","Farkların coğrafi nedenlerini açıkladım.","Müze duvarı infografiğini \"Bugün nerede?\" etiketleriyle hazırladım."],"rubric":[{"k":"Karşılaştırma","d":"Benzerlik ve farkları ölçütlere göre ortaya koyma","l4":"5 ölçütte benzerlik ve farkları gerekçeli biçimde gösterir","l3":"4 ölçütte doğru karşılaştırma yapar","l2":"Karşılaştırma 2-3 ölçütle sınırlı","l1":"Yalnızca liste yapar, karşılaştırmaz"},{"k":"Tarihsel Doğruluk","d":"Katkıları doğru medeniyete atfetme","l4":"Tüm katkılar doğru medeniyetle eşleşmiş","l3":"Bir hata dışında doğru","l2":"Birkaç önemli hata var","l1":"Eşleşmelerin çoğu yanlış"},{"k":"Bugünle İlişki","d":"Ortak mirasın bugüne etkisini görme","l4":"Her katkıyı bugünkü bir örnekle özgün biçimde ilişkilendirir","l3":"Katkıların çoğunu bugünle ilişkilendirir","l2":"Bağlantılar yüzeysel","l1":"Bağlantı kurulmamış"},{"k":"Dijital Ürün","d":"İnfografiğin düzeni ve anlaşılırlığı","l4":"Düzenli, okunaklı, kaynakları belirtilmiş","l3":"Anlaşılır, küçük eksikler var","l2":"Dağınık ya da eksik","l1":"Ürün hazırlanmamış"}],"navi":["Bugün kullandığın bir eşyadan geriye doğru gitsen, ilk hangi buluşa ulaşırsın?","Bir nehir kıyısında yaşamak ile dağlık bir yarımadada yaşamak, insanların neye ihtiyaç duyduğunu nasıl değiştirir?"],"diff":{"destek":"Hazır verilen 8 katkı kartını yalnızca Venn şemasına yerleştir ve her bölgeden birini bugünle ilişkilendir.","ileri":"Mezopotamya ile Anadolu arasındaki ticaret ve etkileşimin ortak mirası nasıl beslediğini gösteren bir ok şeması çiz ve bir örnek üzerinden açıkla."},"misconception":"Eski medeniyetlerin katkılarının yalnızca geçmişte kaldığını ve bugünkü hayatımızla bağı olmadığını düşünmek."},{"id":"sos-5-04","course":"SOS","grade":5,"themeNo":4,"themeName":"Yaşayan Demokrasimiz","title":"Sorun Var, Kapı Nerede?","subtitle":"İhtiyaç ve Sorunlarda Başvurulacak Kurumlar","kazanim":["Bir ihtiyaç hâlinde veya sorun karşısında başvuru yapılabilecek kurumlar hakkında bilgi toplayabilme"],"skills21":["Etkin vatandaşlık","Sorumlu karar verme","İletişim","Eleştirel düşünme"],"digital":["Dijital Vatandaşlık Araçları","Dijital İçerik Üretimi"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Kurumların resmî web siteleri","NavigAItor Stüdyo","Kâğıt-kalem"],"scenario":"Mahallendeki parkın aydınlatması haftalardır bozuk, okul bahçesindeki salıncak kırık ve yaşlı komşunun bir ihtiyacı var. Herkes şikâyet ediyor ama kimse nereye başvurulacağını bilmiyor. Sen bir \"Vatandaş Rehberi\" hazırlamaya karar veriyorsun. Doğru sorunu doğru kuruma ulaştırmak neden bu kadar önemli?","visual":{"type":"sort","params":{"bins":["Belediye","Muhtarlık","Aile sağlığı merkezi","Okul müdürlüğü"],"items":[{"t":"Parktaki lambalar yanmıyor","b":0},{"t":"Sokaktaki çöpler toplanmıyor","b":0},{"t":"Mahalleye yeni taşınan ailenin yerleşim bilgisi","b":1},{"t":"Yalnız yaşayan yaşlı komşunun ihtiyacının bildirilmesi","b":1},{"t":"Kardeşinin aşı zamanını öğrenmek","b":2},{"t":"Uzun süren öksürük için muayene","b":2},{"t":"Okul bahçesindeki kırık salıncak","b":3},{"t":"Sınıf kitaplığı için kitap ihtiyacı","b":3}]},"caption":"Her sorun kartını başvurulması gereken kurumun kutusuna sürükle."},"steps":[{"title":"Sorunları Eşleştir","mode":"Bireysel · 15 dk","items":["Görseldeki sorun kartlarını uygun kuruma yerleştir.","Kararsız kaldığın bir kart için iki kurumu da düşün; hangisinin görev alanına girdiğini gerekçesiyle yaz.","Acil durumlarda (yangın, kaza) hangi numaranın aranacağını not et ve neden ayrı bir yol olduğunu açıkla."],"warn":"Sık yapılan hata: Her sorun için doğrudan en üst makama başvurulması gerektiğini düşünmek. Sorunu çözme yetkisi olan en yakın kuruma başvurmak daha hızlı sonuç verir."},{"title":"Kurumları Araştır","mode":"İkili · 25 dk","items":["Belediye, muhtarlık ve il sağlık müdürlüğünün resmî web sitelerinde \"İletişim\" ve \"Başvuru\" bölümlerini inceleyin.","Her kurum için şu bilgileri tabloya yazın: Görevleri, başvuru yolları (yüz yüze, telefon, dijital), dikkat edilmesi gerekenler.","Resmî site ile resmî olmayan site arasındaki farkı nasıl anladığınızı açıklayın (uzantı, kurum logosu, iletişim bilgisi)."],"warn":"Sık yapılan hata: Kişisel bilgileri her siteye girmek. Dijital başvuruda yalnızca resmî kurum sitelerini kullan ve bir yetişkinle birlikte işlem yap."},{"title":"Örnek Başvuru Yaz","mode":"Bireysel · 20 dk","items":["Parktaki aydınlatma sorunu için belediyeye kısa bir başvuru metni yaz: Sorun ne? Nerede? Ne zamandan beri? Ne öneriyorsun?","Metninde saygılı bir dil ve açık bilgiler kullan; suçlayıcı ifadelerden kaçın.","Metnini ikilinle değiş tokuş et ve bir eksik bulmasını iste."]},{"title":"Vatandaş Rehberini Hazırla","mode":"İkili · 20 dk","items":["NavigAItor Stüdyo'da \"Bu sorun varsa bu kapıyı çal\" başlıklı tek sayfalık bir rehber tasarlayın.","Rehbere en az 4 kurum, görevleri ve başvuru yolları ekleyin.","Rehberin sonuna \"Başvuru yapmak neden vatandaşlık sorumluluğudur?\" sorusuna iki cümlelik cevabınızı yazın."]}],"checklist":["Sorun kartlarını uygun kurumlarla eşleştirdim.","En az 3 kurumun görev ve başvuru yollarını tabloya yazdım.","Resmî siteyi nasıl tanıdığımı açıkladım.","Saygılı ve açık bir başvuru metni yazdım.","Vatandaş rehberini en az 4 kurumla tamamladım."],"rubric":[{"k":"Bilgi Toplama","d":"Kurumlar hakkında doğru ve güvenilir bilgi toplama","l4":"Resmî kaynaklardan 4+ kurum için eksiksiz bilgi toplar","l3":"3 kurum için doğru bilgi toplar","l2":"Bilgiler eksik ya da kaynaksız","l1":"Bilgi toplamamış"},{"k":"Eşleştirme","d":"Sorunu yetkili kurumla ilişkilendirme","l4":"Tüm eşleştirmeleri gerekçeleriyle doğru yapar","l3":"Eşleştirmelerin çoğu doğru","l2":"Birkaç eşleştirme yanlış","l1":"Kurum görevlerini ayırt edemez"},{"k":"Başvuru Metni","d":"Açık, saygılı ve eksiksiz başvuru yazma","l4":"Tüm öğeler var, dil saygılı, öneri içeriyor","l3":"Öğelerin çoğu var, dil uygun","l2":"Bilgi eksik ya da dil yer yer uygunsuz","l1":"Metin yazılmamış"},{"k":"Rehber Ürünü","d":"Rehberin işlevselliği","l4":"Anlaşılır, düzenli, gerçek hayatta kullanılabilir","l3":"Anlaşılır, küçük eksikler var","l2":"Dağınık ya da eksik","l1":"Rehber hazırlanmamış"}],"navi":["Bir sorunu çözme yetkisi kimdeyse, ona ulaşmak neden en kısa yoldur?","Kimse başvuru yapmazsa bozuk lamba ne zaman tamir edilir? Bunun sorumluluğu kimde?"],"diff":{"destek":"Yalnızca belediye ve muhtarlık ile çalış; başvuru metnini dört boşluklu hazır şablonla yaz.","ileri":"Bir sorunun çözülmesi için birden fazla kurumun iş birliği gerektiği bir durum tasarla (ör. okul yolundaki trafik tehlikesi) ve kurumların rollerini bir akış şemasıyla göster."},"misconception":"Kamu sorunlarının çözümünün yalnızca kurumların görevi olduğunu, vatandaşın bildirimde bulunma sorumluluğu olmadığını düşünmek."},{"id":"sos-5-05","course":"SOS","grade":5,"themeNo":5,"themeName":"Hayatımızdaki Ekonomi","title":"Harçlık Kavanozları","subtitle":"İhtiyaç-İstek Ayrımı ve Kişisel Bütçe Yönetimi","kazanim":["İhtiyaç ve isteklerini karşılamak için gerekli bütçe kaynaklarını yönetebilme"],"skills21":["Finansal okuryazarlık","Karar verme","Öz düzenleme","Sorumluluk"],"digital":["Finansal Okuryazarlık","Veri Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Bireysel","tools":["Ücretsiz bir elektronik tablo aracı","Hesap makinesi","Kâğıt-kalem"],"scenario":"Ailen bu aydan itibaren sana aylık 600 TL harçlık vermeye karar verdi ve bir koşul koydu: Paranı kendin planlayacaksın, ay sonunda da nasıl kullandığını anlatacaksın. Okul kantini, kırtasiye, arkadaşının doğum günü hediyesi ve uzun zamandır istediğin bir kutu oyunu aklında. Para sınırlı, istekler sınırsız. Ayın sonunda hem ihtiyaçlarını karşılamış hem de hedefine yaklaşmış olmak için nasıl bir plan yaparsın?","visual":{"type":"budget","params":{"items":[{"label":"Okul kantini","value":"240 TL"},{"label":"Kırtasiye","value":"90 TL"},{"label":"Hediye","value":"120 TL"},{"label":"Biriktirme","value":"150 TL"}],"total":"600 TL"},"caption":"Parayı kavanozlara dağıt; toplam 600 TL'yi aşmadan kendi planını oluştur."},"steps":[{"title":"İhtiyaç mı, İstek mi?","mode":"Bireysel · 15 dk","items":["Bir ay boyunca harcama yapabileceğin 10 kalemi listele.","Her kalemin yanına \"İhtiyaç\" ya da \"İstek\" yaz ve neden öyle düşündüğünü bir kelimeyle belirt.","Bir kalemin duruma göre değişebileceği bir örnek bul (ör. su: ihtiyaç, markalı su şişesi: istek)."],"warn":"Sık yapılan hata: Çok istediğin bir şeyi ihtiyaç saymak. Kendine sor: \"Bu olmazsa günlük hayatım ya da sağlığım gerçekten etkilenir mi?\""},{"title":"Kavanozları Doldur","mode":"Bireysel · 20 dk","items":["Görseldeki örnek dağılımı incele, sonra kendi dağılımını yap.","Önce ihtiyaçlara, sonra biriktirmeye, en son isteklere pay ayır.","Kutu oyunu 450 TL ise biriktirme kavanozunla kaç ayda alabileceğini hesapla."],"warn":"Sık yapılan hata: Biriktirmeyi ay sonunda kalan paraya bırakmak. Çoğu zaman geriye bir şey kalmaz; birikim payını en başta ayır."},{"title":"Dijital Takip Tablosu","mode":"Bireysel · 25 dk","items":["Ücretsiz bir elektronik tablo aracında Tarih, Harcama, Kavanoz, Tutar ve Kalan sütunlarından oluşan bir tablo kur.","Ayın ilk iki haftası için hayali ama gerçekçi 8 harcama gir.","\"Kalan\" sütununu toplama-çıkarma formülüyle hesapla ve kavanozlardan birinin bitip bitmediğini kontrol et."]},{"title":"Ay Sonu Değerlendirmesi","mode":"Bireysel · 20 dk","items":["Beklenmedik bir harcama çıktı (ör. kaybolan kalem): Planında hangi kavanozdan, neden kısarsın?","Kaynakları verimli kullanmanın sana ve ailene sağladığı iki yararı yaz.","Ailene sunacağın üç cümlelik \"Bütçe Raporu\"nu hazırla."]}],"checklist":["10 harcama kalemini ihtiyaç ve istek olarak ayırdım.","Kavanoz dağılımımı toplamı 600 TL olacak şekilde yaptım.","Hedefim için kaç ay biriktirmem gerektiğini hesapladım.","Elektronik tabloda harcama takibi yaptım.","Beklenmedik harcama için planımı güncelledim.","Ailem için bütçe raporumu yazdım."],"rubric":[{"k":"İhtiyaç-İstek Ayrımı","d":"Kalemleri doğru sınıflama ve gerekçelendirme","l4":"Tüm kalemleri gerekçeli ayırır, duruma bağlı örnek verir","l3":"Kalemlerin çoğunu doğru ayırır","l2":"Ayrımda tutarsızlıklar var","l1":"Ayrım yapamaz"},{"k":"Bütçe Planı","d":"Kaynakları önceliğe göre dağıtma","l4":"Toplam doğru, öncelik sırası mantıklı, birikim hedefi hesaplanmış","l3":"Toplam doğru, öncelik çoğunlukla uygun","l2":"Toplam ya da öncelikte hata var","l1":"Plan yapılmamış"},{"k":"Dijital Takip","d":"Tabloyu doğru kurma ve kullanma","l4":"Tablo eksiksiz, kalan tutar formülle doğru hesaplanmış","l3":"Tablo doğru, küçük hesap hatası var","l2":"Tablo eksik","l1":"Tablo kurulmamış"},{"k":"Uyarlama ve Yansıtma","d":"Beklenmedik duruma göre karar verme","l4":"Değişikliği gerekçeli yapar, verimliliğin yararlarını açıklar","l3":"Uygun değişiklik yapar","l2":"Değişiklik gerekçesiz","l1":"Değişiklik yapmaz"}],"navi":["Bir ay sonra bu harcamayı hatırlayacak mısın? Hatırlamayacaksan bu sana ne söylüyor?","Biriktirme kavanozun hiç dolmuyorsa sorun paranın azlığında mı, sıralamada mı olabilir?"],"diff":{"destek":"Yalnızca 3 kavanozla (İhtiyaç, Biriktirme, İstek) çalış ve tabloyu hazır formüllü şablonla doldur.","ileri":"Ailenin bir aylık elektrik ya da su tüketimini azaltmak için 3 öneri hazırla, olası tasarrufu tahmini olarak hesapla ve bu tasarrufun doğaya etkisini yorumla."},"misconception":"Bütçe yapmanın yalnızca parası az olan kişilerin işi olduğunu ve harcamayı kısıtlamaktan ibaret olduğunu düşünmek."},{"id":"sos-6-06","course":"SOS","grade":6,"themeNo":2,"themeName":"Evimiz Dünya","title":"Dünya Turu Kaptanı","subtitle":"Ülkemizin, Kıtaların ve Okyanusların Konumu","kazanim":["Ülkemizin, kıtaların ve okyanusların konum özelliklerini algılayabilme"],"skills21":["Mekânsal düşünme","Harita okuryazarlığı","Analitik düşünme","Sistematik olma"],"digital":["Dijital Harita ve CBS","Dijital Sunum"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Dijital harita uygulaması","Dilsiz dünya haritası","Ücretsiz bir sunum aracı"],"scenario":"Bir araştırma gemisinin genç kaptan yardımcısısın. Gemi Türkiye'den yola çıkıp tüm okyanuslardan geçerek dünyayı dolaşacak ve her durakta seyir defterine konum bilgisi yazılması gerekiyor. Ama telsizden gelen bir mesajda yalnızca \"Ekvator'un güneyinde, başlangıç meridyeninin doğusunda\" yazıyor. Bir yeri tarif ederken hangi bilgiler onu dünyada tek ve kesin kılar?","visual":{"type":"map","params":{"region":"dunya","pins":[{"label":"Türkiye","x":57,"y":33},{"label":"Asya","x":72,"y":28},{"label":"Afrika","x":53,"y":55},{"label":"Güney Amerika","x":31,"y":66},{"label":"Atlas Okyanusu","x":39,"y":45},{"label":"Hint Okyanusu","x":68,"y":62},{"label":"Büyük Okyanus","x":10,"y":52},{"label":"Antarktika","x":50,"y":93}]},"caption":"Etiketleri dünya haritasında doğru yerlere taşı ve gemi rotasını çiz."},"steps":[{"title":"Haritayı Tanı","mode":"Bireysel · 15 dk","items":["Görseldeki etiketleri doğru yerlere yerleştir.","Ekvator ve başlangıç meridyenini haritada bul; Türkiye'nin hangi yarım kürelerde olduğunu yaz.","Türkiye'nin yaklaşık enlem ve boylam aralığını dijital haritadan bul ve not et."],"warn":"Sık yapılan hata: Enlem ile boylamı karıştırmak. Enlemler Ekvator'a paralel uzanır ve kuzey-güney konumu, boylamlar kutuplar arasında uzanır ve doğu-batı konumu gösterir."},{"title":"Seyir Defterini Doldur","mode":"İkili · 25 dk","items":["Türkiye'den başlayıp üç okyanustan geçen bir rota planlayın.","Her durak için seyir defterine kıta/okyanus adı, yarım küre ve yaklaşık koordinat yazın.","Her durağı bir de göreceli konumla tarif edin (ör. \"Afrika'nın doğusunda, Asya'nın güneyinde\")."],"warn":"Sık yapılan hata: Göreceli konumu tek bir yönle yazmak. Bir yeri tanımlamak için en az iki komşu kara ya da su kütlesini kullan."},{"title":"Telsiz Bilmecesi","mode":"İkili · 20 dk","items":["Birbirinize yalnızca yarım küre ve komşu bilgileri içeren 3 konum bilmecesi yazın.","Partnerinizin bilmecesini dijital haritada çözün; çözüm için kaç ipucunun yettiğini not edin.","Hangi bilginin konumu en çok daralttığını tartışın: matematik konum mu, göreceli konum mu?"]},{"title":"Türkiye Konum Kartı","mode":"Bireysel · 20 dk","items":["Ücretsiz bir sunum aracında Türkiye'nin matematik ve göreceli konumunu gösteren tek slaytlık bir kart hazırla.","Türkiye'yi çevreleyen denizleri ve köprü konumundaki kıtaları haritada göster.","\"Türkiye'nin konumu ona hangi avantajları sağlar?\" sorusuna iki gerekçe yaz."]}],"checklist":["Kıta ve okyanus etiketlerini doğru yerleştirdim.","Türkiye'nin yarım kürelerini ve koordinat aralığını yazdım.","Seyir defterinde her durağı iki konum türüyle tarif ettim.","Konum bilmecesi yazıp partnerimin bilmecesini çözdüm.","Türkiye konum kartını hazırladım."],"rubric":[{"k":"Konum Algısı","d":"Kıta, okyanus ve Türkiye'nin konumunu doğru belirleme","l4":"Tüm öğeleri doğru yerleştirir ve yarım küreleri doğru adlandırır","l3":"Bir hata dışında doğru","l2":"Birkaç önemli hata var","l1":"Öğeleri yerleştiremez"},{"k":"Konum Türleri","d":"Matematik ve göreceli konumu ayırt edip kullanma","l4":"İki konum türünü her durakta doğru ve tutarlı kullanır","l3":"İki türü çoğunlukla doğru kullanır","l2":"Türleri karıştırır","l1":"Konum tarifi yapamaz"},{"k":"Dijital Harita Kullanımı","d":"Dijital haritada koordinat ve rota bulma","l4":"Koordinatları bağımsız bulur, rotayı doğru çizer","l3":"Küçük yardımla doğru bulur","l2":"Koordinatlarda hatalar var","l1":"Aracı kullanamaz"},{"k":"Ürün","d":"Konum kartının doğruluğu ve açıklığı","l4":"Doğru, düzenli ve gerekçeli","l3":"Doğru, küçük eksikler var","l2":"Eksik ya da hatalı bilgi var","l1":"Kart hazırlanmamış"}],"navi":["\"Ekvator'un güneyinde\" ipucu dünyanın ne kadarını eler? Bir ipucu daha eklersen ne olur?","Komşuların kim olduğunu bilmek, bir yerin konumu hakkında koordinatın söyleyemediği neyi söyler?"],"diff":{"destek":"Yalnızca kıtaları ve okyanusları yerleştir; seyir defterinde 3 durak için hazır seçeneklerden yarım küreyi işaretle.","ileri":"Türkiye'nin konumunun iklim ve ulaşım üzerindeki etkisini, aynı enlemdeki başka bir ülkeyle karşılaştırarak açıkla."},"misconception":"Bir yerin konumunu yalnızca koordinatla anlatmanın yeterli olduğunu, göreceli konumun önemsiz olduğunu düşünmek."},{"id":"sos-6-07","course":"SOS","grade":6,"themeNo":3,"themeName":"Ortak Mirasımız","title":"Anadolu'nun Kapısı Açılıyor","subtitle":"XI-XIII. Yüzyıl Olayları ve Anadolu'nun Türkleşmesi","kazanim":["XI-XIII. yüzyıllar arasında meydana gelen siyasi faaliyetler ve askerî mücadelelerin Anadolu’nun Türkleşmesi ve İslamlaşmasına etkisini özetleyebilme"],"skills21":["Tarihsel sorgulama","Sistematik düşünme","Analitik düşünme","Eleştirel bakma"],"digital":["Dijital Zaman Şeridi","Dijital Arşiv ve Veri Tabanları"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor Stüdyo","Dijital zaman şeridi aracı","Kâğıt-kalem"],"scenario":"Bir belgesel ekibinin genç araştırmacısısın ve \"Anadolu'nun Kapısı\" adlı belgeselin kurgusu karıştı: Sahnelerin sırası kaybolmuş. Yönetmen senden olayları doğru sıraya dizmeni ve her olayın Anadolu'nun Türkleşmesi ve İslamlaşmasına nasıl katkı yaptığını kısa bir anlatıcı metniyle açıklamanı istiyor. Bir olayın önemini, ondan sonra gelenlere bakmadan anlayabilir miyiz?","visual":{"type":"timeline","params":{"events":[{"y":"1040","t":"Dandanakan Savaşı: Büyük Selçuklu Devleti'nin kuruluşu"},{"y":"1071","t":"Malazgirt Meydan Muharebesi"},{"y":"1075","t":"Türkiye Selçuklu Devleti'nin kuruluşu"},{"y":"1096","t":"Haçlı Seferlerinin başlaması"},{"y":"1176","t":"Miryokefalon Savaşı"},{"y":"1243","t":"Kösedağ Savaşı"}],"shuffle":true},"caption":"Karışık verilen olay kartlarını zaman şeridinde doğru sıraya diz."},"steps":[{"title":"Sahneleri Sırala","mode":"Bireysel · 15 dk","items":["Görseldeki olayları kronolojik sıraya diz.","Ardışık iki olay arasındaki yıl farkını hesapla; en uzun aralığın hangisi olduğunu bul.","Olayları \"Kapıyı açan\", \"Yurdu kalıcı kılan\", \"Dengeyi değiştiren\" gruplarına ayır."],"warn":"Sık yapılan hata: Malazgirt'ten hemen sonra Anadolu'nun tamamen Türkleştiğini sanmak. Türkleşme ve İslamlaşma yüzyıllar süren, göç ve yerleşmeyle ilerleyen bir süreçtir."},{"title":"5N1K ile Sorgula","mode":"Grup · 25 dk","items":["Gruptaki her öğrenci bir olay seçer ve güvenilir dijital kaynaklardan 5N1K sorularının cevaplarını toplar.","Her olay için \"Bu olaydan önce ne vardı, sonra ne değişti?\" sorusuna iki cümlelik cevap yazın.","Kaynaklarınızı listeleyin; aynı bilgiyi en az iki kaynakta doğrulayın."],"warn":"Sık yapılan hata: Savaşları yalnızca kazanan-kaybeden olarak anlatmak. Asıl soru, savaşın göç, yerleşme ve kültür üzerindeki sonuçlarıdır."},{"title":"Neden-Sonuç Zinciri Kur","mode":"Grup · 20 dk","items":["Olayları oklarla birbirine bağlayan bir neden-sonuç zinciri çizin.","Anadolu'da kurulan şehirler, kervansaraylar ve medreselerin Türkleşme-İslamlaşmaya etkisini zincire ekleyin.","Zincirdeki en kritik halkayı seçin ve gerekçesini yazın."]},{"title":"Anlatıcı Metnini Yaz","mode":"Bireysel · 20 dk","items":["NavigAItor Stüdyo'da belgesel için 6-8 cümlelik bir anlatıcı metni yaz.","Metinde en az 4 olayı doğru sırayla ve sonuçlarıyla özetle.","Metnin sonunda izleyiciye düşündürücü bir soru sor."]}],"checklist":["Olayları doğru kronolojik sıraya dizdim.","Seçtiğim olayı 5N1K ile araştırdım.","Bilgimi en az iki kaynakta doğruladım.","Neden-sonuç zincirini çizdim.","Anlatıcı metnini en az 4 olayla yazdım.","Metnimde Türkleşmenin bir süreç olduğunu vurguladım."],"rubric":[{"k":"Kronoloji","d":"Olayları doğru sıralama ve aralıkları yorumlama","l4":"Sıralama doğru, aralıkları sürece bağlar","l3":"Sıralama doğru","l2":"Bir-iki sıralama hatası var","l1":"Sıralama yapamaz"},{"k":"Özetleme","d":"Olayların Türkleşme-İslamlaşmaya etkisini özetleme","l4":"Her olayın etkisini öz ve doğru biçimde açıklar","l3":"Etkilerin çoğunu doğru açıklar","l2":"Etkiler yüzeysel ya da eksik","l1":"Etki açıklanmamış"},{"k":"Kanıt Kullanımı","d":"Bilgiyi kaynaklarla destekleme ve doğrulama","l4":"Çoklu kaynakla doğrular, kaynakları belirtir","l3":"Kaynak belirtir, kısmen doğrular","l2":"Tek ve belirsiz kaynak","l1":"Kaynak yok"},{"k":"Anlatı Ürünü","d":"Anlatıcı metninin akışı ve tutarlılığı","l4":"Akıcı, tutarlı ve düşündürücü","l3":"Anlaşılır, küçük kopukluklar var","l2":"Kopuk ya da eksik","l1":"Metin yazılmamış"}],"navi":["Bir savaş kazanılsa ama ardından kimse o bölgeye yerleşmese, o toprak gerçekten yurt olur mu?","Kervansaray ve medrese gibi yapılar bir orduya göre daha yavaş ama daha kalıcı ne yapar?"],"diff":{"destek":"Yalnızca 4 olayı (1040, 1071, 1075, 1176) sırala ve her biri için hazır sonuç kartlarından uygun olanı eşleştir.","ileri":"Haçlı Seferlerinin Anadolu'daki Türk varlığını nasıl etkilediğini iki farklı bakış açısından (Türkiye Selçuklu ve Bizans) değerlendiren kısa bir karşılaştırma yaz."},"misconception":"Anadolu'nun Türkleşmesini tek bir savaşla bir anda gerçekleşmiş bir olay sanmak."},{"id":"sos-6-08","course":"SOS","grade":6,"themeNo":4,"themeName":"Yaşayan Demokrasimiz","title":"Tek Tıkla Vatandaş","subtitle":"Dijitalleşmenin Vatandaşlık Haklarına Etkisi","kazanim":["Vatandaşlık haklarının kullanımında dijitalleşme ve teknolojik gelişmelerin etkilerini sorgulayabilme"],"skills21":["Dijital vatandaşlık","Eleştirel düşünme","Katılım","Sorumlu karar verme"],"digital":["Dijital Katılım Araçları","Medya Okuryazarlığı","Dijital Etik ve Mahremiyet"],"duration":"80 dk (2 ders)","format":"Grup","tools":["Kâğıt-kalem","NavigAItor Stüdyo","Ücretsiz bir anket aracı"],"scenario":"Yerel bir gazetede belediyenin dijital başvuru sistemiyle ilgili bir haber çıktı: Başvurular hızla artmış ama bazı yaşlı vatandaşlar sistemi kullanamadığını söylüyor. Şehir meclisine \"Çocuk Danışma Kurulu\" üyesi olarak davet edildin ve senden dijitalleşmenin haklarımızı kullanmayı kolaylaştırıp kolaylaştırmadığı konusunda görüş isteniyor. Teknoloji herkes için aynı kapıyı mı açar?","visual":{"type":"news","params":{"headline":"Dijital Dilekçe Dönemi: Başvurular Üçe Katlandı, Peki Herkes Ulaşabiliyor mu?","lead":"Belediyenin çevrim içi başvuru sistemi bir yılda üç kat daha fazla başvuru aldı. Gençler hızdan memnun; ancak internet erişimi olmayan ya da teknolojiyi kullanmakta zorlanan bazı vatandaşlar kendilerini dışarıda kalmış hissettiğini söylüyor.","tags":["dijital katılım","eşitlik","kişisel veri"]},"caption":"Haberi oku; olguları ve görüşleri farklı renkle işaretle."},"steps":[{"title":"Haberi Çözümle","mode":"Bireysel · 15 dk","items":["Haberdeki olgu (kanıtlanabilir bilgi) ve görüş (kişisel düşünce) ifadelerini ayır.","Haberde sesi duyulan ve duyulmayan grupları belirle.","Haberi okuyunca aklına gelen iki soruyu yaz."],"warn":"Sık yapılan hata: \"Başvurular arttı\" bilgisini doğrudan \"herkes memnun\" diye yorumlamak. Bir sayı artışı tek başına herkesin hakka eşit eriştiğini göstermez."},{"title":"Artılar ve Riskler Tablosu","mode":"Grup · 20 dk","items":["Dijitalleşmenin dilekçe hakkı, bilgi edinme hakkı ve eğitim hakkı üzerindeki olumlu etkilerini yazın.","Aynı haklar için olası riskleri yazın: erişim eşitsizliği, kişisel verilerin korunması, yanlış bilgi.","Her risk için kimin en çok etkileneceğini belirtin."],"warn":"Sık yapılan hata: Kişisel veriyi yalnızca şifre sanmak. Ad, adres, fotoğraf ve kimlik bilgileri de kişisel veridir ve korunmalıdır."},{"title":"Küçük Bir Araştırma","mode":"Grup · 25 dk","items":["Ücretsiz bir anket aracıyla ya da kâğıt üzerinde ailenizden ve okul çalışanlarından en az 10 kişiye 3 soruluk anonim bir anket uygulayın (dijital başvuru kullanıyor mu, zorlanıyor mu, neden).","Sonuçları sayın ve yüzde olarak özetleyin.","Sonuçların haberdeki iddiayı destekleyip desteklemediğini tartışın."]},{"title":"Kurula Görüş Bildir","mode":"Grup · 20 dk","items":["NavigAItor Stüdyo'da şehir meclisine sunulacak tek sayfalık bir görüş yazısı hazırlayın.","Yazıda bir tespit, iki kanıt ve herkesin hakka erişimini kolaylaştıracak iki somut öneri bulunsun.","Önerilerinizin olası bir dezavantajını da dürüstçe belirtin."]}],"checklist":["Haberdeki olgu ve görüşleri ayırdım.","Dijitalleşmenin artı ve risklerini haklar üzerinden tabloya yazdım.","Kişisel verinin neleri kapsadığını açıkladım.","Anonim anket uygulayıp sonuçları yüzdeyle özetledim.","Kanıta dayalı iki öneri içeren görüş yazısını hazırladık."],"rubric":[{"k":"Sorgulama","d":"Dijitalleşmenin etkilerini çok yönlü sorgulama","l4":"Olumlu ve olumsuz etkileri farklı gruplar açısından derinlemesine sorgular","l3":"İki yönlü etkileri açıklar","l2":"Tek yönlü değerlendirir","l1":"Sorgulama yapmaz"},{"k":"Medya Okuryazarlığı","d":"Olgu ve görüşü ayırt etme","l4":"Tüm ifadeleri doğru ayırır, eksik sesleri fark eder","l3":"İfadelerin çoğunu doğru ayırır","l2":"Ayrımda karışıklık var","l1":"Ayrım yapamaz"},{"k":"Kanıt Kullanımı","d":"Anket verisini görüşü desteklemek için kullanma","l4":"Veriyi doğru özetler ve görüşle tutarlı biçimde kullanır","l3":"Veriyi özetler, kısmen kullanır","l2":"Veri eksik ya da yanlış özetlenmiş","l1":"Veri toplanmamış"},{"k":"Öneri ve Katılım","d":"Uygulanabilir ve kapsayıcı öneriler geliştirme","l4":"Somut, kapsayıcı, dezavantajı da düşünülmüş öneriler","l3":"Uygulanabilir iki öneri","l2":"Öneriler genel","l1":"Öneri yok"}],"navi":["Bir hakkı kullanmanın yolu kolaylaştığında, o yolu kullanamayanlar için ne değişir?","Bir sisteme bilgi verirken, o bilginin nerede ve kimde kaldığını hiç düşündün mü?"],"diff":{"destek":"Haberden yalnızca 2 olgu ve 2 görüş bul; artılar-riskler tablosunu tek hak (dilekçe hakkı) üzerinden doldur.","ileri":"Dijital kapsayıcılık için belediyeye bir \"Yardım Masası\" modeli tasarla; hangi gruplara, nerede ve nasıl hizmet vereceğini bir akış şemasıyla göster."},"misconception":"Dijitalleşmenin herkes için otomatik olarak eşit bir kolaylık sağladığını ve hiçbir risk taşımadığını düşünmek."},{"id":"sos-6-09","course":"SOS","grade":6,"themeNo":5,"themeName":"Hayatımızdaki Ekonomi","title":"Okul Girişimcileri Fuarı","subtitle":"Ürün Tasarımı, Yatırım ve Pazarlama Önerisi","kazanim":["Tasarladığı bir ürün için yatırım ve pazarlama proje önerisi hazırlayabilme"],"skills21":["Girişimcilik","Yaratıcılık","Finansal okuryazarlık","Analitik düşünme"],"digital":["Dijital Proje Yönetimi","Finansal Okuryazarlık"],"duration":"120 dk (3 ders)","format":"Grup","tools":["Ücretsiz bir sunum aracı","Ücretsiz bir elektronik tablo aracı","Kâğıt-kalem"],"scenario":"Okulun bahar döneminde bir \"Girişimciler Fuarı\" düzenlenecek ve her grup gerçek bir ihtiyaca cevap veren bir ürün fikri sunacak. Jüri, ürünü üretmek için 1000 TL'lik hayali bir başlangıç sermayesi veriyor ve paranın nasıl harcanacağını, ürünün kime nasıl ulaştırılacağını soruyor. Grubunuz bu projenin hem tasarımcısı hem de finans ekibi. İyi bir fikri, yatırım yapılabilir bir projeye dönüştüren nedir?","visual":{"type":"pie","params":{"labels":["Malzeme","Üretim araçları","Ambalaj","Tanıtım","Yedek bütçe"],"values":[40,20,15,15,10]},"caption":"Örnek yatırım dağılımını incele, kendi ürünün için dilimleri yeniden düzenle."},"steps":[{"title":"İhtiyacı Bul","mode":"Grup · 20 dk","items":["Okulunuzda ya da mahallenizde çözüm bekleyen 3 küçük ihtiyacı listeleyin.","En az 5 kişiyle kısa görüşme yaparak hangi ihtiyacın daha yaygın olduğunu belirleyin.","Seçtiğiniz ihtiyaca yönelik ürün fikrinizi bir çizim ve iki cümleyle tanımlayın."],"warn":"Sık yapılan hata: Önce ürünü düşünüp sonra ona müşteri aramak. Girişim, gerçek bir ihtiyaçtan başlar."},{"title":"Yatırım Planı","mode":"Grup · 35 dk","items":["Ücretsiz bir elektronik tablo aracında 1000 TL'lik sermayenin dağılımını kalem kalem planlayın.","Bir ürünün maliyetini, satış fiyatını ve ürün başına kârı hesaplayın.","Başlangıç sermayesini geri kazanmak için kaç ürün satılması gerektiğini bulun ve görseldeki gibi bir daire grafiği oluşturun."],"warn":"Sık yapılan hata: Satış gelirinin tamamını kâr sanmak. Kâr, gelirden tüm giderler çıkarıldıktan sonra kalan tutardır."},{"title":"Pazarlama Stratejisi","mode":"Grup · 30 dk","items":["Hedef müşterinizi tanımlayın: Kimler? Ürününüzü neden alsınlar?","Ürün için bir ad, slogan ve ambalaj fikri geliştirin.","Ürünü tanıtmak için ücretsiz ya da düşük maliyetli 2 tanıtım yolu seçin ve neden etkili olacağını açıklayın."]},{"title":"Jüriye Sun","mode":"Grup · 35 dk","items":["Ücretsiz bir sunum aracında 5 slaytlık proje önerisi hazırlayın: İhtiyaç, Ürün, Yatırım Planı, Pazarlama, Riskler.","Projeyi 4 dakikada sunun; jüriden gelen bir soruya verilerle cevap verin.","Diğer grupların sunumlarından birine yapıcı bir geri bildirim yazın."]}],"checklist":["Gerçek bir ihtiyacı görüşmelerle belirledik.","1000 TL'lik yatırım planını tabloya döktük.","Maliyet, fiyat ve kârı doğru hesapladık.","Hedef müşteri ve pazarlama yollarını belirledik.","5 slaytlık proje önerisini sunduk.","Başka bir gruba yapıcı geri bildirim verdim."],"rubric":[{"k":"İhtiyaç ve Ürün","d":"Ürünün gerçek bir ihtiyaca cevap vermesi","l4":"İhtiyaç verilerle desteklenmiş, ürün özgün ve uygulanabilir","l3":"İhtiyaç belirgin, ürün uygulanabilir","l2":"İhtiyaç belirsiz","l1":"Ürün fikri yok"},{"k":"Yatırım Planı","d":"Sermaye dağılımı ve kâr hesabı","l4":"Dağılım gerekçeli, hesaplar doğru, başa baş noktası bulunmuş","l3":"Dağılım ve hesaplar çoğunlukla doğru","l2":"Hesaplarda önemli hatalar var","l1":"Plan yapılmamış"},{"k":"Pazarlama","d":"Hedef kitle ve tanıtım stratejisi","l4":"Hedef kitle net, strateji yaratıcı ve maliyetine uygun","l3":"Hedef kitle ve strateji uygun","l2":"Strateji genel ifadelerden oluşuyor","l1":"Pazarlama planı yok"},{"k":"Sunum ve İş Birliği","d":"Önerinin sunumu ve grup katkısı","l4":"Akıcı, verilerle desteklenmiş; herkes görev almış","l3":"Anlaşılır, katkı dengeli","l2":"Eksik ya da katkı dengesiz","l1":"Sunum yapılmamış"}],"navi":["Ürününü almayacak birinin aklındaki soru ne olabilir? O soruya planında bir cevap var mı?","Yedek bütçe ayırmazsan, beklenmedik bir masrafta projene ne olur?"],"diff":{"destek":"Hazır bir ürün fikri (ör. sınıf için kalem düzenleyici) seç; yatırım planını 3 kalemli hazır tabloyla, pazarlamayı tek slogan ve tek tanıtım yoluyla yap.","ileri":"Ürününüz için iki farklı fiyat senaryosu hazırlayın; her birinde satılması gereken ürün sayısını hesaplayın ve hangisini neden seçtiğinizi verilerle savunun."},"misconception":"Bir ürünün başarısının yalnızca iyi bir fikre bağlı olduğunu, maliyet ve pazarlama planının ikinci planda kaldığını düşünmek."},{"id":"sos-6-10","course":"SOS","grade":6,"themeNo":6,"themeName":"Teknoloji Ve Sosyal Bilimler","title":"Bu Fikir Kimin?","subtitle":"Telif ve Patent Hakları Üzerine Araştırma","kazanim":["Bir ürün veya fikrin telif ve patent haklarıyla ilgili bilgi toplayabilme"],"skills21":["Bilgi okuryazarlığı","Eleştirel bakma","Sorumlu karar verme","Sistematik düşünme"],"digital":["Patent ve Telif Araçları","Veri Doğrulama","Dijital Raporlama"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Resmî kurum web siteleri","NavigAItor Stüdyo","Kâğıt-kalem"],"scenario":"Sınıf arkadaşın, su tasarrufu sağlayan küçük bir musluk başlığı tasarladı ve bunu okul bilim şenliğinde sergiledi. Bir hafta sonra benzer bir tasarımın, adı belirtilmeden bir video kanalında paylaşıldığını gördünüz. Aynı günlerde sen de kendi yazdığın bir şiiri bir yarışmaya göndermek istiyorsun. Bir fikri ya da eseri kimin olduğunu nasıl koruruz ve hangi hak hangi ürün için geçerlidir?","visual":{"type":"sort","params":{"bins":["Telif hakkı","Patent"],"items":[{"t":"Yazdığın bir şiir","b":0},{"t":"Çektiğin bir fotoğraf","b":0},{"t":"Bestelenmiş bir şarkı","b":0},{"t":"Bir çizgi roman karakteri çizimi","b":0},{"t":"Su tasarruflu musluk başlığı","b":1},{"t":"Yeni bir kilit mekanizması","b":1},{"t":"Daha hızlı şarj eden pil yöntemi","b":1},{"t":"Katlanabilir yeni bir sandalye düzeneği","b":1}]},"caption":"Her ürün kartını korunduğu hak türüne göre doğru kutuya sürükle."},"steps":[{"title":"Hakları Sınıflandır","mode":"Bireysel · 15 dk","items":["Görseldeki kartları telif hakkı ve patent kutularına yerleştir.","İki kutudaki ürünlerin ortak özelliklerini bul: Biri hangi tür ürünleri, diğeri hangi tür ürünleri koruyor?","Bu farkı kendi cümlelerinle tek cümlede tanımla."],"warn":"Sık yapılan hata: Telif ile patenti aynı şey sanmak. Telif hakkı edebiyat, müzik, resim gibi fikir ve sanat eserlerini; patent ise yeni ve sanayiye uygulanabilir buluşları korur."},{"title":"Üç Kaynaktan Bilgi Topla","mode":"İkili · 25 dk","items":["Patent ve marka işleriyle ilgilenen resmî kurumun web sitesi ile telif haklarıyla ilgili resmî kaynakları inceleyin.","Şu soruların cevaplarını en az üç farklı kaynakta arayın: Bu haklar nasıl kazanılır? Ne kadar süre korunur? İhlal edilirse ne olur?","Kaynaklardaki bilgiler uyuşuyor mu? Uyuşmayan bilgi varsa hangisine neden güvendiğinizi yazın."],"warn":"Sık yapılan hata: İnternette ücretsiz bulunan her içeriğin herkes tarafından serbestçe kullanılabileceğini düşünmek. Ücretsiz erişim, kullanım izni anlamına gelmez."},{"title":"Vakayı Çöz","mode":"İkili · 20 dk","items":["Senaryodaki iki durumu (musluk başlığı ve şiir) inceleyin: Hangi hak geçerli, hak sahibi ne yapabilir?","Musluk başlığının sahibinin fikrini korumak için atabileceği adımları sırayla yazın.","Başkasının eserini kullanırken nasıl izin alınabileceğini ve kaynak gösterilebileceğini bir örnekle gösterin."]},{"title":"Dijital Rapor Hazırla","mode":"Bireysel · 20 dk","items":["NavigAItor Stüdyo'da \"Fikrimi Nasıl Korurum?\" başlıklı tek sayfalık bir rapor hazırla.","Raporda telif ve patentin farkını, koruma süreçlerini ve kullandığın kaynakları göster.","Raporu kendi ürettiğin bir görsel ya da şemayla destekle ve altına kendi adını eser sahibi olarak yaz."]}],"checklist":["Ürün kartlarını doğru hak türüne yerleştirdim.","Telif ve patent farkını kendi cümlemle tanımladım.","Bilgileri en az üç kaynakta karşılaştırdım.","Senaryodaki iki vakayı çözdüm.","Kaynaklarını gösterdiğim dijital raporu hazırladım."],"rubric":[{"k":"Bilgi Toplama","d":"Telif ve patent hakkında güvenilir bilgi toplama","l4":"Üç resmî/güvenilir kaynaktan eksiksiz bilgi toplar ve karşılaştırır","l3":"İki-üç kaynaktan doğru bilgi toplar","l2":"Tek kaynak ya da eksik bilgi","l1":"Bilgi toplamamış"},{"k":"Kavram Ayrımı","d":"Telif ve patenti doğru ayırt etme","l4":"Tüm örnekleri doğru sınıflar, farkı özgün tanımlar","l3":"Örneklerin çoğunu doğru sınıflar","l2":"Kavramları yer yer karıştırır","l1":"Ayrım yapamaz"},{"k":"Vaka Çözümü","d":"Bilgiyi gerçek duruma uygulama","l4":"İki vakayı da doğru hak ve adımlarla çözer","l3":"Vakaları çoğunlukla doğru çözer","l2":"Çözüm eksik","l1":"Vaka çözülmemiş"},{"k":"Dijital Rapor ve Etik","d":"Raporun düzeni ve kaynak gösterimi","l4":"Düzenli, özgün görselli, tüm kaynaklar belirtilmiş","l3":"Anlaşılır, kaynaklar belirtilmiş","l2":"Kaynaklar eksik","l1":"Rapor hazırlanmamış"}],"navi":["Bir şiiri ve bir makineyi korumak için neden farklı kurallar gerekebilir? İkisini kopyalamak arasında ne fark var?","Senin çizdiğin bir resmi biri izinsiz kullansa neler hissederdin? Bu his sana kaynak göstermenin önemi hakkında ne söylüyor?"],"diff":{"destek":"Sınıflandırmayı 4 kartla yap; bilgi toplama aşamasında öğretmenin verdiği tek resmî kaynaktan 3 soruya cevap bul.","ileri":"Okulunuz için \"Dijital İçerik Kullanım Kuralları\" adlı 5 maddelik bir sözleşme taslağı hazırla ve her maddeyi telif veya patent bilgisiyle gerekçelendir."},"misconception":"İnternette erişilebilen her içeriğin sahipsiz olduğunu ve izin almadan kullanılabileceğini düşünmek."},{"id":"sos-7-11","course":"SOS","grade":7,"themeNo":1,"themeName":"Birlikte Yaşamak","kazanim":["Özel gereksinimli bireyler için fırsat eşitliğini sürdürmeye yönelik fikir üretebilme"],"title":"Okulumuz Herkes İçin mi?","subtitle":"Fırsat eşitliği ve erişilebilirlik denetimi","skills21":["Empati","Sosyal farkındalık","Problem çözme","Girişkenlik"],"digital":["Dijital Proje Tasarımı","Dijital Etik ve Nezaket"],"duration":"80 dk (2 ders)","format":"Grup","tools":["Tablet veya telefon kamerası","Kâğıt-kalem ve kroki kâğıdı","Ücretsiz bir dijital pano aracı","NavigAItor Stüdyo"],"scenario":"Okul müdürü, gelecek dönem okula tekerlekli sandalye kullanan, az gören ve işitme cihazı kullanan üç yeni öğrencinin katılacağını duyurdu. Okul meclisi sizin grubunuzu \"Erişilebilirlik Ekibi\" olarak görevlendirdi. Bir hafta içinde okulu gezip engelleri belirleyecek ve uygulanabilir çözümler önereceksiniz. Okulumuz bugün herkes için eşit fırsat sunuyor mu, sunmuyorsa ilk neyi değiştirmeliyiz?","visual":{"type":"sort","params":{"bins":["Fiziksel erişim","Bilgiye erişim","Sosyal katılım"],"items":[{"t":"Ana girişte yalnızca merdiven var","b":0},{"t":"Lavabo kapısı tekerlekli sandalye için dar","b":0},{"t":"Yemekhane tezgâhı çok yüksek","b":0},{"t":"Duyurular yalnızca sesli anonsla yapılıyor","b":1},{"t":"Kütüphanede büyük puntolu kitap yok","b":1},{"t":"Sınav yönergeleri yalnızca küçük yazıyla veriliyor","b":1},{"t":"Teneffüs oyunları herkesin katılımına uygun değil","b":2},{"t":"Kulüp seçiminde kimse destek önermiyor","b":2}]},"caption":"Okulda karşılaşılabilecek engelleri doğru kutuya sürükle ve hangi kutunun en kalabalık olduğuna dikkat et."},"steps":[{"title":"Engelleri Sınıflandır","mode":"Bireysel · 10 dk","items":["Görseldeki 8 engeli üç kutuya yerleştir.","Her kutu için aklına gelen bir engeli daha deftere ekle.","Hangi engelin hangi yeni öğrenciyi en çok etkileyeceğini yanına not et."],"warn":"Sık yapılan hata: Erişilebilirliği yalnızca rampa ve asansörden ibaret sanmak. Bilgiye ulaşamamak ya da oyunlara katılamamak da fırsat eşitsizliğidir."},{"title":"Okulu Denetle","mode":"Grup · 25 dk","items":["Okulun girişini, koridorları, kantini ve bahçeyi gezin; engel gördüğünüz yerleri kişi görünmeyecek şekilde fotoğraflayın.","Okulun basit bir krokisini çizip her engeli numarayla işaretleyin.","Her engel için \"Kimi etkiliyor? Ne kadar sık karşılaşılır?\" sorularını yanıtlayın."],"warn":"Sık yapılan hata: Fotoğraflarda öğrencilerin yüzlerini çekmek. Denetim mekânla ilgilidir; kişilerin mahremiyetine saygı göster."},{"title":"Çözüm Üret ve Önceliklendir","mode":"Grup · 25 dk","items":["Her engel için en az bir çözüm yaz: hemen yapılabilecek, okul bütçesi gerektirmeyen bir çözüm ve uzun vadeli bir çözüm.","Çözümleri \"etkisi büyük / uygulaması kolay\" olarak puanlayın ve ilk üç öneriyi seçin.","Çözümlerinizi özel gereksinimli bir öğrencinin gözünden tekrar okuyun: Bu çözüm onu dışarıda bırakıyor mu?"]},{"title":"Dijital Panoyu Hazırla ve Sun","mode":"Grup · 20 dk","items":["Krokiniz, fotoğraflarınız ve ilk üç önerinizle bir dijital pano oluşturun.","Panoya \"Biz Ne Yapabiliriz?\" başlıklı, öğrencilerin kendi başlattığı bir mini kampanya ekleyin.","Panoyu okul meclisine 3 dakikada sunun ve gelen soruları not edin."]}],"checklist":["Engelleri üç türe ayırdım ve her türe kendi örneğimi ekledim","Okul krokisinde en az 5 engeli işaretledim","Fotoğraflarda kimsenin yüzü görünmediğinden emin oldum","Her engel için kısa ve uzun vadeli bir çözüm yazdım","İlk üç önerimizi gerekçesiyle seçtim","Dijital panoyu NavigAItor Stüdyo'ya yükledim"],"rubric":[{"k":"Engel tespiti","d":"Farklı türdeki engelleri belirleme","l4":"Üç türde de çok sayıda gerçekçi engel belirler ve etkilenenleri açıklar","l3":"Üç türde engel belirler","l2":"Yalnızca fiziksel engellere odaklanır","l1":"Engelleri belirlemekte zorlanır"},{"k":"Çözüm önerisi","d":"Uygulanabilir ve eşitlikçi fikir üretme","l4":"Özgün, bütçe gerektirmeyen ve kimseyi dışlamayan çözümler önerir","l3":"Uygulanabilir çözümler önerir","l2":"Çözümler genel ve belirsizdir","l1":"Çözüm önermez ya da sorunu tekrar eder"},{"k":"Empati ve bakış açısı","d":"Özel gereksinimli bireyin gözünden değerlendirme","l4":"Her çözümü farklı gereksinimler açısından sınar","l3":"Çoğu çözümde kullanıcıyı düşünür","l2":"Kullanıcıyı ara sıra düşünür","l1":"Kullanıcının bakış açısını dikkate almaz"},{"k":"Dijital pano ve sunum","d":"Bulguları açık ve etik biçimde paylaşma","l4":"Pano düzenli, kanıtlı ve mahremiyete saygılıdır; sunum ikna edicidir","l3":"Pano ve sunum anlaşılırdır","l2":"Pano eksik ya da dağınıktır","l1":"Pano hazırlanmamıştır"}],"navi":["Gözlerini kapatıp okulun girişinden sınıfına kadar yürüdüğünü düşün; hangi noktada ilk kez yardıma ihtiyaç duyardın?","Önerdiğin çözüm bir öğrenciye yardım ederken başka bir öğrenciyi zorlaştırıyor olabilir mi?"],"diff":{"destek":"Öğrenci yalnızca sınıfını ve sınıfa giden koridoru denetler; çözümleri hazır bir \"engel – çözüm\" tablosuna yazar.","ileri":"Öğrenci, önerilerini belediyenin engelsiz yaşam birimine iletilecek kısa ve nazik bir dilekçeye dönüştürür."},"misconception":"Fırsat eşitliği herkese aynı şeyi vermek değil, herkesin aynı noktaya ulaşabilmesi için gereken desteği sağlamaktır."},{"id":"sos-7-12","course":"SOS","grade":7,"themeNo":2,"themeName":"Evimiz Dünya","kazanim":["Küreselleşmenin insan ve toplum hayatında meydana getirdiği değişimi yorumlayabilme"],"title":"Kahvaltı Sofrası Dünyayı Dolaşıyor","subtitle":"Küreselleşmenin günlük hayata etkisi — ürün izi haritası","skills21":["Küresel farkındalık","Analitik düşünme","İletişim","İş birliği"],"digital":["Dijital Harita ve CBS","Dijital Sunum"],"duration":"80 dk (2 ders)","format":"İkili","tools":["Dijital harita uygulaması","Ürün etiketleri (evden getirilecek)","Ücretsiz bir sunum aracı","Kâğıt-kalem"],"scenario":"Okulunuzun haber bülteni \"Bir Sabah, Kaç Ülke?\" başlıklı bir dosya hazırlıyor ve sizden bir harita istiyor. Kahvaltı sofranızdaki ürünlerin, giydiğiniz kıyafetin ve telefonunuzun parçalarının nereden geldiğini izleyeceksiniz. Büyükanne ve büyükbabanızın çocukluğundaki sofrayla bugünkünü karşılaştıracaksınız. Dünya küçüldükçe bizim hayatımız neler kazandı, neler kaybetti?","visual":{"type":"map","params":{"region":"dunya","pins":[{"label":"Kakao – Batı Afrika","x":48,"y":56},{"label":"Muz – Orta Amerika","x":24,"y":52},{"label":"Telefon parçaları – Doğu Asya","x":80,"y":42},{"label":"Pamuk – Orta Asya","x":66,"y":36},{"label":"Çay – Doğu Karadeniz","x":58,"y":35}]},"caption":"Kendi ürünlerinin geldiği yerlere iğne ekle ve iğneleri sofrana çizgilerle bağla."},"steps":[{"title":"Ürün Dedektifliği","mode":"İkili · 15 dk","items":["Evden getirdiğiniz en az 6 ürün etiketinde \"menşe\" ya da \"üretim yeri\" bilgisini bulun.","Ürünleri bir tabloya yazın: ürün, üretildiği yer, yaklaşık uzaklık.","Yerli ve yurt dışından gelen ürünleri sayın."],"warn":"Sık yapılan hata: Markanın adı yabancı diye ürünün yurt dışında üretildiğini düşünmek. Her zaman etiketteki üretim yerine bak."},{"title":"Haritaya Dök","mode":"İkili · 20 dk","items":["Ürünlerin geldiği yerleri dijital haritada işaretleyin.","En uzak ve en yakın ürünü belirleyip aradaki farkı hesaplayın.","Haritaya bakarak ürünlerin size hangi yollarla (deniz, kara, hava) ulaşmış olabileceğini tahmin edin."]},{"title":"Dün ve Bugün","mode":"Bireysel · 20 dk","items":["Ailenizden bir büyüğe çocukluğundaki kahvaltıyı ve oyuncaklarını sorun (en az 3 soru).","Cevapları bugünkü sofrayla karşılaştırarak iki sütunlu bir tablo yapın.","Küreselleşmenin değiştirdiği en az 2 alanı (beslenme, iletişim, giyim, meslekler vb.) örnekle açıklayın."],"warn":"Sık yapılan hata: Küreselleşmeyi yalnızca olumlu ya da yalnızca olumsuz anlatmak. Yerel üreticiye, çevreye ve kültüre etkisini de tartış."},{"title":"Bültene Sayfa Hazırla","mode":"İkili · 25 dk","items":["Haritanızı, karşılaştırma tablonuzu ve bir yorum paragrafını tek sayfalık bir sunuma dönüştürün.","Yorumunuzda \"kazandıklarımız\" ve \"kaybettiklerimiz\" başlıklarına en az ikişer örnek yazın.","Sayfanın sonuna okura yönelik bir soru ekleyin."]}],"checklist":["En az 6 ürünün üretim yerini etiketten buldum","Ürünleri dijital haritada işaretledim","Bir aile büyüğüyle görüşüp cevaplarını not ettim","Dün ve bugünü karşılaştıran bir tablo yaptım","Küreselleşmenin olumlu ve olumsuz etkilerini örnekledim","Bülten sayfamı NavigAItor Stüdyo'ya yükledim"],"rubric":[{"k":"Veri toplama","d":"Etiketlerden ve görüşmeden doğru bilgi edinme","l4":"Çok sayıda ürünü doğru kaydeder, görüşmeyi derinleştirir","l3":"Gerekli bilgileri doğru toplar","l2":"Bilgiler eksik ya da kısmen hatalıdır","l1":"Veri toplamaz"},{"k":"Harita kullanımı","d":"Mekânsal ilişkiyi haritada gösterme","l4":"Harita doğru, okunaklıdır ve taşıma yollarını yorumlar","l3":"Harita doğru ve okunaklıdır","l2":"Bazı konumlar hatalıdır","l1":"Harita yoktur"},{"k":"Değişimi yorumlama","d":"Küreselleşmenin insan ve toplum hayatına etkisini açıklama","l4":"Çok yönlü, olumlu ve olumsuz etkileri kanıtla yorumlar","l3":"En az iki alanda değişimi açıklar","l2":"Değişimi tek yönlü anlatır","l1":"Değişimi açıklayamaz"},{"k":"İletişim ve iş birliği","d":"Ortak ürünün kalitesi ve görev paylaşımı","l4":"Görevler dengeli, sayfa özgün ve dikkat çekicidir","l3":"İş birliği yeterli, sayfa anlaşılırdır","l2":"Görevler dengesiz dağılmıştır","l1":"İş birliği gözlenmez"}],"navi":["Sofrandaki ürünlerden biri bir gün gelmeseydi bunu ilk kim fark ederdi ve neden?","Uzaktan gelen ucuz bir ürün, yakındaki üretici için ne anlama geliyor olabilir?"],"diff":{"destek":"Öğrenci 4 ürünle çalışır ve hazır bir karşılaştırma tablosu şablonunu doldurur.","ileri":"Öğrenci bir ürünün tarladan sofraya yolculuğunu adım adım çizer ve bu yolculuğun çevresel etkisini tartışır."},"misconception":"Küreselleşmenin yalnızca yabancı ürün tüketmek olduğu sanılır; oysa iletişimi, meslekleri, kültürü ve yerel üretimi de dönüştüren çok yönlü bir süreçtir."},{"id":"sos-7-13","course":"SOS","grade":7,"themeNo":3,"themeName":"Ortak Mirasımız","kazanim":["Değişen dünya dengeleri karşısında Osmanlı Devleti’nin uyguladığı yenilikleri neden ve sonuçlarıyla yorumlayabilme"],"title":"Değişen Dünyada Bir Saray Danışmanı","subtitle":"Osmanlı yenilikleri ve Avrupa — eş zamanlı zaman şeridi","skills21":["Tarihsel sorgulama","Analitik düşünme","Sistematik olma","Empati"],"digital":["Dijital Zaman Şeridi","Dijital Tarih Araştırması","Dijital Etik"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Bilgisayar veya tablet","Ücretsiz bir zaman şeridi aracı","Güvenilir tarih kaynakları (MEB dijital içerikleri)","Kâğıt-kalem"],"scenario":"Yıl 1800'lerin başı. Sen, Avrupa'daki gelişmeleri yakından izleyen genç bir saray danışmanısın. Avrupa'da fabrikalar çoğalıyor, ordular yeni yöntemlerle eğitiliyor, yeni fikirler sınır tanımıyor. Padişah senden, devletin hangi alanda neden yenilik yapması gerektiğini ve bunun ne gibi sonuçlar doğurabileceğini anlatan bir rapor istiyor. Değişen dünya dengeleri karşısında Osmanlı Devleti yenilik yapmasaydı ne olurdu?","visual":{"type":"timeline","params":{"events":[{"y":"1727","t":"İstanbul'da ilk Türk matbaası kuruldu"},{"y":"1760'lar","t":"Avrupa'da Sanayi İnkılabı başladı"},{"y":"1789","t":"Fransız İhtilali gerçekleşti"},{"y":"1793","t":"Nizam-ı Cedid ordusu kuruldu"},{"y":"1826","t":"Yeniçeri Ocağı kaldırıldı"},{"y":"1839","t":"Tanzimat Fermanı ilan edildi"},{"y":"1856","t":"Islahat Fermanı ilan edildi"},{"y":"1876","t":"Kanun-i Esasi ilan edildi, I. Meşrutiyet başladı"}],"shuffle":true},"caption":"Karışık verilen Osmanlı ve Avrupa olaylarını doğru sıraya diz, ardından birbirini etkileyen olayları oklarla eşleştir."},"steps":[{"title":"Olayları Sıraya Diz","mode":"Bireysel · 15 dk","items":["Görseldeki olayları kronolojik sıraya koy.","Avrupa'da yaşanan olayları bir renkle, Osmanlı'daki yenilikleri başka bir renkle işaretle.","Bir Avrupa olayının ardından gelen Osmanlı yeniliklerini oklarla bağla."],"warn":"Sık yapılan hata: Olayların yalnızca tarihlerini ezberlemek. Asıl soru, iki olay arasında bir etki bağı olup olmadığıdır."},{"title":"Neden – Sonuç Zinciri","mode":"Bireysel · 20 dk","items":["Askerî, eğitim ve yönetim alanlarından birer yenilik seç.","Her biri için \"Neden yapıldı? Ne değişti? Kimler etkilendi?\" sorularını kaynaklardan araştırarak yanıtla.","Kullandığın her kaynağın adını ve adresini not et."],"warn":"Sık yapılan hata: Kaynaktaki cümleleri olduğu gibi kopyalamak. Bilgiyi kendi cümlelerinle yaz, kaynağını belirt."},{"title":"Saray Danışmanı Raporu","mode":"Bireysel · 25 dk","items":["Padişaha hitap eden 150–200 kelimelik bir rapor yaz.","Raporda en az bir yeniliği önerirken o dönemin şartlarını gerekçe olarak kullan.","Bu yeniliğe kimlerin karşı çıkabileceğini ve nedenini de belirt."]},{"title":"Danışmanlar Meclisi","mode":"Grup · 20 dk","items":["Raporlarınızı grupta okuyun ve önerileri karşılaştırın.","Grup olarak \"en acil yenilik\" konusunda karar verin ve gerekçesini tek cümleyle yazın.","Ortak dijital zaman şeridinize kararınızı ekleyin."]}],"checklist":["Olayları doğru sıraya dizdim","Avrupa ve Osmanlı olayları arasında en az iki etki bağı kurdum","Üç alandan yenilik seçip neden ve sonuçlarını yazdım","Kaynaklarımı belirttim, kopyalamadım","Raporumda yeniliğe karşı çıkabilecekleri de düşündüm","Grubun zaman şeridine katkı verdim"],"rubric":[{"k":"Kronoloji ve eş zamanlılık","d":"Olayları sıralama ve dönemler arası ilişki kurma","l4":"Sıralama doğru, Avrupa–Osmanlı bağlarını kanıtla gösterir","l3":"Sıralama doğru, en az bir bağ kurar","l2":"Sıralamada birkaç hata vardır","l1":"Olayları sıralayamaz"},{"k":"Neden – sonuç ilişkisi","d":"Yeniliklerin gerekçe ve etkilerini açıklama","l4":"Çok yönlü nedenleri ve kısa/uzun vadeli sonuçları açıklar","l3":"Temel neden ve sonuçları açıklar","l2":"Yalnızca neden ya da yalnızca sonuç yazar","l1":"Neden–sonuç ilişkisi kurmaz"},{"k":"Tarihsel empati","d":"Dönemin koşulları ve farklı kesimlerin bakışı","l4":"Dönemin şartlarını ve karşı görüşleri dengeli yansıtır","l3":"Dönemin şartlarını dikkate alır","l2":"Bugünün bakışıyla yargılar","l1":"Dönem bağlamı yoktur"},{"k":"Kaynak kullanımı","d":"Güvenilir kaynak ve özgün anlatım","l4":"Birden çok güvenilir kaynak kullanır, tamamen özgün yazar","l3":"Kaynak belirtir, büyük ölçüde özgündür","l2":"Kaynak eksik ya da kopya parçalar vardır","l1":"Kaynak belirtmez, kopyalar"}],"navi":["Bir devlet, komşusunun ordusunun güçlendiğini öğrenince ilk olarak neyi değiştirmek ister sence?","Yeniçeri Ocağı'nın kaldırılmasını herkes aynı şekilde karşılamış olabilir mi? Kim kaybettiğini düşünmüş olabilir?"],"diff":{"destek":"Öğrenci yalnızca 5 olayla çalışır ve neden–sonuç tablosunu tek bir yenilik için doldurur.","ileri":"Öğrenci, aynı yeniliği destekleyen ve ona karşı çıkan iki kişinin gözünden kısa birer mektup yazar."},"misconception":"Osmanlı yeniliklerinin Avrupa'yı taklit etmek için yapıldığı sanılır; oysa çoğu, değişen güç dengeleri karşısında devleti korumaya yönelik bilinçli çözüm arayışlarıdır."},{"id":"sos-7-14","course":"SOS","grade":7,"themeNo":4,"themeName":"Yaşayan Demokrasimiz","kazanim":["Türkiye Cumhuriyeti Devleti’nin yönetim yapısını çözümleyebilme"],"title":"Üç Kuvvet, Bir Devlet","subtitle":"Yasama, yürütme ve yargı — rol kartlarıyla yönetim yapısı","skills21":["Etkin vatandaşlık","Hukuk okuryazarlığı","Sorumlu karar verme","Yaratıcılık"],"digital":["Dijital Anayasa ve Mevzuat","Dijital Oyun ve Simülasyon"],"duration":"80 dk (2 ders)","format":"Grup","tools":["Anayasa'nın resmî dijital metni","Rol kartları (kâğıt)","Ücretsiz bir sunum aracı","NavigAItor Stüdyo"],"scenario":"Sınıfınız, okul meclisinin hazırladığı \"Okul Bahçesinde Telefonsuz Teneffüs\" kuralının uygulanması sırasında bir anlaşmazlık yaşadı. Öğretmeniniz bu olayı küçük bir devlet simülasyonuna dönüştürmeye karar verdi. Bir grup kuralı yapacak, bir grup uygulayacak, bir grup da anlaşmazlıkta karar verecek. Bu deneyimi Türkiye Cumhuriyeti Devleti'nin yönetim yapısıyla karşılaştıracaksınız. Tek bir kişi ya da kurum hem kural koyup hem uygulayıp hem de yargılasaydı ne olurdu?","visual":{"type":"sort","params":{"bins":["Yasama","Yürütme","Yargı"],"items":[{"t":"Kanun yapmak, değiştirmek ve kaldırmak","b":0},{"t":"Bütçe kanununu kabul etmek","b":0},{"t":"Savaş hâli ilanına karar vermek","b":0},{"t":"Bakanları atamak","b":1},{"t":"Kanunları uygulamak ve ülkeyi yönetmek","b":1},{"t":"Mahkemelerde anlaşmazlıkları karara bağlamak","b":2},{"t":"Kanunların Anayasa'ya uygunluğunu denetlemek","b":2}]},"caption":"Görev kartlarını yasama, yürütme ve yargı kutularına sürükle; kararsız kaldığın kartı not et."},"steps":[{"title":"Görevleri Ayır","mode":"Bireysel · 10 dk","items":["Görseldeki görev kartlarını üç kutuya yerleştir.","Her kutunun hangi kurum ya da kişiler tarafından kullanıldığını Anayasa'nın resmî dijital metninden bulup yaz.","Kararsız kaldığın kartı ve nedenini deftere not et."],"warn":"Sık yapılan hata: Yargının kanun yaptığını düşünmek. Mahkemeler kanun yapmaz; var olan kanunlara göre karar verir."},{"title":"Okul Devleti Simülasyonu","mode":"Grup · 30 dk","items":["Sınıf üç gruba ayrılır: Okul Meclisi (kural yapar), Okul Yönetimi (uygular), Okul Hakem Kurulu (anlaşmazlıkta karar verir).","Meclis, telefonsuz teneffüs kuralını madde madde yazar; Yönetim uygulama planı hazırlar.","Öğretmenin verdiği bir anlaşmazlık kartını Hakem Kurulu, yazılı kurala dayanarak karara bağlar."],"warn":"Sık yapılan hata: Hakem Kurulu'nun kuralı beğenmediği için değiştirmesi. Her grup yalnızca kendi yetkisini kullanır."},{"title":"Karşılaştır ve Çözümle","mode":"Grup · 20 dk","items":["Simülasyondaki üç grubu Türkiye'deki yasama, yürütme ve yargı ile eşleştiren bir tablo hazırlayın.","Bir grubun diğerinin işini yapmaya çalıştığı bir anı hatırlayın ve sonucunu tartışın.","Kuvvetler ayrılığının vatandaşın haklarını nasıl koruduğunu iki cümleyle yazın."]},{"title":"Rehber Kart Hazırla","mode":"Grup · 20 dk","items":["Bir alt sınıftaki öğrenciye yönetim yapısını anlatan 3 slaytlık bir rehber hazırlayın.","Her slayta bir organ, görevi ve günlük hayattan bir örnek koyun.","Rehberi NavigAItor Stüdyo'ya yükleyin."]}],"checklist":["Görev kartlarını üç kuvvete doğru yerleştirdim","Her kuvveti kullanan kurumu resmî kaynaktan buldum","Simülasyonda yalnızca grubumun yetkisini kullandım","Simülasyon ile gerçek yapıyı tabloda karşılaştırdım","Kuvvetler ayrılığının önemini kendi cümlelerimle yazdım","Rehber slaytlarını yükledim"],"rubric":[{"k":"Kavram doğruluğu","d":"Yasama, yürütme ve yargının görevlerini ayırt etme","l4":"Tüm görevleri doğru ayırır ve ilgili kurumları belirtir","l3":"Görevlerin çoğunu doğru ayırır","l2":"Birkaç görevi karıştırır","l1":"Kuvvetleri ayırt edemez"},{"k":"Yönetim yapısını çözümleme","d":"Organlar arası ilişkiyi ve dengeyi açıklama","l4":"Organların birbirini nasıl dengelediğini örnekle açıklar","l3":"Organların ayrı görevlerini açıklar","l2":"Açıklamalar yüzeyseldir","l1":"İlişki kurmaz"},{"k":"Simülasyona katılım","d":"Rolün gereklerine uygun ve sorumlu davranma","l4":"Rolünü yetki sınırları içinde, gerekçeli kararlarla yürütür","l3":"Rolünü büyük ölçüde doğru yürütür","l2":"Rolünün sınırlarını zaman zaman aşar","l1":"Simülasyona katılmaz"},{"k":"Rehber ürün","d":"Bilgiyi yaşa uygun ve yaratıcı aktarma","l4":"Rehber doğru, yaratıcı ve günlük hayattan örnekli","l3":"Rehber doğru ve anlaşılır","l2":"Rehberde eksik ya da hatalı bilgi var","l1":"Rehber hazırlanmamış"}],"navi":["Bir oyunda kuralları koyan kişi aynı zamanda hakemlik de yapsaydı, kaybeden takım ne hissederdi?","Kararsız kaldığın kartta, o görevi yapan kişinin seçilmiş mi yoksa atanmış mı olduğunu düşünmek sana yardımcı olur mu?"],"diff":{"destek":"Öğrenci yalnızca 3 kartla başlar; her kuvvetin bir örnek görevini resimli kartlarla eşleştirir.","ileri":"Öğrenci, bir kanunun teklif edilmesinden yürürlüğe girmesine kadar geçen süreci akış şeması olarak çizer."},"misconception":"Devletin tüm kararlarını tek bir makamın verdiği sanılır; oysa yasama, yürütme ve yargı yetkileri farklı organlara verilerek birbirini dengeler."},{"id":"sos-7-15","course":"SOS","grade":7,"themeNo":5,"themeName":"Hayatımızdaki Ekonomi","kazanim":["Ekonomik gelişmişlik ile üretim, dağıtım ve tüketim döngüsü arasındaki ilişkiyi çözümleyebilme"],"title":"Domatesin Değer Yolculuğu","subtitle":"Üretim–dağıtım–tüketim döngüsü ve ekonomik gelişmişlik","skills21":["Ekonomik okuryazarlık","Sistematik düşünme","Sorumluluk","Değişim ve süreklilik"],"digital":["Dijital Veri ve Grafik Okuryazarlığı","Dijital Karşılaştırma"],"duration":"80 dk (2 ders)","format":"İkili","tools":["Elektronik tablo uygulaması","Market ürün etiketleri","Hesap makinesi","Kâğıt-kalem"],"scenario":"Köyünüzdeki domates üreticileri bir karar vermek zorunda: Domatesleri hasattan hemen sonra ham hâlde mi satsınlar, yoksa ortak bir tesis kurup salça ve kurutulmuş domates olarak mı? Kooperatif başkanı sizden, iki seçeneği üretim, dağıtım ve tüketim adımlarıyla karşılaştıran bir rapor istiyor. Raporunuzda bu kararın köyün ve ülkenin ekonomik gelişmişliğiyle ilişkisini de açıklayacaksınız. Bir ürün işlendikçe kimin geliri artar ve bu döngü bir ülkeyi nasıl güçlendirir?","visual":{"type":"flow","params":{"kind":"dongu","steps":["Ham madde (domates tarlası)","Üretim (salça tesisi)","Dağıtım (depo, kamyon, market rafı)","Tüketim (evdeki mutfak)","Gelir ve talep (yeni yatırım, yeni iş)"]},"caption":"Döngünün her halkasına tıklayıp orada çalışan meslekleri ve oluşan geliri yaz."},"steps":[{"title":"Döngüyü Tamamla","mode":"İkili · 15 dk","items":["Görseldeki döngünün her halkasında çalışan en az iki meslek yazın.","Döngünün herhangi bir halkası kopsaydı ne olacağını bir örnekle açıklayın.","Ham domates satışı ile salça üretiminde döngünün hangi halkalarının uzadığını işaretleyin."],"warn":"Sık yapılan hata: Dağıtımı yalnızca taşımacılık sanmak. Depolama, paketleme, pazarlama ve satış da dağıtımın parçasıdır."},{"title":"Değer Hesabı","mode":"İkili · 25 dk","items":["Öğretmenin verdiği örnek fiyatlarla 100 kg domatesin ham satış gelirini ve salçaya dönüştürüldüğünde oluşan geliri tabloya yazın.","Salça üretiminin ek giderlerini (kavanoz, enerji, işçilik) çıkarın.","Elektronik tabloda iki seçeneği gösteren bir sütun grafiği çizin."],"warn":"Sık yapılan hata: Yalnızca satış fiyatına bakıp giderleri unutmak. Asıl karşılaştırma, giderler düşüldükten sonra kalan kazançtır."},{"title":"Gelişmişlikle İlişkilendir","mode":"Bireysel · 20 dk","items":["Ham madde satan ve işlenmiş ürün satan iki hayalî ülkeyi karşılaştıran kısa bir paragraf yazın.","İşlenmiş ürünün istihdama, teknolojiye ve ihracata etkisini en az birer cümleyle açıklayın.","Bilinçli tüketicinin bu döngüdeki sorumluluğuna bir örnek verin."]},{"title":"Kooperatife Rapor","mode":"İkili · 20 dk","items":["Grafiğinizi ve gerekçelerinizi içeren bir sayfalık rapor hazırlayın.","Raporun sonunda net bir öneri yapın ve bir riskini belirtin.","Raporu NavigAItor Stüdyo'ya yükleyin."]}],"checklist":["Döngünün her halkasına meslek ve gelir örneği yazdım","Ham ve işlenmiş satışın kazancını giderleri düşerek hesapladım","Elektronik tabloda karşılaştırma grafiği çizdim","İşlenmiş ürünün ülke ekonomisine etkisini açıkladım","Bilinçli tüketiciye bir örnek verdim","Önerimi ve bir riskini raporda yazdım"],"rubric":[{"k":"Döngüyü çözümleme","d":"Üretim, dağıtım ve tüketim arasındaki bağları açıklama","l4":"Halkalar arası bağları ve kopmanın etkilerini örnekle açıklar","l3":"Halkaları doğru tanımlar ve bağlar","l2":"Halkaları tanımlar ama ilişki kurmaz","l1":"Döngüyü tanımlayamaz"},{"k":"Veri ve grafik","d":"Hesaplama ve grafikle karşılaştırma","l4":"Hesaplar doğru, grafik açık ve yorumlu","l3":"Hesaplar ve grafik doğru","l2":"Hesaplarda ya da grafikte hata var","l1":"Hesap ve grafik yok"},{"k":"Gelişmişlik bağlantısı","d":"Döngü ile ekonomik gelişmişlik arasındaki ilişkiyi kurma","l4":"İstihdam, teknoloji ve ihracat boyutlarıyla çok yönlü ilişki kurar","l3":"En az iki boyutta ilişki kurar","l2":"İlişkiyi tek boyutla açıklar","l1":"İlişki kurmaz"},{"k":"Karar ve gerekçe","d":"Kanıta dayalı öneri ve risk değerlendirmesi","l4":"Öneri net, verilerle desteklenmiş ve riski gerçekçi","l3":"Öneri gerekçeli","l2":"Öneri gerekçesiz ya da belirsiz","l1":"Öneri yok"}],"navi":["Bir kavanoz salçanın fiyatına kaç kişinin emeği giriyor olabilir? Hepsini sayabilir misin?","Bir ülke hep ham madde satarsa, işlenmiş ürünü kimden ve hangi fiyata alır?"],"diff":{"destek":"Öğrenci hesaplamaları hazır tabloda yalnızca toplama–çıkarma ile tamamlar; grafiği şablondan seçer.","ileri":"Öğrenci aynı karşılaştırmayı yaşadığı bölgenin başka bir ürünü (fındık, pamuk, süt vb.) için kurar ve sonuçları karşılaştırır."},"misconception":"Bir ülkenin zenginliğinin yalnızca sahip olduğu doğal kaynağa bağlı olduğu sanılır; oysa kaynağı işleyip değer katan üretim, dağıtım ve bilinçli tüketim döngüsü belirleyicidir."},{"id":"sos-7-16","course":"SOS","grade":7,"themeNo":6,"themeName":"Teknoloji Ve Sosyal Bilimler","kazanim":["Toplumsal hayatta karşılaşabileceği bir probleme yönelik bilimsel sorgulama yapabilme"],"title":"Okul Kapısındaki Sabah Düğümü","subtitle":"Toplumsal bir probleme bilimsel sorgulama — anket ve veri analizi","skills21":["Bilimsel sorgulama","Problem çözme","Sistematik olma","Yaratıcılık"],"digital":["Dijital Problem Çözme","Dijital Poster ve Raporlama"],"duration":"120 dk (3 ders)","format":"Grup","tools":["Ücretsiz bir çevrim içi anket aracı","Elektronik tablo uygulaması","Ücretsiz bir poster tasarım aracı","Kâğıt-kalem"],"scenario":"Her sabah 08.10 ile 08.25 arasında okul kapısının önü araçlar, servisler ve yayalarla dolup taşıyor; geçen hafta bir öğrenci az kalsın bir araca çarpıyordu. Okul aile birliği bu soruna bilimsel bir çözüm arayan bir öğrenci araştırma ekibi kurdu ve siz o ekiptesiniz. Sorunu tanımlayacak, veri toplayacak, bir çözüm önerecek ve önerinizi sınayacaksınız. Bu sabah düğümünü çözmek için önce neyi bilmemiz gerekiyor?","visual":{"type":"bars","params":{"title":"Örnek sınıf anketi: Okula nasıl geliyorsun?","labels":["Yürüyerek","Okul servisi","Özel araç","Toplu taşıma","Bisiklet"],"values":[38,22,31,7,2],"unit":"öğrenci","editable":true},"caption":"Örnek değerleri kendi anketinden elde ettiğin sonuçlarla değiştir ve sorunun asıl kaynağını grafikte bul."},"steps":[{"title":"Problemi Tanımla","mode":"Grup · 20 dk","items":["Sorunu tek ve ölçülebilir bir soru cümlesiyle yazın (örneğin \"Sabah kapı önündeki yoğunluğun en büyük nedeni nedir?\").","En az iki tahmin (hipotez) yazın.","Hangi verilerin bu tahminleri sınayacağını listeleyin."],"warn":"Sık yapılan hata: Problemi çözümle birlikte tanımlamak (\"Sorun, ikinci kapının açılmamasıdır\"). Önce sorunu tarafsız tanımla, çözüm veriyle gelsin."},{"title":"Veri Topla","mode":"Grup · 30 dk","items":["Okula geliş biçimi, geliş saati ve kapıya yakınlık sorularından oluşan en fazla 5 soruluk bir çevrim içi anket hazırlayın.","Öğretmen gözetiminde, okul önünde 15 dakika boyunca araç ve yaya sayımı yapın.","Ankette ad, soyad ve ev adresi gibi kişisel bilgiler istemeyin."],"warn":"Sık yapılan hata: Yalnızca kendi sınıfınıza anket yapıp okulun tamamı hakkında kesin sonuç çıkarmak. Örneklemin kimleri kapsadığını raporda belirt."},{"title":"Analiz Et","mode":"Grup · 25 dk","items":["Anket sonuçlarını elektronik tabloya aktarın ve grafiğe dönüştürün.","Sayım verilerinde en yoğun 5 dakikalık dilimi bulun.","Verilerinizin hangi tahmini desteklediğini, hangisini desteklemediğini yazın."]},{"title":"Çözüm Öner ve Sına","mode":"Grup · 25 dk","items":["Verilere dayanan en az iki çözüm önerin (örneğin kademeli giriş saati, yürüyen okul otobüsü grubu, bırakma noktası).","Her çözümün kimleri etkileyeceğini ve olası yan etkisini tartışın.","Bir çözümü bir hafta boyunca küçük bir grupla deneyecek bir plan yazın."]},{"title":"Bilimsel Poster","mode":"Grup · 20 dk","items":["Problem, tahmin, yöntem, bulgular, sonuç ve öneri bölümlerinden oluşan bir dijital poster hazırlayın.","Posteri okul aile birliğine sunun.","Posteri NavigAItor Stüdyo'ya yükleyin."]}],"checklist":["Problemi ölçülebilir bir soru olarak yazdım","En az iki tahmin oluşturdum","Kişisel bilgi istemeyen bir anket hazırladım","Verileri tabloya ve grafiğe aktardım","Önerilerimi verilere dayandırdım ve yan etkilerini düşündüm","Bilimsel posterimizi sunup yükledim"],"rubric":[{"k":"Problem ve hipotez","d":"Problemi tanımlama ve sınanabilir tahmin kurma","l4":"Problem net ve ölçülebilir; hipotezler sınanabilir ve birbirinden farklı","l3":"Problem ve hipotezler anlaşılır","l2":"Problem belirsiz ya da hipotez sınanamaz","l1":"Problem tanımlanmamış"},{"k":"Veri toplama ve etik","d":"Uygun yöntemle ve mahremiyete saygıyla veri toplama","l4":"Birden çok yöntem kullanır, örneklemi ve sınırlılıkları belirtir","l3":"Uygun yöntemle veri toplar","l2":"Veriler eksik ya da tek kaynaklı","l1":"Veri toplamaz"},{"k":"Analiz ve sonuç","d":"Verileri yorumlayıp hipotezle ilişkilendirme","l4":"Grafikleri doğru yorumlar, desteklenmeyen hipotezi de açıkça belirtir","l3":"Verileri doğru yorumlar","l2":"Yorum verilerle tam uyuşmaz","l1":"Analiz yapmaz"},{"k":"Çözüm ve sunum","d":"Veriye dayalı öneri ve bilimsel poster","l4":"Öneriler yaratıcı, sınanabilir; poster tüm bölümleri içerir","l3":"Öneriler veriye dayalı; poster anlaşılır","l2":"Öneriler veriden kopuk","l1":"Öneri ve poster yok"}],"navi":["Tahminin doğru çıkmasaydı bu senin için bir başarısızlık mı olurdu, yoksa yeni bir bilgi mi?","Sadece sabah 08.15'te yapılan bir sayım, tüm haftayı temsil eder mi? Nasıl emin olabilirsin?"],"diff":{"destek":"Öğrenci hazır 4 soruluk anket şablonunu kullanır ve grafiği öğretmenin hazırladığı tabloya veri girerek oluşturur.","ileri":"Öğrenci aynı problemi okul çevresindeki başka bir kurumla (örneğin yakındaki bir okul) karşılaştırmak için ikinci bir veri seti planlar."},"misconception":"Bilimsel sorgulamanın yalnızca laboratuvarda yapıldığı sanılır; oysa toplumsal sorunlar da problem, hipotez, veri ve sonuç adımlarıyla sistemli biçimde araştırılabilir."},{"id":"sos-8-17","course":"SOS","grade":8,"themeNo":1,"themeName":"Mustafa Kemal'in Hayatı","kazanim":["Mustafa Kemal’in doğduğu dönemde Osmanlı Devleti’nin içinde bulunduğu siyasi, sosyal ve ekonomik durumu neden ve sonuçlarıyla yorumlayabilme"],"title":"1881'de Selanik'ten Bir Mektup","subtitle":"Mustafa Kemal'in doğduğu dönemde Osmanlı Devleti — siyasi, sosyal, ekonomik durum","skills21":["Tarihsel empati","Eleştirel düşünme","Analitik düşünme","İletişim"],"beceri21Kaynak":"çıkarım","digital":["Dijital Tarih Araştırması","Veri Doğrulama"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Güvenilir dijital tarih kaynakları (MEB dijital içerikleri)","Dijital harita uygulaması","Kâğıt-kalem","NavigAItor Stüdyo"],"scenario":"Yıl 1881. Selanik limanında çalışan bir gümrük memurunun çocuğusun ve İstanbul'daki kuzenine bir mektup yazıyorsun. Limana her gün farklı dillerden konuşan tüccarlar geliyor, şehirde yeni okullar açılıyor, büyükler ise devletin borçlarından ve kaybedilen topraklardan endişeyle söz ediyor. Mektubunda kuzenine şehrinde ve devlette olup biteni anlatacaksın. Bir çocuğun gözünden bakıldığında, 1881'de Osmanlı Devleti nasıl bir dönemden geçiyordu ve bunun nedenleri nelerdi?","visual":{"type":"organizer","params":{"kind":"tablo","slots":["Siyasi durum","Sosyal durum","Ekonomik durum","Nedeni ne?","Sonucu ne oldu?"]},"caption":"Her alana araştırmandan bir bilgi yaz ve bilgiyi neden–sonuç sütunlarıyla bağla."},"steps":[{"title":"Dönemi Haritada Gör","mode":"Bireysel · 15 dk","items":["Dijital haritada Selanik'in yerini bul ve neden önemli bir liman şehri olduğunu iki gerekçeyle yaz.","1878'deki savaş ve antlaşmalardan sonra Osmanlı'nın Balkanlarda kaybettiği toprakları kaynaklardan araştır.","Selanik'in bu değişimden nasıl etkilenmiş olabileceğini tahmin et."]},{"title":"Üç Alanı Araştır","mode":"Bireysel · 25 dk","items":["Siyasi, sosyal ve ekonomik alanların her biri için en az iki bilgi bul (örneğin milliyetçilik akımları, Duyun-ı Umumiye, yeni okullar, demiryolu).","Her bilgiyi tablodaki ilgili kutuya yaz ve nedenini, sonucunu ekle.","Her bilgiyi en az iki güvenilir kaynakta doğrula."],"warn":"Sık yapılan hata: Bir bilgiyi tek bir internet sayfasından alıp doğru kabul etmek. Tarihî bilgiyi en az iki güvenilir kaynakla karşılaştır."},{"title":"Mektubu Yaz","mode":"Bireysel · 25 dk","items":["Kuzenine 150–200 kelimelik bir mektup yaz; üç alandan en az birer gelişmeyi anlat.","Mektupta bir çocuğun gördüğü ve duyduğu somut ayrıntılar (liman, pazar, okul, sohbetler) kullan.","Mektubun sonunda geleceğe dair bir umut ya da endişeni yaz."],"warn":"Sık yapılan hata: Mektuba 1881'de henüz yaşanmamış olayları eklemek. Yazdığın her gelişmenin tarihini kontrol et."},{"title":"Mektup Okuma Saati","mode":"Grup · 15 dk","items":["Mektuplarınızı grupta okuyun ve hangi alanın en çok anlatıldığını belirleyin.","\"Bu ortamda büyüyen bir çocuk hangi soruları sormaya başlar?\" sorusunu birlikte tartışın.","Tartışmanın özetini tek paragraf olarak yükleyin."]}],"checklist":["Selanik'in konumunu ve önemini açıkladım","Siyasi, sosyal ve ekonomik alandan en az ikişer bilgi buldum","Her bilgiyi iki kaynakta doğruladım","Bilgileri neden ve sonuçlarıyla tabloya yazdım","Mektubumda yalnızca 1881 öncesi ve o yıla ait gelişmeleri kullandım","Grup tartışmasının özetini yükledim"],"rubric":[{"k":"Dönem bilgisi","d":"Siyasi, sosyal ve ekonomik durumu doğru belirleme","l4":"Üç alanda da doğru, ayrıntılı ve tarihli bilgi verir","l3":"Üç alanda doğru bilgi verir","l2":"Bir alan eksik ya da hatalıdır","l1":"Dönem bilgisi yetersizdir"},{"k":"Neden – sonuç yorumu","d":"Gelişmelerin nedenlerini ve sonuçlarını ilişkilendirme","l4":"Alanlar arası etkileşimi de gösteren zincirler kurar","l3":"Her gelişmeye neden ve sonuç yazar","l2":"Neden ya da sonuç eksiktir","l1":"İlişki kurmaz"},{"k":"Tarihsel empati","d":"Dönemin insanının gözünden anlatma","l4":"Mektup döneme uygun, inandırıcı ve somut ayrıntılarla zengindir","l3":"Mektup döneme uygundur","l2":"Mektupta bugünün bakış açısı baskındır","l1":"Dönem yansıtılmaz"},{"k":"Kaynak doğrulama","d":"Bilgiyi güvenilir kaynaklarla teyit etme","l4":"Tüm bilgileri birden çok güvenilir kaynakla doğrular","l3":"Bilgilerin çoğunu doğrular","l2":"Az sayıda bilgiyi doğrular","l1":"Doğrulama yapmaz"}],"navi":["Bir devletin borcunu ödeyemediği bir dönemde, limandaki gümrük memurunun işi nasıl değişmiş olabilir?","Farklı dillerin konuşulduğu bir şehirde yeni fikirler nasıl yayılır? Bu fikirler devleti nasıl etkileyebilir?"],"diff":{"destek":"Öğrenci her alan için verilen iki bilgi kartından birini seçer ve mektubu cümle başlangıçları verilmiş bir şablonla yazar.","ileri":"Öğrenci aynı dönemi Selanik'teki farklı bir topluluğa mensup bir çocuğun gözünden ikinci bir mektupla anlatır ve iki mektubu karşılaştırır."},"misconception":"Mustafa Kemal'in yetiştiği dönemin sakin ve sorunsuz olduğu ya da yalnızca askerî sorunlar içerdiği sanılır; oysa dönem siyasi, sosyal ve ekonomik açıdan iç içe geçmiş derin sorunlarla doluydu."},{"id":"sos-8-18","course":"SOS","grade":8,"themeNo":2,"themeName":"Birinci Dünya Savaşı","kazanim":["Birinci Dünya Savaşı’nın sonuçlarını tablo, grafik, şekil ve diyagram üzerinden yorumlayabilme"],"title":"Rakamların Anlattığı Savaş","subtitle":"Birinci Dünya Savaşı'nın sonuçları — grafik ve diyagram okuma","skills21":["Veri okuryazarlığı","Eleştirel düşünme","Analitik düşünme","Küresel farkındalık"],"beceri21Kaynak":"çıkarım","digital":["Dijital Veri ve Grafik Okuryazarlığı","Veri Doğrulama"],"duration":"80 dk (2 ders)","format":"İkili","tools":["Elektronik tablo uygulaması","Güvenilir dijital tarih kaynakları","Ücretsiz bir infografik aracı","Kâğıt-kalem"],"scenario":"Bir tarih dergisi, Birinci Dünya Savaşı'nın bitişinin yıl dönümü için öğrencilerden \"Savaş Bittiğinde Dünya\" başlıklı bir infografik istiyor. Elinizde savaşta hayatını kaybeden askerlere ait yaklaşık sayılar, savaş sonunda dağılan imparatorlukların listesi ve imzalanan antlaşmalar var. Bu verileri doğru okuyup savaşın siyasi, ekonomik ve toplumsal sonuçlarını görsel olarak anlatacaksınız. Bir grafik, savaşın sonuçlarını anlatmaya yeter mi, neyi gösterir ve neyi gizler?","visual":{"type":"bars","params":{"title":"Birinci Dünya Savaşı'nda hayatını kaybeden askerler (yaklaşık tahmin)","labels":["Almanya","Rusya","Fransa","Avusturya-Macaristan","İngiltere","Osmanlı Devleti"],"values":[2.0,1.8,1.4,1.1,0.9,0.8],"unit":"milyon kişi","editable":false},"caption":"Grafikteki çubukları karşılaştır ve bu sayıların neden \"yaklaşık\" olarak verildiğini düşün."},"steps":[{"title":"Grafiği Oku","mode":"İkili · 15 dk","items":["En büyük ve en küçük kaybı yaşayan devletleri belirleyin ve aradaki farkı hesaplayın.","Grafikteki devletleri İtilaf ve İttifak devletleri olarak iki gruba ayırıp her grubun toplam kaybını bulun.","Grafiğin başlığındaki \"yaklaşık tahmin\" ifadesinin neden önemli olduğunu yazın."],"warn":"Sık yapılan hata: Kaybı en fazla olan devletin savaşı kaybettiğini düşünmek. Kayıp sayısı ile savaşın sonucu aynı şey değildir; galip devletlerin kayıpları da çok büyüktür."},{"title":"Sonuçları Diyagrama Dök","mode":"İkili · 25 dk","items":["Savaş sonunda yıkılan dört imparatorluğu ve yerlerinde ortaya çıkan yeni devletlerden örnekleri bir diyagramda gösterin.","Yenilen devletlerle imzalanan antlaşmaları bir tabloya yazın.","Milletler Cemiyeti'nin kuruluş amacını bir cümleyle diyagrama ekleyin."],"warn":"Sık yapılan hata: Savaşın sonuçlarını yalnızca sınır değişikliği olarak görmek. Ekonomik yıkım, göç, salgın ve yeni bir savaşa zemin hazırlayan gerginlikler de sonuçtur."},{"title":"Sayıların Arkasındaki İnsan","mode":"Bireysel · 15 dk","items":["Kaynaklardan savaşın sivil halka etkisine dair iki örnek bulun (kıtlık, göç, yetim kalan çocuklar vb.).","Bu etkileri grafiğin neden gösteremediğini açıklayın.","Savaşın Osmanlı toplumuna etkisine dair bir cümlelik çıkarım yazın."]},{"title":"İnfografiği Hazırla","mode":"İkili · 25 dk","items":["Grafik, diyagram ve antlaşma tablosundan oluşan bir infografik tasarlayın.","Siyasi, ekonomik ve toplumsal sonuçları ayrı renklerle gösterin.","İnfografiğin altına kullandığınız kaynakları yazın ve NavigAItor Stüdyo'ya yükleyin."]}],"checklist":["Grafikteki verileri karşılaştırıp hesap yaptım","Sayıların tahmin olduğunu ve kaynağa göre değiştiğini belirttim","Yıkılan imparatorlukları ve yeni devletleri diyagramda gösterdim","Antlaşmaları doğru devletlerle eşleştirdim","Siyasi, ekonomik ve toplumsal sonuçları ayrı ayrı gösterdim","Kaynaklarımı infografiğe ekledim"],"rubric":[{"k":"Grafik okuma","d":"Verileri doğru okuma ve karşılaştırma","l4":"Verileri doğru okur, gruplar arası karşılaştırma yapar ve sınırlılıklarını belirtir","l3":"Verileri doğru okur ve karşılaştırır","l2":"Okumada hatalar vardır","l1":"Grafiği yorumlayamaz"},{"k":"Sonuçları yorumlama","d":"Siyasi, ekonomik ve toplumsal sonuçları açıklama","l4":"Üç boyutu da örneklerle ve birbirine bağlayarak açıklar","l3":"Üç boyutu da açıklar","l2":"Yalnızca siyasi sonuçlara odaklanır","l1":"Sonuçları açıklayamaz"},{"k":"Diyagram ve tablo","d":"Bilgiyi görsel olarak düzenleme","l4":"Diyagram doğru, düzenli ve öz","l3":"Diyagram doğru","l2":"Diyagramda eksik ya da hatalar var","l1":"Diyagram yok"},{"k":"Eleştirel bakış","d":"Verinin sınırlarını ve insani boyutu fark etme","l4":"Tahmin farklılıklarını ve grafiğin gizlediklerini kanıtla tartışır","l3":"Verinin sınırlılığını belirtir","l2":"Verileri kesin bilgi olarak kabul eder","l1":"Eleştirel değerlendirme yok"}],"navi":["Aynı savaş için iki farklı kaynak farklı sayılar veriyorsa, bu sana kaynaklar hakkında ne söyler?","Haritadan dört imparatorluk silindiğinde, o topraklarda yaşayan insanların günlük hayatında ilk ne değişmiş olabilir?"],"diff":{"destek":"Öğrenci yalnızca üç devletin verisini karşılaştırır ve diyagramı boşlukları doldurulacak bir şablonla tamamlar.","ileri":"Öğrenci aynı verileri farklı bir kaynaktan bularak iki grafiği yan yana koyar ve farkların olası nedenlerini yazar."},"misconception":"Savaşın sonuçlarının yalnızca kazananlar ve kaybedenler listesinden ibaret olduğu sanılır; oysa savaş, galip ve mağlup tüm toplumlarda derin ekonomik ve toplumsal yaralar açmıştır."},{"id":"sos-8-19","course":"SOS","grade":8,"themeNo":3,"themeName":"Millî Mücadele","kazanim":["Mondros Mütarekesi’ne karşı Osmanlı yönetiminin, Mustafa Kemal’in, aydınların ve halkın tutumunu karşılaştırabilme"],"title":"Mütareke Ertesi: Dört Ses, Bir Ülke","subtitle":"Mondros Mütarekesi'ne farklı tutumlar — karşılaştırmalı analiz","skills21":["Eleştirel düşünme","Tarihsel empati","Karşılaştırma","Sorumlu karar verme"],"beceri21Kaynak":"çıkarım","digital":["Dijital Tarih Araştırması","Dijital Hikâye Anlatıcılığı"],"duration":"80 dk (2 ders)","format":"Grup","tools":["Güvenilir dijital tarih kaynakları","Ücretsiz bir sunum aracı","Kâğıt-kalem","NavigAItor Stüdyo"],"scenario":"Kasım 1918. Mondros Mütarekesi'nin haberi kahvehanelerde, gazete sayfalarında ve köy meydanlarında konuşuluyor. Herkes aynı habere farklı tepki veriyor: Kimi barışın geldiğine seviniyor, kimi büyük bir devletin korumasına girmeyi öneriyor, kimi silahını bırakmamaya karar veriyor. Siz bir okul radyosu ekibi olarak bu farklı tepkileri bir arada anlatan kısa bir program hazırlayacaksınız. Aynı mütarekeye neden bu kadar farklı tepkiler verildi ve hangisi geleceği belirledi?","visual":{"type":"chat","params":{"lines":[{"who":"İstanbul'da bir memur","t":"Savaş bitti, artık sessiz kalmalı ve galip devletleri kızdırmamalıyız."},{"who":"Gazeteci bir aydın","t":"Tek başımıza ayakta kalamayız; güçlü bir devletin himayesini istemeliyiz."},{"who":"Ege'de bir çiftçi","t":"Köyümüze yabancı askerler geliyor. Kimse bizi korumazsa kendimiz korumalıyız!"},{"who":"Bir öğretmen","t":"Bu mütarekenin bazı maddeleri, istedikleri her yeri işgal edebilecekleri anlamına geliyor."}]},"caption":"Her konuşma balonunun hangi kesimin tutumunu yansıttığını belirle ve eksik kalan sesi kaynaklardan bulup ekle."},"steps":[{"title":"Mütareke Maddelerini İncele","mode":"Grup · 15 dk","items":["Kaynaklardan Mondros Mütarekesi'nin işgallere zemin hazırlayan maddelerini bulun.","Bu maddelerin neden tehlikeli olduğunu kendi cümlelerinizle yazın.","Mütarekenin imzalandığı günlerde Mustafa Kemal'in görevini ve bulunduğu yeri araştırın."],"warn":"Sık yapılan hata: Mütarekeyi bir barış antlaşması sanmak. Mütareke ateşkestir; kalıcı barış şartları henüz belirlenmemişti."},{"title":"Dört Tutumu Karşılaştır","mode":"Grup · 25 dk","items":["Osmanlı yönetimi, Mustafa Kemal, aydınlar ve halkın tutumlarını dört sütunlu bir tabloya yazın.","Her tutumun gerekçesini ve bu tutumu destekleyen bir kanıtı ekleyin.","Aydınların farklı görüşlerini (manda, himaye, tam bağımsızlık) ayrı ayrı belirtin."],"warn":"Sık yapılan hata: Tüm aydınların veya tüm halkın aynı düşündüğünü varsaymak. Her kesimin içinde farklı görüşler vardı."},{"title":"Radyo Programını Yaz","mode":"Grup · 25 dk","items":["Dört kesimin temsilcisini konuşturan 3 dakikalık bir radyo metni yazın; konuşmaları kaynaklardaki bilgilere dayandırın.","Gerçek tarihî kişilerin ağzından uydurma sözler yazmayın; onların tutumunu anlatıcının sesiyle aktarın.","Programın sonuna dinleyiciye yönelik bir soru ekleyin."]},{"title":"Yayın ve Değerlendirme","mode":"Grup · 15 dk","items":["Programı sınıfa okuyun ya da ses kaydı olarak yükleyin.","Dinleyen gruplar, hangi tutumun Millî Mücadele'ye yol açtığını gerekçesiyle yazsın.","Gelen geri bildirimle metninizi düzeltin."]}],"checklist":["Mütarekenin işgallere zemin hazırlayan maddelerini buldum","Dört kesimin tutumunu gerekçe ve kanıtıyla tabloya yazdım","Aydınlar arasındaki farklı görüşleri belirttim","Tarihî kişilere uydurma söz yazmadım","Radyo programımızı kaynaklara dayandırdım","Programı yükleyip geri bildirime göre düzelttim"],"rubric":[{"k":"Karşılaştırma","d":"Dört kesimin tutumunu benzerlik ve farklılıklarıyla ortaya koyma","l4":"Dört tutumu gerekçe ve kanıtlarla ayrıntılı karşılaştırır","l3":"Dört tutumu doğru belirler","l2":"Bir ya da iki tutumu eksik belirler","l1":"Tutumları ayırt edemez"},{"k":"Tarihsel bağlam","d":"Mütarekenin içeriğini ve dönemin koşullarını açıklama","l4":"Maddeleri ve sonuçlarını dönemin şartlarıyla ilişkilendirir","l3":"Temel maddeleri ve etkisini açıklar","l2":"Bağlam yüzeyseldir","l1":"Bağlam yoktur"},{"k":"Kaynak kullanımı ve etik","d":"Bilgiyi doğru kaynaklara dayandırma","l4":"Tüm bilgiler güvenilir kaynaklara dayalı, uydurma alıntı yok","l3":"Bilgilerin çoğu kaynaklara dayalı","l2":"Kaynaksız iddialar var","l1":"Kaynak kullanılmamış"},{"k":"Radyo programı","d":"Tarihî bilgiyi dinleyiciye etkili aktarma","l4":"Program özgün, akıcı ve düşündürücü","l3":"Program anlaşılır","l2":"Program dağınık","l1":"Program hazırlanmamış"}],"navi":["Aynı haberi İstanbul'daki bir memur ile işgal edilen bir köydeki çiftçi neden farklı yorumlamış olabilir?","Bir ülkenin geleceğini başka bir devletin korumasına bırakmanın bedeli ne olabilirdi?"],"diff":{"destek":"Öğrenci karşılaştırma tablosunu her kesim için verilen ipucu kartlarıyla doldurur ve radyo metninde yalnızca bir sesi yazar.","ileri":"Öğrenci, dört tutumun kısa vadede ve uzun vadede ülkeye olası etkilerini karşılaştıran bir senaryo tablosu hazırlar."},"misconception":"Mondros Mütarekesi'ne karşı herkesin aynı tepkiyi verdiği sanılır; oysa yönetim, aydınlar, halk ve Mustafa Kemal farklı ve kimi zaman birbirine zıt tutumlar sergilemiştir."},{"id":"sos-8-20","course":"SOS","grade":8,"themeNo":4,"themeName":"Türkiye Cumhuriyeti’nin Kuruluşu Ve İnkılaplar","kazanim":["Atatürk ilke ve inkılapları arasındaki ilişkiyi ortaya koyan özgün bir ürün oluşturabilme"],"title":"İlkeler Haritası","subtitle":"Atatürk ilke ve inkılapları arasındaki ilişki — kavram ağı","skills21":["Analitik düşünme","Sistematik düşünme","Yaratıcılık","Etkin vatandaşlık"],"beceri21Kaynak":"çıkarım","digital":["Dijital İçerik Üretimi","Dijital Zaman Şeridi"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Ücretsiz bir kavram haritası aracı","Güvenilir dijital tarih kaynakları","Renkli kartlar","NavigAItor Stüdyo"],"scenario":"Okulunuzda kurulacak \"Cumhuriyet Köşesi\" için bir duvar panosu hazırlanacak ve tasarım görevi sınıfınıza verildi. Panoda Atatürk ilkeleri ile Cumhuriyet döneminde yapılan inkılapların birbirine nasıl bağlandığı tek bakışta görülmeli. Ancak bir inkılabı yalnızca tek bir ilkeye bağlamak çoğu zaman yetmiyor. İlkeler ve inkılaplar birbirine nasıl bağlanır, panoda bu ağı nasıl gösterirsiniz?","visual":{"type":"sort","params":{"bins":["Cumhuriyetçilik","Milliyetçilik","Halkçılık","Laiklik","Devletçilik"],"items":[{"t":"Saltanatın kaldırılması","b":0},{"t":"Cumhuriyet'in ilanı","b":0},{"t":"Türk Tarih Kurumu'nun kurulması","b":1},{"t":"Türk Dil Kurumu'nun kurulması","b":1},{"t":"Aşar vergisinin kaldırılması","b":2},{"t":"Soyadı Kanunu","b":2},{"t":"Halifeliğin kaldırılması","b":3},{"t":"Birinci Beş Yıllık Sanayi Planı","b":4}]},"caption":"Her inkılabı en güçlü ilişkili olduğu ilkeye sürükle; birden fazla ilkeye uyan kartları ayrıca işaretle."},"steps":[{"title":"İlk Eşleştirme","mode":"Bireysel · 15 dk","items":["Görseldeki inkılapları en güçlü ilişkili oldukları ilkeye yerleştir.","Birden fazla ilkeye uyduğunu düşündüğün kartları listele ve gerekçesini yaz.","İnkılapçılık ilkesinin neden ayrı bir kutuda yer almadığını tahmin et."],"warn":"Sık yapılan hata: Her inkılabın yalnızca tek bir ilkeyle ilişkili olduğunu düşünmek. Örneğin bir inkılap hem Halkçılık hem Laiklik ile bağlantılı olabilir."},{"title":"İlkeleri Tanımla","mode":"Bireysel · 15 dk","items":["Her ilkeyi kendi cümlelerinle bir cümlede tanımla.","Her ilkenin hangi soruna çözüm getirdiğini kaynaklardan araştırarak yaz.","İlkelerin demokrasinin ilkeleriyle (eşitlik, egemenliğin millete ait olması vb.) ilişkisini bir örnekle göster."]},{"title":"Kavram Ağı Kur","mode":"Grup · 30 dk","items":["Dijital kavram haritası aracında ilkeleri merkeze, inkılapları çevreye yerleştirin.","Her bağlantı çizgisinin üzerine ilişkiyi açıklayan kısa bir ifade yazın.","İnkılapçılık ilkesini ağın tamamını çevreleyen bir çerçeve olarak gösterin ve nedenini açıklayın."],"warn":"Sık yapılan hata: Bağlantı çizgilerini açıklamasız bırakmak. Çizgi tek başına ilişkiyi göstermez; \"neden bağlı?\" sorusunun cevabı çizginin üzerinde olmalı."},{"title":"Pano Sunumu","mode":"Grup · 20 dk","items":["Kavram ağınızı Cumhuriyet Köşesi panosu için düzenleyin.","Panoya, bugünün hayatında bu ilkelerden birinin izini gösteren bir örnek ekleyin.","Panoyu sınıfa sunun ve NavigAItor Stüdyo'ya yükleyin."]}],"checklist":["İnkılapları ilkelerle eşleştirdim","Birden fazla ilkeye bağlanan inkılapları gerekçesiyle belirttim","Her ilkeyi kendi cümlelerimle tanımladım","Kavram ağındaki her bağlantıya açıklama yazdım","İnkılapçılığın ağın tamamıyla ilişkisini gösterdim","Bugünden bir örnek ekleyip panoyu yükledim"],"rubric":[{"k":"İlke bilgisi","d":"İlkelerin anlamını ve amacını doğru açıklama","l4":"Tüm ilkeleri doğru, özgün cümlelerle ve amaçlarıyla açıklar","l3":"İlkeleri doğru tanımlar","l2":"Bazı ilkeleri karıştırır","l1":"İlkeleri tanımlayamaz"},{"k":"İlişki kurma","d":"İnkılaplarla ilkeler arasındaki bağı gerekçelendirme","l4":"Çoklu ilişkileri gerekçeleriyle gösterir","l3":"Temel ilişkileri doğru kurar","l2":"İlişkiler gerekçesizdir","l1":"İlişki kurmaz"},{"k":"Özgün ürün","d":"Kavram ağının düzeni ve yaratıcılığı","l4":"Ağ özgün, okunaklı ve bütüncül; İnkılapçılık yaratıcı biçimde gösterilmiş","l3":"Ağ düzenli ve okunaklı","l2":"Ağ dağınık ya da eksik","l1":"Ürün oluşturulmamış"},{"k":"Günümüzle bağlantı","d":"İlkelerin bugünkü yansımalarını örnekleme","l4":"Somut, güncel ve iyi gerekçelendirilmiş örnek verir","l3":"Uygun bir örnek verir","l2":"Örnek belirsizdir","l1":"Örnek yoktur"}],"navi":["Bir inkılabı yaparken devletin amacı kimin hayatını değiştirmekti? Bu soru hangi ilkeyi düşündürüyor?","Bir inkılap yapıldıktan sonra korunmasaydı ne olurdu? Bu, ağdaki hangi ilkeyle ilgili?"],"diff":{"destek":"Öğrenci 5 inkılap ve 3 ilkeyle çalışır; bağlantı ifadelerini hazır kelime bankasından seçer.","ileri":"Öğrenci kavram ağına inkılapların yıllarını ekleyerek ağı bir zaman şeridiyle birleştirir ve ilkelerin hangi sırayla öne çıktığını yorumlar."},"misconception":"Atatürk ilkelerinin birbirinden bağımsız kurallar olduğu ve her inkılabın yalnızca bir ilkeye ait olduğu sanılır; oysa ilkeler birbirini tamamlayan bir bütündür."},{"id":"ing-5-01","course":"ING","grade":5,"themeNo":1,"themeName":"School Life","title":"Okul Rehberi Sensin!","subtitle":"School Life — Yeni öğrenciye okul turu (konuşma)","kazanim":["Tema kapsamı: school life with school rules; people, roles and responsibilities at school; school routines; national days and celebrations","Speaking (Konuşma) — okulunu, okuldaki kişileri ve okul kurallarını basit cümlelerle tanıtma"],"skills21":["İletişim","İş Birliği","Sorumluluk","Merak"],"digital":["Dijital Okuryazarlık","Dijital İçerik Üretimi"],"duration":"80 dk (2 ders)","format":"İkili","tools":["Kâğıt-kalem","Tablet veya telefonun ses kayıt uygulaması","NavigAItor Stüdyo"],"scenario":"Okulunuza yurt dışından yeni bir öğrenci geldi ve Türkçe henüz bilmiyor. Okul müdürü seni 'okul elçisi' seçti: ona okulu İngilizce gezdireceksin. Kimin ne iş yaptığını, hangi kurallara uyulduğunu ve günlük okul rutinini anlatman gerekiyor. Yeni arkadaşının okulda kendini yalnız hissetmemesi için ona ilk 5 dakikada neleri söylemelisin?","visual":{"type":"chat","params":{"lines":[{"who":"Leo","t":"Hi! I'm Leo. Is this the library?"},{"who":"Defne","t":"Yes, it is. Mrs. Kaya is our librarian. She helps us find books."},{"who":"Leo","t":"Can I eat here?"},{"who":"Defne","t":"No, you can't. You must be quiet in the library."},{"who":"Leo","t":"What time does the first lesson start?"},{"who":"Defne","t":"It starts at 8:30. Don't be late!"}]},"caption":"Öğrenci diyaloğu sesli okur, ardından boş bırakılan Defne balonlarına kendi okuluna uygun cevapları yazar."},"steps":[{"title":"Okulunu Haritala","mode":"Bireysel · 15 dk","items":["Okulundaki 5 yeri (library, canteen, gym, teachers' room, garden) bir kâğıda kaba bir plan olarak çiz.","Her yerin yanına orada çalışan kişiyi yaz: teacher, librarian, school nurse, cleaner, principal.","Her kişi için bir görev cümlesi yaz: 'The school nurse helps sick students.'"]},{"title":"Kurallar ve Rutin","mode":"Bireysel · 15 dk","items":["Her yer için bir kural yaz: 'You must…' / 'You mustn't…' / 'Don't…'.","Okul gününü 4 cümleyle anlat: 'School starts at…', 'We have lunch at…', 'Lessons finish at…'.","Bir ulusal günü ekle: 'On 29th October, we celebrate Republic Day.'"],"warn":"Sık yapılan hata: 'You must not' yerine 'You don't must' demek. Yasak bildiren kalıbı kendi cümlenle kontrol et: hangi kelime 'must'ın arkasına gelir?"},{"title":"Tur Provası","mode":"İkili · 25 dk","items":["Biri 'okul elçisi', diğeri 'yeni öğrenci' olsun. Yeni öğrenci her yerde en az bir soru sorsun: 'Who is she?', 'Can I…?', 'What time…?'.","Rolleri değiştirin ve turu tekrar yapın.","Arkadaşının söylediği bir doğru cümleyi ve bir düzeltilecek cümleyi not et."],"warn":"Sık yapılan hata: Kâğıttan okumak. Konuşurken sadece anahtar kelimelere bak, cümleyi kendin kur."},{"title":"Sesli Okul Turu Kaydı","mode":"İkili · 25 dk","items":["Turunuzu 1–2 dakikalık bir ses kaydına dönüştürün ve NavigAItor Stüdyo'ya yükleyin.","Kayıtta en az 3 kişi, 3 kural ve 2 saat ifadesi geçsin.","Kaydı dinleyip kendinize bir yıldız (iyi olan) ve bir dilek (geliştirilecek olan) yazın."]}],"checklist":["Okulumdaki en az 5 yeri ve orada çalışan kişileri İngilizce adlandırdım.","En az 3 kural cümlesini must / mustn't ile kurdum.","Okul rutinimi saat ifadeleriyle anlattım.","Arkadaşımla rolleri değiştirerek turu iki kez prova ettim.","Ses kaydımı yükledim ve kendime bir yıldız, bir dilek yazdım."],"rubric":[{"k":"Söz varlığı","d":"Okul yerleri, kişiler ve görevlerle ilgili kelime kullanımı","l4":"Tüm yer ve kişileri doğru ve çeşitli kelimelerle adlandırır","l3":"Çoğu yer ve kişiyi doğru adlandırır","l2":"Birkaç temel kelimeyi kullanır, bazılarında Türkçeye başvurur","l1":"Kelimeleri büyük ölçüde Türkçe söyler"},{"k":"Kural ve rutin cümleleri","d":"must / mustn't ve saat ifadelerini doğru kullanma","l4":"Kural ve saat cümlelerini hatasız ve akıcı kurar","l3":"Küçük hatalarla anlaşılır cümleler kurar","l2":"Kalıpları yalnızca örneğe bakarak kullanabilir","l1":"Kalıpları kullanamaz"},{"k":"Etkileşim","d":"Soru sorma ve soruya yanıt verme","l4":"Doğal sorular sorar, her soruya uygun yanıt verir","l3":"Çoğu soruya uygun yanıt verir","l2":"Yanıtları kısa ve tek kelimeliktir","l1":"Etkileşime katılmakta zorlanır"},{"k":"Sesli ürün","d":"Kaydın anlaşılırlığı ve kapsamı","l4":"Kayıt net, istenen tüm öğeleri içerir","l3":"Kayıt anlaşılır, öğelerin çoğu var","l2":"Kayıt kısa, bazı öğeler eksik","l1":"Kayıt tamamlanmamış"}],"navi":["Yeni gelen biri okulda en çok neyi merak eder sence? Bunu hangi soru kelimesiyle sorardın?","Kütüphanede yapılmaması gereken bir şeyi söylemek istesen cümleye nasıl başlardın?","Kaydını dinlediğinde seni en çok hangi cümlen gururlandırdı, neden?"],"diff":{"destek":"Yer ve kişi kelimeleri resimli bir listeyle verilir; öğrenci 'This is the… / He is the…' kalıbını tamamlar.","ileri":"Turun sonuna okulunun en sevdiği kuralını ve nedenini anlatan 3 cümlelik bir kapanış ekler (because ile)."},"misconception":"Öğrenciler 'must not' ile 'don't have to' ifadelerini aynı anlamda sanır; birinin yasak, diğerinin zorunluluk olmadığını ayırt edemez."},{"id":"ing-5-02","course":"ING","grade":5,"themeNo":3,"themeName":"Personal Life","title":"Gizemli Sınıf Arkadaşı","subtitle":"Personal Life — Görünüş ve kişilik kelimeleriyle tahmin oyunu","kazanim":["Tema kapsamı: personal life with body parts and physical appearance and (features); clothing and dressing; personality traits","Vocabulary (Söz Varlığı) — dış görünüş, kıyafet ve kişilik özelliklerini anlatan kelimeleri kullanma"],"skills21":["Yaratıcılık","İletişim","Analitik Düşünme","Özgüven"],"digital":["Dijital Sanat","Dijital Okuryazarlık"],"duration":"40 dk","format":"Bireysel + Grup","tools":["Kelime kartları","Kâğıt ve boya kalemleri","Ücretsiz bir dijital çizim aracı"],"scenario":"Sınıfınıza bir 'gizemli karakter' gelecek, ama kimse onu görmedi. Sadece İngilizce bir tarif var. Sen bir karakter tasarımcısısın: kendi gizemli karakterini çizecek ve onu yalnızca kelimelerle anlatacaksın. Arkadaşların senin tarifinden doğru karakteri bulabilecek mi?","visual":{"type":"cards","params":{"items":[{"w":"curly hair","tr":"kıvırcık saç","ic":"👩‍🦱"},{"w":"glasses","tr":"gözlük","ic":"👓"},{"w":"scarf","tr":"atkı","ic":"🧣"},{"w":"boots","tr":"bot","ic":"🥾"},{"w":"cap","tr":"şapka (kep)","ic":"🧢"},{"w":"jacket","tr":"ceket","ic":"🧥"},{"w":"friendly","tr":"arkadaş canlısı","ic":"😊"},{"w":"shy","tr":"utangaç","ic":"🙈"}]},"caption":"Öğrenci kartları çevirerek anlamları kontrol eder ve karakterine uyan kartları seçer."},"steps":[{"title":"Kartlarla Isın","mode":"Bireysel · 8 dk","items":["Kartları önce İngilizce yüzünden oku, anlamı tahmin et, sonra çevir.","Kelimeleri üç gruba ayır: Body / Clothes / Personality.","Her gruba kendi bildiğin bir kelime daha ekle."],"warn":"Sık yapılan hata: Kişilik kelimelerini (friendly, shy) kıyafet gibi 'wear' ile kullanmak. 'She wears friendly' neden olmaz, düşün."},{"title":"Karakterini Tasarla","mode":"Bireysel · 12 dk","items":["Kâğıtta ya da dijital çizim aracında bir karakter çiz.","Ona en az 2 görünüş, 2 kıyafet ve 1 kişilik özelliği ver.","5 cümlelik bir tarif yaz: 'He has got…', 'She is wearing…', 'He is…'."],"warn":"Sık yapılan hata: Sıfat sırasını karıştırmak ('hair curly'). İngilizcede sıfat ismin neresinde durur?"},{"title":"Kim Bu?","mode":"Grup · 15 dk","items":["Grupta çizimleri ters çevirip karıştırın, sonra hepsini masaya açın.","Sırayla tarifini oku; diğerleri doğru çizimi bulsun.","Bulunamayan karakterin tarifine hangi kelime eklenirse daha kolay bulunurdu, birlikte karar verin."]},{"title":"Kelime Defterine Ekle","mode":"Bireysel · 5 dk","items":["Bugün öğrendiğin 5 kelimeyi resimli kelime defterine yaz.","Her birini kendinle ilgili bir cümlede kullan."]}],"checklist":["Kartlardaki kelimeleri üç gruba ayırdım.","Karakterimi çizdim ve ona görünüş, kıyafet, kişilik özelliği verdim.","has got / is wearing / is kalıplarıyla 5 cümle yazdım.","Tarifimi grupta yüksek sesle okudum.","5 yeni kelimeyi kendimle ilgili cümlelerde kullandım."],"rubric":[{"k":"Kelime bilgisi","d":"Görünüş, kıyafet ve kişilik kelimelerini doğru kullanma","l4":"Tüm kelimeleri doğru ve yerinde kullanır, yeni kelimeler ekler","l3":"Kelimelerin çoğunu doğru kullanır","l2":"Kelimeleri karıştırır","l1":"Kelimeleri tanımakta zorlanır"},{"k":"Sınıflandırma","d":"Kelimeleri anlam grubuna ayırma","l4":"Tüm kelimeleri doğru gruplar ve gerekçelendirir","l3":"Çoğunu doğru gruplar","l2":"Birkaç kelimeyi yanlış gruba koyar","l1":"Gruplamayı yapamaz"},{"k":"Tarif cümleleri","d":"has got / is wearing / is yapılarıyla tarif","l4":"Cümleler açık, doğru ve ayırt edici","l3":"Cümleler anlaşılır, küçük hatalar var","l2":"Cümleler eksik ya da kalıplar karışık","l1":"Tarif yazılamamış"},{"k":"Grup katılımı","d":"Tarifi paylaşma ve geri bildirim","l4":"Tarifini akıcı okur, yapıcı öneri verir","l3":"Tarifini okur, öneriye katılır","l2":"İsteksiz katılır","l1":"Katılmaz"}],"navi":["Karakterini kalabalık bir sınıfta en hızlı ne ayırt ettirir: saçı mı, kıyafeti mi, kişiliği mi?","Bir kıyafeti anlatırken 'has got' mı yoksa 'is wearing' mi daha doğal geliyor? Neden?"],"diff":{"destek":"Öğrenci yalnızca 4 kartla çalışır ve 'He/She has got… / is wearing…' boşluklu cümleleri tamamlar.","ileri":"Karakterine kişilik özelliğini kanıtlayan bir davranış cümlesi ekler: 'She is friendly. She always helps new students.'"},"misconception":"Öğrenciler görünüşü anlatan 'has got' ile kişiliği anlatan 'is' yapısını karıştırır ('He has got friendly')."},{"id":"ing-5-03","course":"ING","grade":5,"themeNo":5,"themeName":"Life In The Neighbourhood & City","title":"Mahalle Radyosu","subtitle":"Life in the Neighbourhood & City — Dinleyerek yer ve hizmetleri sınıflandırma","kazanim":["Tema kapsamı: life in the neighbourhood and city with attractions and recreational places, services, and transportation in the neighbourhood and the city","Listening (Dinleme) — mahalle ve şehirdeki yerler, hizmetler ve ulaşımla ilgili kısa bir anlatımdan ayrıntı çıkarma"],"skills21":["Analitik Düşünme","Problem Çözme","Planlama","Sorumluluk"],"digital":["Dijital Harita ve Navigasyon","Dijital İçerik Üretimi"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor sesli metin oynatıcısı","Dijital harita uygulaması","Kâğıt-kalem"],"scenario":"Mahallenin çocuk radyosunda 'Welcome to Green Street' adlı bir program yayımlanıyor. Sunucu mahalledeki eğlence yerlerini, hizmetleri ve ulaşım seçeneklerini anlatıyor. Sen mahalle rehberi hazırlayan ekibin dinleme sorumlususun ve hiçbir bilgiyi kaçırmamalısın. Yeni taşınan bir aile bu rehberle her şeyi bulabilir mi?","visual":{"type":"sort","params":{"bins":["Recreation","Services","Transportation"],"items":[{"t":"park","b":0},{"t":"cinema","b":0},{"t":"playground","b":0},{"t":"hospital","b":1},{"t":"post office","b":1},{"t":"pharmacy","b":1},{"t":"bus stop","b":2},{"t":"metro station","b":2},{"t":"bike lane","b":2}]},"caption":"Öğrenci radyo programında duyduğu yerleri doğru kutuya sürükler."},"steps":[{"title":"Dinlemeden Önce Tahmin Et","mode":"Bireysel · 10 dk","items":["Program adını oku: 'Welcome to Green Street'. Sence sunucu hangi yerlerden bahsedecek? 5 kelime tahmin et.","Yön kalıplarını hatırla: next to, opposite, between, near, turn left, go straight."]},{"title":"Birinci Dinleme: Genel Fikir","mode":"Bireysel · 10 dk","items":["NavigAItor'daki sesli metni bir kez durdurmadan dinle.","Duyduğun yerleri sıralama kartlarında doğru kutuya sürükle.","Tahminlerinden kaç tanesi doğru çıktı? Say ve not et."],"warn":"Sık yapılan hata: İlk dinlemede her kelimeyi anlamaya çalışmak. Şimdilik sadece yer adlarına odaklan."},{"title":"İkinci Dinleme: Ayrıntı","mode":"Bireysel · 15 dk","items":["Metni gerektiğinde durdurarak tekrar dinle.","Bir tablo yap: Place | Where is it? | When is it open? | How can you go there?","En az 5 yer için tabloyu doldur."],"warn":"Sık yapılan hata: 'opposite' (karşısında) ile 'next to' (yanında) ifadelerini karıştırmak. Kafa karışıklığında o bölümü bir kez daha dinle."},{"title":"Mahalle Rehberi","mode":"Grup · 45 dk","items":["Grupça dinlediğiniz bilgilere dayanarak basit bir mahalle planı çizin veya dijital harita uygulamasında kendi mahallenizden benzer yerleri işaretleyin.","Rehberinize her kategoriden en az 2 yer ve bir 'How to get there' cümlesi ekleyin.","Rehberi 4 sayfalık dijital mini kitap olarak NavigAItor Stüdyo'da paylaşın."]}],"checklist":["Dinlemeden önce tahminlerimi yazdım.","Birinci dinlemede duyduğum yerleri doğru kategoriye yerleştirdim.","İkinci dinlemede en az 5 yerin konumunu ve ulaşım bilgisini tabloya yazdım.","Yön ifadelerini (next to, opposite, between) doğru kullandım.","Grubumla dijital mahalle rehberini tamamladık ve paylaştık."],"rubric":[{"k":"Genel anlama","d":"Dinlenen metindeki yerleri tanıma","l4":"Tüm yerleri doğru tanır ve sınıflandırır","l3":"Yerlerin çoğunu doğru sınıflandırır","l2":"Yarısından azını tanır","l1":"Yerleri tanımakta zorlanır"},{"k":"Ayrıntı çıkarma","d":"Konum, saat ve ulaşım bilgisini yakalama","l4":"Tüm ayrıntıları doğru not eder","l3":"Ayrıntıların çoğunu doğru not eder","l2":"Bazı ayrıntıları karıştırır","l1":"Ayrıntı not edemez"},{"k":"Yön ifadeleri","d":"Konum bildiren kalıpların kullanımı","l4":"Tüm kalıpları doğru ve çeşitli kullanır","l3":"Kalıpların çoğunu doğru kullanır","l2":"Bir iki kalıbı ezbere kullanır","l1":"Kalıpları kullanamaz"},{"k":"Rehber ürünü","d":"Grubun dijital mini kitabı","l4":"Rehber eksiksiz, düzenli ve kullanışlı","l3":"Rehber anlaşılır, küçük eksikler var","l2":"Rehberde önemli eksikler var","l1":"Rehber tamamlanmamış"}],"navi":["Sunucu bir yeri tarif ederken hangi kelimeleri vurguluyordu? O kelimeler sana ne ipucu verdi?","Bir yerin 'service' mi 'recreation' mı olduğuna nasıl karar verdin?","Yeni taşınan bir aile rehberinde ilk neyi arar sence?"],"diff":{"destek":"Metin daha yavaş hızda ve altyazılı dinletilir; tablo yalnızca 'Place' ve 'Where' sütunlarıyla doldurulur.","ileri":"Öğrenci kendi mahallesi için 30 saniyelik bir radyo tanıtımı yazar ve kaydeder."},"misconception":"Öğrenciler dinlemede her kelimeyi anlamadan görevi yapamayacaklarını düşünür; anahtar bilgiye odaklanma stratejisini kullanmaz."},{"id":"ing-5-04","course":"ING","grade":5,"themeNo":6,"themeName":"Life In The World","title":"Dünya Lezzet Festivali Davetiyesi","subtitle":"Life in the World — Ülke, milliyet ve mutfak temalı davetiye yazımı","kazanim":["Tema kapsamı: continents, countries, nationalities, and languages; different cuisines from the world; food festivals from different parts of the world","Writing (Yazma) — farklı ülkelerin mutfaklarını ve yemek festivallerini tanıtan kısa bir metin yazma"],"skills21":["Kültürel Farkındalık","Açık Fikirlilik","Karşılaştırma","Araştırma"],"digital":["Dijital Okuryazarlık","Dijital Sunum","Kültür Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Bireysel","tools":["Dijital harita uygulaması","Ücretsiz bir sunum aracı","Kâğıt-kalem"],"scenario":"Okulunuz bahar döneminde 'World Food Day' adlı bir festival düzenleyecek ve her öğrenci bir ülkenin standını hazırlayacak. Sen de bir ülke seçip ziyaretçileri standına çağıran İngilizce bir davetiye yazacaksın. Davetiye ülkeyi, dilini, milliyetini ve en lezzetli yemeğini tanıtmalı. Davetiyeni okuyan biri neden önce senin standına gelmek istesin?","visual":{"type":"map","params":{"region":"dunya","pins":[{"label":"Türkiye","x":57,"y":35},{"label":"Italy","x":51,"y":33},{"label":"Japan","x":86,"y":37},{"label":"Mexico","x":19,"y":45},{"label":"India","x":70,"y":45},{"label":"Brazil","x":32,"y":65}]},"caption":"Öğrenci haritadaki ülkelere dokunur, kıtasını, dilini ve milliyetini not eder ve standı için bir ülke seçer."},"steps":[{"title":"Ülke Kartı","mode":"Bireysel · 15 dk","items":["Haritadan bir ülke seç. Kıtasını, dilini ve milliyetini yaz: 'Mexico is in North America. People speak Spanish. They are Mexican.'","Güvenilir bir dijital kaynaktan o ülkenin 2 geleneksel yemeğini ve içindeki malzemeleri bul.","Bilgiyi hangi kaynaktan aldığını not et."],"warn":"Sık yapılan hata: Ülke adı ile milliyeti karıştırmak ('I am Japan', 'Italian is a country'). Kendi cümlelerinde ikisini ayırt et."},{"title":"Karşılaştır","mode":"Bireysel · 15 dk","items":["Seçtiğin ülkenin bir yemeğini Türk mutfağından bir yemekle karşılaştır.","Benzerlik ve farkları iki sütunda yaz: 'Both have…', '…is spicy, but…is sweet.'","Bu ülkede yapılan bir yemek festivalini kendi cümlelerinle hayal et ve tanımla."]},{"title":"Davetiyeyi Yaz","mode":"Bireysel · 30 dk","items":["Davetiye 60–80 kelime olsun ve şu bölümleri içersin: başlık, ülke ve dil bilgisi, yemek tanıtımı, festival saati ve yeri, davet cümlesi.","En az 3 lezzet sıfatı kullan: delicious, spicy, sweet, salty, crispy.","Taslağını yüksek sesle oku ve büyük harf, nokta, yazım hatalarını düzelt."],"warn":"Sık yapılan hata: Ülke ve dil adlarını küçük harfle yazmak (italy, spanish). İngilizcede bu kelimeler nasıl yazılır?"},{"title":"Dijital Davetiye","mode":"Bireysel · 20 dk","items":["Davetiyeni ücretsiz bir sunum aracında tek sayfalık bir afişe dönüştür.","Telifsiz bir görsel ya da kendi çizimini ekle.","NavigAItor'da paylaş ve iki arkadaşının davetiyesine birer soru yaz."]}],"checklist":["Seçtiğim ülkenin kıtasını, dilini ve milliyetini doğru yazdım.","Yemek bilgisini güvenilir bir kaynaktan aldım ve kaynağı not ettim.","Bir yabancı yemeği Türk mutfağıyla karşılaştırdım.","60–80 kelimelik davetiyemde tüm bölümler var.","Ülke, dil ve milliyetleri büyük harfle yazdım.","Dijital davetiyemi paylaştım ve iki arkadaşıma soru yazdım."],"rubric":[{"k":"İçerik","d":"Ülke, dil, milliyet ve yemek bilgisinin doğruluğu","l4":"Tüm bilgiler doğru, ayrıntılı ve kaynaklı","l3":"Bilgiler doğru, birkaç ayrıntı eksik","l2":"Bazı bilgiler eksik ya da hatalı","l1":"Bilgiler büyük ölçüde hatalı"},{"k":"Metin düzeni","d":"Davetiye bölümlerinin varlığı ve sırası","l4":"Tüm bölümler mantıklı sırada","l3":"Bölümlerin çoğu var","l2":"Bölümler dağınık","l1":"Metin düzensiz"},{"k":"Dil kullanımı","d":"Sıfatlar, karşılaştırma ve yazım kuralları","l4":"Çeşitli sıfatlar, doğru karşılaştırma, hatasız yazım","l3":"Küçük yazım hataları var","l2":"Hatalar anlamı zaman zaman bozar","l1":"Hatalar anlamı engeller"},{"k":"Kültürel saygı","d":"Farklı mutfakları önyargısız tanıtma","l4":"Mutfağı saygılı ve merak uyandırıcı tanıtır","l3":"Saygılı ve doğru tanıtır","l2":"Genellemeler yapar","l1":"Önyargılı ifadeler kullanır"}],"navi":["Davetiyeni okuyan biri ilk üç saniyede neyi görmeli?","Seçtiğin yemeğin hangi özelliği Türk mutfağından bir yemeği hatırlatıyor?","Bilgiyi aldığın kaynağın güvenilir olduğunu nereden anladın?"],"diff":{"destek":"Öğrenciye boşluklu bir davetiye şablonu verilir: 'Come to the ___ stand! People in ___ speak ___. Try ___. It is ___.'","ileri":"Davetiyeye festivalde sorulabilecek 3 soruluk bir mini quiz ekler."},"misconception":"Öğrenciler her ülkenin dilinin ülke adıyla aynı olduğunu düşünür (ör. Brezilya'da 'Brazilian' konuşulduğunu sanır)."},{"id":"ing-5-05","course":"ING","grade":5,"themeNo":8,"themeName":"Life In The Universe","title":"Gezegen Kimlik Kartları","subtitle":"Life in the Universe — Bilgi metni okuma ve karşılaştırma","kazanim":["Tema kapsamı: life in the universe with planets in the solar system; facts about planets; earth as a planet; extreme weather conditions","Reading (Okuma) — gezegenler ve hava koşullarıyla ilgili kısa bilgi metinlerinden belirli bilgileri bulma"],"skills21":["Merak","Sistematik Düşünme","Çıkarım Yapma","Sınıflandırma"],"digital":["Dijital Simülasyon","Dijital Araştırma","Dijital Poster"],"duration":"80 dk (2 ders)","format":"İkili","tools":["NavigAItor okuma metinleri","Güneş sistemi simülasyonu","Kâğıt-kalem","Ücretsiz bir sunum aracı"],"scenario":"Bir uzay ajansı 'Planet Holiday' adlı hayali bir yarışma açtı: kazananlar bir gezegeni 'tatil yeri' olarak tanıtacak. Önünde dört gezegenin İngilizce bilgi metinleri var. Hangi gezegen çok sıcak, hangisi çok rüzgârlı, hangisinin halkaları var? Okuyarak bul ve karar ver: insanlar için en 'az tehlikeli' tatil gezegeni hangisi olurdu?","visual":{"type":"solar","params":{"mode":"gunes-sistemi"},"caption":"Öğrenci animasyonu oynatarak gezegenlerin Güneş'e uzaklık sırasını izler ve okuduğu bilgilerle karşılaştırır."},"steps":[{"title":"Okumadan Önce","mode":"İkili · 10 dk","items":["Simülasyonu oynatın ve gezegenleri Güneş'e yakından uzağa sıralayın.","Şu kelimelerin anlamını tahmin edin: hot, cold, windy, stormy, rocky, rings, moon."]},{"title":"Taramalı Okuma","mode":"Bireysel · 20 dk","items":["Dört kısa bilgi metnini hızlıca tara ve her gezegen için bir kimlik kartı doldur: Name | Size | Temperature | Weather | Moons | Fun fact.","Sayıları ve sıfatları altını çizerek işaretle."],"warn":"Sık yapılan hata: Metni baştan sona kelime kelime okumak. Kimlik kartındaki başlıkları anahtar kelime gibi kullanıp sadece o bilgiyi ara."},{"title":"Karşılaştır ve Çıkarım Yap","mode":"İkili · 20 dk","items":["Kartlarınızı karşılaştırın: 'Venus is hotter than Mars.' 'Jupiter is bigger than Earth.' gibi 4 cümle yazın.","Metinde açıkça yazmayan ama çıkarım yapabileceğiniz bir bilgi bulun: 'People can't live on Venus because…'.","Dünya'daki aşırı hava olaylarından biriyle (storm, heatwave, blizzard) bir gezegeni eşleştirin."],"warn":"Sık yapılan hata: Karşılaştırmalı sıfatı yanlış kurmak ('more big', 'hoter'). Kısa sıfatlarda -er eklerken son harfe dikkat et."},{"title":"Tatil Afişi","mode":"İkili · 30 dk","items":["Seçtiğiniz gezegen için ücretsiz bir sunum aracında bir 'Planet Holiday' afişi hazırlayın.","Afişte 3 gerçek bilgi ve 1 güvenlik uyarısı olsun: 'Take a warm coat! It's −150 °C.'","Afişi paylaşın ve kararınızı iki cümleyle gerekçelendirin."]}],"checklist":["Gezegenleri Güneş'e uzaklık sırasına göre dizdim.","Dört gezegen için kimlik kartı doldurdum.","Karşılaştırmalı sıfatlarla en az 4 doğru cümle yazdım.","Metinden bir çıkarım yaptım ve because ile gerekçelendirdim.","Gezegen afişimde 3 gerçek bilgi ve 1 uyarı var."],"rubric":[{"k":"Bilgi bulma","d":"Metinden istenen bilgileri çıkarma","l4":"Tüm kartları eksiksiz ve doğru doldurur","l3":"Kartların çoğunu doğru doldurur","l2":"Bazı bilgileri karıştırır","l1":"Bilgi bulmakta zorlanır"},{"k":"Karşılaştırma","d":"Karşılaştırmalı sıfatların doğru kullanımı","l4":"Çeşitli ve doğru karşılaştırmalar yapar","l3":"Küçük hatalarla karşılaştırır","l2":"Kalıbı yalnızca örnekle kullanır","l1":"Karşılaştırma yapamaz"},{"k":"Çıkarım","d":"Metinde açık olmayan bilgiye ulaşma","l4":"Mantıklı ve gerekçeli çıkarım yapar","l3":"Mantıklı çıkarım yapar, gerekçe zayıf","l2":"Çıkarım metinle tam uyuşmaz","l1":"Çıkarım yapamaz"},{"k":"Afiş","d":"Bilgi doğruluğu ve sunum","l4":"Afiş doğru, yaratıcı ve dikkat çekici","l3":"Afiş doğru ve anlaşılır","l2":"Afişte eksik ya da hatalı bilgi var","l1":"Afiş tamamlanmamış"}],"navi":["Kimlik kartındaki 'Temperature' satırını doldurmak için metinde hangi işaretleri aradın?","Bir gezegenin 'tehlikeli' olduğunu hangi iki bilgiyi birleştirerek söyleyebilirsin?","Dünya'yı bu dört gezegenden ayıran en önemli özellik sence nedir?"],"diff":{"destek":"Metinler kısaltılır ve bilgiler kalın yazılır; öğrenci iki gezegenle çalışır.","ileri":"Öğrenci ikinci bir kaynaktan bir gezegenle ilgili bir bilgiyi doğrular ve iki kaynağı karşılaştırır."},"misconception":"Öğrenciler Güneş'e en yakın gezegenin her zaman en sıcak gezegen olduğunu düşünür."},{"id":"ing-6-06","course":"ING","grade":6,"themeNo":3,"themeName":"Personal Life & Well-Being","title":"Telefonum Uykumu mu Çalıyor?","subtitle":"Personal Life & Well-Being — Ekran süresi üzerine okuma ve veri yorumlama","kazanim":["Tema kapsamı: personal life and well-being with mobile phones and their impact on health and social life personal preferences for films and visual arts","Reading (Okuma) — cep telefonlarının sağlık ve sosyal hayat üzerindeki etkilerini anlatan bir metni okuyup ana fikri ve destekleyici bilgileri belirleme"],"skills21":["Eleştirel Düşünme","Analitik Düşünme","Sağlık Bilinci","Medya Okuryazarlığı"],"digital":["Dijital Okuryazarlık","Bilgi Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor okuma metni","Telefonun ekran süresi ayarı (ailenin izniyle)","Kâğıt-kalem"],"scenario":"Okul gazetesinin sağlık köşesine 'Is Your Phone Stealing Your Sleep?' başlıklı bir yazı geldi. Yazıda bir sınıfın haftalık ekran süresi verileri ve uzman önerileri var. Sen gazetenin genç editörüsün: yazıyı okuyup ana fikri bulacak, verileri yorumlayacak ve okurlara kısa bir 'akıllı kullanım' önerisi yazacaksın. Telefonlar gerçekten bir sorun mu, yoksa sorun onları nasıl kullandığımız mı?","visual":{"type":"bars","params":{"title":"Class 6-B: Weekly phone use","labels":["Videos","Games","Messaging","Homework","Music"],"values":[8,6,4,3,2],"unit":"hours/week","editable":false},"caption":"Öğrenci grafiği okuyarak en çok ve en az zaman alan etkinliği bulur ve metindeki iddialarla karşılaştırır."},"steps":[{"title":"Başlıktan Tahmin","mode":"Bireysel · 10 dk","items":["Başlığı ve grafiği incele. Yazar telefonlara karşı mı, yanında mı olabilir? Tahminini bir cümleyle yaz.","Anahtar kelimeleri öğren: screen time, sleep, headache, eye strain, social life, addiction."]},{"title":"Ana Fikir ve Destekler","mode":"Bireysel · 25 dk","items":["Metni oku ve her paragrafa bir başlık ver.","Ana fikri tek cümleyle yaz, ardından onu destekleyen 3 bilgiyi listele.","Grafikteki hangi verinin metindeki hangi cümleyi desteklediğini eşleştir."],"warn":"Sık yapılan hata: Metindeki ilginç bir ayrıntıyı ana fikir sanmak. Kendine sor: Bu cümle bütün paragrafları kapsıyor mu?"},{"title":"Gerçek mi, Görüş mü?","mode":"Grup · 20 dk","items":["Metinden 6 cümle seçin ve 'Fact' ya da 'Opinion' olarak ayırın.","Görüş cümlelerinin hangisine katılıp hangisine katılmadığınızı 'I agree because…' / 'I disagree because…' ile tartışın.","Grup olarak telefonların bir olumlu ve bir olumsuz etkisini kararlaştırın."],"warn":"Sık yapılan hata: 'Experts say…' ile başlayan her cümleyi kesin gerçek kabul etmek. Bu cümle veriye mi dayanıyor, birinin düşüncesine mi?"},{"title":"Editör Notu","mode":"Bireysel · 25 dk","items":["Okurlara 50–70 kelimelik bir 'Smart Phone Tips' notu yaz: should / shouldn't kullan.","Kendi bir günlük ekran süreni (ailenin izniyle) gözlemle ve notuna bir kişisel hedef ekle.","Notunu NavigAItor'da paylaş."]}],"checklist":["Okumadan önce başlık ve grafikle tahmin yaptım.","Her paragrafa başlık verdim ve ana fikri tek cümleyle yazdım.","Grafikteki verileri metindeki cümlelerle eşleştirdim.","Gerçek ve görüş cümlelerini ayırdım.","should / shouldn't ile öneri notumu yazdım ve kişisel hedef ekledim."],"rubric":[{"k":"Ana fikir","d":"Ana fikri ve destekleyici bilgileri belirleme","l4":"Ana fikri ve tüm destekleri doğru belirler","l3":"Ana fikri doğru, desteklerin çoğunu bulur","l2":"Ana fikri ayrıntıyla karıştırır","l1":"Ana fikri belirleyemez"},{"k":"Veri okuma","d":"Grafik ile metni ilişkilendirme","l4":"Tüm eşleştirmeleri doğru ve gerekçeli yapar","l3":"Eşleştirmelerin çoğu doğru","l2":"Grafiği okur ama metinle ilişkilendiremez","l1":"Grafiği yorumlayamaz"},{"k":"Eleştirel okuma","d":"Gerçek / görüş ayrımı","l4":"Tüm cümleleri doğru ayırır ve gerekçelendirir","l3":"Cümlelerin çoğunu doğru ayırır","l2":"Ayrımı tutarsız yapar","l1":"Ayrım yapamaz"},{"k":"Öneri yazısı","d":"should / shouldn't ile öneri","l4":"Öneriler açık, gerçekçi ve doğru yazılmış","l3":"Öneriler anlaşılır, küçük hatalar var","l2":"Öneriler genel ve hatalı","l1":"Öneri yazılmamış"}],"navi":["Grafikteki en uzun çubuk, metindeki hangi uyarıyla ilgili olabilir?","Bir cümlenin görüş olduğunu sana hangi kelimeler düşündürdü?","Telefonu tamamen bırakmadan uykunu korumanın bir yolu olabilir mi?"],"diff":{"destek":"Metin üç paragrafa indirilir ve her paragraf için iki seçenekli başlık sunulur.","ileri":"Öğrenci grafikteki verilerle sınıfı için bir haftalık 'dijital denge' planı önerir ve yüzdeyle destekler."},"misconception":"Öğrenciler bir metindeki her bilgiyi, kaynağı ve kanıtı sorgulamadan gerçek kabul eder."},{"id":"ing-6-07","course":"ING","grade":6,"themeNo":4,"themeName":"Family Life & Home","title":"Aile Toplantısı","subtitle":"Family Life & Home — Problem ve çözüm odaklı canlandırma","kazanim":["Tema kapsamı: family life and home with relationships, problems, and solutions in the family; different families and family houses","Speaking (Konuşma) — ailede yaşanan bir sorunu anlatma, öneride bulunma ve ortak bir çözüme ulaşma"],"skills21":["Empati","İletişim","Problem Çözme","Sorumluluk"],"digital":["Dijital Hikaye Anlatıcılığı","Dijital Okuryazarlık"],"duration":"80 dk (2 ders)","format":"Grup","tools":["Rol kartları","Tablet veya telefonun video kayıt uygulaması","NavigAItor Stüdyo"],"scenario":"Yıldız ailesi küçük bir apartman dairesine taşındı. Artık iki kardeş aynı odayı paylaşıyor ve evde sürekli tartışma çıkıyor: biri gece ışıkla ders çalışmak istiyor, diğeri erken uyumak. Ailenin bir üyesi olarak 'aile toplantısına' katılacaksın. Herkesin kendini dinlenmiş hissedeceği adil bir çözüm bulabilecek misiniz?","visual":{"type":"chat","params":{"lines":[{"who":"Elif","t":"I can't sleep! The light is on until midnight."},{"who":"Mert","t":"But I have an exam. I need to study."},{"who":"Mum","t":"OK, let's talk. What's the problem, exactly?"},{"who":"Elif","t":"Why don't you study in the living room?"},{"who":"Mert","t":"It's too noisy there. Dad watches the news."},{"who":"Dad","t":"Hmm… What about a small desk lamp?"}]},"caption":"Öğrenci diyaloğu okur, sorunu ve önerileri renklerle işaretler, ardından kendi aile toplantısı diyaloğunu kurar."},"steps":[{"title":"Sorunu Anla","mode":"Grup · 15 dk","items":["Diyaloğu rollere ayrılarak sesli okuyun.","Sorunu (problem), duyguları (feelings) ve önerileri (suggestions) ayrı renklerle işaretleyin.","Öneri kalıplarını listeleyin: Why don't you…?, What about…?, You should…, Let's…"]},{"title":"Yeni Sorun, Yeni Roller","mode":"Grup · 15 dk","items":["Grupça farklı bir aile sorunu seçin: ev işlerinin paylaşımı, tek bilgisayar, evcil hayvanın bakımı ya da misafir odası.","Her üye bir rol kartı alsın: anne/baba, abla/ağabey, kardeş, büyükanne/büyükbaba.","Her rol için bir 'I feel… because…' cümlesi yazın."],"warn":"Sık yapılan hata: Herkesin sadece kendi isteğini tekrar etmesi. Bir aile toplantısında karşı tarafın duygusunu da söylemek gerekir: 'I understand, but…'"},{"title":"Toplantıyı Canlandır","mode":"Grup · 25 dk","items":["3–4 dakikalık bir aile toplantısı canlandırın: sorun → duygular → en az 3 öneri → ortak karar.","Her üye en az bir öneri ve bir kabul/ret cümlesi söylesin: 'That's a good idea.' / 'I'm not sure about that.'","Canlandırmayı video olarak kaydedin."],"warn":"Sık yapılan hata: 'Why don't you…?' sorusunu gerçek bir 'neden' sorusu sanıp 'Because…' ile yanıtlamak. Bu kalıp aslında ne işe yarıyor?"},{"title":"Değerlendir ve Paylaş","mode":"Grup · 25 dk","items":["Videoyu NavigAItor Stüdyo'ya yükleyin ve başka bir grubun videosunu izleyin.","İzlediğiniz grubun çözümünü 'fair / not fair' olarak değerlendirip bir öneri yazın.","Kendi aile toplantınızdan öğrendiğiniz bir iletişim kuralını sınıfla paylaşın."]}],"checklist":["Diyalogdaki sorun, duygu ve önerileri işaretledim.","Rolüm için 'I feel… because…' cümlesi yazdım.","Toplantıda en az bir öneri ve bir kabul/ret cümlesi söyledim.","Grubumla ortak bir karara ulaştık ve kaydettik.","Başka bir grubun çözümünü değerlendirip öneri yazdım."],"rubric":[{"k":"Öneri dili","d":"Öneri kalıplarının doğru kullanımı","l4":"Çeşitli öneri kalıplarını doğal ve doğru kullanır","l3":"Kalıpları çoğunlukla doğru kullanır","l2":"Tek bir kalıbı tekrar eder","l1":"Öneri yapamaz"},{"k":"Duygu ifadesi","d":"Duygu ve gerekçe bildirme","l4":"Duygusunu nedeniyle açık anlatır, karşı tarafı anladığını gösterir","l3":"Duygusunu nedeniyle anlatır","l2":"Duygu var, neden eksik","l1":"Duygu ifade etmez"},{"k":"Etkileşim ve çözüm","d":"Dinleme, yanıt verme ve uzlaşma","l4":"Diğerlerini dinler, uzlaşmaya katkı verir","l3":"Etkileşime katılır, uzlaşmayı kabul eder","l2":"Az katılır","l1":"Etkileşime katılmaz"},{"k":"Akıcılık ve telaffuz","d":"Konuşmanın anlaşılırlığı","l4":"Akıcı ve anlaşılır konuşur","l3":"Küçük duraksamalarla anlaşılır","l2":"Sık duraksar, anlaşılırlık azalır","l1":"Konuşma anlaşılmaz"}],"navi":["Elif ile Mert'in ikisi de haklı olabilir mi? Bunu İngilizce nasıl söylersin?","Bir öneriyi kırıcı olmadan reddetmek istesen hangi kelimelerle başlardın?","Ortak kararınızda herkes bir şeyden vazgeçti mi? Bu çözümü adil yapan ne?"],"diff":{"destek":"Öğrenci hazır cümle şeritlerinden seçerek konuşur; rolü yalnızca 3 replikten oluşur.","ileri":"Öğrenci 'arabulucu' rolünü üstlenir; toplantıyı yönetir ve sonunda kararı özetler."},"misconception":"Öğrenciler 'Why don't you…?' kalıbını bir öneri değil, eleştiri ya da gerçek bir neden sorusu olarak algılar."},{"id":"ing-6-08","course":"ING","grade":6,"themeNo":5,"themeName":"Life In The Neighbourhood, City & Social Life","title":"Şehir mi, Köy mü?","subtitle":"Life in the Neighbourhood, City & Social Life — Karşılaştırma kelimeleri","kazanim":["Tema kapsamı: life in the neighbourhood, city and social life with different lifestyles in the city and rural areas; sports events in the city and rural areas","Vocabulary (Söz Varlığı) — şehir ve kırsal yaşamı ile spor etkinliklerini karşılaştıran kelime ve ifadeleri kullanma"],"skills21":["Analitik Düşünme","Karşılaştırma","Esneklik","Toplumsal Farkındalık"],"digital":["Dijital Okuryazarlık","Veri Okuryazarlığı"],"duration":"40 dk","format":"İkili","tools":["Kelime kartları","Ücretsiz bir çevrim içi anket aracı","Kâğıt-kalem"],"scenario":"Kuzenin köyde, sen şehirde yaşıyorsun ve yaz tatilini birlikte geçirmek istiyorsunuz. Ama nerede? Bir 'City vs. Village' tartışması başladı ve kazanmak için doğru kelimeleri seçmen gerekiyor. Her iki yaşamın da artıları ve eksileri var. Hangi kelimeler tartışmayı senin lehine çevirir?","visual":{"type":"cards","params":{"items":[{"w":"crowded","tr":"kalabalık","ic":"🏙️"},{"w":"peaceful","tr":"huzurlu","ic":"🌾"},{"w":"noisy","tr":"gürültülü","ic":"🔊"},{"w":"fresh air","tr":"temiz hava","ic":"🌬️"},{"w":"traffic jam","tr":"trafik sıkışıklığı","ic":"🚗"},{"w":"village festival","tr":"köy şenliği","ic":"🎪"},{"w":"football match","tr":"futbol maçı","ic":"⚽"},{"w":"horse riding","tr":"binicilik","ic":"🐎"}]},"caption":"Öğrenci kartları çevirir, her kelimeyi 'City', 'Village' ya da 'Both' olarak işaretler."},"steps":[{"title":"Kartları Sınıflandır","mode":"İkili · 10 dk","items":["Kartları çevirerek anlamları kontrol edin.","Her kelimeyi City / Village / Both sütunlarına yerleştirin.","Her sütuna kendi bulduğunuz bir kelime daha ekleyin (ör. skyscraper, farm, stadium)."],"warn":"Sık yapılan hata: Bir kelimeyi yalnızca tek bir yere ait sanmak. 'Football match' köyde de yapılamaz mı? Gerekçeni söyle."},{"title":"Karşılaştırma Cümleleri","mode":"İkili · 15 dk","items":["Kartları kullanarak 6 karşılaştırma cümlesi kurun: 'The city is noisier than the village.' 'The village is more peaceful than the city.'","Bir spor etkinliğini iki yerde karşılaştırın: 'People watch football matches in big stadiums in the city, but…'"],"warn":"Sık yapılan hata: Uzun sıfatlarda -er eklemek ('peacefuller'). Hangi sıfatlar 'more' ile kullanılır, kartlardan örnek bul."},{"title":"Mini Tartışma ve Anket","mode":"İkili · 15 dk","items":["Biri şehri, diğeri köyü savunsun; her biri 3 kelime kartını 'kanıt' olarak masaya koysun.","Ücretsiz bir anket aracıyla sınıfa 'City or Village for a summer holiday?' sorusunu sorun.","Sonucu yeni kelimelerle bir cümlede yorumlayın: 'Most of the class prefer the village because it is more peaceful.'"]}],"checklist":["Kartlardaki 8 kelimenin anlamını öğrendim.","Kelimeleri City / Village / Both olarak sınıflandırdım ve gerekçelendirdim.","6 doğru karşılaştırma cümlesi kurdum.","Tartışmada en az 3 yeni kelimeyi kullandım.","Anket sonucunu İngilizce bir cümleyle yorumladım."],"rubric":[{"k":"Kelime bilgisi","d":"Şehir, kırsal yaşam ve spor kelimelerini bilme","l4":"Tüm kelimeleri doğru kullanır ve yenilerini ekler","l3":"Kelimelerin çoğunu doğru kullanır","l2":"Bazı kelimeleri karıştırır","l1":"Kelimeleri tanımakta zorlanır"},{"k":"Sınıflandırma","d":"Kelimeleri bağlama göre gruplama","l4":"Doğru gruplar ve 'Both' kararlarını gerekçelendirir","l3":"Çoğunu doğru gruplar","l2":"Gruplamada tutarsızdır","l1":"Gruplama yapamaz"},{"k":"Karşılaştırma yapısı","d":"-er / more ... than kullanımı","l4":"Tüm cümleler doğru ve çeşitli","l3":"Küçük hatalar var","l2":"Kural karışık uygulanıyor","l1":"Karşılaştırma cümlesi kuramaz"},{"k":"Tartışma katılımı","d":"Kelimeleri kanıt olarak kullanma","l4":"İkna edici ve kelime açısından zengin savunma yapar","l3":"Anlaşılır savunma yapar","l2":"Kısa ve tekrar eden ifadeler kullanır","l1":"Tartışmaya katılmaz"}],"navi":["'Peaceful' kelimesi bir yeri anlatırken olumlu mu olumsuz mu bir his verir? 'Quiet' ile aynı mı?","Şehri savunuyorsan 'crowded' kelimesini olumlu bir şekilde kullanabilir misin?"],"diff":{"destek":"Öğrenci 4 kartla çalışır ve 'The ___ is ___er than the ___.' kalıbını tamamlar.","ileri":"Öğrenci kartlara 4 yeni kelime ekleyip bir arkadaşı için çevrilebilir kart seti hazırlar."},"misconception":"Öğrenciler tüm sıfatların karşılaştırmasının -er ile yapıldığını düşünür ('beautifuller', 'peacefuller')."},{"id":"ing-6-09","course":"ING","grade":6,"themeNo":7,"themeName":"Life In Nature & Global Problems","title":"Acil Durum Anonsu","subtitle":"Life in Nature & Global Problems — Afet duyurusunu dinleyip eylem planı çıkarma","kazanim":["Tema kapsamı: life in nature and global problems with natural disasters and their harms on animals and nature; natural disasters and their harms on humans","Listening (Dinleme) — doğal afetlerle ilgili bir duyuruyu dinleyip afet öncesi, sırası ve sonrasında yapılacakları sıralama"],"skills21":["Eleştirel Düşünme","Duyarlılık","Sorumluluk","Problem Çözme"],"digital":["Dijital Simülasyon","Sürdürülebilirlik Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor sesli metin oynatıcısı","Kâğıt-kalem","Ücretsiz bir sunum aracı"],"scenario":"Bir yaz kampındasın ve kampın hoparlöründen İngilizce bir anons geliyor: bölgede şiddetli yağış ve sel riski var. Kamp liderleri senden anonstaki talimatları dinleyip küçük yaştaki kampçılar için resimli bir eylem planı hazırlamanı istiyor. Anonsu yanlış anlamak hem insanları hem de kamptaki hayvanları riske atabilir. Hangi adımı hangi sırayla yapmalısınız?","visual":{"type":"flow","params":{"kind":"algoritma","steps":["Listen to the warning","Pack an emergency bag","Move to higher ground","Stay away from rivers","Help animals and younger children","Wait for the all-clear"]},"caption":"Öğrenci karışık verilen adımları anonsta duyduğu sıraya göre dizer ve eksik adımı ekler."},"steps":[{"title":"Dinlemeden Önce","mode":"Grup · 10 dk","items":["Afet kelimelerini gözden geçirin: flood, earthquake, wildfire, storm, emergency bag, shelter, evacuate.","Sel sırasında insanlar ve hayvanlar için hangi tehlikeler olabilir? Türkçe değil, 3 İngilizce kelimeyle tahmin edin."]},{"title":"Birinci Dinleme: Ne Oluyor?","mode":"Bireysel · 10 dk","items":["Anonsu bir kez dinle ve şu soruları yanıtla: What is the danger? When will it start? Who is speaking?","Anonsun ses tonundan ne kadar acil olduğunu tahmin et ve gerekçeni yaz."],"warn":"Sık yapılan hata: 'will' ve 'won't' sesini karıştırmak. Bu iki kelime anonsun anlamını tamamen değiştirir; şüphede kal ve tekrar dinle."},{"title":"İkinci Dinleme: Sırayı Kur","mode":"Bireysel · 20 dk","items":["Anonsu tekrar dinle ve akış şemasındaki adımları sıraya diz.","Before / During / After başlıklı bir tablo yap ve her talimatı doğru sütuna yaz.","Anonsta 'must' ve 'mustn't' ile verilen talimatları ayrıca işaretle."],"warn":"Sık yapılan hata: Talimatları duyulma sırasına göre değil, kendi tahmin ettiği sıraya göre dizmek. Sıralamayı sadece duyduğun bağlaçlara (first, then, after that, finally) göre yap."},{"title":"Resimli Eylem Planı","mode":"Grup · 40 dk","items":["Ücretsiz bir sunum aracında küçük kampçılar için 6 kartlık resimli bir eylem planı hazırlayın.","Her kartta bir kısa İngilizce talimat ve bir çizim/simge olsun.","Bir kartı sel sırasında hayvanların korunmasına ayırın.","Planı sınıfa 1 dakikada sunun."]}],"checklist":["Afet kelimelerini dinlemeden önce gözden geçirdim.","Birinci dinlemede tehlikeyi, zamanı ve konuşanı belirledim.","Talimatları duyduğum sıraya göre dizdim.","Before / During / After tablosunu doldurdum.","Grubumla hayvanları da kapsayan resimli bir eylem planı hazırladım."],"rubric":[{"k":"Genel anlama","d":"Anonsun konusunu ve aciliyetini anlama","l4":"Tehlike, zaman ve konuşanı doğru belirler, aciliyeti gerekçelendirir","l3":"Temel bilgileri doğru belirler","l2":"Bilgilerin bir kısmını kaçırır","l1":"Anonsun konusunu anlayamaz"},{"k":"Sıralama","d":"Talimatları doğru sıraya koyma","l4":"Tüm adımları doğru sıralar ve eksik adımı ekler","l3":"Adımların çoğunu doğru sıralar","l2":"Sıralamada birkaç hata var","l1":"Sıralama yapamaz"},{"k":"Talimat dili","d":"must / mustn't ve emir kipini anlama ve kullanma","l4":"Tüm talimatları doğru yorumlar ve yazar","l3":"Çoğunu doğru yorumlar","l2":"Yasak ve zorunluluğu karıştırır","l1":"Talimatları anlayamaz"},{"k":"Eylem planı","d":"Grubun resimli planı","l4":"Plan açık, doğru ve küçük yaştakiler için uygun","l3":"Plan doğru ve anlaşılır","l2":"Planda eksik ya da karışık adımlar var","l1":"Plan tamamlanmamış"}],"navi":["Konuşan kişi hangi kelimeleri daha yavaş ve vurgulu söyledi? Bu sana ne anlatıyor?","'Stay away from rivers' talimatı neden 'during' sütununda? Başka bir sütuna da uyar mı?","Küçük bir çocuk bu planı okusa hangi kartı ilk anlar, hangisinde zorlanır?"],"diff":{"destek":"Öğrenci anonsu altyazılı dinler ve 4 adımlık kısaltılmış akış şemasıyla çalışır.","ileri":"Öğrenci aynı anonsu başka bir afet (orman yangını) için yeniden yazar ve kaydeder."},"misconception":"Öğrenciler doğal afetlerin yalnızca insanlara zarar verdiğini düşünür; hayvanlar ve doğa üzerindeki etkileri göz ardı eder."},{"id":"ing-6-10","course":"ING","grade":6,"themeNo":8,"themeName":"Life In The Universe & Future","title":"2050'den Uzay Günlüğü","subtitle":"Life in the Universe & Future — Gelecek zaman ile yaratıcı yazma","kazanim":["Tema kapsamı: life in the universe and future with life in the universe; life in the future; space and technology","Writing (Yazma) — gelecekte uzayda yaşamı ve teknolojiyi anlatan kısa bir günlük metni yazma"],"skills21":["Yaratıcılık","Merak","Sistematik Düşünme","Analitik Düşünme"],"digital":["Dijital Hikaye","Dijital Okuryazarlık"],"duration":"80 dk (2 ders)","format":"Bireysel","tools":["Kâğıt-kalem","NavigAItor Stüdyo","Ücretsiz bir dijital hikaye aracı"],"scenario":"Yıl 2050 ve sen Ay'daki ilk okul istasyonunda bir öğrencisin. Dünya'daki bir okul, uzayda bir gününün nasıl geçeceğini merak ediyor ve senden İngilizce bir günlük sayfası istiyor. Yemek, uyku, ders ve robot yardımcılar uzayda nasıl olacak? Okurlarının hem şaşıracağı hem de inanacağı bir gün nasıl anlatılır?","visual":{"type":"routine","params":{"items":[{"time":"07:00","t":"Wake up in a sleeping bag on the wall"},{"time":"08:00","t":"Eat breakfast from a food pouch"},{"time":"09:30","t":"Science lesson with a robot teacher"},{"time":"13:00","t":"Exercise for two hours"},{"time":"16:00","t":"Video call with family on Earth"},{"time":"21:00","t":"Look at Earth from the window"}]},"caption":"Öğrenci çizelgeyi düzenler, saatleri değiştirir ve kendi uzay gününe yeni etkinlikler ekler."},"steps":[{"title":"Fikir Topla","mode":"Bireysel · 15 dk","items":["Çizelgeyi incele: uzayda hangi günlük işler Dünya'dakinden farklı olurdu? 3 fark yaz.","Gelecek teknolojilerini düşün: robot helper, smart watch, 3D food printer, space bus. Hangilerini kullanacaksın?","Bilgi için güvenilir bir kaynaktan uzay istasyonundaki yaşamla ilgili 2 gerçek bilgi bul."]},{"title":"Planla","mode":"Bireysel · 15 dk","items":["Çizelgeyi kendi gününe göre düzenle: en az 6 saat ve etkinlik.","Günlüğünü üç paragrafta planla: Morning / Afternoon / Evening.","Her paragrafa bir duygu ekle: 'I will feel…', 'It will be…'."],"warn":"Sık yapılan hata: Gerçek bilgi ile hayal ürününü karıştırıp okuru yanıltmak. Hangi bilginin gerçek, hangisinin senin tahminin olduğunu kendine işaretle."},{"title":"Günlüğü Yaz","mode":"Bireysel · 30 dk","items":["80–100 kelimelik bir günlük sayfası yaz: tarih, selamlama, üç paragraf, kapanış.","Gelecek için will / won't kullan; en az 2 zaman bağlacı ekle: first, then, after that, finally.","Taslağını kontrol listesiyle gözden geçir ve bir arkadaşının da okumasını iste."],"warn":"Sık yapılan hata: 'will' sonrasında fiile ek getirmek ('I will eats', 'I will to sleep'). will'den sonra fiil hangi biçimde gelir?"},{"title":"Dijital Hikaye","mode":"Bireysel · 20 dk","items":["Günlüğünü ücretsiz bir dijital hikaye aracında 4 sayfalık resimli bir hikayeye dönüştür.","İstersen kendi sesinle okuyup kaydet.","NavigAItor Stüdyo'da paylaş ve 'Life in Space' sınıf albümüne ekle."]}],"checklist":["Uzaydaki yaşamla Dünya'daki yaşam arasında 3 fark buldum.","Güvenilir bir kaynaktan 2 gerçek bilgi ekledim.","80–100 kelimelik, üç paragraflı günlüğümü yazdım.","will / won't ve zaman bağlaçlarını doğru kullandım.","Gerçek bilgi ile hayal ürünü bölümleri ayırt ettim.","Dijital hikayemi paylaştım."],"rubric":[{"k":"İçerik ve yaratıcılık","d":"Uzay yaşamını özgün ve inandırıcı anlatma","l4":"Özgün fikirler gerçek bilgilerle dengeli","l3":"İlgi çekici, birkaç özgün fikir var","l2":"Fikirler sınırlı ya da tutarsız","l1":"İçerik çok kısa ya da konudan uzak"},{"k":"Metin düzeni","d":"Günlük biçimi ve paragraf sırası","l4":"Tüm bölümler var, akış bağlaçlarla düzgün","l3":"Bölümler var, akış çoğunlukla düzgün","l2":"Bölümler eksik, akış kopuk","l1":"Düzen yok"},{"k":"Dil kullanımı","d":"will / won't ve zaman bağlaçları","l4":"Yapılar doğru ve çeşitli","l3":"Küçük hatalar var","l2":"Hatalar anlamı zaman zaman bozar","l1":"Yapılar kullanılmamış"},{"k":"Dijital ürün","d":"Resimli hikayenin kalitesi","l4":"Görseller metni destekler, sunum özenli","l3":"Görseller uygun, sunum anlaşılır","l2":"Görseller metinle ilgisiz","l1":"Ürün tamamlanmamış"}],"navi":["Yerçekimi olmasa sabah kahvaltısı nasıl değişirdi? Bunu bir 'will' cümlesiyle anlatabilir misin?","Okurunun sana inanması için günlüğüne hangi gerçek bilgiyi koymalısın?","Uzayda en çok neyi özleyeceğini düşünüyorsun? Bu duygu günlüğünün neresinde olmalı?"],"diff":{"destek":"Öğrenciye her paragraf için cümle başlangıçları verilir: 'In the morning, I will…', 'After lunch, I will…'.","ileri":"Öğrenci günlüğüne 2050'deki teknolojinin bir sorununu ve olası çözümünü anlatan bir paragraf ekler."},"misconception":"Öğrenciler 'will' yapısından sonra fiile -s veya 'to' ekler ('I will goes', 'I will to go')."},{"id":"ing-7-11","course":"ING","grade":7,"themeNo":1,"themeName":"School Life & Education","title":"Gezi Broşürü Ekibi","subtitle":"Okul gezisi programı ve İngilizce tanıtım broşürü","kazanim":["Tema kapsamı: school life and education with educational activities, competitions, and celebrations at school; school trips; national days and celebrations","Writing — okul gezisi için tanıtım broşürü yazma (geçmiş ve gelecek etkinlikleri anlatma)"],"skills21":["İletişim","İş Birliği","Yaratıcılık","Sorumluluk"],"digital":["Dijital Okuryazarlık","Dijital İçerik Üretimi"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Defter ve kalem","Ücretsiz bir sunum aracı","NavigAItor Stüdyo"],"scenario":"Okulun kardeş okulundan gelecek misafir öğrenciler için bir günlük şehir gezisi düzenleniyor. Okul müdürü, misafirlerin programı kendi dillerinde anlayabilmesi için senin ekibinden İngilizce bir broşür istiyor. Broşür hem gezide neler yapılacağını hem de geçen yılki geziden kısa bir anıyı içermeli. Misafirleri bu geziye katılmaya nasıl heveslendirirsin?","visual":{"type":"routine","params":{"items":[{"time":"08:30","t":"Meet at the school gate"},{"time":"09:30","t":"Visit the science museum"},{"time":"12:00","t":"Lunch in the park"},{"time":"13:30","t":"Workshop: make a kite"},{"time":"15:30","t":"Return to school"}]},"caption":"Öğrenci gezi programındaki saatleri ve etkinlikleri düzenleyip kendi broşür planını oluşturur."},"steps":[{"title":"Programı Çöz","mode":"Bireysel · 10 dk","items":["Görseldeki gezi programını incele; her saatte ne yapılacağını Türkçe değil, İngilizce tek cümleyle yaz (ör. At 9:30, we are going to visit the science museum.).","Programa misafirlerin ilgisini çekecek bir etkinlik daha ekle ve saatini belirle."],"warn":"Sık yapılan hata: Planlanmış gelecek etkinlikler için 'will' ile 'be going to' yapısını karıştırmak; programda kesinleşmiş planlar için 'be going to' kullan."},{"title":"Geçen Yılın Anısı","mode":"Bireysel · 15 dk","items":["Geçen yılki bir okul gezisini ya da okul etkinliğini 3–4 cümleyle anlat (Last year, we went to... We saw... It was...).","En az iki düzensiz fiilin geçmiş halini kullan ve altını çiz."],"warn":"Sık yapılan hata: Geçmiş zamanda 'goed', 'seed' gibi yanlış biçimler yazmak; düzensiz fiil listesini kontrol et."},{"title":"Broşürü Tasarla","mode":"Grup · 35 dk","items":["Grup olarak bir başlık, program bölümü, 'Last Year' bölümü ve 'What to bring' listesi içeren broşürü ücretsiz bir sunum aracında hazırlayın.","Her bölümü farklı bir grup üyesi yazsın, sonra birbirinizin metnini düzeltin.","Görsel olarak kendi çizimlerinizi veya ücretsiz görselleri kullanın."]},{"title":"Sun ve Değerlendir","mode":"Grup · 20 dk","items":["Broşürünüzü 2 dakikada İngilizce tanıtın.","Diğer grupların broşürlerine 'I like... because...' cümlesiyle geri bildirim verin."]}],"checklist":["Programdaki her etkinliği İngilizce bir cümleyle yazdım.","Geçmiş bir geziyi en az 3 cümleyle anlattım.","En az iki düzensiz fiili doğru kullandım.","Broşürde 'What to bring' listesi hazırladım.","Arkadaşımın metnini okuyup en az bir düzeltme önerdim.","Broşürü sınıfa İngilizce tanıttım."],"rubric":[{"k":"Görev Tamamlama","d":"Broşürün tüm bölümleri var mı?","l4":"Tüm bölümler eksiksiz ve özgün","l3":"Bölümler var, biri kısa","l2":"Bir bölüm eksik","l1":"Birden fazla bölüm eksik"},{"k":"Dil Doğruluğu","d":"Geçmiş ve gelecek yapılarının doğru kullanımı","l4":"Hatalar anlamı hiç bozmuyor","l3":"Birkaç küçük hata var","l2":"Hatalar zaman zaman anlamı bozuyor","l1":"Yapılar çoğunlukla hatalı"},{"k":"Okuyucuya Uygunluk","d":"Misafir öğrencileri heveslendiriyor mu?","l4":"Dikkat çekici, davetkâr dil","l3":"Anlaşılır ama sade","l2":"Bilgi var, çekicilik az","l1":"Okuyucu düşünülmemiş"},{"k":"İş Birliği","d":"Grup içi görev paylaşımı ve akran düzeltmesi","l4":"Herkes katkı verdi, düzeltmeler yapıldı","l3":"Çoğu üye katkı verdi","l2":"Katkı dengesiz","l1":"İş tek kişide kaldı"}],"navi":["Broşürü okuyan bir misafir, saat 12:00'de nerede olacağını hemen bulabiliyor mu?","Geçen yılki anını anlatırken hangi fiiller geçmiş zamanda farklı biçim alıyor?"],"diff":{"destek":"Öğrenciye 'At ___, we are going to ___.' ve 'Last year, we ___.' kalıplarıyla boşluk doldurmalı bir broşür iskeleti verilir.","ileri":"Broşüre misafirlerin sorabileceği üç soruyu ve cevaplarını içeren bir 'FAQ' bölümü eklenir."},"misconception":"Öğrenciler geçmiş zamanda tüm fiillere -ed eklenebileceğini düşünür."},{"id":"ing-7-12","course":"ING","grade":7,"themeNo":3,"themeName":"Personal Life & Well-Being","title":"Ekranın Öbür Yüzü","subtitle":"Sosyal medya alışkanlıkları üzerine anket raporu okuma","kazanim":["Tema kapsamı: personal life and well-being with advantages and disadvantages of social media; staying healthy and fit","Reading — sosyal medyanın avantaj ve dezavantajlarını anlatan bir anket raporunu okuyup çıkarım yapma"],"skills21":["Analitik Düşünme","Medya Okuryazarlığı","Sağlık Bilinci","Karar Verme"],"digital":["Dijital Okuryazarlık","Veri Okuryazarlığı"],"duration":"40 dk","format":"Bireysel + Grup","tools":["NavigAItor Stüdyo","Defter ve kalem","Renkli kalemler"],"scenario":"Okul sağlık kulübü, 7. sınıf öğrencilerinin boş zamanlarında ekranda ne yaptığını araştırdı ve sonuçları İngilizce bir rapor olarak yayımladı. Kulüp başkanı senden raporu okuyup arkadaşlarına kısa bir özet çıkarmanı istiyor. Raporda bazı bilgiler grafikte, bazıları ise metnin satır aralarında gizli. Bu verilere bakarak sosyal medya kullanımı hakkında hangi kararı önerirsin?","visual":{"type":"pie","params":{"labels":["Chatting with friends","Watching videos","Playing games","Learning new things","Sharing photos"],"values":[30,28,20,12,10]},"caption":"Öğrenci grafikteki dilimleri okuyup metindeki ifadelerle eşleştirir ve en büyük ile en küçük payı yorumlar."},"steps":[{"title":"Göz Gezdir","mode":"Bireysel · 5 dk","items":["Raporun başlığına ve grafiğe bak; raporun ne hakkında olduğunu tek cümleyle tahmin et.","Metinde 'advantage', 'disadvantage', 'screen time', 'addicted' kelimelerini bul ve işaretle."]},{"title":"Ayrıntıyı Yakala","mode":"Bireysel · 15 dk","items":["Rapordan sosyal medyanın iki avantajını ve iki dezavantajını İngilizce olarak tabloya yaz.","Grafikteki her dilim için 'About ___ percent of students spend time ___.' cümlesini kur.","Metinde açıkça yazmayan ama verilerden çıkarılabilecek bir sonuç yaz (ör. Most students use social media for ___, not for ___.)."],"warn":"Sık yapılan hata: Grafikte en büyük dilimi 'en faydalı' etkinlik sanmak; çok yapılan bir şeyin iyi mi kötü mü olduğu ayrıca değerlendirilmeli."},{"title":"Karar Ver ve Paylaş","mode":"Grup · 20 dk","items":["Grupça rapora dayanan üç maddelik 'Smart Social Media Tips' listesi hazırlayın (You should... / You shouldn't...).","Her öneriyi rapordaki bir bilgiyle destekleyin."],"warn":"Sık yapılan hata: Öneri yazarken rapordaki veriyi değil kişisel görüşü kanıt olarak sunmak."}],"checklist":["Raporun ana fikrini tek cümleyle yazdım.","İki avantaj ve iki dezavantajı tabloya yazdım.","Grafikteki dilimleri yüzdeleriyle İngilizce cümlelere dönüştürdüm.","Metinden en az bir çıkarım yaptım.","Önerilerimi rapordaki bilgilere dayandırdım."],"rubric":[{"k":"Ana Fikri Bulma","d":"Raporun amacını doğru özetleme","l4":"Ana fikir doğru ve öz","l3":"Ana fikir doğru, ayrıntı fazla","l2":"Ana fikir kısmen doğru","l1":"Ana fikir bulunamadı"},{"k":"Ayrıntı ve Veri Okuma","d":"Grafik ve metindeki bilgileri doğru aktarma","l4":"Tüm veriler doğru aktarıldı","l3":"Bir küçük hata var","l2":"Birkaç veri yanlış","l1":"Veriler okunamadı"},{"k":"Çıkarım","d":"Açıkça yazılmayan sonucu kanıtla bulma","l4":"Mantıklı çıkarım, kanıtı net","l3":"Mantıklı çıkarım, kanıt zayıf","l2":"Çıkarım metinden kopuk","l1":"Çıkarım yok"},{"k":"Karar ve Öneri","d":"Verilere dayalı öneri üretme","l4":"Üç öneri, hepsi kanıtlı","l3":"Öneriler var, biri kanıtsız","l2":"Öneriler genel","l1":"Öneri üretilemedi"}],"navi":["Grafikte en çok zaman alan etkinlik ile en az zaman alan arasında nasıl bir fark var; bu fark sana ne düşündürüyor?","Bu öneriyi rapordaki hangi cümle destekliyor?"],"diff":{"destek":"Rapor kısaltılmış biçimde ve anahtar kelimelerin Türkçe karşılıklarıyla birlikte verilir; tablo ilk satırı doldurulmuş olarak sunulur.","ileri":"Öğrenci kendi sınıfından 5 kişilik mini bir anket yapar ve sonuçlarını raporla karşılaştıran iki cümle yazar."},"misconception":"Öğrenciler bir etkinliğin çok yapılmasını onun faydalı olduğunun kanıtı sayar."},{"id":"ing-7-13","course":"ING","grade":7,"themeNo":5,"themeName":"Life In The Neighbourhood, City & Social Life","title":"Mahalle Gönüllüleri","subtitle":"Yardım kampanyası planlama ve İngilizce kamu spotu","kazanim":["Tema kapsamı: life in the neighbourhood and city including social life with helping people in need in the neighbourhood and the city; technology in cities and rural areas","Speaking — mahallede ihtiyaç sahiplerine yardım için öneride bulunma ve gönüllü planı tartışma"],"skills21":["Empati","Sosyal Farkındalık","Sorumluluk","Problem Çözme","Vatandaşlık"],"digital":["Dijital Okuryazarlık","Dijital İş Birliği"],"duration":"80 dk (2 ders)","format":"İkili","tools":["Tablet veya telefon (ses kaydı için)","NavigAItor Stüdyo","Defter ve kalem"],"scenario":"Mahallendeki yaşlı komşular kışın market alışverişine çıkmakta zorlanıyor, parktaki kedilerin de yiyecek ihtiyacı var. Belediyenin gençlik merkezi, okulların İngilizce kulüplerinden kısa birer kamu spotu ve gönüllü planı istiyor. Sen ve arkadaşın, yapılabilecekleri tartışıp en uygulanabilir fikri seçeceksiniz. Hangi yardım en çok kişiye en kolay şekilde ulaşır?","visual":{"type":"chat","params":{"lines":[{"who":"Deniz","t":"Our elderly neighbours can't carry heavy bags in winter."},{"who":"Arda","t":"Why don't we organise a shopping team on Saturdays?"},{"who":"Deniz","t":"Good idea! We could also collect food for the cats in the park."},{"who":"Arda","t":"How about making a poster to find more volunteers?"}]},"caption":"Öğrenci diyalogdaki öneri kalıplarını bulur ve kendi diyaloğunu bu balonlara benzer şekilde kurar."},"steps":[{"title":"Kalıpları Keşfet","mode":"İkili · 10 dk","items":["Görseldeki diyaloğu sesli okuyun; öneri bildiren ifadelerin altını çizin (Why don't we..., We could..., How about...).","Bu ifadelere kendiniz iki yeni kalıp ekleyin (ör. Let's..., What about...)."],"warn":"Sık yapılan hata: 'How about' sonrasında fiilin yalın halini kullanmak; 'How about making' gibi -ing ile devam etmelidir."},{"title":"Fikir Fırtınası","mode":"İkili · 20 dk","items":["Mahallede yardıma ihtiyaç duyabilecek üç grup belirleyin (elderly people, animals, families...).","Her grup için bir yardım fikri önerin; arkadaşınız 'I agree / I'm not sure, because...' ile cevap versin.","En uygulanabilir fikri seçin ve gerekçesini İngilizce iki cümleyle yazın."],"warn":"Sık yapılan hata: Para gerektiren ya da öğrencilerin yapamayacağı fikirler seçmek; zaman ve emekle yapılabilecek yardımları düşünün."},{"title":"Kamu Spotunu Kaydet","mode":"İkili · 30 dk","items":["Seçtiğiniz fikir için 45–60 saniyelik İngilizce bir kamu spotu metni yazın: sorun, öneri, davet.","Metni prova edin ve tablet ya da telefonla ses kaydı alın; kayıtta yüzünüz veya kişisel bilginiz yer almasın."]},{"title":"Dinle ve Geri Bildir","mode":"Grup · 20 dk","items":["Diğer ikililerin kayıtlarını dinleyin ve en ikna edici öneriyi oylayın.","Kendi kaydınızda telaffuzu geliştirmek istediğiniz bir kelimeyi not edin."]}],"checklist":["En az üç farklı öneri kalıbı kullandım.","Arkadaşımın önerisine gerekçeli cevap verdim.","Seçtiğimiz fikrin neden uygulanabilir olduğunu açıkladım.","Kamu spotunda sorun, öneri ve davet bölümleri vardı.","Kayıtta kişisel bilgi paylaşmadım.","Telaffuzunu geliştireceğim bir kelime belirledim."],"rubric":[{"k":"Öneri Dili","d":"Öneri kalıplarının çeşitli ve doğru kullanımı","l4":"Üç+ kalıp, hepsi doğru","l3":"İki kalıp doğru","l2":"Tek kalıp tekrar ediliyor","l1":"Kalıp kullanılmıyor"},{"k":"Etkileşim","d":"Karşılıklı konuşmayı sürdürme","l4":"Doğal ve dengeli alışveriş","l3":"Dengeli ama kısa","l2":"Bir taraf baskın","l1":"Etkileşim yok"},{"k":"Akıcılık ve Telaffuz","d":"Kayıttaki anlaşılırlık","l4":"Akıcı ve net","l3":"Ara ara duraksama","l2":"Sık duraksama, anlaşılır","l1":"Anlaşılması güç"},{"k":"Toplumsal Duyarlılık","d":"Fikrin gerçek bir ihtiyaca uygun olması","l4":"Gerçekçi, empatik ve uygulanabilir","l3":"Uygulanabilir ama genel","l2":"İhtiyaçla bağı zayıf","l1":"Uygulanamaz"}],"navi":["Bu yardım fikrini uygulamak için ihtiyacınız olan tek şey zaman ve gönüllü mü, yoksa başka şeyler de mi gerekir?","Yardım ettiğin kişi bu öneriyi duysa nasıl hisseder?"],"diff":{"destek":"Öğrenciye 'Why don't we ___? / That's a good idea because ___.' kalıplarını içeren konuşma kartları ve kelime bankası verilir.","ileri":"İkili, kamu spotuna mahalle sakinlerinden gelebilecek bir itiraza (I don't have time...) ikna edici bir cevap ekler."},"misconception":"Öğrenciler 'How about' ve 'What about' kalıplarından sonra fiilin yalın halinin geldiğini düşünür."},{"id":"ing-7-14","course":"ING","grade":7,"themeNo":6,"themeName":"Life In The World & Culture","title":"Dünya Sofrası Dedektifi","subtitle":"Sağlıklı ve ekolojik yiyecek söz varlığı","kazanim":["Tema kapsamı: life in the world and culture with healthy food and unhealthy food in the world (ecological food) and international events","Vocabulary — dünyadan sağlıklı, sağlıksız ve ekolojik yiyeceklerle ilgili kelimeleri sınıflandırma ve kullanma"],"skills21":["Kültürel Farkındalık","Sağlıklı Yaşam","Eleştirel Düşünme","Merak"],"digital":["Dijital Okuryazarlık","Dijital İçerik Üretimi"],"duration":"40 dk","format":"Bireysel","tools":["NavigAItor Stüdyo","Defter ve kalem"],"scenario":"Uluslararası bir gençlik festivalinde 'Healthy Food Corner' standı açılacak ve menüyü sen hazırlayacaksın. Önündeki yiyeceklerin bazıları sağlıklı, bazıları sağlıksız, bazıları da doğaya zarar vermeden üretilmiş. Ziyaretçiler etiketleri İngilizce okuyacak. Hangi yiyecek hangi rafa girer ve sen menüne neleri koyarsın?","visual":{"type":"sort","params":{"bins":["Healthy","Unhealthy","Ecological / Organic"],"items":[{"t":"fresh vegetables","b":0},{"t":"fizzy drinks","b":1},{"t":"whole grain bread","b":0},{"t":"fried chips","b":1},{"t":"local seasonal fruit","b":2},{"t":"home-grown tomatoes","b":2},{"t":"processed sausages","b":1},{"t":"lentil soup","b":0}]},"caption":"Öğrenci yiyecekleri sürükleyerek sağlıklı, sağlıksız ve ekolojik raflarına yerleştirir."},"steps":[{"title":"Rafları Doldur","mode":"Bireysel · 10 dk","items":["Görseldeki yiyecekleri doğru raflara sürükle.","Kararsız kaldığın bir yiyecek için 'I put it here because...' cümlesi yaz."],"warn":"Sık yapılan hata: 'Organic/ecological' ile 'healthy' kavramlarını aynı sanmak; ekolojik ürün üretim biçimini, sağlıklı ise beslenme değerini anlatır."},{"title":"Kelime Ağı Kur","mode":"Bireysel · 15 dk","items":["'healthy', 'unhealthy', 'ecological' kelimeleriyle birlikte sık kullanılan sıfat ve fiilleri topla (rich in vitamins, high in sugar, grown locally, contains...).","Her rafa en az bir kendi bildiğin yiyeceği ekle."]},{"title":"Festival Menüsü","mode":"Bireysel · 15 dk","items":["Standın için dört ürünlük bir menü kartı yaz; her ürün için bir açıklama ekle (ör. ___ is rich in ___ and it is grown locally.).","Menünü NavigAItor Stüdyo'da tasarlayıp kaydet."],"warn":"Sık yapılan hata: 'a lot of' ve 'too much' ifadelerini aynı anlamda kullanmak; 'too much' gereğinden fazla demektir."}],"checklist":["Tüm yiyecekleri bir rafa yerleştirdim.","Kararsız kaldığım bir seçimi İngilizce gerekçelendirdim.","En az altı yeni ifade içeren kelime ağı hazırladım.","Her rafa kendi bildiğim bir yiyecek ekledim.","Dört ürünlük menüyü açıklamalarıyla yazdım."],"rubric":[{"k":"Sınıflandırma","d":"Yiyecekleri doğru kategoriye koyma","l4":"Tümü doğru ve gerekçeli","l3":"Bir hata var","l2":"İki-üç hata var","l1":"Çoğu yanlış"},{"k":"Söz Varlığı Genişliği","d":"Yeni kelime ve eşdizimleri kullanma","l4":"Çeşitli ve doğru eşdizimler","l3":"Yeterli çeşitlilik","l2":"Sınırlı kelime","l1":"Yalnızca verilen kelimeler"},{"k":"Bağlamda Kullanım","d":"Kelimeleri menü açıklamalarında doğru kullanma","l4":"Doğal ve doğru cümleler","l3":"Küçük hatalar var","l2":"Anlam zaman zaman bozuluyor","l1":"Cümle kurulamamış"},{"k":"Kültürel Farkındalık","d":"Farklı mutfaklardan örnek ekleme","l4":"Farklı kültürlerden bilinçli seçim","l3":"Bir farklı kültür örneği","l2":"Yalnızca tanıdık yiyecekler","l1":"Ekleme yok"}],"navi":["Bir yiyecek hem ekolojik hem de sağlıksız olabilir mi? Bir örnek düşünebilir misin?","'high in' ve 'rich in' ifadelerini hangi tür besinler için kullanırsın?"],"diff":{"destek":"Kartlar resimli ve Türkçe karşılıklı verilir; raf sayısı ikiye (Healthy / Unhealthy) indirilir.","ileri":"Öğrenci menüsüne iki farklı ülkenin geleneksel bir yemeğini ekler ve neden sağlıklı olduğunu üç cümleyle açıklar."},"misconception":"Öğrenciler 'organik/ekolojik' bir yiyeceğin otomatik olarak sağlıklı olduğunu düşünür."},{"id":"ing-7-15","course":"ING","grade":7,"themeNo":8,"themeName":"Life In The Universe & Future","title":"Robotun Kayıp Talimatları","subtitle":"Geleceğin teknolojileri üzerine sıralı talimat dinleme","kazanim":["Tema kapsamı: life in the universe and future with time travel; future technologies and their use (robots, robotics)","Listening — gelecekteki bir robotun kullanım talimatlarını dinleyip ana fikir ve sıralı ayrıntıları belirleme"],"skills21":["Yaratıcılık","Merak","Analitik Düşünme","Problem Çözme"],"digital":["Dijital Okuryazarlık","Dijital Simülasyon"],"duration":"40 dk","format":"Bireysel + Grup","tools":["Kulaklık","NavigAItor Stüdyo (sesli kayıt)","Defter ve kalem"],"scenario":"Yıl 2050 ve okulunun kütüphanesine kitapları yerleştiren bir yardımcı robot geldi. Robotun kullanım kılavuzu kaybolmuş ama mühendisin bıraktığı bir ses kaydı var. Kaydı dinleyip robotun çalışma adımlarını doğru sıraya koymazsan kitaplar karışacak. Robotu doğru çalıştırmak için hangi adımı ne zaman yapmalısın?","visual":{"type":"flow","params":{"kind":"algoritma","steps":["Press the green button","Scan the book's barcode","Choose the shelf number","Let the robot carry the book","Check the screen for 'Done'"]},"caption":"Öğrenci dinlediği talimatlara göre akış şemasındaki adımları doğru sıraya dizer."},"steps":[{"title":"Dinlemeye Hazırlan","mode":"Bireysel · 5 dk","items":["Akış şemasındaki ifadeleri oku; bilmediğin kelimeleri (scan, barcode, shelf) tahmin etmeye çalış.","Talimatlarda sıralama bildiren kelimeleri listele: first, then, after that, finally."]},{"title":"Genel Dinleme","mode":"Bireysel · 10 dk","items":["Kaydı bir kez dinle ve robotun asıl görevini tek cümleyle yaz.","Kaydı ikinci kez dinle ve akış şemasındaki adımları sıraya diz."],"warn":"Sık yapılan hata: Adımları kayıtta ilk duyduğun sırayla dizmek; konuşmacı 'Before you do this...' diyerek geri dönebilir, sıralama kelimelerine dikkat et."},{"title":"Ayrıntıyı Yakala","mode":"Bireysel · 10 dk","items":["Kayıtta robotun yapamayacağı iki şeyi bul (It can't...).","Bir uyarı cümlesini aynen not et (ör. Don't...)."],"warn":"Sık yapılan hata: 'can' ile 'can't' sözcüklerini dinlerken karıştırmak; vurgu ve sondaki 't' sesine dikkat et."},{"title":"Robotu Geliştir","mode":"Grup · 15 dk","items":["Grupça robota yeni bir görev ekleyin ve bu görev için dört adımlık İngilizce talimat yazın.","Talimatlarınızı başka bir gruba okuyun; onlar da akış şemasına dönüştürsün."]}],"checklist":["Robotun asıl görevini tek cümleyle yazdım.","Beş adımı doğru sıraya dizdim.","Robotun yapamadığı iki şeyi buldum.","Sıralama kelimelerini kendi talimatlarımda kullandım.","Başka bir grubun talimatlarını akış şemasına dönüştürdük."],"rubric":[{"k":"Ana Fikir","d":"Kaydın genel amacını anlama","l4":"Tam ve doğru","l3":"Doğru ama eksik","l2":"Kısmen doğru","l1":"Anlaşılmadı"},{"k":"Sıralı Ayrıntı","d":"Adımları doğru dizme","l4":"Tüm adımlar doğru","l3":"Bir adım yer değiştirmiş","l2":"İki-üç adım hatalı","l1":"Sıralama rastgele"},{"k":"Seçici Dinleme","d":"can/can't ve uyarıları ayırt etme","l4":"Tüm ayrıntılar doğru","l3":"Bir ayrıntı eksik","l2":"Ayrıntılar karışık","l1":"Ayrıntı yakalanmadı"},{"k":"Talimat Üretme","d":"Yeni görev için açık talimat yazma","l4":"Açık, sıralı, uygulanabilir","l3":"Anlaşılır, bir belirsizlik var","l2":"Sıralama belirsiz","l1":"Talimat yazılamadı"}],"navi":["Konuşmacı bir adımı anlatırken 'before' dediğinde, o adım şemada nereye gitmeli?","Robot 'Done' yazısını göstermeden önce neyin tamamlanmış olması gerekir?"],"diff":{"destek":"Kayıt yavaşlatılmış hızda ve metin desteğiyle (altyazı) dinletilir; adımların ilk ikisi yerleştirilmiş olarak verilir.","ileri":"Öğrenci robotun bir hata yaptığı durumu anlatan kısa bir zaman yolculuğu hikâyesi yazar ve hatanın hangi adımdan kaynaklandığını açıklar."},"misconception":"Öğrenciler bir talimatı duydukları sırayla uygulamanın her zaman doğru olduğunu düşünür."},{"id":"ing-8-16","course":"ING","grade":8,"themeNo":2,"themeName":"Classroom Life & Learning","title":"Ekran mı, Sıra mı?","subtitle":"Çevrim içi ve yüz yüze öğrenme üzerine yapılandırılmış tartışma","kazanim":["Tema kapsamı: classroom life and learning with challenges in the classroom and improving classroom environment; pros and cons of online learning and traditional learning","Speaking — çevrim içi ve geleneksel öğrenmenin olumlu ve olumsuz yönlerini karşılaştırarak görüş bildirme"],"skills21":["Eleştirel Düşünme","Karşılaştırma","Karar Verme","Medya Okuryazarlığı"],"digital":["Dijital Okuryazarlık","Dijital İş Birliği","Bilgi Okuryazarlığı"],"duration":"80 dk (2 ders)","format":"Grup","tools":["Ücretsiz bir çevrim içi anket aracı","NavigAItor Stüdyo","Defter ve kalem"],"scenario":"Okul yönetimi, kötü hava günlerinde derslerin çevrim içi yapılıp yapılmayacağına karar verecek ve öğrenci meclisinden görüş istiyor. Sınıfınız İngilizce kulübü adına bir 'Class Debate' düzenleyecek. Sen bir tarafın sözcüsüsün ama önce iki tarafın güçlü ve zayıf yönlerini bilmelisin. Kötü hava günlerinde öğrenme için en iyi çözüm hangisi?","visual":{"type":"organizer","params":{"kind":"venn","slots":["Online learning","Both","Traditional learning"]},"caption":"Öğrenci çevrim içi ve geleneksel öğrenmenin özelliklerini Venn şemasına yerleştirir, ortak yönleri ortaya yazar."},"steps":[{"title":"Karşılaştır","mode":"Grup · 15 dk","items":["Venn şemasını İngilizce ifadelerle doldurun (flexible time, face-to-face interaction, internet connection...).","Her taraf için en az iki 'pro' ve iki 'con' belirleyin."],"warn":"Sık yapılan hata: Bir özelliği tek tarafa ait sanmak; örneğin 'teacher feedback' iki ortamda da vardır, fark biçimindedir."},{"title":"Mini Anket","mode":"Grup · 15 dk","items":["Ücretsiz bir çevrim içi anket aracıyla sınıfa üç soruluk İngilizce anket hazırlayın (ad-soyad sormayın).","Sonuçları 'Most of us... / Only a few students...' kalıplarıyla özetleyin."]},{"title":"Argümanını Kur","mode":"Grup · 20 dk","items":["Size verilen tarafı savunan üç argüman yazın; her birini bir anket sonucu veya örnekle destekleyin.","Karşılaştırma kalıplarını kullanın: more flexible than, not as ... as, while, on the other hand."],"warn":"Sık yapılan hata: 'more better' gibi çift karşılaştırma kullanmak; 'better' zaten karşılaştırma biçimidir."},{"title":"Tartış ve Karar Ver","mode":"Grup · 30 dk","items":["Her taraf 2 dakika açılış, 1 dakika cevap konuşması yapsın.","Tartışma sonunda sınıf, iki tarafın güçlü yönlerini birleştiren ortak bir öneri yazsın."]}],"checklist":["Venn şemasında her alana en az iki ifade yazdım.","Anket sorularında kişisel bilgi istemedim.","Argümanlarımı veriyle ya da örnekle destekledim.","En az üç karşılaştırma yapısı kullandım.","Karşı tarafın bir argümanına saygılı biçimde cevap verdim.","Ortak öneriye katkı sundum."],"rubric":[{"k":"Karşılaştırma","d":"İki öğrenme biçimini dengeli analiz etme","l4":"Dengeli, ayrıntılı, ortaklar belirgin","l3":"Dengeli ama yüzeysel","l2":"Tek taraf baskın","l1":"Karşılaştırma yok"},{"k":"Argüman ve Kanıt","d":"Görüşleri veriyle destekleme","l4":"Tüm argümanlar kanıtlı","l3":"Çoğu kanıtlı","l2":"Kanıt zayıf","l1":"Kanıtsız görüş"},{"k":"Dil Kullanımı","d":"Karşılaştırma ve görüş bildirme yapıları","l4":"Çeşitli ve doğru","l3":"Küçük hatalar","l2":"Sınırlı yapı","l1":"Yapılar hatalı"},{"k":"Etkileşim ve Saygı","d":"Dinleme, cevap verme, sözü sırayla alma","l4":"Etkin ve saygılı","l3":"Saygılı ama pasif","l2":"Söz kesme var","l1":"Etkileşim yok"}],"navi":["Bir özelliği hem avantaj hem dezavantaj olarak görebilir misin? Kimin açısından?","Anket sonucun argümanını gerçekten destekliyor mu, yoksa yalnızca bir kısmını mı?"],"diff":{"destek":"Öğrenciye 'I think ___ is better because ___. / On the other hand, ___.' kalıplı konuşma kartları ve Venn için kelime bankası verilir.","ileri":"Öğrenci karşı tarafın en güçlü argümanını önceden tahmin edip ona yönelik bir cevap hazırlar ve tartışmanın moderatörlüğünü üstlenir."},"misconception":"Öğrenciler bir öğrenme biçiminin tüm durumlarda diğerinden kesin olarak daha iyi olduğunu düşünür."},{"id":"ing-8-17","course":"ING","grade":8,"themeNo":3,"themeName":"Personal Life & Well-Being","title":"Yeşil Gardırop","subtitle":"Sürdürülebilir moda söz varlığı ve kişisel stil planı","kazanim":["Tema kapsamı: personal life and well-being with self-care and mindfulness for well-being; creating a personal wardrobe and sustainable fashion","Vocabulary — sürdürülebilir moda ve kişisel gardırop oluşturmayla ilgili kelime ve ifadeleri öğrenip kullanma"],"skills21":["Öz Farkındalık","Sürdürülebilirlik","Yaratıcılık","Karar Verme","Estetik"],"digital":["Dijital Portfolyo","Sürdürülebilirlik Okuryazarlığı"],"duration":"40 dk","format":"Bireysel","tools":["NavigAItor Stüdyo","Defter ve kalem","Renkli kalemler"],"scenario":"Okulda 'Swap Day' düzenleniyor: öğrenciler artık giymedikleri ama iyi durumdaki kıyafetlerini değiş tokuş edecek. Etkinlik afişinde ve tanıtımlarında İngilizce moda terimleri kullanılacak. Sen hem kendi gardırobunu gözden geçirecek hem de bu kelimeleri arkadaşlarına öğreteceksin. Daha az alıp daha uzun süre kullanarak nasıl şık olunabilir?","visual":{"type":"cards","params":{"items":[{"w":"second-hand","tr":"ikinci el","ic":"🔁"},{"w":"fast fashion","tr":"hızlı moda","ic":"⚡"},{"w":"recycle","tr":"geri dönüştürmek","ic":"♻️"},{"w":"swap","tr":"takas etmek","ic":"🤝"},{"w":"durable","tr":"dayanıklı","ic":"🧵"},{"w":"outfit","tr":"kıyafet takımı","ic":"👕"},{"w":"mend","tr":"onarmak","ic":"🪡"},{"w":"trendy","tr":"moda olan","ic":"✨"}]},"caption":"Öğrenci kartları çevirerek kelimeleri öğrenir ve her kartı kendi gardırobundan bir örnekle eşleştirir."},"steps":[{"title":"Kartlarla Tanış","mode":"Bireysel · 10 dk","items":["Kartları çevir; önce İngilizceden Türkçeye, sonra Türkçeden İngilizceye kendini test et.","Kelimeleri 'çevreye dost' ve 'çevreye zararlı' olarak iki gruba ayır."],"warn":"Sık yapılan hata: 'trendy' kelimesini her zaman olumlu sanmak; bağlama göre kısa ömürlü tüketimi de çağrıştırabilir."},{"title":"Gardırobunu Tara","mode":"Bireysel · 15 dk","items":["Kendi gardırobundan beş kıyafeti düşün ve her birini en az bir kart kelimesiyle anlatan cümle yaz (My jeans are durable. I can swap my old jacket.).","Bu kıyafetlerden hangisini onarabilir, takas edebilir ya da yeniden kullanabilirsin? Karar ver ve gerekçelendir."],"warn":"Sık yapılan hata: 'clothes' kelimesini tekil gibi kullanmak (a clothes); 'clothes' çoğuldur, tekil için 'a piece of clothing' denir."},{"title":"Swap Day Sloganı","mode":"Bireysel · 15 dk","items":["En az üç kart kelimesi içeren kısa bir İngilizce afiş metni ve slogan yaz.","Metnini NavigAItor Stüdyo'daki dijital portfolyona 'Green Wardrobe' başlığıyla ekle."]}],"checklist":["Sekiz kelimenin hepsini iki yönde test ettim.","Kelimeleri çevreye etkisine göre gruplandırdım.","Kendi kıyafetlerimle ilgili beş cümle yazdım.","Bir kıyafet için sürdürülebilir bir karar verip gerekçelendirdim.","Sloganımda en az üç yeni kelime kullandım."],"rubric":[{"k":"Anlam Bilgisi","d":"Kelimelerin anlamını doğru bilme","l4":"Sekiz kelimenin tamamı","l3":"Altı-yedi kelime","l2":"Dört-beş kelime","l1":"Üç ve altı"},{"k":"Bağlamda Kullanım","d":"Kelimeleri kendi cümlelerinde doğru kullanma","l4":"Doğal ve doğru","l3":"Küçük hatalar","l2":"Anlam yer yer bozuk","l1":"Kullanılamıyor"},{"k":"Sürdürülebilir Karar","d":"Kıyafetler için bilinçli seçim yapma","l4":"Gerekçeli ve özgün karar","l3":"Karar var, gerekçe kısa","l2":"Gerekçesiz karar","l1":"Karar yok"},{"k":"Yaratıcı Ürün","d":"Afiş metni ve sloganın etkisi","l4":"Akılda kalıcı ve doğru","l3":"Anlaşılır ve uygun","l2":"Sade, kelime kullanımı az","l1":"Ürün eksik"}],"navi":["'Fast fashion' bir kıyafetin fiyatı dışında neye mal oluyor olabilir?","Bir kıyafeti 'durable' yapan şey sence nedir; bunu nasıl anlarsın?"],"diff":{"destek":"Kart sayısı beşe indirilir ve her kart için örnek cümle verilir; öğrenci yalnızca boşluk doldurur.","ileri":"Öğrenci kendi 'capsule wardrobe' planını (8 parça ile 10 farklı kombin) İngilizce açıklayan kısa bir blog yazısı hazırlar."},"misconception":"Öğrenciler sürdürülebilir modanın yalnızca yeni 'çevreci' ürünler satın almak olduğunu düşünür."},{"id":"ing-8-18","course":"ING","grade":8,"themeNo":4,"themeName":"Family Life & Home","title":"Büyük Aile Buluşması","subtitle":"Aile buluşması planını dinleme ve sıralama","kazanim":["Tema kapsamı: family life and home with family reunions and celebrations; relationships between the family and the community","Listening — bir aile buluşmasına ait sesli davet ve planı dinleyip olayların sırasını ve ayrıntıları belirleme"],"skills21":["İletişim","Empati","Toplumsal Farkındalık","Aile Bütünlüğü"],"digital":["Dijital Okuryazarlık","Dijital İçerik Üretimi"],"duration":"40 dk","format":"Bireysel + Grup","tools":["Kulaklık","NavigAItor Stüdyo (sesli kayıt)","Defter ve kalem"],"scenario":"Yurt dışında yaşayan kuzenin, büyükannenin 80. doğum gününde yapılacak aile buluşmasına katılacak ama Türkçe bilmiyor. Teyzen sana İngilizce bir sesli mesaj bıraktı ve planı kuzenine anlatmanı istiyor. Mesajda etkinlikler karışık sırayla anlatılıyor ve kimin hangi görevi üstlendiği de geçiyor. Kuzenin hiçbir şeyi kaçırmaması için planı nasıl aktarırsın?","visual":{"type":"timeline","params":{"shuffle":true,"events":[{"y":"10:00","t":"Guests arrive at grandma's garden"},{"y":"11:00","t":"Family photo under the old tree"},{"y":"12:30","t":"Lunch prepared by the uncles"},{"y":"14:00","t":"Cousins perform a short play"},{"y":"16:00","t":"Cutting the birthday cake"},{"y":"17:30","t":"Neighbours join for tea"}]},"caption":"Öğrenci karışık verilen etkinlik kartlarını dinlediği mesaja göre zaman çizelgesinde doğru sıraya dizer."},"steps":[{"title":"Tahmin Et","mode":"Bireysel · 5 dk","items":["Zaman çizelgesindeki etkinlikleri oku; bir aile buluşmasında hangi sırayla olabileceklerini tahmin et.","'reunion', 'gather', 'relatives', 'host' kelimelerinin anlamını bağlamdan çıkar."]},{"title":"Dinle ve Sırala","mode":"Bireysel · 15 dk","items":["Sesli mesajı dinle ve etkinlik kartlarını doğru saatlere yerleştir.","İkinci dinlemede kimin hangi görevi üstlendiğini bir tabloya yaz (Who? / What?)."],"warn":"Sık yapılan hata: Saatleri dinlerken 'half past' ve 'quarter to' ifadelerini karıştırmak; 'quarter to five' 16:45'tir."},{"title":"Kuzenine Aktar","mode":"Grup · 20 dk","items":["İkili ya da üçlü gruplarla planı İngilizce anlatan kısa bir sesli mesaj veya yazılı mesaj hazırlayın (First,... After that,... Don't forget to...).","Mesaja kuzeninizin kendini dışlanmış hissetmemesi için ona özel bir görev ekleyin.","Mesajınızı başka bir gruba dinletin; onlar zaman çizelgesini sizin mesajınıza göre kursun."],"warn":"Sık yapılan hata: Mesajda saatleri ve sırayı belirtmeden yalnızca etkinlikleri sıralamak; dinleyen kişi ne zaman nerede olacağını bilemez."}],"checklist":["Altı etkinliği doğru sıraya dizdim.","Görev tablosunu kişi ve görev olarak doldurdum.","Saat ifadelerini doğru anladım ve yazdım.","Kuzenime planı sıralama kelimeleriyle anlattım.","Kuzenim için özel bir görev önerdim."],"rubric":[{"k":"Sıralama","d":"Olayları doğru zamana yerleştirme","l4":"Tümü doğru","l3":"Bir hata","l2":"İki-üç hata","l1":"Sıralama yapılamadı"},{"k":"Ayrıntı Yakalama","d":"Kişi-görev ve saat bilgisini anlama","l4":"Tüm ayrıntılar doğru","l3":"Çoğu doğru","l2":"Yarısı doğru","l1":"Ayrıntı yok"},{"k":"Aktarım","d":"Planı açık ve sıralı biçimde iletme","l4":"Açık, eksiksiz, akıcı","l3":"Açık ama bir eksik","l2":"Sıra belirsiz","l1":"Aktarılamadı"},{"k":"Empati","d":"Uzaktaki aile üyesini kapsayıcı dil","l4":"Sıcak ve kapsayıcı","l3":"Nazik ama genel","l2":"Bilgi odaklı, mesafeli","l1":"Karşı taraf düşünülmemiş"}],"navi":["Mesajda bir etkinlikten önce 'Right after the photo...' dendiğinde bu etkinlik nereye gelir?","Kuzenin hiç tanımadığı akrabalarla karşılaşacak; mesajında onu rahatlatacak ne söyleyebilirsin?"],"diff":{"destek":"Mesaj iki parçaya bölünerek ve yavaş hızda dinletilir; saat ifadeleri için bir görsel saat kartı verilir.","ileri":"Öğrenci aynı buluşmaya mahalle sakinlerini de davet eden kısa bir İngilizce duyuru yazar ve aile-toplum ilişkisini iki cümleyle yorumlar."},"misconception":"Öğrenciler dinleme metnindeki olayların, anlatıldıkları sırayla gerçekleştiğini varsayar."},{"id":"ing-8-19","course":"ING","grade":8,"themeNo":5,"themeName":"Life In The Neighbourhood & City & Social Life","title":"2040'ın Akıllı Şehri","subtitle":"Geleceğin şehirleri üzerine haber okuma ve değerlendirme","kazanim":["Tema kapsamı: life in the neighbourhood and city and social life with city development and city services; future of cities","Reading — geleceğin şehirleri ve şehir hizmetleriyle ilgili bir haber metnini okuyup ana fikir, ayrıntı ve yazarın görüşünü belirleme"],"skills21":["Analitik Düşünme","Gelecek Okuryazarlığı","Problem Çözme","Sorumluluk"],"digital":["Dijital Okuryazarlık","Dijital Modelleme"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["NavigAItor Stüdyo","Ücretsiz bir dijital çizim aracı","Defter ve kalem"],"scenario":"Belediye, 2040 yılı için şehir planına gençlerin de görüşlerini eklemek istiyor ve okullara İngilizce bir haber metni gönderdi. Haberde akıllı ulaşım, enerji ve atık hizmetleriyle ilgili yenilikler anlatılıyor; ancak her yeniliğin bir bedeli de var. Genç şehir danışmanı olarak haberi okuyup belediyeye bir öneri sunacaksın. Hangi yenilik şehrini gerçekten daha yaşanabilir yapar?","visual":{"type":"news","params":{"headline":"Our City in 2040: Smart, Green and Connected?","lead":"Driverless buses, solar-powered streets and bins that call the rubbish truck when they are full could be part of daily life in 2040. But some residents worry about the cost and their privacy.","tags":["smart city","public transport","renewable energy","waste"]},"caption":"Öğrenci haber kartındaki başlık ve girişten ana fikri tahmin eder, etiketleri metindeki paragraflarla eşleştirir."},"steps":[{"title":"Başlıktan Tahmin","mode":"Bireysel · 10 dk","items":["Başlık ve giriş paragrafını oku; başlıktaki soru işaretinin ne anlama geldiğini Türkçe tartış.","Haberin hangi şehir hizmetlerinden söz edeceğini tahmin edip listele."]},{"title":"Derinlemesine Oku","mode":"Bireysel · 25 dk","items":["Her paragrafın ana fikrini İngilizce birer cümleyle yaz.","Her yenilik için bir avantaj ve bir olası sorunu tabloya aktar.","Yazarın tarafsız mı, olumlu mu, olumsuz mu yazdığını metinden iki ifadeyle kanıtla."],"warn":"Sık yapılan hata: Haberde bir sakinin görüşünü yazarın görüşü sanmak; tırnak içindeki ifadeler alıntıdır."},{"title":"Geleceği Tasarla","mode":"Grup · 30 dk","items":["Grupça haberdeki yeniliklerden birini seçip kendi mahallenize uyarlayan basit bir dijital çizim veya model hazırlayın.","Modelinize 'In 2040, people will be able to...' ile başlayan üç açıklama ekleyin."],"warn":"Sık yapılan hata: Gelecek hakkında yazarken 'will can' yapısını kullanmak; doğrusu 'will be able to'dur."},{"title":"Belediyeye Öneri","mode":"Grup · 15 dk","items":["Belediyeye 60–80 kelimelik İngilizce bir öneri notu yazın: hangi yenilik, neden, hangi sorun nasıl çözülür."]}],"checklist":["Her paragrafın ana fikrini bir cümleyle yazdım.","Yeniliklerin avantaj ve sorunlarını tabloya aktardım.","Yazarın tutumunu metinden kanıtla belirledim.","Alıntı ile yazar görüşünü ayırt ettim.","Modelimize gelecek zaman açıklamaları ekledik.","Öneri notunda bir sorun için çözüm sundum."],"rubric":[{"k":"Ana Fikir ve Ayrıntı","d":"Paragraf ana fikirleri ve destekleyici bilgiler","l4":"Tümü doğru ve öz","l3":"Çoğu doğru","l2":"Yarısı doğru","l1":"Belirlenemedi"},{"k":"Eleştirel Okuma","d":"Yazarın tutumunu ve alıntıları ayırt etme","l4":"Tutum kanıtlı, alıntılar ayrılmış","l3":"Tutum doğru, kanıt zayıf","l2":"Alıntı ile görüş karışık","l1":"Tutum belirlenemedi"},{"k":"Gelecek Tasarımı","d":"Yeniliği yerel ihtiyaca uyarlama","l4":"Özgün ve gerçekçi","l3":"Gerçekçi ama genel","l2":"Uyarlama zayıf","l1":"Model yok"},{"k":"Öneri Yazımı","d":"Gerekçeli ve doğru dilde öneri","l4":"Gerekçeli, doğru, ikna edici","l3":"Gerekçeli, küçük hatalar","l2":"Gerekçe zayıf","l1":"Öneri yok"}],"navi":["Başlıktaki soru işareti yazarın yenilikler hakkında ne düşündüğüne dair bir ipucu olabilir mi?","Bir yenilik bazı insanların hayatını kolaylaştırırken kimin hayatını zorlaştırabilir?"],"diff":{"destek":"Haber metni kısaltılmış ve paragraf başlıkları verilmiş biçimde sunulur; tablo için kelime bankası eklenir.","ileri":"Öğrenci haberi farklı bir bakış açısından (ör. yaşlı bir şehir sakini) yeniden yazan kısa bir okuyucu mektubu hazırlar."},"misconception":"Öğrenciler haber metinlerinin her zaman tarafsız olduğunu ve alıntılanan görüşlerin yazara ait olduğunu düşünür."},{"id":"ing-8-20","course":"ING","grade":8,"themeNo":7,"themeName":"Life In Nature & Global Problems","title":"Bir Haftalık Çöp Raporu","subtitle":"Tüketim alışkanlıkları üzerine veri destekli rapor yazma","kazanim":["Tema kapsamı: life in nature and global problems with impact of technology on global issues; impact of consumerism on people's life and nature","Writing — tüketim alışkanlıklarının doğaya etkisini verilerle anlatan kısa bir rapor yazma"],"skills21":["Eleştirel Düşünme","Sistematik Olma","Sorumluluk","Duyarlılık"],"digital":["Dijital Okuryazarlık","Dijital Raporlama"],"duration":"80 dk (2 ders)","format":"Bireysel + Grup","tools":["Ücretsiz bir hesap tablosu aracı","NavigAItor Stüdyo","Defter ve kalem"],"scenario":"Okulun çevre kulübü, 8. sınıfların bir haftada kantinde ve evde ne kadar tek kullanımlık ürün tükettiğini kaydetti. Sonuçlar grafikte duruyor ama kimse okumuyor. Kulüp, verileri anlamlı hâle getiren İngilizce bir rapor yazılmasını ve okul bültenine konulmasını istiyor. Bu rakamlar alışkanlıklarımız hakkında ne söylüyor ve neyi değiştirmeliyiz?","visual":{"type":"bars","params":{"title":"Single-use items used by 8th graders in one week","labels":["Plastic bottles","Snack wrappers","Paper cups","Plastic bags","Straws"],"values":[140,210,75,60,45],"unit":"items","editable":true},"caption":"Öğrenci grafikteki değerleri okuyup karşılaştırır ve kendi sınıfının tahmini verilerini girerek grafiği günceller."},"steps":[{"title":"Veriyi Oku","mode":"Bireysel · 15 dk","items":["Grafikteki en yüksek ve en düşük değeri bul; aradaki farkı hesapla.","Veriyi anlatan üç İngilizce cümle yaz (The most common item is... / ___ is three times more than ___.)."],"warn":"Sık yapılan hata: 'less' ve 'fewer' kelimelerini karıştırmak; sayılabilen nesneler için 'fewer bottles' denir."},{"title":"Rapor Planı","mode":"Grup · 20 dk","items":["Raporun bölümlerini planlayın: Introduction, Findings, Effects on Nature, Recommendations.","Grafikteki her ürünün doğaya olası etkisini bir neden-sonuç cümlesiyle yazın (Because..., ... As a result,...)."]},{"title":"Raporu Yaz","mode":"Bireysel · 30 dk","items":["120–150 kelimelik raporunu yaz; en az iki veri, iki neden-sonuç bağlacı ve iki öneri kullan.","Önerilerini 'We should... / If we..., we will...' yapılarıyla yaz."],"warn":"Sık yapılan hata: Raporu kişisel duygularla doldurup veriye dayanmamak; her önerinin bir bulguyla bağı olmalı."},{"title":"Düzelt ve Yayınla","mode":"Grup · 15 dk","items":["Grup içinde raporları kontrol listesine göre karşılıklı okuyun ve en az iki düzeltme önerin.","Düzeltilmiş raporu NavigAItor Stüdyo'da bülten formatına aktarın."]}],"checklist":["Grafikten en az iki veriyi raporumda kullandım.","Raporumu dört bölüme ayırdım.","En az iki neden-sonuç bağlacı kullandım.","Önerilerimi bulgulara dayandırdım.","Arkadaşımın raporuna en az iki düzeltme önerdim.","Kelime sınırına uydum."],"rubric":[{"k":"Veri Kullanımı","d":"Grafikteki bilgileri doğru ve anlamlı aktarma","l4":"Veriler doğru ve yorumlu","l3":"Veriler doğru, yorum az","l2":"Bir veri hatalı","l1":"Veri kullanılmamış"},{"k":"Organizasyon","d":"Rapor bölümleri ve paragraf düzeni","l4":"Dört bölüm net ve akıcı","l3":"Bölümler var, geçişler zayıf","l2":"Bir bölüm eksik","l1":"Düzensiz metin"},{"k":"Dil Doğruluğu","d":"Karşılaştırma, bağlaç ve koşul yapıları","l4":"Çeşitli ve doğru","l3":"Küçük hatalar","l2":"Hatalar anlamı etkiliyor","l1":"Yapılar çoğunlukla hatalı"},{"k":"Çözüm Önerisi","d":"Bulgulara dayalı uygulanabilir öneriler","l4":"Gerçekçi ve bulguya bağlı","l3":"Gerçekçi ama genel","l2":"Bulguyla bağı zayıf","l1":"Öneri yok"}],"navi":["En çok kullanılan ürün mü, yoksa doğada en uzun süre kalan ürün mü daha büyük sorun olabilir?","Önerin bir hafta sonra grafikte hangi çubuğu nasıl değiştirirdi?"],"diff":{"destek":"Öğrenciye bölüm başlıkları ve her bölüm için cümle başlatıcıları içeren bir rapor şablonu verilir; kelime sınırı 80–100'e indirilir.","ileri":"Öğrenci kendi evinde bir hafta boyunca veri toplar, grafiği günceller ve raporuna sınıf verisiyle karşılaştırma bölümü ekler."},"misconception":"Öğrenciler tüketim sorununun yalnızca geri dönüşümle çözüleceğini, azaltmanın gerekmediğini düşünür."}];
